```cpp
// H. Remove the Grail Tree
// 题意：树上每点有权 a_v。只要某点满足「a_v 与它的剩余邻居权值和的奇偶性不同」就可以删掉它，
//       删掉后它的边也一起消失。问能否把整棵树删光；能就输出任意一个删除顺序。
// 关键转化（把「删除顺序」换成「给边定向」）：
//   记 b_v = a_v mod 2。删 v 时它的剩余邻居，恰好是「先被删的 v 指向后被删的邻居」这条定向里的出邻居。
//   树没有环 —— 任何定向都无环，按拓扑序删就能实现；反过来任何删除顺序也诱导出一个定向。
//   所以「能删光」⇔ 存在一种定向，使每个 v 满足  b_v + (出邻居中 b=1 的个数) ≡ 1 (mod 2)。
// 把边分两类：
//   · 偶点—奇点的边：只有当偶点是尾时才给偶点贡献一个「奇数出邻居」，
//     所以每个偶点必须至少有一个奇邻居（判据①），并挑一条偶→奇的边即可；其余混合边方向随便（取奇→偶）。
//   · 奇点—奇点的边（这些边诱导出森林 F）：奇点要「奇数出邻居个数为偶」，即 F 中出度为偶。
//     对 F 的每个连通块自底向上定：孩子边已定，父边朝上朝下二选一，总能把该点出度配成偶；
//     而块根（离全局根最近的那个奇点）的出度奇偶 = 块内边数的奇偶，
//     所以每个连通块的边数必须是偶数（判据②）。
// 复杂度：O(n)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不混 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;

        vector<int> b(n + 1);                       // b[v] = a_v mod 2
        for (int i = 1; i <= n; i++) {
            long long x;
            cin >> x;
            b[i] = (int)(x & 1);
        }

        vector<vector<int>> adj(n + 1);
        vector<pair<int, int>> edges;
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
            edges.push_back({u, v});
        }

        bool ok = true;

        // 判据①：每个偶点都要有奇邻居
        for (int v = 1; v <= n && ok; v++) {
            if (b[v]) continue;
            bool found = false;
            for (int u : adj[v])
                if (b[u]) { found = true; break; }
            if (!found) ok = false;
        }
        if (!ok) { cout << "NO\n"; continue; }

        // 以 1 为根 BFS，拿到父指针与顺序（order 是 BFS 序，逆序即自底向上）
        vector<int> par(n + 1, 0), order;
        vector<char> vis(n + 1, 0);
        order.reserve(n);
        order.push_back(1);
        vis[1] = 1;
        for (size_t h = 0; h < order.size(); h++) {
            int v = order[h];
            for (int u : adj[v])
                if (!vis[u]) { vis[u] = 1; par[u] = v; order.push_back(u); }
        }

        // 判据②：奇点诱导森林 F 的每个连通块边数为偶数
        vector<char> seen(n + 1, 0);
        for (int s = 1; s <= n && ok; s++) {
            if (!b[s] || seen[s]) continue;
            long long degsum = 0;                   // F 内度数之和 = 2 × 边数
            vector<int> st;
            st.push_back(s);
            seen[s] = 1;
            while (!st.empty()) {
                int v = st.back();
                st.pop_back();
                for (int u : adj[v])
                    if (b[u]) {
                        degsum++;
                        if (!seen[u]) { seen[u] = 1; st.push_back(u); }
                    }
            }
            if ((degsum / 2) % 2 == 1) ok = false;   // 边数为奇 → 块根出度配不成偶
        }
        if (!ok) { cout << "NO\n"; continue; }

        // 开始定向：out[v] = v 的出边（v 必须先于这些点被删）
        vector<vector<int>> out(n + 1);
        vector<int> outCnt(n + 1, 0);   // outCnt[v] = F 中已定成 v→(某个奇孩子) 的边数

        // 奇—奇边：自底向上定，保证每个非块根奇点的 F 出度为偶
        for (int idx = n - 1; idx >= 0; idx--) {
            int v = order[idx], p = par[v];
            if (p && b[v] && b[p]) {
                if (outCnt[v] % 2 == 0) {            // 孩子边已给 v 偶数出度 → 父边定成 p→v
                    out[p].push_back(v);
                    outCnt[p]++;
                } else {                             // 奇数 → 父边定成 v→p，把出度补成偶
                    out[v].push_back(p);
                }
            }
        }

        // 每个偶点挑一个奇邻居，把这条混合边定成 偶→奇（保证它的奇出邻居个数为 1，即奇数）
        vector<int> chosen(n + 1, 0);
        for (int v = 1; v <= n; v++) {
            if (b[v]) continue;
            for (int u : adj[v])
                if (b[u]) { chosen[v] = u; break; }
        }
        for (auto& e : edges) {
            int u = e.first, w = e.second;
            if (b[u] && b[w]) continue;                          // 奇—奇边上面已定
            if (!b[u] && !b[w]) { out[u].push_back(w); continue; } // 偶—偶边：不影响任何约束
            int even = b[u] ? w : u, odd = b[u] ? u : w;
            if (chosen[even] == odd)
                out[even].push_back(odd);                        // 偶点 → 它挑中的奇点
            else
                out[odd].push_back(even);                        // 其余混合边：奇 → 偶
        }

        // 拓扑排序（树无环，一定排得完），得到删除顺序
        vector<int> indeg(n + 1, 0);
        for (int v = 1; v <= n; v++)
            for (int u : out[v]) indeg[u]++;
        vector<int> q;
        for (int v = 1; v <= n; v++)
            if (!indeg[v]) q.push_back(v);
        for (size_t h = 0; h < q.size(); h++) {
            int v = q[h];
            for (int u : out[v])
                if (--indeg[u] == 0) q.push_back(u);
        }

        cout << "YES\n";
        for (int i = 0; i < n; i++) cout << q[i] << (i + 1 == n ? '\n' : ' ');
    }
    return 0;
}
```

### 易错点

奇点块检查的是边数偶，不是点数偶。当前可删的点不一定可以随意删，必须遵循构造的顺序。

## A. Sieve of Erato67henes

### 题意

从正整数数组中选至少一个元素，使乘积恰好为 $67$，判断是否可能。

### 思路

目标乘积是质数 $67$，因此先看这个目标能怎样分解。数组元素都是正整数；一组数相乘等于 $67$ 时，每个因子只能是 $1$ 或 $67$，且必须恰有一个 $67$。不可能靠几个小于 $67$ 的其他正整数凑出它，因为这些整数会给乘积引入其他质因子。

于是必要条件是原数组里出现 $67$。它也充分：只选择这一项，得到的子序列非空，乘积恰好为 $67$；无需把旁边的 $1$ 一起选上。

例如 $[1,67,2]$ 选择中间一项即可；$[1,1,1]$ 即使全选，乘积仍为 $1$。因此无需枚举子序列，也无需实际计算可能溢出的乘积。代码边读入边记录是否见过 $67$，读完本组所有元素后输出判断。时间 $O(n)$，额外空间 $O(1)$。

### 参考代码

```cpp
// A. Sieve of Erato67henes —— 正解
// 题意：给 n 个正整数 a_1..a_n，问能否挑出若干个（至少一个）元素，使它们的乘积恰好等于 67。
// 思路：67 是质数，而所有 a_i 都是正整数（最小是 1）。
//       正整数相乘等于 67，每个因子只能是 1 或 67，
//       所以能凑出 67 的唯一形态就是「若干个 1 + 一个 67」——数组里必须真的出现 67。
//       反过来，只要出现了 67，单独选它一个就够了。
//       于是判据：67 是否出现在数组里。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 C 标准流的同步（全篇只用 cin/cout，不与 stdio 混用）
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定，避免每次读入都顺带刷新输出

    int t;                         // t：测试组数
    cin >> t;
    while (t--) {                  // 一组一组处理
        int n;                     // n：本组元素个数（1 <= n <= 5）
        cin >> n;
        bool found = false;        // 本组里是否出现过 67
        for (int i = 0; i < n; ++i) {
            int x;                 // 当前读入的元素值（1 <= x <= 67）
            cin >> x;
            if (x == 67) found = true;   // 出现 67 就一定能凑出 67（选它自己，乘积就是 67）
        }
        // 有 67 → YES；没有 67 时所有元素要么是 1、要么是别的数，乘积只会越来越偏离 67 → NO
        cout << (found ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

不需要真的枚举子集或计算乘积。

## B. Heapify 1

### 题意

排列可以交换位置 $i$ 与 $2i$，允许任意次，判断能否排序。

### 思路

#### 先找到哪些位置互相可达

交换只发生在位置 $i$ 和 $2i$ 之间。不断除去一个正整数中的因子 $2$，剩下的奇数称为它的奇数部分，记作 $o(i)$。位置 $i$ 与 $2i$ 的奇数部分相同，因此任何元素在移动过程中所在位置的奇数部分都不变。

所有奇数部分为 $r$ 的位置恰好组成一条链 $r,2r,4r,\ldots$，保留不超过 $n$ 的项。链内相邻位置可以交换，所以元素可以通过连续交换走到链上任意位置；进一步，沿链做相邻交换就能实现链内任意排列。不同链之间则完全不能交换。

#### 对每个元素检查目的地

排序完成后，数值 $a_i$ 必须处于位置 $a_i$。它现在在位置 $i$，故必要条件是 $o(i)=o(a_i)$。如果每个元素都满足此条件，则每条链里装的正是这条链最终需要的那些数，利用链内相邻交换即可分别排好，因此条件也充分。

例如位置 $3$ 的数可以去 $6$、$12$，却永远去不了 $2$；奇数部分分别是 $3$ 和 $1$。代码对位置与值分别反复除以 $2$，比较剩余奇数，出现一次不同就把答案标记为否。即使已经不可能，也仍须读完当前排列。

每项最多除 $O(\log n)$ 次，直接上界为 $O(n\log n)$，额外空间 $O(1)$。这里检查的是位置所属的交换链，不能只比较当前位置和数值的奇偶性，因为偶数中还包含许多不同的链。

### 参考代码

```cpp
// B. Heapify 1 —— 正解
// 题意：给一个 1..n 的排列 a，每次操作可以选 i（1 <= i <= n/2，向下取整）交换 a_i 与 a_{2i}，
//       操作可以做任意多次，问能否把 a 排成严格升序。
// 思路：把「位置」看成点，把一次允许的交换 (i, 2i) 看成一条边。
//       · 偶数位置 j 一定连到 j/2（因为 j <= n 保证 j/2 <= n/2，这条边总是可用的）；
//       · 奇数位置没有出边，只有可能作为某个偶数位置的父节点。
//       所以整张图是一堆互不相交的**链**。同一条链上的位置有什么关系？
//       从一个位置不停乘 2 或者不停除以 2，只会改变编号里因子 2 的个数，
//       不会改变它「把因子 2 全部除干净之后剩下的那个奇数」——这个奇数叫编号的奇数部分。
//       于是：链 = 奇数部分相同的一批位置，形如 {o, 2o, 4o, ...}（o 是奇数）。
//       链内的相邻位置可以互相交换 → 相邻对换能生成整条链上的任意排列，
//       所以同一条链上的元素可以**任意重排**，不同链之间永远换不过去。
//       排成升序要求位置 i 上正好是数值 i，
//       于是充要条件：每条链上的「数值集合」与「位置集合」完全一致。
//       逐位写就是：位置 i 上的数值 x，必须与 i 有相同的奇数部分。
#include <bits/stdc++.h>
using namespace std;

// 求 v 的奇数部分：把 v 里的因子 2 全部除掉（v >= 1）
int oddPart(int v) {
    while (v % 2 == 0) v /= 2;     // 一直除以 2，直到变成奇数
    return v;
}

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;                         // t：测试组数
    cin >> t;
    while (t--) {
        int n;                     // n：排列长度（1 <= n <= 2e5，所有组 n 之和 <= 2e5）
        cin >> n;
        bool ok = true;            // 是否每条链都「位置集合 == 数值集合」
        for (int i = 1; i <= n; ++i) {
            int x;                 // 位置 i 上的数值
            cin >> x;
            // 数值和位置的奇数部分不同 → 这个数永远换不到这条链上 → 排不成升序
            if (oddPart(x) != oddPart(i)) ok = false;
        }
        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

判断的是位置与数值的奇数部分，不能只比较奇偶性。

## C. Dice Roll Sequence

### 题意

骰子相对面为 $(1,6),(2,5),(3,4)$。修改尽量少的序列元素，使每对相邻元素既不相同，也不是相对面。

### 思路

#### 修改选择只需要记住最后一面

相邻骰子面必须既不相同，也不互为对面。标准骰子对面之和为 $7$，因此前一面为 $u$、后一面为 $v$ 时，允许相邻的条件正是 $u\ne v$ 且 $u+v\ne7$。

前面整段具体改成什么，对后续的影响仅由最后一面决定。令 $dp[v]$ 表示已经处理完当前前缀、最后一个面改成 $v$ 时的最少修改次数。每个位置只有六种终态，枚举它们比枚举整条序列容易得多。

处理原值为 $a_i$ 的新位置时，令新数组为 $ndp$，则
$$ndp[v]=[v\ne a_i]+\min_{u\ne v,\ u+v\ne7}dp[u].$$
方括号在条件成立时为 $1$，否则为 $0$。第一项是本位置的修改代价；后半项选择所有能够接在 $v$ 前面的最优前缀。第一面没有前驱，直接按是否等于原值初始化即可，代码用首位置的特殊分支实现。

#### 为什么局部状态没有漏解

任意合法修改方案都有确定的末面 $v$ 和倒数第二面 $u$，它必满足转移条件；其前缀代价不可能低于旧状态 $dp[u]$。反过来，把取得最小值的前缀接上 $v$，唯一新增的相邻关系也合法，因此转移得到的值确实能实现。按位置归纳即可得到全局最优。

例如原序列 $[1,6,1]$ 中，两对相邻都互为对面，但把中间的 $6$ 改成 $2$ 就能同时修复，答案为 $1$。这说明不能看到一个坏相邻对就独立付一次修改费。

最后取六个末面状态的最小值。每个位置枚举 $6\times6$ 对面值，时间 $O(36n)=O(n)$，滚动数组额外空间 $O(6)$。必须先算完新一层再覆盖旧层，否则会把同一位置重复使用。

### 参考代码

```cpp
// C. Dice Roll Sequence —— 正解（6 状态线性 DP）
// 题意：骰子相对的两面是 (1,6)、(2,5)、(3,4)。一个序列合法 ⟺ 每一对相邻元素都在**相邻面**上，
//       也就是 a_i != a_{i+1} 且 a_i + a_{i+1} != 7。
//       每次操作可以把任意一个位置改成 1..6 中任意值，求让序列合法的最少操作次数。
// 思路：约束只发生在相邻两个位置之间 → 从左往右做 DP。
//       记 dp[v] = 处理完当前这个位置、并且它最后取值 v 的最小改动次数。
//       转移时枚举上一个位置的取值 u（必须与 v 相邻），代价再加上「当前位置本来是不是 v」：
//           dp'[v] = (a_i != v) + min{ dp[u] : u 与 v 相邻 }
//       第一个位置没有前驱约束，dp[v] 初值就是 (a_1 != v)。
//       每个位置只枚举 6 x 6 种搭配，总复杂度 O(36 n)，sum n <= 3e5，绰绰有余。
#include <bits/stdc++.h>
using namespace std;

// 两个面是否相邻：编号不同（同面不算相邻），且不是相对面（相对面和为 7）
bool adjacent(int u, int v) {
    return u != v && u + v != 7;
}

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    const int INF = 1e9;           // 哨兵：表示「这个取值暂时不可达」
    int t;                         // t：测试组数
    cin >> t;
    while (t--) {
        int n;                     // n：序列长度（1 <= n <= 3e5，所有组 n 之和 <= 3e5）
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        vector<int> dp(7, 0), nd(7, INF);      // 下标 1..6 对应骰子的六个面
        for (int i = 0; i < n; ++i) {
            fill(nd.begin(), nd.end(), INF);   // 重开一层
            for (int v = 1; v <= 6; ++v) {     // 枚举当前位置的取值 v
                int best;
                if (i == 0) {
                    best = 0;                  // 第一个位置没有前驱，不受约束
                } else {
                    best = INF;
                    for (int u = 1; u <= 6; ++u)
                        if (adjacent(u, v)) best = min(best, dp[u]);   // 前一个位置必须与 v 相邻
                }
                if (best < INF)
                    nd[v] = best + (a[i] != v);   // 取值与原来的数不同 → 花掉一次操作
            }
            dp.swap(nd);                        // 滚动到下一层
        }
        cout << *min_element(dp.begin() + 1, dp.end()) << '\n';   // 最后一个位置取哪个值都行，取最小
    }
    return 0;
}
```

### 易错点

既要排除同面，也要排除相对面。当前层用新数组计算，避免把刚更新的状态当作上一位。

## D. Absolute Cinema

### 题意

已知 $f(x)=\sum_{i=1}^n a_i|i-x|$ 在 $x=1\ldots n$ 的所有值，保证原整数数组唯一，求出它。

### 思路

#### 相邻差分能分开左右贡献

记题目给出的值为 $f_x=\sum_{i=1}^n a_i|i-x|$。把观察点从 $x$ 移到 $x+1$：左侧及位置 $x$ 的距离都增加 $1$，右侧距离都减少 $1$。若 $S_x=\sum_{i=1}^x a_i$，则
$$f_{x+1}-f_x=S_x-(S_n-S_x)=2S_x-S_n.$$
即使某个 $a_i$ 为负，等式仍成立，因为我们只是对各项做代数运算。

再减去前一个相邻差分，总和 $S_n$ 被消去，留下
$$f_{x+1}-2f_x+f_{x-1}=2a_x.$$
所以对所有内部位置 $2\le x\le n-1$，直接由二阶差分除以 $2$ 求出 $a_x$。题目保证数据确有来源，因此该分子一定是偶数。

#### 两端用原式补回

内部值确定后，代入左端的原式：
$$f_1=\sum_{i=2}^{n-1}a_i(i-1)+a_n(n-1).$$
这里 $a_1$ 的系数为零，因此可单独解出 $a_n$。同理，右端满足
$$f_n=a_1(n-1)+\sum_{i=2}^{n-1}a_i(n-i),$$
从而求出 $a_1$。这也说明为什么只用二阶差分还不够：它无法直接覆盖缺少左右邻居的两个端点。

例如 $a=[2,-1,3]$ 对应 $f=[5,5,3]$。中间值为 $(3-2\cdot5+5)/2=-1$；再由左端得到 $a_3=(5+1)/2=3$，由右端得到 $a_1=(3+1)/2=2$。

代码先填内部位置，再计算两个带权和及端点。当 $n=2$ 时内部循环为空，公式自然退化为 $a_2=f_1,a_1=f_2$，无需另写复杂分支。所有求和、乘法和差分用 $64$ 位有符号整数。时间 $O(n)$，空间 $O(n)$。

### 参考代码

```cpp
// D. Absolute Cinema —— 正解（差分）
// 题意：有一个隐藏的整数序列 a_1..a_n（n >= 2，|a_i| <= 1000），
//       已知 f(x) = sum_{i=1..n} a_i * |i - x|（x = 1..n 全部给定），求 a。答案唯一。
// 思路：对 f 做一阶差分。记 S_x = a_1 + ... + a_x（前缀和），逐项看 |i-x| 在 x 加一时怎么变：
//       · i <= x 时 |i-(x+1)| - |i-x| = (x+1-i) - (x-i) = +1；
//       · i >= x+1 时 |i-(x+1)| - |i-x| = (i-x-1) - (i-x) = -1。
//       于是 d_x := f(x+1) - f(x) = S_x - (S_n - S_x) = 2*S_x - S_n。
//       再做一次差分就把未知的 S_n 消掉了：
//           d_x - d_{x-1} = 2*(S_x - S_{x-1}) = 2*a_x，
//       所以中间那些位置（2 <= x <= n-1）可以直接由二阶差分读出：a_x = (d_x - d_{x-1}) / 2。
//       剩下两个端点用 f 的两个端点值各解一次（n >= 2 保证 (n-1) 不为 0）：
//           f(1) = sum_{i>=2} a_i * (i-1)  → a_n = ( f(1) - sum_{2<=i<=n-1} a_i*(i-1) ) / (n-1)；
//           f(n) = sum_{i<=n-1} a_i * (n-i) → a_1 = ( f(n) - sum_{2<=i<=n-1} a_i*(n-i) ) / (n-1)。
//       题目保证 a 是整数，所以这两处除法都整除。整体 O(n)。
//       数值范围：|a_i| <= 1000、n <= 3e5，f 的差分最大 2e14，求和式最大约 4.5e13，long long 足够。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;                         // t：测试组数
    cin >> t;
    while (t--) {
        int n;                     // n：序列长度（2 <= n <= 3e5，所有组 n 之和 <= 3e5）
        cin >> n;
        vector<ll> f(n + 1);
        for (int i = 1; i <= n; ++i) cin >> f[i];      // f[1..n]，|f(i)| <= 1e14

        vector<ll> a(n + 1, 0);
        for (int x = 2; x <= n - 1; ++x) {             // ① 中间位置：由二阶差分直接得到
            ll dLeft = f[x] - f[x - 1];                // d_{x-1} = f(x) - f(x-1)
            ll dRight = f[x + 1] - f[x];               // d_x     = f(x+1) - f(x)
            a[x] = (dRight - dLeft) / 2;               // = 2*a_x / 2，整除
        }

        ll T = 0, U = 0;                               // T = sum a_i*(i-1)，U = sum a_i*(n-i)，i 只跑中间段
        for (int i = 2; i <= n - 1; ++i) {
            T += a[i] * (i - 1);
            U += a[i] * (n - i);
        }

        a[n] = (f[1] - T) / (n - 1);                   // ② 用 f(1) 定 a_n
        a[1] = (f[n] - U) / (n - 1);                   // ③ 用 f(n) 定 a_1

        for (int i = 1; i <= n; ++i) cout << a[i] << " \n"[i == n];   // 一组一行，空格分隔
    }
    return 0;
}
```

### 易错点

权值可为负，差分也可能为负；中间的加权和使用 64 位整数。题目保证可还原，除法应整除。

## E. Idiot First Search

### 题意

根零只有儿子一，其他节点是叶子或恰有左右两个儿子。节点初始无标记：第一次访问内部点写左标记并去左儿子，第二次改为右并去右儿子，第三次擦除标记并去父亲；叶子直接去父亲。求从每个节点出发首次到零的步数模 $10^9+7$。

### 从零讲：一趟 = $2\operatorname{size} - 1$（走完一棵子树，字母全被擦回空）

叶子从自己到父亲只需一步，且没有标记残留。对内部节点，它会先走向左儿子，完整执行左子树的一趟，再对右儿子做同样的事，最后擦掉自身标记并走向父亲。

![子树往返代价](assets/e-tour.svg)

归纳假设儿子的每一趟都会恢复空状态，那么父节点离开时，左右子树和自己也全部为空。所有子树内部边恰好向下、向上各走一次，另有一条到父亲的边走一次，总步数为
$$2(\operatorname{size}(v)-1)+1=2\operatorname{size}(v)-1.$$
这份“恢复原状”的性质比步数公式更关键。否则走到父亲后，它再次访问刚才的子树可能出现不同路线，就不能简单累加祖先代价。

### 思路

#### 把复杂移动切成可以重复的一趟

定义节点 $v$ 的“一趟”：从整棵子树标记全空的 $v$ 出发，直到第一次走到它的父亲。叶子的一趟只有一步，结束后没有标记残留。内部节点则依次执行“向左一步、左儿子一趟、向右一步、右儿子一趟、向父亲一步”。在最后一步之前，自身的右标记也被擦掉。

对子树归纳可知，每一趟结束后，整棵子树重新全空。这一点保证了同一子树下次被进入时，仍能重复相同路线。它并不是只被访问一次：从某个后代出发时，之后父亲的一趟还会再次访问刚走完的子树。

设子树点数为 $sz_v$。一趟中，子树内部的 $sz_v-1$ 条边都下行、上行各一次，最后再跨出子树一次，故代价
$$c_v=2(sz_v-1)+1=2sz_v-1.$$

#### 到父亲时，又回到一份全空问题

从 $v$ 开始，先用 $c_v$ 步到父亲。在此之前父亲和其他子树没有被访问，刚走过的子树又已恢复空状态，因此此时的后续过程，恰等于独立从父亲的全空状态出发。若 $T_v$ 为到节点 $0$ 的总步数，就有
$$T_v=c_v+T_{\operatorname{par}(v)},\qquad T_0=0.$$

例如节点 $1$ 有两个叶子 $2,3$。从 $1$ 的路线为 $1,2,1,3,1,0$，需要 $5$ 步；从 $2$ 出发先花一步回到 $1$，此时 $1$ 还是空标记，接着完整执行上述路线，所以共 $6$ 步，而不是只走 $2,1,0$。

#### 两个遍历方向各解决一个依赖

代码先用队列式数组得到父亲在儿子之前的顺序。逆序时儿子大小已知，可计算 $sz_v=1+sz_l+sz_r$；正序时父亲答案已知，可计算 $T_v$。编号并不保证符合父子先后关系，因此不能直接按编号递推。

每次相加对 $10^9+7$ 取模即可；子树大小仍保存真实整数。迭代遍历避免深树递归栈风险。每个节点只处理常数次，时间、空间均为 $O(n)$。

### 参考代码

```cpp
// E. Idiot First Search
//
// 结论：设 size(v) 为以 v 为根的子树点数（顶点 v 自己算 1），
//       令 cost(v) = 2*size(v) - 1（= 从 v 出发、下方全空时，
//       「走完 v 的整棵子树并跨出 v 到父亲」所需的移动次数），
//       则答案 tau_k = sum{ cost(v) : v 是 k 的祖先（含 k 自己，一直到顶点 1） }。
//
// 理由：从 k 出发，先把 k 的子树整棵走完（此时子树里所有字母都被擦回空），
//       走到父亲 p；此刻 p 的整棵子树都还是空的，于是 Bob 在 p 上又走一遍
//       「完整的一趟」，其耗时恰好也是 cost(p)；再往上同理，直到从顶点 1 跨到 0。
#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;   // 题目要求的取模数

int main() {
    ios::sync_with_stdio(false);      // 关掉与 stdio 的同步（只用 cin/cout）
    cin.tie(nullptr);                 // 解除 cin 与 cout 的绑定，读得更快

    int t;
    cin >> t;                         // 测试组数
    while (t--) {
        int n;
        cin >> n;                     // 除根 0 之外的顶点数（保证是奇数）

        vector<int> lc(n + 1, 0), rc(n + 1, 0);   // 左右儿子，0 表示没有
        vector<int> par(n + 1, 0);               // 父亲（顶点 1 的父亲是 0）
        for (int i = 1; i <= n; i++) {
            cin >> lc[i] >> rc[i];               // 第 i 行：顶点 i 的两个儿子
            if (lc[i]) {                         // 有儿子 => 两个儿子都在（题面保证）
                par[lc[i]] = i;                  // 登记左儿子的父亲
                par[rc[i]] = i;                  // 登记右儿子的父亲
            }
        }

        // 从根 1 出发做 BFS，拿到「父亲一定排在儿子前面」的顺序
        vector<int> ord;                         // BFS 序
        ord.reserve(n);
        ord.push_back(1);                        // 顶点 1 是这棵子树（1..n）的根
        for (size_t h = 0; h < ord.size(); h++) {
            int v = ord[h];
            if (lc[v]) {                         // 叶子没有儿子，跳过
                ord.push_back(lc[v]);            // 左儿子入队
                ord.push_back(rc[v]);            // 右儿子入队
            }
        }

        // 逆 BFS 序求子树大小：儿子一定先于父亲被处理完
        vector<int> sz(n + 1, 0);                // sz[v] = 子树 v 的点数
        for (int i = n - 1; i >= 0; i--) {
            int v = ord[i];
            sz[v] = 1 + sz[lc[v]] + sz[rc[v]];   // 自己 + 左子树 + 右子树
        }

        // 正 BFS 序推答案：T[v] = T[par[v]] + (2*sz[v]-1)，T[0] = 0
        vector<long long> T(n + 1, 0);           // T[v] = 从 v 出发到 0 的耗时（模意义下）
        for (int i = 0; i < n; i++) {
            int v = ord[i];
            long long cost = (2LL * sz[v] - 1) % MOD;   // 走完子树 v 并跨出 v 的步数
            T[v] = (T[par[v]] + cost) % MOD;            // 加上祖先链上前一段
        }

        for (int k = 1; k <= n; k++) {                // 按顶点编号 1..n 输出
            cout << T[k] << (k == n ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

每趟包含最后走到父亲的那一步，所以代价为 $2\operatorname{size}-1$。深树使用迭代遍历。

## F. Parabola Independence

### 题意

给出两两不同的二次函数。若两个函数在所有实数处都不相等，称它们独立。对每个函数求包含它、且两两独立的最大子集大小。

### 从零讲：把「两抛物线有没有交点」翻成「时空里的类时」

两条抛物线相交，等价于差函数 $Ax^2+Bx+C=0$ 有实根。$A\ne0$ 时，无实根条件是 $B^2-4AC<0$；$A=0,B\ne0$ 时总有一个根；$A=B=0$ 时为非零常数，两函数始终不相等。

代码把每个函数映射成 $T=a+c,P=b,Q=a-c$。对两函数做差，恒等式给出
$$\Delta P^2+\Delta Q^2-\Delta T^2=(\Delta b)^2-4\Delta a\,\Delta c.$$
所以二次差函数无实根，正好是平面距离平方小于 $T$ 差的平方，即注释里的“类时”判据；另外补上相同 $a,b$ 的常数差情况。

无需依赖几何术语也能理解传递性：若每个实数处都有 $f<g$、$g<h$，自然处处有 $f<h$。例如 $x^2,x^2+1,2x^2+2$ 形成三条链；而 $x^2$ 与 $2x^2$ 在零处相交，不能同时选入。将函数的偏序转成有向无环图上的最长路，就是正文的两遍 DP。

### 思路

#### 先把独立关系变成可计算的条件

两函数相交当且仅当差函数 $Ax^2+Bx+C$ 有实根。若 $A\ne0$，无实根恰等价于判别式 $B^2-4AC<0$。若 $A=0$，还要单独判断：$B\ne0$ 的一次式一定有根；$B=0$ 时，由函数两两不同可知 $C\ne0$，所以是没有根的非零常数。

代码保存 $T=a+c,P=b,Q=a-c$，因为
$$\Delta P^2+\Delta Q^2-\Delta T^2=(\Delta b)^2-4\Delta a\Delta c.$$
于是先判断左边是否小于零，再补上二次系数与一次系数都相同的平移情况。无需浮点数，也无需真的求交点。系数绝对值至多 $10^6$，差值平方及平方和均能放进代码使用的 $64$ 位整数。

#### 独立集合其实是一条上下排列的链

两个连续函数若处处不相等，其中一个就必须处处在另一个上方；否则差函数从正变负，会在中间取到零。把这种关系写作 $f\prec g$，表示对所有实数都有 $f(x)<g(x)$。该关系具有传递性：$f\prec g$ 且 $g\prec h$ 时自然有 $f\prec h$。

因此两两独立集合可以按上下关系排成链。反过来，只要相邻函数构成这样的严格上升链，传递性就保证链中所有函数两两独立。这让原本看似需要求最大团的问题变成最长链问题。

代码按 $T$ 排序是合法的。如果 $g-f$ 恒正，它或者是正常数，或者是开口向上且无实根的二次式；其常数项严格为正、二次系数非负，所以 $T_g-T_f>0$。因此独立的一对必然沿 $T$ 增大的方向连边，同 $T$ 的函数之间没有边。

#### 包含指定函数，需要左右各做一次最长路

正序计算 $down_i$，表示以函数 $i$ 为最高端点的最长链。初值为只选自己的 $1$，枚举所有更早、且与它独立的函数 $j$，用 $down_j+1$ 更新。倒序同理求以它为最低端点的最长链 $up_i$。

答案是 $down_i+up_i-1$。两段都包含函数 $i$，故减去一次重复；下半段任意函数都在 $i$ 下方，上半段任意函数都在 $i$ 上方，传递性保证跨段也独立，所以这个长度能够实现。任何包含 $i$ 的链拆成上下两段后，又分别不超过这两个最优值，因此不会存在更优答案。

例如 $x^2,x^2+1,2x^2+2$ 可组成长度 $3$ 的链；$x^2$ 与 $2x^2$ 在零处相等，不能因为二次系数不同就认为独立。两遍各枚举 $O(n^2)$ 对函数，排序的 $O(n\log n)$ 被覆盖，总时间 $O(n^2)$，额外空间 $O(n)$。

### 参考代码

```cpp
// F. Parabola Independence
//
// 两个抛物线 f_i, f_j 独立 <=> 方程 f_i(x) = f_j(x) 没有实数解。
// 记 A=Δa, B=Δb, C=Δc（都是两个函数之差）：
//   · A = 0：一次方程 Bx + C = 0，无解 <=> B = 0（此时两函数是上下平移，永不相交）；
//   · A ≠ 0：判别式 B^2 - 4AC < 0。
//
// 关键恒等式：B^2 - 4AC = B^2 + (A-C)^2 - (A+C)^2。
// 把每个函数映成三维点 (T, P, Q) = (a+c, b, a-c)，则
//   「独立」<=> P、Q 方向的欧氏距离 < |ΔT|  （即闵可夫斯基意义下的「类时」），
//   例外是 A = B = 0（上下平移）—— 这时恰好取等号，但两点确实不相交。
//
// 因为「类时」满足三角形不等式推出的传递性（严格步与取等步混着也成立），
// 关系  i ≺ j  <=>  T_i < T_j 且 i、j 独立   是一个**严格偏序**，
// 于是「两两独立的集合」= 偏序里的链，答案是
//   s_i = down[i] + up[i] - 1
// （down[i] = 以 i 结尾的最长链，up[i] = 以 i 开头的最长链）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);       // 只用 cin/cout，不碰 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                          // 测试组数
    while (t--) {
        int n;
        cin >> n;                      // 抛物线个数
        vector<long long> A(n), P(n), Q(n), T(n);   // A = a, P = b, Q = a-c, T = a+c
        for (int i = 0; i < n; i++) {
            long long a, b, c;
            cin >> a >> b >> c;        // f_i(x) = a x^2 + b x + c
            A[i] = a;
            P[i] = b;
            Q[i] = a - c;
            T[i] = a + c;
        }

        // 独立判据：ΔP^2 + ΔQ^2 < ΔT^2，或（A 与 P 都相同 => 纯上下平移）
        auto independent = [&](int i, int j) -> bool {
            long long dP = P[i] - P[j];
            long long dQ = Q[i] - Q[j];
            long long dT = T[i] - T[j];
            if (dP * dP + dQ * dQ < dT * dT) return true;
            return A[i] == A[j] && P[i] == P[j];
        };

        // 按 T 排序：独立的一对必然 T 不同，所以同 T 之间没有边
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y) { return T[x] < T[y]; });

        vector<int> down(n, 1), up(n, 1);          // 链长度初值 = 只有自己
        for (int i = 0; i < n; i++) {              // 正序：算 down
            int v = ord[i];
            int best = 0;
            for (int k = 0; k < i; k++) {
                int u = ord[k];
                if (T[u] < T[v] && independent(u, v)) best = max(best, down[u]);
            }
            down[v] = best + 1;
        }
        for (int i = n - 1; i >= 0; i--) {         // 倒序：算 up
            int v = ord[i];
            int best = 0;
            for (int k = i + 1; k < n; k++) {
                int u = ord[k];
                if (T[u] > T[v] && independent(v, u)) best = max(best, up[u]);
            }
            up[v] = best + 1;
        }

        for (int i = 0; i < n; i++) {              // 含 f_i 的最长链
            cout << down[i] + up[i] - 1 << (i + 1 == n ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

差函数可能降为一次式或常数，不能只看二次判别式。平方和用足够宽的整数，避免溢出。

## G. Idiot First Search and Queries

### 题意

沿用 E 题的树和访问规则。每次询问从初始空状态的节点 $v$ 出发，恰走 $k$ 步后的位置，保证还没到根零。

### 从零讲：为什么只模拟一次就够（子树的一趟 = 全程里的一段）

E 题证明，一棵子树从空状态开始执行完一趟后仍为空。因此任何时候从空状态进入同一节点，都会重复同一段确定路线。

从根一出发的完整路线中，每个节点都在空状态下首次进入，所以其子树的一趟就是这条总路线里的一个连续片段。模拟一次并记录片段起点，就保存了所有节点的一趟，无需分别模拟。

从任意 $v$ 出发则是“$v$ 的一趟、父亲的一趟、祖父的一趟……”依次拼接。整段代价的和已由 $T$ 给出，查询只需要找 $k$ 落在哪一段。倍增先跳过已经完整走完的阶段，再用片段起点加偏移查表。图中从三出发先走五步到一，之后路线就是从一出发那趟九步的开头。

### 思路

#### 每次查询的路线由祖先的一趟拼接

从全空子树 $v$ 出发，第一次到父亲时所有标记恢复全空，代价为 $c_v=2sz_v-1$。所以从 $v$ 到节点 $0$ 的全过程依次是 $v$ 的一趟、父亲的一趟、祖父的一趟，直到节点 $1$ 的一趟。预处理真实总时间
$$T_v=T_{\operatorname{par}(v)}+c_v,\qquad T_0=0.$$
这里必须保存真实值，不能沿用上一题取模后的答案，因为查询需要比较阶段边界。

直接把每个起点的完整路线存下会重复大量片段。关键是任一子树的一趟，都等于从节点 $1$ 开始完整遍历时的一段连续路线：第一次进入该子树时它全空，而之后的行为只取决于子树内标记。

#### 用一次短模拟保存所有子树片段

从 $1$ 到 $0$ 只需 $2n-1$ 步。代码按题意模拟，令 $pos[s]$ 表示走完 $s$ 步后的位置，包含 $pos[0]=1$。再记录每个子树片段的起始下标 $start_v$。

根的起点为零；左儿子在父亲开始后一步进入，所以 $start_l=start_v+1$。进入左儿子后，需要 $c_l$ 步完整走完左子树并回到父亲，再花一步去右儿子，因此
$$start_r=start_v+2+c_l.$$
这里 $c_l$ 已经包含从左儿子返回父亲的那一步，不应再多加一次。

#### 先定位阶段，再查询阶段内的位置

对于询问 $(v,k)$，若当前进行的是祖先 $u$ 的一趟，那么此前走完的阶段总长为 $T_v-T_u$。因此应有
$$T_v-T_u\le k<T_v-T_{\operatorname{par}(u)}.$$
改写左边可知，需要寻找满足 $T_u\ge T_v-k$ 的最高祖先。祖先方向上 $T$ 严格递减，满足条件的祖先构成连续一段，可以用二进制祖先表从大到小尝试向上跳；不能跳到节点 $0$。

确定 $u$ 后，阶段内已经走了 $\tau=k-(T_v-T_u)$ 步，答案直接查
$$pos[start_u+\tau].$$
最高祖先的选择保证 $0\le\tau<c_u$，查到的下标落在对应子树片段内。

例如根 $1$ 有叶子 $2,3$，从 $2$ 出发时 $T_2=6,T_1=5$。当 $k=0$ 时还在 $2$ 的阶段；当 $k=1$ 时恰好结束这一趟，应该切换到 $1$ 的阶段且局部时间为零，输出 $1$。代码中的非严格比较正是为了处理这个边界。

子树大小逆遍历计算，时间和片段起点正遍历计算；祖先表预处理为 $O(n\log n)$，每个查询为 $O(\log n)$，空间 $O(n\log n)$。总时间可能达到平方量级，所有时间量使用 $64$ 位整数。

### 参考代码

```cpp
// G. Idiot First Search and Queries
//
// 与 E 同一套背景，先把「全局走位表」钉死，再做询问。
//
// 1) 记 cost(v) = 2*size(v) - 1（size = 子树点数）：从 v 出发、子树全空时，
//    「走完整棵子树并从 v 跨到父亲」的步数。它的第一段是左子树的整趟、
//    第二段是右子树的整趟，第三段是走上父亲，故 cost(v) = cost(l)+cost(r)+3。
// 2) 从 v 出发的实际过程 = 依次做「子树 v 的一趟、子树 par(v) 的一趟、…、子树 1 的一趟」。
//    第 j 趟的起点时刻是 S_j = T(v) - T(u_j)，其中 u_0 = v, u_1 = par(v), …, T(u) = 到 0 的总步数。
//    问「走 k 步后在哪」=> 找**最高**的祖先 u 使 T(u) >= T(v) - k（同 T 的祖先里取最靠上那个），
//    再在该趟里按局部时刻 tau = k - (T(v) - T(u)) 查表。
// 3) 关键：任何一棵子树的「一趟」都**逐字等于**从顶点 1 出发那一趟里对应的一段
//    （因为进入子树时它一定是全空的，行为只取决于子树内部）。
//    所以只需模拟一次「从 1 出发」的 2n-1 步，得到 pos[0..2n-1]；
//    子树 u 那一趟的起点是 a(u)，于是答案 = pos[a(u) + tau]。
//    a(1) = 0，左儿子 a = a(p)+1，右儿子 a = a(p)+2+cost(左儿子)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);        // 只用 cin/cout，不碰 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                           // 测试组数
    while (t--) {
        int n, q;
        cin >> n >> q;                  // n 个点（除根 0 外）、q 个询问
        vector<int> lc(n + 1, 0), rc(n + 1, 0), par(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            cin >> lc[i] >> rc[i];
            if (lc[i]) {                // 有儿子就两个都有（题面保证）
                par[lc[i]] = i;
                par[rc[i]] = i;         // 顶点 1 的父亲保持 0
            }
        }

        // BFS 序：保证父亲排在儿子前面
        vector<int> ord;
        ord.reserve(n);
        ord.push_back(1);
        for (size_t h = 0; h < ord.size(); h++) {
            int v = ord[h];
            if (lc[v]) {
                ord.push_back(lc[v]);
                ord.push_back(rc[v]);
            }
        }

        // 逆序求子树大小，再正序求 cost 与 T
        vector<int> sz(n + 1, 0);
        vector<long long> cost(n + 1, 0), T(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int v = ord[i];
            sz[v] = 1 + sz[lc[v]] + sz[rc[v]];
        }
        for (int i = 0; i < n; i++) {
            int v = ord[i];
            cost[v] = 2LL * sz[v] - 1;              // 走完整棵子树并跨出 v
            T[v] = T[par[v]] + cost[v];             // T[0] = 0
        }

        // 窗口起点 a(v)：子树 v 那一趟在「从 1 出发」那一趟里的起始时刻
        vector<long long> astart(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int v = ord[i];
            if (lc[v]) {
                astart[lc[v]] = astart[v] + 1;                       // 第 1 步去左儿子
                astart[rc[v]] = astart[v] + 2 + cost[lc[v]];         // 左子树整趟后再去右儿子
            }
        }

        // 模拟从顶点 1 出发的 2n-1 步：pos[s] = 第 s 步之后所在的顶点
        vector<int> pos(2 * n + 1, 0);
        vector<unsigned char> mark(n + 1, 0);       // 0 空 / 1 'L' / 2 'R'
        int cur = 1;
        pos[0] = 1;
        for (int s = 1; s <= 2 * n - 1; s++) {
            if (lc[cur] == 0) {                     // 叶子：回父亲
                cur = par[cur];
            } else if (mark[cur] == 0) {            // 空：写 L，去左儿子
                mark[cur] = 1;
                cur = lc[cur];
            } else if (mark[cur] == 1) {            // L：改写 R，去右儿子
                mark[cur] = 2;
                cur = rc[cur];
            } else {                                // R：擦掉，回父亲
                mark[cur] = 0;
                cur = par[cur];
            }
            pos[s] = cur;                           // 最后一步落在 0 上
        }

        // 二进制跳表：up[k][v] = v 的第 2^k 个祖先（0 表示不存在）
        const int LOG = 20;                         // 2^19 = 524288 > 300001
        vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
        for (int v = 1; v <= n; v++) up[0][v] = par[v];
        for (int k = 1; k < LOG; k++)
            for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];

        string out;
        out.reserve((size_t)q * 8);
        bool first = true;                          // 一组测例的 q 个答案打在同一行
        while (q--) {
            int v;
            long long k;
            cin >> v >> k;                          // 保证 k < min(1e9+7, T(v))
            long long X = T[v] - k;                 // 本趟的祖先 u 满足 T(u) >= X
            int u = v;                              // 往上跳到「T 仍 >= X」的最高祖先
            for (int j = LOG - 1; j >= 0; j--) {
                int anc = up[j][u];
                if (anc != 0 && T[anc] >= X) u = anc;
            }
            long long tau = k - (T[v] - T[u]);      // 在本趟里的局部时刻
            if (!first) out += ' ';
            first = false;
            out += to_string(pos[astart[u] + tau]);
        }
        out += '\n';
        cout << out;
    }
    return 0;
}
```

### 易错点

跳祖先的时间使用 64 位真实值，不是 E 题输出的模数值。$k=0$ 应返回起点；恰好结束一趟时已经站在父亲。

## H. Codeforces Heuristic Contest 001

### 题意

在 $3n\times3n$ 整点点阵上，放尽量多面积恰为 $1/2$ 的三角形，任意两个三角形不能有任何公共点。输出最大数量及一种构造。

### 从零讲：面积恰好 1/2 的整点三角形长什么样

整点三角形的两倍面积是一个整数：以一点 $A$ 为基准，另外两条边向量为 $(u_x,u_y)$、$(v_x,v_y)$，有
$$2S=|u_xv_y-u_yv_x|.$$
所以面积为 $1/2$ 等价于这个行列式绝对值为一。单位方格取三个角显然满足，但这只是方便构造的一类，并非所有解：例如 $(0,0),(2,1),(1,1)$ 的行列式也为一，却不在一个单位方格内。

本题不需要枚举全部可能形状，只需找到能达到点数上界的一种铺法。一个三列两行的砖块有六个点，图中两个朝相反方向的单位三角形各用三个点，中间留下空隙，从而把局部构造复制到大点阵。

奇数边长无法直接被两行砖铺满，因此单独准备一个九乘九的完整基块，再用宽度为六的条带扩展。基块每个三角形都可以用行列式检查面积；共享点与相交也能独立检查。图和参考代码使用完全同一份基块坐标，便于逐个核对。

### 思路

#### 点数先给出一个明确上界

点阵共有 $9n^2$ 个可用顶点。三角形不能接触，所以两个三角形连顶点也不能共用，每个三角形至少独占三个点，数量至多为 $3n^2$。我们接下来构造恰好用完所有点的方案；只要同时保证面积和不相交，就达到了最优。

#### 偶数情况用六点砖块铺满

取三列两行的点，左下坐标为 $(x,y)$。放入三角形
$$\{(x,y),(x,y+1),(x+1,y)\}$$
和
$$\{(x+1,y+1),(x+2,y),(x+2,y+1)\}.$$
二者都是单位直角三角形，面积为 $1/2$。第一个完全在直线 $X=x+1$ 左侧，只在该直线的下端点接触它；第二个完全在右侧，只在上端点接触它，因此两个三角形没有公共点。六个顶点则恰好全部使用。

当 $n$ 为偶数时，$3n$ 同时能按列分成宽三的组、按行分成高二的组。把每组六点放上述两个三角形即可。相邻砖块的坐标范围之间至少隔着一个单位距离，例如一块最大横坐标为 $x+2$，下一块最小横坐标为 $x+3$，所以跨砖块也不会接触。代码的两层循环正是在枚举这些砖块。

#### 奇数情况由一个有限基块扩展

当 $n\ge3$ 为奇数时，令 $N=3n$，则 $N-9$ 是六的倍数。代码中的 $27$ 行固定坐标给出左下 $9\times9$ 点阵的一份完整铺法，图中画的也是这份表。固定基块承担的任务仅是处理奇数宽度，后面的扩展不需要重新搜索。

基块的合法性可按坐标直接核验：每行三点的行列式绝对值为 $1$；所有 $81$ 个顶点各出现一次；各三角形连边界都不相交。对于这样的有限构造，表本身就是存在性证明的一部分，不需要声称任意选取单位三角形都能铺满。

剩余区域分成两块：右侧的坐标为 $10\le x\le N,1\le y\le9$，用旋转后的两列三行砖块铺满；上方的坐标为 $1\le x\le N,10\le y\le N$，用三列两行砖块铺满。前者宽为偶数、高为三的倍数，后者宽为三的倍数、高为偶数，因此都能整除。三块区域在坐标上分开，不会产生跨区域接触，全部点仍恰好被使用一次。

#### 最小点阵为什么例外

$n=1$ 时上界是三个，但若真能放三个就必须用完九个点，包括四个角点。三个三角形覆盖四个角点，至少一个三角形包含两个角点。这两个角点的坐标差都是偶数，拿它们作为一条边计算两倍面积，得到的行列式必为偶数，不可能等于 $1$，矛盾。因此至多两个；代码给出的两个分离的单位三角形恰好实现。

最终答案为 $n=1$ 时的 $2$，其他情况的 $3n^2$。构造和保存输出均为 $O(n^2)$，与必须输出的三角形数同阶。面积为 $1/2$ 的整点三角形未必都是单位方格的三个角；我们只需使用这一类方便的形状达到上界即可。

### 参考代码

```cpp
// H. Codeforces Heuristic Contest 001
//
// 本构造选用单位格子的 3 个角，行列式绝对值为 1，面积恰为 1/2。
// 一般的面积 1/2 整点三角形不一定属于这种形状；这里不需要枚举所有形状。
// 只需在 3n x 3n 点阵上用这类三角形达到点数上界（n=1 单独处理）。
//
// 上界：3n^2（点数 9n^2 除以 3，每个三角形吃 3 个不同的点）。
//   · n 为偶数：下面的「砖块」铺法正好盖满全部点 => 答案 3n^2。
//   · n 为奇数且 n >= 3：9x9 基块 + 6 宽的条带也正好盖满 => 答案 3n^2。
//   · n = 1：3x3 只有 9 个点，官方样例给出的最大值就是 2（放满 3 个要求
//     9 点全用上，本地对 3x3 上全部面积 1/2 的三角形做穷举，确认做不到）=> 答案 2。
//
// 砖块（都盖满 6 个点、互不相交）：
//   横砖 blockH(x,y)：3 列 x..x+2、2 行 y..y+1
//   竖砖 blockV(x,y)：2 列 x..x+1、3 行 y..y+2
// n 偶数：整张图 = (3n/2) 条「两行带」x n 个「三列带」的横砖。
// n 奇数：左下 9x9 用基块表，右边 6k 宽 x 9 高的条带用竖砖，
//         上面 6k 高 x 3n 宽的条带用横砖（3n = 9 + 6k）。
#include <bits/stdc++.h>
using namespace std;

// 9x9 完美覆盖基块：27 个三角形（坐标 1-indexed，(x1,y1,x2,y2,x3,y3)）。
// 来源：本地 MRV 精确覆盖搜索求出（_work/h_search.py，独立校验脚本确认
// 两两不相交且铺满 81 个点）。
static const int BASE[27][6] = {
    {1, 1, 1, 2, 2, 2}, {2, 1, 3, 1, 3, 2}, {4, 1, 4, 2, 5, 2},
    {5, 1, 6, 1, 6, 2}, {7, 1, 7, 2, 8, 2}, {8, 1, 9, 1, 9, 2},
    {1, 3, 1, 4, 2, 4}, {2, 3, 3, 3, 3, 4}, {4, 3, 4, 4, 5, 4},
    {5, 3, 6, 3, 6, 4}, {7, 3, 7, 4, 8, 4}, {8, 3, 9, 3, 9, 4},
    {1, 5, 1, 6, 2, 6}, {2, 5, 3, 5, 3, 6}, {4, 5, 5, 5, 5, 6},
    {6, 5, 7, 5, 7, 6}, {8, 5, 9, 5, 9, 6}, {3, 7, 4, 6, 4, 7},
    {5, 7, 6, 6, 6, 7}, {8, 6, 8, 7, 9, 7}, {1, 7, 2, 7, 2, 8},
    {7, 7, 7, 8, 8, 8}, {1, 8, 1, 9, 2, 9}, {3, 8, 3, 9, 4, 9},
    {4, 8, 5, 8, 5, 9}, {6, 8, 6, 9, 7, 9}, {8, 9, 9, 8, 9, 9},
};

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不碰 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                      // 测试组数
    while (t--) {
        int n;
        cin >> n;                  // 边长 = 3n
        const int N = 3 * n;       // 点阵坐标范围 1..N

        vector<array<int, 6>> tris;   // 收集全部三角形

        if (n == 1) {
            // 3x3：最大 2（9 个点凑不出 3 个互不相交的三角形）
            tris.push_back({1, 1, 1, 2, 2, 1});
            tris.push_back({2, 3, 3, 2, 3, 3});
        } else if (n % 2 == 0) {
            // 偶数 n：横砖铺满（每块 3 列 x 2 行）
            for (int y = 1; y + 1 <= N; y += 2) {          // 两行一组
                for (int x = 1; x + 2 <= N; x += 3) {      // 三列一组
                    tris.push_back({x, y, x, y + 1, x + 1, y});            // 少右上角
                    tris.push_back({x + 1, y + 1, x + 2, y, x + 2, y + 1}); // 少左下角
                }
            }
        } else {
            // 奇数 n >= 3：9x9 基块 + 两条 6 宽条带
            for (int i = 0; i < 27; i++) {                 // 左下角 9x9 基块
                tris.push_back({BASE[i][0], BASE[i][1], BASE[i][2],
                                BASE[i][3], BASE[i][4], BASE[i][5]});
            }
            for (int x = 10; x + 1 <= N; x += 2) {         // 右侧条带：宽 N-9，高 9
                for (int y = 1; y + 2 <= 9; y += 3) {      // 竖砖 2 列 x 3 行
                    tris.push_back({x, y, x, y + 1, x + 1, y});
                    tris.push_back({x + 1, y + 1, x + 1, y + 2, x, y + 2});
                }
            }
            for (int y = 10; y + 1 <= N; y += 2) {         // 上方条带：高 N-9，宽 N
                for (int x = 1; x + 2 <= N; x += 3) {      // 横砖 3 列 x 2 行
                    tris.push_back({x, y, x, y + 1, x + 1, y});
                    tris.push_back({x + 1, y + 1, x + 2, y, x + 2, y + 1});
                }
            }
        }

        // 输出：第一行是最大值 m，随后 m 行每行一个三角形的 6 个坐标
        string out;
        out.reserve(tris.size() * 32 + 16);
        out += to_string(tris.size());
        out += '\n';
        for (const auto &a : tris) {
            for (int i = 0; i < 6; i++) {
                out += to_string(a[i]);
                out += (i == 5 ? '\n' : ' ');
            }
        }
        cout << out;
    }
    return 0;
}
```

### 易错点

面积小不等于一定落在一个单位方格里；这里主动选用单位直角三角形来构造。不同三角形连边界接触也不允许。

## A. Eating Game

### 题意

玩家围成一圈，每次轮到有菜的人就吃一盘，空手者跳过。吃掉最后一盘者获胜，可以任选先手，求可能获胜的玩家数量。

### 思路

固定先手后，每个人被访问的顺序都已确定。把从先手开始绕桌一周称为一轮，并让轮数 $k$ 从零开始：第 $k$ 轮轮到玩家 $i$ 时，他此前已经获得了 $k$ 次吃菜机会，因此这次还有菜恰当且仅当 $a_i>k$。

代码依次枚举全部 $n$ 个先手。对于先手 $s$，本轮访问次序为 $(s+step)\bmod n$；每遇到 $a_i>k$ 就让已吃盘数增加一。已吃数量第一次等于总盘数时，当前玩家就是这次模拟的赢家。用布尔数组标记他，最后数出不同赢家数量。同一个人可能对应多个先手，不能按模拟次数累加答案。

例如菜数为 $[2,1,2]$，最后一轮只剩第一个和第三个玩家吃菜，谁在这两人中后被访问，谁获胜。换先手可以让这两人分别成为赢家，而只有一盘的玩家不可能获胜。

这个例子也解释了模拟背后的结论：最后有菜的必然是初始菜数最大的玩家；从某个最大值玩家的下一位开始，就能让他在最后一轮最后行动。因此答案等于最大值的出现次数，枚举模拟会得到完全相同的集合。参考代码采用直接模拟，因数据很小，时间 $O(n^2\max a_i)$、空间 $O(n)$ 已足够。

### 参考代码

```cpp
// A. Eating Game
// 题意：n 个玩家围成一圈，第 i 个玩家有 a[i] 盘菜；可以任选一名玩家先手，
//       之后回合按环上顺序一直传给下一位；轮到自己时「有菜就必须吃恰好一盘」，
//       没有菜的人这一轮直接跳过。吃完最后一盘菜的人获胜。
//       问：有多少个玩家可能成为赢家（把 n 种先手都试一遍）。
//
// 做法：对每个先手 s，按「轮」来算——第 k 轮（k 从 0 开始）里，
//       只有 a[i] > k 的玩家还有菜可吃，他们按从 s 开始的环形顺序各吃一盘。
//       吃到第 S 盘（S = 所有菜之和）的那位玩家就是赢家。
//       把 n 个先手各自算出的赢家并起来，数个数即可。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        int total = 0;                      // 菜的总盘数 S
        for (int i = 0; i < n; i++) {
            cin >> a[i];
            total += a[i];
        }

        vector<bool> canWin(n, false);       // canWin[i]：玩家 i 能不能成为赢家
        for (int s = 0; s < n; s++) {        // 枚举先手玩家 s
            int eaten = 0;                   // 已经被吃掉的盘数
            int winner = -1;                 // 赢家
            // k = 第几轮（0 起）；最多 a[i] 轮就全吃完了，一定会退出
            for (int k = 0; winner < 0; k++) {
                for (int step = 0; step < n; step++) {   // 按环上顺序走一圈
                    int i = (s + step) % n;              // 这一轮轮到的玩家
                    if (a[i] > k) {              // 他第 k 轮还有菜，就吃一盘
                        eaten++;
                        if (eaten == total) {    // 正好吃到最后一盘 → 他赢
                            winner = i;
                            break;
                        }
                    }
                }
            }
            canWin[winner] = true;            // 记录「s 先手时赢家是谁」
        }

        int ans = 0;                          // 统计不同的赢家个数
        for (int i = 0; i < n; i++)
            if (canWin[i]) ans++;
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

统计不同赢家，不能把同一个人因多个先手位置获胜重复计数。

## B. Deletion Sort

### 题意

每回合先检查数组是否非递减，若是则立刻结束；否则可删除任意一个元素。求结束时最少剩下几个元素。

### 思路

题目的检查发生在删除之前。一旦数组非递减，便没有下一次删除机会。因此先判断原数组：若每对相邻元素都满足 $a_i\le a_{i+1}$，第一回合就结束，必须留下全部 $n$ 个元素。

若原数组不满足非递减，取一对逆序元素 $a_i>a_j$，其中 $i<j$。暂时固定保留这两个元素，依次删除其他所有元素。删除不会改变剩余元素之间的相对顺序，所以只要这对元素都还在，数组中就仍存在逆序，游戏不会提前结束。

最终只剩这两个逆序元素，此时仍允许操作。再删去其中任意一个，长度变成一，数组必然有序，游戏结束。我们于是构造出了只剩一个元素的方案；零个不可能，因为长度为一时已经停止，所以最优答案恰为 $1$。

例如 $[2,1,3]$ 可以保留前两项、先删 $3$，得到 $[2,1]$，再删一项。反而若先删 $2$，剩下 $[1,3]$ 就会过早结束。证明中的保留逆序对正是避免这种错误顺序。

实现无需真的找出或执行删除方案，只扫描相邻元素判断是否有严格下降。相等元素符合非递减要求。时间 $O(n)$，参考代码保存输入，空间 $O(n)$。

### 参考代码

```cpp
// B. Deletion Sort
// 题意：每回合先检查数组：若已「非递减」游戏立刻结束；否则可以删掉任意一个元素。
//       问最终最少能剩几个元素（删哪些、按什么顺序删都由你决定）。
//
// 结论：数组本来非递减 → 第一回合就结束，答案是 n；
//       否则答案恒为 1。
// 为什么是 1：数组非递减 ⟺ 数组里不存在逆序对 (i<j 且 a[i]>a[j])。
//       先取定一对逆序对 (i,j)。只要这两个元素还在数组里，就仍能找到这对逆序对，
//       数组就不是非递减、游戏不会结束 —— 所以可以放心地一个个删掉其它元素；
//       等只剩 i、j 两个（此时 a[i]>a[j]，仍不是非递减，游戏继续），
//       再删掉其中一个，数组长度变成 1，长度为 1 一定非递减，游戏结束。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        bool sorted = true;                  // 数组是否已经非递减
        for (int i = 0; i + 1 < n; i++)
            if (a[i] > a[i + 1]) sorted = false;   // 出现相邻逆序即「不是非递减」

        cout << (sorted ? n : 1) << "\n";     // 已排好就一个都删不掉；否则能删到只剩 1 个
    }
    return 0;
}
```

### 易错点

不能在已经有序后继续删除，因此已排序数组的答案不是一。

## C. Specialty String

### 题意

每次选两个相同的未删除字符，要求它们之间的字符都已经被删掉，再将这两个字符删除。判断能否删空原串。

### 思路

#### 把星号从视野中去掉

两个待删字符之间全是星号，等价于它们在“尚未删除的字符序列”中相邻。因此原操作就是反复删除相邻的两个相同字符，原下标是否相邻并不重要。

从左往右扫描，用栈保存已读前缀消去后剩下的字符。新字符若等于栈顶，这两个字符在当前剩余序列中相邻，可以一起消去，于是弹出栈顶；否则把新字符压栈。例如 $\texttt{abba}$ 的栈依次为 $\texttt{a},\texttt{ab},\texttt{a}$、空，第二个 $\texttt{b}$ 触发一次消去，最后两个 $\texttt{a}$ 再消去。

#### 立即删除为何不会错失另一种方案

需要排除“现在删了这一对，之后反而删不空”的顾虑。考虑两个当前可删的对：若它们互不重叠，先删哪一对都不影响另一对，两个删除顺序可交换；若重叠，局部只能是三个相同字符，删左边一对或右边一对都留下同一个字符。因此从同一串出发的不同第一步总能重新汇合。每步都会缩短串，反复使用这个性质可知，所有删除顺序最终得到的不可再删字符串相同。

栈算法选择的也是合法删除顺序，并且栈内始终没有相邻相同字符，故扫描完就是这个唯一的最终剩余串。它为空时显然有成功方案；它不为空时，换一种删除顺序也无法删空。

只统计每种字符出现偶数次并不够，例如 $\texttt{abab}$ 中每种字符都出现两次，却连第一步也无法执行。栈保留了必要的顺序信息。每个字符至多入栈、出栈一次，时间 $O(n)$，最坏空间 $O(n)$。

### 参考代码

```cpp
// C. Specialty String
// 题意：每次可以选两个位置 i<j，要求 s[i] == s[j] 且 i、j 之间（不含端点）全是 '*'，
//       然后把这两个位置也变成 '*'。问能否把整个串都变成 '*'。
//
// 结论：能赢 ⟺「不断删掉相邻的两个相同字符」能把串删空。
//   · 必要性：变 '*' 的位置就是被删掉的位置；「i、j 之间全是 '*'」正好说明
//     这两个位置在当时剩下的字符里是相邻的。
//   · 充分性：按下面的栈规则删（栈顶与当前字符相同就弹、否则压），
//     得到的删除顺序每一步都满足题面条件。
//   于是做法就是栈模拟：扫一遍串，栈顶与当前字符相同就弹出，否则压入；
//   扫完栈空输出 YES，否则 NO。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        string st;                          // 当栈用：栈里是「消不掉的字符」
        for (char c : s) {
            if (!st.empty() && st.back() == c)  // 栈顶与当前字符相同 → 相邻且相同，删掉这一对
                st.pop_back();
            else
                st.push_back(c);            // 否则只能先留着
        }

        cout << (st.empty() ? "YES" : "NO") << "\n";   // 栈空 = 能全删光
    }
    return 0;
}
```

### 易错点

操作要求当前剩余序列相邻，原下标不必相邻。只有各字符数量为偶数并不充分，例如 $\texttt{abab}$ 无法开始删除。

## D. Portal

### 题意

排列的两个间隙处放有传送门。可把一个门左侧紧邻元素搬到另一门右侧，或把右侧紧邻元素搬到另一门左侧。求能得到的字典序最小排列。

### 从零讲：循环移位与「分界点」

把四种方向的搬运分别代入三段结构：中间段首元素搬到末尾，或末元素搬到开头，只是在旋转 $M$；左外段末元素搬到右外段开头，或反过来，只是在固定序列 $W=L+R$ 上移动切口。

![传送门保留的两种顺序](assets/d-portals.svg)

例如 $L=[1],M=[3,5],R=[2,4]$，外部序列始终为 $[1,2,4]$，只允许把中间块插到不同切口，不能把外部的 $4$ 移到 $2$ 前面。门内操作也不改变门外序列，门外操作不改变门内旋转，所以两种选择独立。

所有可达答案恰为“$W$ 的前缀、$M$ 的某次旋转、$W$ 的后缀”。这一步把复杂搬运变成两个明确参数，正文再分别决定最优旋转和最优切口。

### 思路

#### 操作保留了哪两份顺序

把排列按两个门切成左段 $L$、中段 $M$、右段 $R$。作用在中段边界的操作，是把中段第一个元素搬到末尾，或把末尾搬到开头，所以 $M$ 只能循环旋转，其元素集合和环形顺序都不变。

作用在外侧的操作，则是把 $L$ 的最后一个元素搬到 $R$ 的最前面，或反过来。因此拼接序列 $W=L+R$ 完全不变，变化的只是从哪里把 $W$ 切成左右两部分。通过反复操作，切口可以移动到 $0$ 至 $|W|$ 的任何位置。

两类操作互不影响，所以所有可达答案恰好是“$W$ 的某个前缀，加上 $M$ 的某次旋转，再加上 $W$ 剩下的后缀”。这同时说明中段不能任意排序，外段也不能把不同元素任意交换。

#### 先选旋转，再决定插入点

固定切口后，各种旋转在中段首位就会产生比较。排列元素互异，首位最小的旋转一定最优，也就是从 $M$ 中最小元素 $h$ 开始，随后沿原来的环形次序输出。

接着从 $W$ 开头扫描。如果当前元素小于 $h$，先输出它会比现在插入中段更优，因此继续把切口右移。一旦遇到第一个大于 $h$ 的元素，就立即插入整个中段。任何更靠后的切口都会在这一位先输出较大的外段元素，因此不可能更好；任何更靠前的切口则会把 $h$ 放在某个更小外段元素之前，也不会更好。若所有元素都小于 $h$，中段应放在末尾。

例如 $W=[1,4,2]$，最优中段旋转为 $[3,5]$。扫描先保留 $1$，遇到 $4>3$ 便插入，得到 $[1,3,5,4,2]$；不能跳过 $4$，只为了把后面的 $2$ 也放在中段之前。

代码的零基切分为中段 $[x,y)$，两段外部按原顺序拼接；由于 $x<y$，中段一定非空。找最小值、找切口和拼接都只扫描一遍，时间、空间均为 $O(n)$。

### 参考代码

```cpp
// D. Portal
// 题意：给一个排列 p，两个传送门把数组切成三段：
//       L = 左门左边的元素、M = 两个门之间的元素、R = 右门右边的元素。
//       两种操作（可任意次）：
//         ① 把某个门左边紧挨着的元素，挪到另一个门右边紧挨着的位置；
//         ② 把某个门右边紧挨着的元素，挪到另一个门左边紧挨着的位置。
//       求能得到的字典序最小的排列（传送门本身不参与比较）。
//
// 结论（把三段看成三个序列）：
//   · 作用在 M 上的两种操作只是「循环移位」：末位挪到首位 / 首位挪到末位，
//     所以 M 能变成自己的任意循环移位，M 里的元素也永远留在 M 里（大小不变）。
//   · 作用在 L 与 R 之间的两种操作，在拼接串 W = L + R 上等价于
//     「把 L 与 R 的分界点左右挪一格」——W 本身一个字都不变，
//     分界点 k（左侧留 W 的前 k 个）却能停在 0..|W| 的任意位置。
//   于是答案 = min over 0<=k<=|W| of ( W 前 k 个 + M 的最优循环移位 + W 的剩余部分 )。
//   又因为排列元素互不相同：M 的最优循环移位就是以 M 的最小值为开头的那个；
//   而比较「分界点 k」与「分界点 k+1」时前缀完全相同，
//   第 k 个位置上前者是 M 的首元素、后者是 W[k]，谁小谁赢 ——
//   所以只要 W[k] 比 M 的首元素小，就把分界点往右挪；遇到第一个更大的 W[k] 就停。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 只用 cin/cout，不与 stdio 混用
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, x, y;
        cin >> n >> x >> y;
        vector<int> p(n);
        for (int i = 0; i < n; i++) cin >> p[i];

        vector<int> M(p.begin() + x, p.begin() + y);   // 两门之间（x<y 保证它非空）
        vector<int> W;                                 // L + R
        for (int i = 0; i < x; i++) W.push_back(p[i]); // 左门左边
        for (int i = y; i < n; i++) W.push_back(p[i]); // 右门右边

        // M 的最小值所在位置：以它开头的循环移位就是 M 的最优排列
        int mp = 0;
        for (int i = 1; i < (int)M.size(); i++)
            if (M[i] < M[mp]) mp = i;
        int head = M[mp];                              // 该循环移位的首元素

        int k = 0;                                     // 分界点：W 的前 k 个留在左侧
        while (k < (int)W.size() && W[k] < head) k++;  // 比 head 小的都该排在 head 前面

        vector<int> ans;                               // 拼出答案
        ans.reserve(n);
        for (int i = 0; i < k; i++) ans.push_back(W[i]);                     // 左侧段
        for (int i = 0; i < (int)M.size(); i++)                             // 最优循环移位
            ans.push_back(M[(mp + i) % (int)M.size()]);
        for (int i = k; i < (int)W.size(); i++) ans.push_back(W[i]);         // 右侧段

        for (int i = 0; i < n; i++)
            cout << ans[i] << " \n"[i + 1 == n];
    }
    return 0;
}
```

### 易错点

门的位置是元素之间的间隙，可在最前或最后；切分时按半开区间处理更清楚。

## E. Divisive Battle

### 题意

若数组已非递减，游戏立即结束，Bob 胜。否则轮到的人可以把合数拆成两个大于一的真因子，顺序任选。无法再拆时也结束，若仍非递减则 Bob 胜，否则 Alice 胜。Alice 先手，求胜者。

### 从零讲：把「拆数」看成把质因子分成两堆

乘积拆分相当于把质因子分给左右两块。例如 $12=2\cdot2\cdot3$，可以拆成 $6,2$，也可以拆成 $3,4$；但块不会跨过其他原位置，之后拆出的后代仍留在这块原来的位置范围内。

![用小质数固定永久逆序](assets/e-lock.svg)

选最小质因子 $p$ 放到右边，左块若含更大质因子 $q$，任何后续分解至少有一个左侧数含 $q$，因而大于 $p$。右侧的 $p$ 是质数，无法再拆；这就从一次拆分得到“永远无法有序”的保证，不必预知对手拆法。

若原数只是 $p^e$，它的后代只能是 $p$ 的幂，完全拆开一定是 $e$ 个 $p$，顺序选择不再产生不同终局。于是全为质数幂时，问题转成原位置对应底数的顺序；正文还给出底数下降时如何立即制造永久逆序，补上中途可能提前结束的考虑。

### 思路

#### 胜负不取决于最后是谁操作

只要数组变为非递减，游戏立即结束且 Bob 获胜；如果最终无法拆分但仍存在逆序，Alice 获胜。所以关键是能否保证一对逆序永久存在，而不是研究操作次数的奇偶性。原数组已经非递减时，Alice 根本没有首步，直接输出 Bob。

每个原元素拆出的后代始终占据连续的一块，不会跨过其他原元素。拆分只是在这块内把质因子分配到更小的因子中。下面以此分类。

#### 有混合质因子时，首步就能锁住逆序

设某个数 $x$ 含至少两个不同质因子，最小质因子为 $p$，另有较大的质因子 $q$。Alice 把它拆为 $x/p,p$，小质数 $p$ 放在右边。左块中仍含有质因子 $q$，以后无论如何继续拆，总有一个后代含 $q$，它至少为 $q>p$。右边的 $p$ 是质数，无法再拆。

于是左侧总有一个数大于右侧固定的 $p$，逆序永远消失不了。游戏的拆分次数有限，最后必在无可拆元素时以 Alice 获胜结束。例如把 $12$ 拆成 $6,2$，即使对手把 $6$ 拆成 $2,3$，左块里的 $3$ 仍大于最右侧的 $2$。

#### 全是一或质数幂时，看底数序列

若原元素为 $p^e$，其所有后代只能是同一质数 $p$ 的幂，彻底拆完就得到 $e$ 个 $p$。把每个原元素换成这个底数，一的底数记为一。

若底数序列非递减，完全拆分后的序列必然非递减。如果中途已经有序，Bob 提前获胜；如果一直没有提前停止，最终也会到达这个有序终局，所以 Alice 无法阻止 Bob 获胜。

若相邻底数出现 $p>q$，左块任何后代都至少为 $p$。右块若本来就是质数 $q$ 或一，已有永久逆序；否则右块是 $q^b$ 且 $b\ge2$，Alice 首步把它拆成 $q,q^{b-1}$，把不可再拆的 $q$ 放在该块最前面，同样锁住逆序。这里不要求左右两个原数自身形成下降，真正控制永久逆序的是质因数底数。

代码用最小质因子筛找到每个数的最小质因子，并除去它的全部幂；若还剩大于一的数，就是混合质因子，否则记录该底数。筛的时间 $O(V\log\log V)$，逐组分解为 $O(n\log V)$；参考实现一次读入全部测试，空间为 $O(V+\sum n)$。判断初始有序必须放在分解结论之前。

### 参考代码

```cpp
// E. Divisive Battle
// 题意：Alice 先手。每回合若数组已经非降则游戏立刻结束；否则当前玩家把一个元素 x 换成 y,z（1<y,z<x，x=yz，
//       顺序任选）。没有可换的元素时游戏也结束。结束时数组非降 → Bob 胜，否则 Alice 胜。
//
// 结论（三类判据，已用记忆化极小极大穷举 576+1000+2744+2401 例核对，无一反例）：
//   1) 初始数组已非降 → Bob 胜（Alice 一步都没走就结束）。
//   2) 否则若存在某个 a_i 有 ≥2 个不同质因子 → Alice 胜
//      （她总能借这个元素造出「相邻的两个质数、且左边大」的永久逆序：一旦出现，数组再也不可能是非降的）。
//   3) 否则每个 a_i 都是 1 或质数幂：此时每个块的最终排列被完全确定（底数相同的质数），
//      最终数组 = 各块依次拼接，故 Bob 胜 ⇔ 底数序列（1 的底数记 1）非降。
#include <bits/stdc++.h>
using namespace std;

const int MAXA = 1000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    // 先把所有用例读进来，按实际最大值开筛子（题目保证 a_i ≤ 1e6；这样输入越界也不会越界读）
    vector<vector<int> > tests(T);
    int maxA = 1;
    for (int ti = 0; ti < T; ++ti) {
        int n;
        cin >> n;
        tests[ti].resize(n);
        for (int i = 0; i < n; ++i) {
            cin >> tests[ti][i];
            if (tests[ti][i] > maxA) maxA = tests[ti][i];
        }
    }
    // 埃氏筛最小质因子（按实际最大值开，题目保证 a_i ≤ 1e6）
    int lim = min(maxA, MAXA);
    vector<int> spf(lim + 1, 0);
    for (int i = 2; i <= lim; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if ((long long)i * i <= lim) {
                for (long long j = (long long)i * i; j <= lim; j += i) {
                    if (spf[j] == 0) spf[j] = (int)i;
                }
            }
        }
    }
    for (int ti = 0; ti < T; ++ti) {
        int n = (int)tests[ti].size();
        const vector<int>& a = tests[ti];

        bool nonDec = true;                       // 判据 1
        for (int i = 0; i + 1 < n; ++i) {
            if (a[i] > a[i + 1]) { nonDec = false; break; }
        }
        if (nonDec) {
            cout << "Bob\n";
            continue;
        }

        bool mixed = false;                       // 判据 2：是否有元素含 ≥2 个不同质因子
        vector<int> base(n, 1);                   // 判据 3：质数幂的底数（1 记 1）
        for (int i = 0; i < n && !mixed; ++i) {
            int v = a[i];
            if (v == 1) { base[i] = 1; continue; }
            int p = (v <= lim) ? spf[v] : 0;
            if (p == 0) {                         // 超出筛子范围（题目保证不会发生）：试除兜底
                p = v;
                for (int d = 2; (long long)d * d <= v; ++d) {
                    if (v % d == 0) { p = d; break; }
                }
            }
            base[i] = p;
            while (v % p == 0) v /= p;            // 剥掉最小质因子的全部幂
            if (v > 1) mixed = true;              // 还剩别的质因子
        }
        if (mixed) {
            cout << "Alice\n";
            continue;
        }

        bool ok = true;                           // 判据 3：底数序列非降？
        for (int i = 0; i + 1 < n; ++i) {
            if (base[i] > base[i + 1]) { ok = false; break; }
        }
        cout << (ok ? "Bob" : "Alice") << '\n';
    }
    return 0;
}
```

### 易错点

必须先判初始有序，不能让 Alice 在已经结束的游戏中拆数。只需要存在一对逆序，两个元素不一定相邻。

## F. Mooclear Reactor 2

### 题意

已有粒子 $(x_i,y_i)$，选中它可得能量 $x_i$，但同时选中的其他粒子不能超过 $y_i$ 个。商店中每个候选粒子都独立询问：恰好买它后，允许不用它，最大能量是多少。

### 从零讲：阈值前缀与「前 $s$ 大之和」

固定要选的数量 $s$ 后，只剩两个步骤：筛出反应性达到门槛的粒子，再选能量最大的 $s$ 个。

把粒子按反应性从大到小排序，同时让 $s$ 从大到小扫描。门槛下降，合格集合只会增加；把新合格粒子的能量加入小根堆，堆大小超过 $s$ 就弹掉最小值，并维护堆内和。堆里始终保留目前最大的至多 $s$ 个，大小达到 $s$ 才能记录这一档。

为什么扔掉的值后面不用找回来？未来目标数量只会更少，而当时已经有 $s$ 个不小于它的合格值，这些值以后仍合格；它永远不可能重新进入未来更小数量的最大值集合。

例如旧粒子为 $(67,0),(6,1),(7,1)$，单独用旧粒子最优是 $67$。新粒子 $(62,1)$ 最多再带一个旧粒子，且旧粒子反应性至少一，于是带能量七，得到 $69$。不能把反应性为零的 $67$ 与它一起选。

### 思路

#### 使用新粒子会让旧粒子的门槛增加一

固定商店粒子为 $(x,y)$。若选它，并同时选 $s$ 个旧粒子，总数量为 $s+1$。每个旧粒子看见的其他粒子有 $s$ 个，因此必须满足 $y_i\ge s$；商店粒子自身也要求 $y\ge s$。

令 $T_s$ 为从满足 $y_i\ge s$ 的旧粒子中选恰好 $s$ 个时，最大的能量和。候选不足 $s$ 个则不可行，$T_0=0$。使用商店粒子的最优答案为
$$x+\max_{0\le s\le\min(y,n)}T_s.$$
这张表只依赖旧粒子，因此可以预处理，再做前缀最大值，每个商店候选只需一次查表。

但买下后可以不用，所以还要计算旧粒子单独使用时的最优值 $B$。单独选 $s$ 个时，每个粒子只有 $s-1$ 个同伴，门槛为 $y_i\ge s-1$。最终取 $B$ 和上述使用新粒子收益的最大值，两个门槛不能混淆。

#### 倒着扫描数量，用小根堆选最大能量

将旧粒子按反应性降序排列，让 $s$ 从 $n$ 扫到零。门槛 $s$ 逐渐下降，合格粒子只会增加，把新合格的能量加入小根堆。如果堆大小超过 $s$，不断弹出最小值，同时维护堆内能量和。这样堆保存当前合格集合中最大的至多 $s$ 个能量，大小等于 $s$ 才记录 $T_s$。

被弹出的元素为何不用在后面找回来？它被淘汰时已有足够多的不小于它的合格元素；未来门槛更低，这些元素仍然合格，而需要的数量只会减少，所以它不可能重新成为必选的最大值之一。新加入的更大值只会进一步挤走较小值。

求 $B$ 时重复同一过程，只把阈值记为 $t=s-1$，保留堆中最大的 $t+1$ 个即可。每趟每个粒子入堆、出堆至多一次。

例如旧粒子为 $(67,0),(6,1),(7,1)$，单独最优是能量 $67$。若买 $(62,1)$，最多搭配一个旧粒子；反应性为零的 $67$ 不能与别人共存，应选能量 $7$ 的旧粒子，得到 $69$。若新粒子很弱，则可以仍只使用旧的 $67$。

不可行的 $T_s$ 用负无穷标记，不能错当成零；能量总和使用 $64$ 位整数。总时间 $O(n\log n+m)$，额外空间 $O(n)$，各商店粒子是独立询问，不会真的加入旧粒子集合。

### 参考代码

```cpp
// F. Mooclear Reactor 2
// 题意：n 个粒子 (x,y)，选子集 S 使每个被选粒子满足「其它被选粒子数 ≤ y」，收益 = x 之和；
//       商店里每个粒子（买且只买它一个）分别求最大收益（买了可以不用）。
//
// 关键：若用的自家粒子数为 s，则要求这些粒子的 y ≥ s-1（自家单独用时），
//       若把买来的粒子也算进去（总数 s+1），则要求自家粒子 y ≥ s 且商店粒子 y ≥ s。
//       所以预处理两个数组：
//         T[s]    = 从「y ≥ s」的自家粒子中取 s 个的最大和   （买来的粒子在用时的口径）
//         A[s-1]  = 从「y ≥ s-1」的自家粒子中取 s 个的最大和 （不用买来的粒子时的口径）
//       两个数组都用「按 y 降序扫描 + 小根堆维护前 k 大」在 O(n log n) 求出。
//       每个商店粒子 (x,y) 的答案 = max(基准, x + max_{0≤s≤min(y,n)} T[s])。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll NEG = LLONG_MIN / 4;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n, m;
        cin >> n >> m;
        vector<pair<int, ll>> her(n);              // (y, x)
        for (int i = 0; i < n; ++i) {
            ll x; int y;
            cin >> x >> y;
            her[i] = make_pair(y, x);
        }
        // 按 y 从大到小排序：y ≥ 阈值 的粒子就是前缀
        sort(her.begin(), her.end(),
             [](const pair<int, ll>& a, const pair<int, ll>& b) { return a.first > b.first; });

        // T[s]：取自「y ≥ s」的 s 个粒子的最大能量和（取不满记 NEG）
        vector<ll> T(n + 1, NEG);
        {
            priority_queue<ll, vector<ll>, greater<ll>> pq;   // 小根堆，堆内是当前选中的和最大的一批
            ll sum = 0;
            int idx = 0;
            for (int s = n; s >= 0; --s) {
                while (idx < n && her[idx].first >= s) {      // 新加入「y ≥ s」的粒子
                    pq.push(her[idx].second);
                    sum += her[idx].second;
                    ++idx;
                }
                while ((int)pq.size() > s) {                  // 只保留最大的 s 个
                    sum -= pq.top();
                    pq.pop();
                }
                if ((int)pq.size() == s) T[s] = sum;          // 候选不足 s 个 → 该 s 不可行
            }
        }
        // 基准答案：不用商店粒子，s 个自家粒子要求 y ≥ s-1
        ll base = 0;
        {
            priority_queue<ll, vector<ll>, greater<ll>> pq;
            ll sum = 0;
            int idx = 0;
            for (int t = n - 1; t >= 0; --t) {                // t = s-1
                while (idx < n && her[idx].first >= t) {
                    pq.push(her[idx].second);
                    sum += her[idx].second;
                    ++idx;
                }
                while ((int)pq.size() > t + 1) {
                    sum -= pq.top();
                    pq.pop();
                }
                if ((int)pq.size() == t + 1) base = max(base, sum);
            }
        }
        // T 的前缀最大：max_{0≤s≤k} T[s]
        vector<ll> pref(n + 1, NEG);
        for (int s = 0; s <= n; ++s) {
            pref[s] = T[s];
            if (s) pref[s] = max(pref[s], pref[s - 1]);
        }
        // 逐个商店粒子回答
        for (int j = 0; j < m; ++j) {
            ll x; int y;
            cin >> x >> y;
            if (j) cout << ' ';
            ll k = min<ll>(y, n);                            // 自家最多用 min(y,n) 个
            ll best = base;
            if (pref[k] > NEG / 2) best = max(best, x + pref[k]);
            cout << best;
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

反应性限制的是“其他粒子”数量：是否使用新粒子会使旧粒子的门槛差一。买下不等于必须选用。

## G. Operation Permutation

### 题意

给定初值以及若干加、减、乘、除操作，将所有操作均匀随机排列后依次执行。除法为实数除法，求最终值的期望模 $10^9+7$。

### 从零讲：期望的线性性，与初等对称多项式

期望的线性性说，若一个结果是若干贡献之和，那么期望等于各贡献期望之和，不要求贡献彼此独立。本题就是把初值与每次加法的贡献拆开，从而不必枚举全部操作排列。

为把所有子集按大小求和，定义 $e_s$ 为“选恰好 $s$ 个因子，其乘积之和”。例如三个因子有 $e_0=1$、$e_1=w_1+w_2+w_3$、$e_2=w_1w_2+w_1w_3+w_2w_3$、$e_3=w_1w_2w_3$。这些数就是多项式 $\prod_j(1+w_jz)$ 的系数。

加入新因子 $w$ 时，每个子集分成不选它和选它两类，转移为 $e_s\leftarrow e_s+w e_{s-1}$。原地更新要让 $s$ 从大到小，避免重复选择同一个因子。最终把选 $s$ 个因子的项乘上正文证明的概率 $1/(s+1)$，就得到期望系数。

模质数 $P$ 下除以非零数 $d$，使用 $d^{P-2}$ 作为乘法逆元。本题操作除数与 $s+1$ 均小于 $P$，没有不可逆分母。

### 思路

#### 把最终值拆成每次加法的贡献

把乘除操作都写成乘因子 $v_j$，除以某数对应乘它的倒数；把加减操作写成带符号的增量 $c_i$。对于一个固定操作顺序，初值会经过全部乘因子，而增量只会经过排在它后面的乘因子，所以最终值为
$$x\prod_jv_j+\sum_i c_i\prod_{j\text{ 在操作 }i\text{ 之后}}v_j.$$
由期望的线性性，每份贡献可以分别求期望，不要求它们独立。所有加法在随机排列中的地位相同，因此有同一个期望放大系数 $W$，答案化为
$$x\prod_jv_j+\left(\sum_i c_i\right)W.$$

#### 为什么把因子改写成一加一个增量

令 $w_j=v_j-1$，再令指示量 $I_j$ 表示乘法 $j$ 是否在指定加法之后。其放大倍数为 $\prod_j(1+w_jI_j)$。展开时，每个乘法子集 $S$ 贡献一项 $\prod_{j\in S}w_j$，但只有这些操作全在指定加法之后时，该项才出现。

只看这 $|S|+1$ 个操作的相对顺序，每个操作等概率排第一，因此指定加法排在全部所选乘法前面的概率是 $1/(|S|+1)$。其他操作插在哪里不影响这个概率。于是
$$W=\sum_{S}\frac{\prod_{j\in S}w_j}{|S|+1}.$$
这里各乘法是否在加法之后并不独立，不能简单把每个因子都替换成自己的平均值再相乘。

#### 按子集大小合并，避免指数枚举

令 $e_s$ 为所有大小为 $s$ 的子集乘积之和。初始 $e_0=1$，其余为零；加入新值 $w$ 时，一个子集要么不选它，要么在大小为 $s-1$ 的旧子集后选它，因此转移为 $e_s\leftarrow e_s+w e_{s-1}$。原地更新必须让下标从大到小，防止同一个因子被重复使用。

得到所有系数后，$W=\sum_{s=0}^q e_s/(s+1)$，其中 $q$ 为乘除操作数。例如因子为 $2,3$，则 $w$ 为 $1,2$，系数为 $e_0=1,e_1=3,e_2=2$，所以 $W=1+3/2+2/3=19/6$。

所有计算在模质数 $P=10^9+7$ 下进行，除数和 $s+1$ 都非零模 $P$，用快速幂求逆元即可。减法后的余数要调整为非负。没有乘法时只有 $e_0$，自然得到 $W=1$；没有加法时加法和为零，答案就是初值乘总乘积。时间 $O(n^2+n\log P)$，空间 $O(n)$。

### 参考代码

```cpp
// G. Operation Permutation
// 题意：x 与 n 个操作，随机等概率取一个排列依次作用，求最终 x 的期望值（mod 1e9+7）。
//       操作形如 +y / -y / x y / / y（"x" 表示乘号）。
//
// 思路（线性期望）：
//   把操作分成两类：乘法操作（x y / / y，记因子 v_j）与加法操作（+y / -y，记增量 c_k）。
//   最终值 = x·∏v_j + Σ_k c_k·∏_{排在 k 之后的 v_j}  —— 加法操作的贡献会被其后所有乘法放大。
//   对固定的加法操作 k 与固定的乘法子集 S：P(S 全部排在 k 之后) = 1/(|S|+1)
//   （在 S∪{k} 这 |S|+1 个元素的相对顺序里，k 排最前的概率）。
//   于是 E[∏_{j 在 k 之后} v_j] = Σ_S ∏_{j∈S}(v_j-1)/(|S|+1) = Σ_s e_s(w)/(s+1)，
//   其中 w_j = v_j - 1，e_s 是 w 的 s 次初等对称多项式（O(q²) DP 求出，q = 乘法操作个数）。
//   答案 = x·∏v_j + (Σ_k c_k)·Σ_s e_s/(s+1)  (mod M)。
//   样例 3 手算核对：x=1，乘法 {2,3}，加法和 = 1，w={1,2}，e0=1,e1=3,e2=2
//   → 1·6 + 1·(1 + 3/2 + 2/3) = 6 + 19/6 = 55/6（题面 Note 正是 55/6）。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;

// 快速幂
static ll pw(ll b, ll e) {
    b %= MOD;
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n;
        ll x;
        cin >> n >> x;
        vector<ll> w;                  // w_j = v_j - 1（乘法操作）
        ll prod = 1;                   // ∏ v_j
        ll sumC = 0;                   // Σ c_k
        for (int i = 0; i < n; ++i) {
            string s;
            cin >> s;
            char op = s[0];
            ll y = stoll(s.substr(1)) % MOD;      // y ≤ 1e9 < MOD
            if (op == 'x' || op == '*') {
                prod = prod * y % MOD;
                w.push_back((y - 1 + MOD) % MOD);
            } else if (op == '/') {
                ll v = pw(y, MOD - 2);            // 实数除法 = 乘 y 的逆元
                prod = prod * v % MOD;
                w.push_back((v - 1 + MOD) % MOD);
            } else if (op == '+') {
                sumC = (sumC + y) % MOD;
            } else {                              // '-'
                sumC = (sumC - y % MOD + MOD) % MOD;
            }
        }
        // 初等对称多项式 e_s（就地倒序累加，保证每个 w 只用一次）
        int q = (int)w.size();
        vector<ll> e(q + 1, 0);
        e[0] = 1;
        int cur = 0;
        for (ll wj : w) {
            for (int s = cur + 1; s >= 1; --s) {
                e[s] = (e[s] + e[s - 1] * wj) % MOD;
            }
            ++cur;
        }
        // W = Σ_s e_s/(s+1)
        ll W = 0;
        for (int s = 0; s <= q; ++s) {
            W = (W + e[s] * pw(s + 1, MOD - 2)) % MOD;
        }
        ll ans = (x % MOD) * prod % MOD;
        ans = (ans + sumC * W) % MOD;
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

实数除法对应乘逆元，不是整数向下取整。加法增量有符号，减法取模应规范到非负余数。

## H. Six Seven

### 题意

令 $f_i(v)$ 为 $i$ 的幂整除正整数 $v$ 的最高指数。每次同时给所有数组元素加一，求最少操作次数，使所有元素满足 $f_6(v)>f_7(v)$；不可行输出 $-1$。

### 从零讲：同余方程组的解，与「自相似」的递归下降

同时要求一个数除以互素模数 $u,v$ 有指定余数时，在 $0\ldots uv-1$ 中恰有一个解；其他解都相差 $uv$。这里模数仅为六、七、三十六，直接枚举这一小段即可，不必实现通用中国剩余定理。

例如固定风险组后，同时要求 $a_i+t$ 被 $36$ 和七整除，就等价于被 $252$ 整除。选定最小代表 $t_1$ 后，所有候选操作次数都写成 $t_1+252z$，因此公共因子可以整体抽出。

![抽出公共因子后的递归关系](assets/h-recurse.svg)

$252=6^2\cdot7$，所以抽出它会把六的指数减二、七的指数减一。整数指数满足 $2+f_6(w)>1+f_7(w)$，恰好等价于 $f_6(w)\ge f_7(w)$。而子问题抽出 $42=6\cdot7$ 时，两边同时减一，条件不变，形成真正的递归。

为何每次只递归一个余数组？固定加数模七后，其余六组都不含因子七，非严格条件自动满足；只需继续检查那一个仍可能失败的组。枚举七种加数余数不会漏解，分组缩小数值又保证递归结束。

### 思路

#### 先固定加数的模六，再枚举模七

要满足 $f_6(a_i+t)>f_7(a_i+t)$，左边至少为一，故所有 $a_i+t$ 都必须被六整除。若原数组模六余数不同，任何统一加数都不可能满足要求。否则 $t\equiv-a_1\pmod6$ 已固定。

把原数按模七分组，枚举哪个余数组 $c$ 在加完后被七整除，也就是固定 $t\equiv-c\pmod7$。其他六组的七指数为零，且它们已经被六整除，自动合格；只需继续处理这一组。如果这一组为空，直接在 $0$ 到 $41$ 中枚举满足两个同余式的最小加数即可。

#### 风险组抽出公共因子，严格条件变成非严格条件

若该组非空，其七指数至少为一，六指数就必须至少为二，即所有数加完都被 $36$ 整除。因此组内原数必须模 $36$ 同余，否则这一分支无解。

通过枚举 $0\le t_1<252$，找到同时使该组被 $36$ 和七整除的最小代表。由于 $36$ 与七互质，所有该分支候选恰为 $t=t_1+252z$，其中 $z\ge0$。令 $w_i=(a_i+t_1)/252$，利用 $252=6^2\cdot7$，原条件等价于
$$2+f_6(w_i+z)>1+f_7(w_i+z),$$
也就是 $f_6(w_i+z)\ge f_7(w_i+z)$。接下来只需解这个统一的非严格子问题。

#### 非严格子问题可以递归到自身

设当前集合为 $S$，需要寻找最小的非负加数 $z$，使每项满足六指数不小于七指数。仍按模七分组，枚举风险组。空组对应的最小加数为 $(-c)\bmod7$，因为此时所有数七指数都是零，六指数无需为正也满足要求。

风险组非空时，七指数至少为一，六指数也至少为一，所以这些数必须同时被六和七整除。它们必须模 $42$ 同余；否则当前分支不可行。求出 $0\le z_1<42$ 的同余代表后，将候选写成 $z=z_1+42u$，并把数替换为 $(v+z_1)/42$。

由于 $42=6\cdot7$，两种指数都减少一，条件仍是六指数不小于七指数，所以可调用同一个子问题。分支答案是 $z_1+42$ 乘递归答案。枚举七个分支并取最小，既覆盖所有加数的模七余数，也保证每个返回值可行。

#### 终止与实现边界

每次只继续处理一个余数组，数值约缩小为原来的 $1/42$。唯一需要防止的停滞是归一化后全为一：一的两种指数都是零，直接返回子问题答案零，不必再次递归。例如集合 $\{7\}$ 的非严格问题可以选择加一，得到八，双方指数都是零；并非一定要把它变成六的倍数，这正是保留空风险组分支的原因。

各层不同风险组互不重叠，每个输入元素每层只进入一个子调用，固定小模数枚举下时间为 $O(n\log V)$ 量级。深度为 $O(\log V)$，当前递归链保存的分组空间至多 $O(n\log V)$。代码用 $64$ 位整数保存恢复后的加数，并用大哨兵表示无解；遇到无解子问题时不进行乘法恢复。主问题的严格比较与递归问题的非严格比较必须区分。

### 参考代码

```cpp
// H. Six Seven
// 题意：f_i(j) = 最大的 k 使 i^k | j；j 特殊 ⟺ f_6(j) > f_7(j) ⟺ v_6(j) > v_7(j)。
//       每次操作把所有元素 +1，求最小的操作次数使所有元素同时特殊，无解输出 -1。
//
// 关键事实：
//   1) 特殊 ⟹ 6 | j，所以要求所有 a_i 模 6 同余，否则 -1；记 t0 = (-a_1) mod 6，则 t ≡ t0 (mod 6)。
//   2) 在时刻 t，只有「a_i ≡ -t (mod 7)」的那些元素有被 7 整除的风险（其余元素 v_7 = 0 必然特殊）。
//      所以按 a_i mod 7 分成 7 个组，答案 = 各组各自最优取 min；空组直接给一个很小的候选 t。
//   3) 某组在它的风险时刻全体都要满足 v_6 ≥ 2（即 36 | a_i + t）——否则该组无解。
//      于是该组所有元素必须模 36 同余；写 a_i + t = 252 w，条件化成 v_6(w) ≥ v_7(w)（type B 子问题）。
//   4) type B 自相似：按 w mod 7 分类，风险类全体必须模 42 同余，写 w + x = 42 y，条件又是 v_6(y) ≥ v_7(y)。
//      每递归一层数值缩小 42 倍，深度 O(log_42 a)，故整体 O(n log n)。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = (ll)4e18;   // 代表「无解」

// 求最小的 x ≥ 0 同时满足 x ≡ -c (mod 7)、x ≡ -r (mod 6)（两者互质，必有一解，范围 [0,42)）
static ll crt76(int c, ll r) {
    int a = (7 - c % 7) % 7;         // x mod 7
    int b = (int)(((6 - r % 6) % 6 + 6) % 6);   // x mod 6
    for (ll x = 0; x < 42; ++x) {
        if (x % 7 == a && x % 6 == b) return x;
    }
    return -1;
}

// type B 子问题：求最小的 x ≥ 0，使所有 v ∈ S 满足 v_6(v + x) ≥ v_7(v + x)；无解返回 INF
static ll solveB(const vector<ll>& S) {
    ll best = INF;
    vector<ll> cls[7];
    for (ll v : S) cls[v % 7].push_back(v);          // 按 mod 7 分组
    for (int c = 0; c < 7; ++c) {
        if (cls[c].empty()) {
            // 风险类为空：取最小的 x ≡ -c (mod 7) 即可，此时没有元素被 7 整除
            best = min(best, (ll)((7 - c) % 7));
            continue;
        }
        // 风险类非空：全体必须模 42 同余（既要 6 | v+x 相同，又已经同为 c mod 7）
        ll r = cls[c][0] % 42;
        bool ok = true;
        for (ll v : cls[c]) {
            if (v % 42 != r) { ok = false; break; }
        }
        if (!ok) continue;
        ll x1 = crt76(c, r);                          // 风险时刻的最小非负代表
        vector<ll> Y;
        bool allOne = true;                           // 全是 1 时 (v+x1)/42 仍是自己，会自环，直接判定
        for (ll v : cls[c]) {
            ll y = (v + x1) / 42;
            Y.push_back(y);
            if (y != 1) allOne = false;
        }
        ll sub = allOne ? 0 : solveB(Y);              // 递归到下一层
        if (sub < INF) best = min(best, x1 + 42 * sub);
    }
    return best;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<ll> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        bool same6 = true;                            // 所有 a_i 必须模 6 同余
        for (int i = 1; i < n; ++i) {
            if ((a[i] - a[0]) % 6 != 0) { same6 = false; break; }
        }
        if (!same6) { cout << -1 << '\n'; continue; }

        ll t0 = ((6 - a[0] % 6) % 6 + 6) % 6;         // 需要的 t 模 6
        ll best = INF;
        vector<ll> cls[7];
        for (ll v : a) cls[v % 7].push_back(v);
        for (int c = 0; c < 7; ++c) {
            if (cls[c].empty()) {
                // 该组为空：只要 t ≡ -c (mod 7) 且 t ≡ t0 (mod 6)，全部元素都特殊
                for (ll t = 0; t < 42; ++t) {
                    if (t % 7 == (7 - c) % 7 && t % 6 == t0) { best = min(best, t); break; }
                }
                continue;
            }
            // 非空组：全体必须模 36 同余（风险时刻要 36 | a_i + t）
            ll r = cls[c][0] % 36;
            bool ok = true;
            for (ll v : cls[c]) {
                if (v % 36 != r) { ok = false; break; }
            }
            if (!ok) continue;
            ll t1 = -1;                               // 该组风险时刻的最小非负代表（mod 252）
            for (ll t = 0; t < 252; ++t) {
                if (t % 7 == (7 - c) % 7 && (t + r) % 36 == 0) { t1 = t; break; }
            }
            vector<ll> W;
            for (ll v : cls[c]) W.push_back((v + t1) / 252);
            ll x = solveB(W);
            if (x < INF) best = min(best, t1 + 252 * x);
        }
        cout << (best >= INF ? -1 : best) << '\n';
    }
    return 0;
}
```

### 易错点

主问题是严格大于，除去 $252$ 后变成大于等于，不能仍用同一个严格判定。不可行分支用足够大的哨兵并检查乘法溢出。

## A. Koshary

### 题意

从原点到 $(x,y)$，每步只能把某个坐标加二，整个过程中至多一次可以改为加一。判断能否恰好到达。

### 思路

从原点开始，两个坐标都是偶数。每次长步只给一个坐标加二，不改变任何坐标的奇偶性；唯一一次短步只会改变其中一个坐标的奇偶性。所以如果目标的两个坐标都是奇数，就至少需要两次短步，与限制矛盾。

其余情况也确实都能到达。两个坐标都是偶数时，分别走 $x/2$ 次水平长步和 $y/2$ 次竖直长步即可；只有一个坐标为奇数时，给这个方向用一次短步，剩下的距离都是非负偶数，再用长步补齐。题目允许至多一次短步，因此偶数、偶数的情况可以完全不用它。

例如目标 $(3,4)$ 可在水平方向走一次短步、一次长步，在竖直方向走两次长步；$(3,5)$ 则两个方向都需要短步，不可达。代码只判断是否同时为奇数，每组时间和空间都是 $O(1)$，不需要搜索路径。

### 参考代码

```cpp
// A. Koshary —— 从 (0,0) 走到 (x,y)，长步让某个坐标 +2，短步让某个坐标 +1，短步全场最多一次。
// 坐标都是正数、步长也都是正的，所以只可能往右上走，问题退化成奇偶性：
//   x、y 都偶 → 全用长步；恰有一个奇 → 让那个坐标用掉唯一的短步；
//   x、y 都奇 → 两个坐标各需要一次短步，而短步只有一次，到不了。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int x, y;
        cin >> x >> y;
        // 只有「两个坐标同为奇数」这一种情况到不了
        cout << ((x % 2 == 1 && y % 2 == 1) ? "NO" : "YES") << '\n';
    }
    return 0;
}
```

### 易错点

短步是至多一次，两个坐标都偶数时可以不用。

## B. Party Monster

### 题意

最多选一次连续子串，把其中所有字符取出，再将它们逐个插入任意位置。判断括号串能否变成正规括号序列。

### 从零讲：正规括号序列

把左括号记为 $+1$、右括号记为 $-1$。正规括号序列需满足两件事：总和为零，且任意前缀和不为负。

例如 $\texttt{(())}$ 的前缀和为 $1,2,1,0$，一直非负，最后回到零；$\texttt{)(}$ 虽然总和为零，第一步却为负，表示右括号前面没有可匹配的左括号，所以原串不正规。

本题可以完全重排，只要两种括号数量相等，就能构造“全部左括号、全部右括号”的顺序，前缀和先上升再下降至零。原串是否已经满足前缀条件并不影响可行性。

### 思路

正规括号序列中的每个左括号必须匹配一个右括号，因此两种括号数量相等是必要条件。操作只移动字符，不会改变字符种类或数量，所以数量不等时一定无解。

接着证明这也是充分条件。允许选择的连续子串可以是整个字符串，取出后可以把各字符独立插回任意位置，因此能够任意重排整串。若左右括号各有 $c$ 个，就把所有左括号放在前面、所有右括号放在后面，得到嵌套的正规序列。其前缀余额先从零增加到 $c$，再逐步回到零，从不为负。

例如 $\texttt{))((}$ 虽然开头就是右括号，但只要两种括号数量相等，仍能重排成 $\texttt{(())}$。原串是否已经正规、哪些前缀曾经出现负余额，都不会影响这里的可行性。

所以代码只统计左括号数，检查其两倍是否等于长度 $n$。长度为奇数会自然被排除。扫描时间 $O(n)$，除输入字符串外额外空间 $O(1)$。这里能够改变被取出字符之间的顺序，是结论成立的关键。

### 参考代码

```cpp
// B. Party Monster —— 最多一次操作：选一个子串整段抽出来，再把抽出的字符逐个插到任意位置。
// 关键观察：把「整个串」当成那个子串时，等于允许把整串任意重排。
// 于是能变正规括号串 ⟺ '(' 和 ')' 一样多（一样多时重排成 "(((…)))" 就是正规的）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;
        int open = 0;
        for (char c : s) {
            if (c == '(') open++;
        }
        // 题目保证串只含 '(' 和 ')'：左括号恰好一半即可
        cout << (open * 2 == n ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

取出的字符是逐个插回，彼此可以改变顺序，不是保持原顺序移动一整块。

## C. Snowfall

### 题意

重排正整数数组，使乘积能被六整除的连续子数组数量最少，输出任意最优排列。

### 从零讲：把「乘积能被 6 整除」拆成两个因子

六等于二乘三，而二、三互素。一个区间乘积能被六整除，当且仅当其中至少有一个数提供因子二，且至少有一个数提供因子三。两种因子可以来自同一个数，也可以来自不同数。

例如 $[4,9]$ 虽然没有单独的六的倍数，乘积仍为 $36$；$[5,7,9]$ 只有因子三，乘积不能被六整除。因此每个数的具体大小不重要，只需要记“提供哪些因子”，得到正文的四类。

证明最优排列时，不必计算每种排列的全部乘积。把每个必然满足条件的端点对映射到唯一子数组，就得到清楚的数量下界；再检查构造没有额外区间，即可证明最优。

### 思路

#### 具体数值只通过二、三两个因子起作用

一个区间乘积被六整除，当且仅当区间里既有因子二，也有因子三。将元素分为四类：同时提供两种因子的六类、只提供二的二类、两种都不提供的一类、只提供三的三类，数量分别记为 $c_6,c_2,c_1,c_3$。

构造按“六类、二类、一类、三类”输出。把必定让区间合格的六类集中到一端；把需要互相配合的二类、三类分在中性元素两侧。下面用一个排列无关的下界证明它最优，而不只凭直觉解释。

#### 对任何排列都逃不掉的区间

每个六类元素的单点区间都被计数，共 $c_6$ 个。两个不同位置若至少有一个端点属于六类，它们确定的区间也一定被计数，共有 $\binom{c_6}{2}+c_6(c_1+c_2+c_3)$ 个。再取一个二类位置和一个三类位置作为端点，也会得到合格区间，共 $c_2c_3$ 个。

上述区间按端点分类，彼此不重复。因此任何排列的答案至少为
$$\frac{c_6(c_6+1)}2+c_6(c_1+c_2+c_3)+c_2c_3.$$
这不是要求两个端点相邻；一对端点唯一决定一个连续子数组即可。

#### 构造没有产生下界之外的区间

六类全部在最左端，因此任何包含六类的区间，左端点必然就在六类块内，已经属于上述第一部分。若区间不含六类，就必须同时经过二类块和三类块才能合格；由于一类夹在中间，这种区间的左端点一定是二类，右端点一定是三类，也已经计入下界。

例如四类各一个时，排列 $[6,2,1,3]$ 中包含首个六的区间有四个，另有 $[2,1,3]$，总数五，正好等于公式。各类内部怎么排列都不影响因子性质，因此无需排序，只需四个容器按顺序输出，时间、空间均为 $O(n)$。

### 参考代码

```cpp
// C. Snowfall —— 重排数组，让「乘积能被 6 整除」的子数组个数最少。
// 一个子数组被计数 ⟺ 它同时含有「带因子 2 的元素」和「带因子 3 的元素」。
// 把元素按 4 类分：c1 既非 2 倍也非 3 倍、c2 只是 2 倍、c3 只是 3 倍、c6 是 6 的倍数。
// 最优排列是 [6 的倍数][只是 2 倍][既非 2 也非 3][只是 3 倍]，
// 此时最小值 = g(c6) + c6·(c1+c2+c3) + c2·c3，其中 g(x)=x(x+1)/2。
// 推导见题解「思路」；本文件只负责按这个顺序输出。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> t6, t2, t1, t3;   // 四类各自按输入顺序存
        for (int i = 0; i < n; i++) {
            long long v;
            cin >> v;
            bool two = (v % 2 == 0), three = (v % 3 == 0);
            if (two && three)      t6.push_back((int)v);
            else if (two)          t2.push_back((int)v);
            else if (three)        t3.push_back((int)v);
            else                   t1.push_back((int)v);
        }
        bool first = true;
        for (const vector<int>* g : {&t6, &t2, &t1, &t3}) {
            for (int v : *g) {
                if (!first) cout << ' ';
                first = false;
                cout << v;
            }
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

先判六的倍数，避免把它放入单因子类；各类内部无需排序。

## D. Palindromex

### 题意

长度 $2n$ 的数组中，每个值 $0\ldots n-1$ 恰好出现两次。求所有回文子数组里最大的 MEX。

### 从零讲：Manacher（用回文半径在 $O(n)$ 内判回文）

判断单个区间回文，可以从中心向两侧比较。但候选很多时，反复比较会重复扫描。Manacher 为每个中心一次算出最大的回文半径。

奇回文以元素 $i$ 为中心，半径 $d_1[i]=r$ 表示区间 $[i-r+1,i+r-1]$ 回文；偶回文以 $i-1,i$ 中间的缝为中心，$d_2[i]=r$ 表示 $[i-r,i+r-1]$ 回文。例如 $[2,1,2]$ 的中间奇半径是二，$[2,1,1,2]$ 的中央偶半径是二。

维护目前向右伸得最远的回文区间 $[l,r]$。处理里面的新中心 $i$ 时，它关于区间中心的镜像已经计算过；镜像半径落在 $[l,r]$ 内的部分可以直接照搬，只有越过已知右边界的部分需要重新比较。每次成功比较都会推动最右边界，失败比较每个中心至多一次，所以总时间线性。

查询区间 $[L,R]$ 时，根据长度奇偶找到对应中心，看已知半径是否覆盖该区间即可。本题的小值集合会把回文中心和最小覆盖范围基本确定下来，正好只需这种常数时间判定。

### 思路

#### 把最大 MEX 改成包含一段小值

MEX 至少为 $k$，等价于回文区间包含所有 $0,1,\ldots,k-1$；不要求它排除 $k$。这个可行性随 $k$ 单调，所以可以从 $k=1$ 依次加入一个值，第一次失败就停止。

记值 $v$ 的两个出现位置为 $P_v<Q_v$，区间为 $[L,R]$。回文中的位置必须与位置 $L+R-i$ 相等，而每个值全局只有两次。因此一个被包含的值只有两种可能：两次都在区间里，且 $P_v+Q_v=L+R$；或只出现一次，并且它恰好位于整数中心。一个回文最多容纳一个这样的单次值。

#### 位置和几乎确定了回文中心

对当前必须包含的所有值，按 $P_v+Q_v$ 分组。若有三个不同的和，就不可能：除至多一个中心值之外，其他值必须拥有同一个和，三个组至少会留下两种非中心的和。

只有一组且 $k\ge2$ 时，所有值都必须成对进入回文。令公共和为 $s$，最小覆盖区间为 $[\min P_v,\max Q_v]$，其端点和也为 $s$。若存在更大的同心回文覆盖它，截去两侧相同长度后，这个最小区间也必为回文；所以直接检查最小区间即可，既必要又充分。$k=1$ 可以直接选单个零，需要单独视为可行。

有两组时，其中一组必须只含一个值 $v$，让它作为中心；另一组的公共和记为 $s$。必须先检查 $s$ 为偶数，且 $a_{s/2}=v$。其他值都成对出现，以它们最左侧的首次出现位置确定左边界，再围绕中心对称得到右边界。这个最小覆盖区间是回文时即可通过。如果两组各含一个值，两种中心选择都要尝试，不能随意指定其中一组。

例如 $[0,1,0,1]$ 中，零的位置和与一的位置和不同，但区间 $[0,1,0]$ 让一作为中心，仍能包含零和一，MEX 为二。只有按“成对值加可选中心值”分类，才不会漏掉这种奇回文。

#### 候选区间用半径常数时间检查

Manacher 预处理每个中心的最长奇回文半径与偶回文半径。给定区间后，按长度奇偶确定中心，只需判断对应半径是否足够覆盖它。这样无需对每个候选重新逐项比较。

增量加入值时，代码维护各位置和的计数及代表值，并记录最小、次小的 $P_v$。排除中心候选时，若最小位置恰属于它，就改用次小值；否则仍用最小值。只有一个和时另维护最大 $Q_v$。每次加入后最多检查两个区间，所以除线性的回文预处理外，扫描也是 $O(n)$，总空间 $O(n)$。

### 参考代码

```cpp
// D. Palindromex —— 每个值 0..n-1 恰好出现两次，求「回文子数组的 mex」的最大值。
// 回文子数组 [L,R] 有硬性质：位置 i 与 L+R-i 上的数相等。因为每个值只出现两次，
// 任何出现在子数组里的值 v 只有两种命运：
//   * 两次都在里面  ⟹ 这两次关于中心对称 ⟹ pos1[v]+pos2[v] = L+R；
//   * 只有一次在里面 ⟹ 那一次必定在正中心。
// 所以「存在回文子数组含 0..k-1」按 k 递增检查，只有两种可能：
//   ① 所有 v<k 的和 s 相同：最小覆盖区间 [min(pos1), max(pos2)] 必须本身是回文；
//   ② 恰有一个 v*<k 的和与别人不同：它只能坐在中心 m = s/2，且 a[m] == v*。
// 回文判定靠 Manacher 的 d1/d2 在 O(1) 内回答。答案 = 第一个不成立的 k 减一。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int m = 2 * n;
        vector<int> a(m);
        for (int i = 0; i < m; i++) cin >> a[i];

        // 每个值两次出现的位置（0-indexed）
        vector<int> P(n, -1), Q(n, -1);
        for (int i = 0; i < m; i++) {
            if (P[a[i]] < 0) P[a[i]] = i;
            else             Q[a[i]] = i;
        }

        // Manacher：d1[i] 为以 i 为心的奇回文半径（回文 [i-k+1, i+k-1]）
        //           d2[i] 为以 i-1 与 i 之间为心的偶回文半径（回文 [i-k, i+k-1]）
        vector<int> d1(m, 0), d2(m, 0);
        for (int i = 0, l = 0, r = -1; i < m; i++) {
            int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < m && a[i - k] == a[i + k]) k++;
            d1[i] = k;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
        }
        for (int i = 0, l = 0, r = -1; i < m; i++) {
            int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < m && a[i - k - 1] == a[i + k]) k++;
            d2[i] = k;
            if (i + k - 1 > r) { l = i - k; r = i + k - 1; }
        }
        auto isPal = [&](int L, int R) {
            if ((R - L) % 2 == 0) {                 // 奇数长，心是整数位置
                int c = (L + R) / 2;
                return d1[c] >= (R - L) / 2 + 1;
            }
            int c = (L + R + 1) / 2;                // 偶数长，心在 c-1 与 c 之间
            return d2[c] >= (R - L + 1) / 2;
        };

        // 增量维护：值的和 s = pos1+pos2 的不同取值不超过 2 个时才有戏
        vector<int> cntSum(2 * m + 2, 0);           // s <= (m-1)+(m-2) < 2m
        vector<int> rep(2 * m + 2, -1);             // 每个和的一个代表值
        vector<int> present;                        // 当前出现的不同和（最多留 3 个）
        int minP1 = INT_MAX, arg1 = -1, minP2 = INT_MAX;
        int maxQ = -1;
        int ans = 0;

        for (int k = 1; k <= n; k++) {
            int v = k - 1, s = P[v] + Q[v];
            if (cntSum[s] == 0) present.push_back(s), rep[s] = v;
            cntSum[s]++;
            if (P[v] < minP1) { minP2 = minP1; minP1 = P[v]; arg1 = v; }
            else if (P[v] < minP2) { minP2 = P[v]; }
            maxQ = max(maxQ, Q[v]);

            if ((int)present.size() > 2) break;     // 3 个不同的和：往后都不可能

            bool ok = (k == 1);                     // k=1 只要 0 出现即可（单元素子数组）
            if (!ok && present.size() == 1) {       // ① 全体的和相同
                int s0 = present[0];
                int L = minP1, R = maxQ;            // 此时 L+R 必等于 s0
                if (L + R == s0 && isPal(L, R)) ok = true;
            }
            if (!ok && present.size() == 2) {       // ② 恰有一个值当中心
                for (int idx = 0; idx < 2; idx++) {
                    int sOther = present[idx], sMain = present[1 - idx];
                    if (cntSum[sOther] != 1) continue;   // 只有唯一值才能是中心
                    int vstar = rep[sOther];
                    if (sMain % 2) continue;             // 中心必须是整数位置
                    int c = sMain / 2;
                    if (a[c] != vstar) continue;         // 中心位上得正好是它
                    int mp = (arg1 != vstar) ? minP1 : minP2;
                    if (mp == INT_MAX) continue;
                    int L = min(c, mp), R = 2 * c - L;
                    if (isPal(L, R)) { ok = true; break; }
                }
            }
            if (!ok) break;
            ans = k;
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

“必须包含小于 $k$ 的值”足以判断 MEX 至少为 $k$，不需要主动排除 $k$。唯一出现的值必须真在中心，不能只看分组大小。

## E. It All Went Sideways

### 题意

柱子高度为 $a_i$。每一层的方块向右滑动并压紧，保持该层方块原有顺序。滑动前至多选一根柱子降低一格，求最多有多少方块改变所在列。

### 从零讲：单调栈（找左边最近一个更小的位置）

对每根柱子，都要找它左侧最近的更矮柱子。逐个向左找会平方复杂度，单调栈保留“之后仍可能成为答案”的下标。

从左往右读高度 $h$，把栈顶所有高度不小于 $h$ 的位置弹出。它们不仅不能作为当前的严格更小者，对以后的询问也已被当前位置替代：当前更靠右，且高度不大。弹完后栈顶就是最近的严格更小位置；没有栈顶则说明左侧不存在。然后把当前下标压入。

每个下标只入栈一次、出栈一次，所以全部最近更小位置在线性时间得到。本题用它确定降低一个后缀最小柱子后，影响向左能延伸到哪里。

### 思路

#### 先数不移动的方块

固定某一高度 $h$，这一层的方块只向右压紧，彼此顺序不变。原来在第 $i$ 列的方块不动，当且仅当它右边每一列都有这一层的方块；只要右边有空位，右移压紧后它就会至少前进一列。

因此第 $i$ 列不动的层数，恰好为后缀最小高度 $m_i=\min(a_i,\ldots,a_n)$。所有方块数为 $S=\sum a_i$，原移动数就是
$$M=S-\sum_i m_i.$$
这避免了按每一层实际模拟。

#### 降低一格会改变哪些后缀最小值

把第 $i$ 列高度从 $h=a_i$ 降到 $h-1$。总方块数先减少一。若右边已有高度小于 $h$ 的柱子，由于高度为整数，它至多为 $h-1$，所有包含第 $i$ 列的后缀仍被那个更矮值限制，后缀最小值不会下降。这种操作只会让移动数减少一，不必考虑。

有用的候选满足 $a_i\le m_{i+1}$。此时向左找最近的严格更矮位置 $p$；在 $p+1$ 至 $i$ 之间，所有高度都至少为 $h$，而右侧也至少为 $h$，所以这些位置对应的后缀最小值原来都是 $h$，操作后恰好各减少一。位置不超过 $p$ 的后缀已经包含更矮柱子，不受影响；位置大于 $i$ 的后缀不含修改位置，也不受影响。

故不动方块数减少 $i-p$，而总方块数减少一，净收益为 $i-p-1$。例如高度 $[2,2,2]$ 原来没有方块移动，降低最后一列后最上层两个剩余方块都右移，收益为 $3-1=2$。相等高度不会阻断影响，左边必须找严格更小的位置。

#### 单调栈一次求完左边界

从左到右维护高度严格递增的下标栈，当前高度为 $h$ 时，弹出所有高度大于等于 $h$ 的栈顶，剩余栈顶就是最近严格更小的位置；空栈在零基代码里记为 $-1$。每个下标入栈、出栈至多一次。

后缀最小值从右向左预处理，末尾哨兵为无穷大，使最后一列也能作为候选。取所有候选收益与零的最大值，加到 $M$ 上；零代表不操作。总和使用 $64$ 位整数，时间、空间均为 $O(n)$。

### 参考代码

```cpp
// E. It All Went Sideways —— 右移重力后，最多能有多少个立方体换列（可以先减掉一个立方体）。
// 结论一：高度 h 上，原列 i 的立方体新列 = z_h + (i 前面高度 >= h 的列数)，其中 z_h = 高度 < h 的列数。
//         它不动 ⟺ i 右边没有「高度 < h」的列 ⟺ min(a[i+1..n]) >= h。
//         于是「不动的立方体总数 = Σ min(a[i..n])」（后缀最小值之和）。
//         记 S = Σa_i、sm[i] = min(a[i..n])，则不动数 = Σ sm[i]，移动数 = S − Σ sm[i]。
// 结论二：把 a_i 减 1 只对「a_i <= sm[i+1]」的位置有意义（此时 sm_i 本来就等于 a_i），
//         不动数会减少 (i − prevLess(i))，其中 prevLess(i) 是 i 左边最近一个 a_j < a_i 的位置。
//         所以答案 = max(原值, 原值 + 最大收益 − 1)。prevLess 用单调栈 O(n) 求。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        const int INF = INT_MAX;
        vector<int> sm(n + 1);                      // sm[i] = min(a[i..n-1])，sm[n] = +inf
        sm[n] = INF;
        for (int i = n - 1; i >= 0; i--) sm[i] = min(sm[i + 1], a[i]);

        long long S = 0, sumSm = 0;
        for (int i = 0; i < n; i++) { S += a[i]; sumSm += sm[i]; }
        long long moving = S - sumSm;               // 不做操作时的移动数

        // 单调栈求 prevLess（栈里存下标，值严格递增）
        vector<int> stk;
        long long bestRed = 0;
        for (int i = 0; i < n; i++) {
            while (!stk.empty() && a[stk.back()] >= a[i]) stk.pop_back();
            int prevLess = stk.empty() ? -1 : stk.back();
            if (a[i] <= sm[i + 1]) {                // 减掉这个立方体才有可能让后缀最小值变小
                bestRed = max(bestRed, (long long)(i - prevLess));
            }
            stk.push_back(i);
        }
        long long ans = moving;
        if (bestRed > 0) ans = max(ans, moving + bestRed - 1);
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

左侧找严格更小值，等高柱子不能阻断影响；最后一列也能降低，可把其右侧最小值视为无穷大。

## F. It Just Keeps Going Sideways

### 题意

与 E 题相同的向右重力和至多一次降低柱子操作，求所有剩余方块移动距离之和的最大值。

### 从零讲：树状数组（单点加 + 前缀和）

树状数组维护一排桶，支持把某个桶加上一个值，以及查询前若干桶的和，两个操作都只需对数时间。本题桶的下标是高度，桶里既可以存柱子数量，也可以存高度总和。

它让下标 $i$ 保存结尾为 $i$、长度为 $\operatorname{lowbit}(i)$ 的一块区间和；$\operatorname{lowbit}(i)$ 是二进制最低的一位一代表的数。例如桶八覆盖前八项，桶六覆盖第五、六项。查前缀时不断减去最低位，把前缀拆成互不重叠的块；更新一个桶时不断加上最低位，修正所有包含它的块。

已处理的柱子共有 $c$ 根、总高为 $s$。查询不超过高度 $h$ 的数量 $c_0$ 与总高 $s_0$，那么更高柱子的贡献就是 $(s-s_0)-(c-c_0)h$。这样不用逐根枚举，也能一次统计所有左侧柱子与当前位置形成的距离贡献。

### 思路

#### 一个方块的位移，等于右边空位数

固定高度 $h$，原在列 $i$ 的方块右移时，会补上它右侧这一层的所有空位，因此距离等于右侧高度小于 $h$ 的列数。交换统计顺序：固定两列 $i<j$，右列会给左列高度 $a_j+1$ 至 $a_i$ 的方块各贡献一单位位移，合计为 $\max(0,a_i-a_j)$。

于是原总距离为
$$D=\sum_{i<j}\max(0,a_i-a_j).$$
例如左列高五、右列高二，这一对列贡献三；若左列不比右列高，则贡献为零。这是距离总和的公式，不能沿用上一题只判断动没动的后缀最小值公式。

#### 修改收益只需比较两侧高度

令修改列为 $k$、原高为 $h$。作为右端点时，左侧每根高度至少为 $h$ 的柱子，差值 $\max(0,a_i-h)$ 在降低后增加一；更矮的左柱贡献不变。作为左端点时，右侧每根严格低于 $h$ 的柱子，其差值减少一；高度至少为 $h$ 的右柱贡献始终为零。

因此
$$\Delta_k=\#\{i<k:a_i\ge a_k\}-\#\{j>k:a_j<a_k\}.$$
左侧包含等号、右侧不包含等号，来自两个不同方向的差值变化。例如两根等高柱子，降低右柱会让左柱顶部方块多走一步；降低左柱则不会产生移动。

#### 按高度统计数量和总和

题目高度在 $1$ 至 $n$ 内，代码以高度为树状数组下标。左扫到位置 $j$ 时，查询此前严格小于 $a_j$ 的数量和高度和，用已插入的总量减去它们，得到此前高度至少为 $a_j$ 的部分。它们的贡献为“高度和减去数量乘 $a_j$”；其中等高项贡献零，和只枚举严格更高完全等价。

接着右扫，用计数树状数组求每个位置右边严格更小的数量。再左扫求左侧不小于当前高度的数量，两者相减就是该位置收益。查询必须在插入当前元素之前，避免把自己算入左右侧。

最终输出 $D+\max(0,\max_k\Delta_k)$，保留零是因为允许不修改。每次树状数组操作 $O(\log n)$，总时间 $O(n\log n)$、空间 $O(n)$。距离总和和乘法中间值都使用 $64$ 位整数。

### 参考代码

```cpp
// F. It Just Keeps Going Sideways —— 同 E 的重力设定，但问的是「总移动距离」的最大值。
// 结论一：总距离 = Σ_{i<j} max(0, a_i − a_j)。（原列 i 的立方体在高度 h 上的位移 =
//         i 右边高度 < h 的列数，把它对 h=1..a_i 求和，正好是「右边的更矮列」贡献的高度差）
// 结论二：把 a_k 减 1 只影响和 k 有关的两类点对，净收益
//         Δ(k) = #{i<k : a_i >= a_k} − #{j>k : a_j < a_k}，
//         所以答案 = D + max(0, max_k Δ(k))。
// 两者都用树状数组（值域 1..n）在线统计：一个是「前面比它大的个数与和」，
// 一个是「前面不小于它的个数」与「后面比它小的个数」。
#include <bits/stdc++.h>
using namespace std;

// 树状数组：单点加、前缀和
struct BIT {
    int n;
    vector<long long> t;
    explicit BIT(int n) : n(n), t(n + 1, 0) {}
    void clear() { fill(t.begin(), t.end(), 0); }
    void add(int i, long long v) {
        for (; i <= n; i += i & -i) t[i] += v;
    }
    long long sum(int i) const {                 // 1..i 的和
        long long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        // 第一步：D = Σ_{i<j} max(0, a_i − a_j)
        BIT cnt(n), sm(n);
        long long D = 0, insertedSum = 0;
        for (int j = 0; j < n; j++) {
            long long lessCnt = cnt.sum(a[j] - 1);
            long long lessSum = sm.sum(a[j] - 1);
            D += (insertedSum - lessSum) - (j - lessCnt) * (long long)a[j];
            cnt.add(a[j], 1);
            sm.add(a[j], a[j]);
            insertedSum += a[j];
        }

        // 第二步：Δ(k) = #{i<k : a_i >= a_k} − #{j>k : a_j < a_k}
        vector<int> lessAfter(n, 0);                 // 后面比它小的个数
        cnt.clear();
        for (int k = n - 1; k >= 0; k--) {
            lessAfter[k] = (int)cnt.sum(a[k] - 1);
            cnt.add(a[k], 1);
        }
        cnt.clear();
        long long bestDelta = 0;
        for (int k = 0; k < n; k++) {
            long long geBefore = k - cnt.sum(a[k] - 1);
            bestDelta = max(bestDelta, geBefore - lessAfter[k]);
            cnt.add(a[k], 1);
        }
        cout << D + bestDelta << '\n';
    }
    return 0;
}
```

### 易错点

左侧比较包含等号，右侧不含等号；这来自降低前后差值的变化，不能两边统一成同一种比较。总距离用 64 位整数。

## G. Drowning

### 题意

正整数数组的一次操作可把相邻三项 $x,y,z$ 替换为 $x-y+z$，要求 $x+z>y$。统计能通过若干次操作缩成一个元素的子数组数量。

### 从零讲：交错和（不变量 + 前缀化）

交错和是隔一项换符号的和。把连续三项替换成 $x-y+z$ 时，它们的交错贡献原本就是 $x-y+z$ 或其相反数，替换后恰好保持；长度少二，后面所有符号也不变。因此整体交错和是不变量。

每步长度减二，最后长度为一要求原长为奇数；每个新数仍正，最后的单数又等于原交错和，所以交错和必须为正。

这两个必要条件也充分。假设一个长于一的奇数序列，所有偶数位置都不能作为三项中心，则 $c_i\ge c_{i-1}+c_{i+1}$。把这些不等式相加，偶数位置总和至少等于两端加上所有内部奇数位置的两倍，因此交错和不可能为正，矛盾。总能找到合法一步；做完后奇数长度、正交错和继续保持，归纳即可缩到一个数。

例如 $[10,20,10]$ 的交错和为零，确实不能合并；$[5,1,5]$ 的交错和为九，可以直接合成九。将这个判据写成两个前缀值的比较，才得到正文的快速区间计数。

### 思路

#### 缩成一个数的必要条件

每次长度减少二，所以只有奇数长度可能变成一。再看交错和 $c_1-c_2+c_3-\cdots$：把相邻三项替换为 $x-y+z$ 时，它们对交错和的贡献完全不变；后缀少了两个位置，后续符号也不变。因此交错和是整个操作过程的不变量。

合法操作要求新数严格为正，最后剩下的一个数又等于原交错和，所以它必须为正。于是好区间必然满足“奇数长度且交错和为正”。

#### 这两个条件也足以保证一直操作下去

考虑一个长度大于一的奇数序列。假设每个偶数位置都不能作操作中心，那么
$$c_{2j}\ge c_{2j-1}+c_{2j+1}.$$
对所有偶数位置求和，右边包含两个端点各一次、所有内部奇数位置各两次。因此偶数位置总和至少不小于奇数位置总和，交错和就不可能为正，产生矛盾。

所以总能找到一个合法中心。操作后元素仍全正、长度仍为奇数、交错和仍为正，再对缩短的序列应用同样结论，最终必能变成一个数。这给出完整的充分性证明，无需猜测具体选择哪个局部极值。

#### 把区间交错和化为前缀比较

定义 $P_i=a_1-a_2+\cdots+(-1)^{i+1}a_i$，再令 $C_i=(-1)^{i+1}P_i$，并设 $C_0=0$。当区间长度为奇数时，$l,r$ 同奇偶，直接展开可得其交错和为 $C_r+C_{l-1}$。

所以扫描右端点 $r$，需统计旧前缀下标 $j=l-1<r$ 中，与 $r$ 奇偶相反且满足 $C_j>-C_r$ 的数量。用两棵树状数组分别维护偶下标和奇下标前缀值的出现次数，便能分开长度限制和数值限制。

前缀值可能为负且范围大，先排序去重映射到排名。查询时用 `upper_bound()` 找到不大于 $-C_r$ 的范围，用已插入总数减去该范围数量，严格排除交错和为零的区间。代码每轮先插入 $C_{r-1}$，因此第一轮自然插入 $C_0$，也能统计从首元素开始的区间。

例如 $[10,20,10]$ 的交错和为零，不能合并；$[5,1,5]$ 的交错和为九，可以直接合并。长度一的区间总为正，也被上述计数自动包括。时间 $O(n\log n)$，空间 $O(n)$，前缀和与区间总数均使用 $64$ 位整数。

### 参考代码

```cpp
// G. Drowning
// 一次操作把 (c_{i-1}, c_i, c_{i+1}) 换成 c_{i-1} - c_i + c_{i+1}。
// 关键结论：子数组 c 好 ⟺ |c| 为奇数 且 交错和 c1 - c2 + c3 - ... > 0。
//  * 交错和是操作的不变量（新三元组对交错和的贡献完全一样），最终单元素就是它，
//    所以「好」必须交错和 > 0；偶数长度每次减 2 永远到不了 1。
//  * 反过来：奇数长度、交错和 > 0 时总能找到合法的操作位置
//   （若每个 i 都做不了，即 c_{i-1}+c_{i+1} <= c_i，用 i=2 与 i=4 两条夹逼会推出 c_4 < 0，矛盾），
//    操作后交错和不变、元素保持为正，于是归纳到最后一定剩一个正数。
// 计数办法：令 P[k] = a1 - a2 + a3 - ... +- ak，C[k] = (-1)^{k+1} P[k]（C[0]=0）。
// 区间 [l,r] 的交错和 = C[r] + C[l-1]（只对 l≡r (mod 2) 成立），
// 于是答案是满足「l≡r (mod 2) 且 C[r] + C[l-1] > 0」的 (l,r) 个数。
// 按 r 从小到大扫，用两棵树状数组（按下标 k=l-1 的奇偶分开）数「比 -C[r] 大的已插入值」。
#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<int> t;
    explicit BIT(int n) : n(n), t(n + 1, 0) {}
    void add(int i, int v) { for (; i <= n; i += i & -i) t[i] += v; }
    int sum(int i) const { int s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];

        // C[0..n]
        vector<long long> P(n + 1, 0), C(n + 1, 0);
        for (int k = 1; k <= n; k++) {
            P[k] = P[k - 1] + ((k % 2 == 1) ? a[k] : -a[k]);
            C[k] = (k % 2 == 1) ? P[k] : -P[k];
        }
        // 离散化：所有 C[k] 和所有阈值 -C[r] 都进表
        vector<long long> all;
        all.reserve(2 * n + 1);
        for (int k = 0; k <= n; k++) all.push_back(C[k]);
        for (int r = 1; r <= n; r++) all.push_back(-C[r]);
        sort(all.begin(), all.end());
        all.erase(unique(all.begin(), all.end()), all.end());
        int M = (int)all.size();

        BIT bitEven(M), bitOdd(M);
        long long ans = 0;
        for (int r = 1; r <= n; r++) {
            int k = r - 1;                                   // 这一步插入 C[r-1]
            int rk = (int)(lower_bound(all.begin(), all.end(), C[k]) - all.begin()) + 1;
            (k % 2 == 0 ? bitEven : bitOdd).add(rk, 1);

            BIT& b = (r % 2 == 0) ? bitOdd : bitEven;        // 需要 k 与 r 奇偶相反
            // 数已插入值中 > -C[r] 的个数 = 总数 − 不大于 -C[r] 的个数
            int idx = (int)(upper_bound(all.begin(), all.end(), -C[r]) - all.begin());
            ans += (long long)b.sum(M) - b.sum(idx);
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

条件严格为正，等于阈值的前缀要排除。查询另一种下标奇偶；单个元素也是合法子数组。

## H. Fallen Leaves

### 题意

树的原始叶子集合固定。每次选两个尚未配对的叶子，把它们的距离加入代价，直到最多剩一个叶子。求最小总代价。

### 从零讲：把「配对的距离和」按边拆开

一对叶子的距离等于它们路径上的边数，所以总距离可以改成逐条边计费：每条边被多少条配对路径经过，就贡献多少。

![子树叶子数决定跨边配对奇偶](assets/h-edge.svg)

删去一条父子边，子树里有 $s$ 片需配对的叶子。子树内部配对每次消耗两个，剩下跨到外面的叶子数量与 $s$ 同奇偶。于是 $s$ 为奇数时至少跨一次，为偶数时下界为零。

这些边的下界可以同时达到。自底向上，把各儿子交来的未配对叶子两两配掉，每个子树最多保留一片交给父亲。某条边恰好在对应子树叶数为奇数时被这片剩余叶子跨过一次。叶子总数为偶数时根最终没有剩余，构造达到全部边的下界。

总数为奇数时，只要固定哪片叶子不参与，就回到偶数情形；正文用路径奇偶翻转，一次算完所有留下某片叶子的代价。

### 思路

#### 把路径距离改为逐边计费

一对叶子的距离就是连接它们的路径边数，因此所有配对的距离和，等于每条边被配对路径经过的次数之和。任取根，令 $s_v$ 为节点 $v$ 子树中的原始叶子数。

先考虑叶子总数为偶数、全部要配对的情况。删去父子边后，子树内有 $s_v$ 个待配叶子，内部配对每次消耗两个，所以跨出这条边的叶子数量必须与 $s_v$ 同奇偶。若 $s_v$ 为奇数，至少有一条配对路径跨边；若为偶数，逐边下界为零。因此总下界是
$$B=\sum_{v\ne\text{根}}[s_v\text{ 为奇数}].$$

#### 所有边的下界能够同时达到

自底向上处理子树，各儿子最多交来一个还未配对的叶子。如果当前节点自身是原始叶子，也把它加入候选。把这些剩余叶子两两配掉，只把最后可能剩下的一片交给父亲。

这样每个子树向上交出一片叶子，当且仅当其叶数为奇数。因此对应父子边恰好被跨一次或零次，正好达到上述下界；根处总叶数为偶数，不会留下叶子。代码无需输出配对，证明构造存在后，只统计奇数子树即可。

#### 奇数总数时，枚举留下谁的代价

若总叶数为奇数，必有且仅有一片原始叶子不参与。固定留下叶子 $x$，相当于从所有计数中去掉它，再套用偶数情形。只有根到 $x$ 路径上的子树叶数会减少一，所以这些边的奇偶贡献翻转：原来奇数减一，原来偶数加一。其他边完全不变。

令 $g_x$ 为根到 $x$ 路径上这些增减量之和，则固定留下 $x$ 的最优代价为 $B+g_x$。父亲到儿子的递推为
$$g_v=g_{\operatorname{par}(v)}+1-2[s_v\text{ 为奇数}],$$
根的修正为零。前序一次求出所有 $g_v$，最后只在原始叶子里取最小值。

例如三叶星形树中，三条边的子树叶数都是一，所以 $B=3$；留下任意一片叶子会减去它那条边的贡献，得到答案二，正是另外两片叶子间的距离。

原始叶子按无根树的度数不超过一判断，即使定根后根有一个儿子，它仍可能是原始叶子。配对不会产生新的候选叶子。代码用迭代遍历得到父亲在前的顺序，逆序求叶数、正序求修正，时间和空间均为 $O(n)$；单点树也自然得到零。

### 参考代码

```cpp
// H. Fallen Leaves —— S 固定为整棵树的所有叶子（度 <= 1），要把 S 里的顶点两两配对，
// 每次代价是两点距离，最多剩一个不配对，求总代价最小。
// 以 1 为根。记 s_v = 子树 v 里的叶子个数（含 v 自己是叶子的情况）。
// 结论一：最小总代价 = Σ_{v != 1} [s_v 是奇数]。
//   理由：把每条边 (parent(v), v) 看成「子树这一侧有 s_v 片叶子」。任一对匹配里的路径
//   都在这条边上「跨过」一次当且仅当两侧各有一片叶子被配到另一边 —— 一侧有 s_v 片叶子时，
//   跨过去的对数至少是 s_v 的奇偶性所强制的那个数；对每条边独立地取这个下界，
//   再用「相邻叶子先配对」的贪心就能同时达到所有下界。
// 结论二：|S| 是偶数时答案就是上面那个和；|S| 是奇数时必有一片叶子 x 落单，
//   此时每条边 (parent(v), v) 的子树叶子数整体减一（当 x 在该子树里），
//   所以代价 = Σ [s_v 奇] + Σ_{v 在 root→x 路径上且 v != root} (s_v 偶数 ? +1 : -1)。
//   对每片叶子 x 的这条「路径代价」取最小值即可，用一次 DFS 递推。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        // 迭代 DFS 定根（父在子前）
        vector<int> parent(n + 1, 0), order;
        vector<char> seen(n + 1, 0);
        vector<int> stk{1};
        seen[1] = 1;
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int w : adj[u]) {
                if (!seen[w]) {
                    seen[w] = 1;
                    parent[w] = u;
                    stk.push_back(w);
                }
            }
        }
        // 子树叶子数
        vector<int> s(n + 1, 0);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            int c = ((int)adj[u].size() <= 1) ? 1 : 0;
            for (int w : adj[u]) {
                if (w != parent[u]) c += s[w];
            }
            s[u] = c;
        }
        int leaves = s[1];
        long long base = 0;
        for (int v = 2; v <= n; v++) {
            if (s[v] % 2 == 1) base++;
        }
        if (leaves % 2 == 0) {
            cout << base << '\n';
            continue;
        }
        vector<int> g(n + 1, 0);                 // g[x] = 路径(除根)上「偶 +1 / 奇 -1」之和
        for (int u : order) {
            for (int w : adj[u]) {
                if (w != parent[u]) g[w] = g[u] + (s[w] % 2 == 0 ? 1 : -1);
            }
        }
        int best = INT_MAX;
        for (int v = 1; v <= n; v++) {
            if ((int)adj[v].size() <= 1) best = min(best, g[v]);
        }
        cout << base + best << '\n';
    }
    return 0;
}
```

### 易错点

叶子由原树度数决定，配对时不会产生新的候选叶子。奇数情况只能选择一片原始叶子不参与，不能在任意节点取最小修正。

## A. Games on the Train

### 题意

每座塔必须恰好加高一次，增量在 $1\ldots k$ 内。要求所有塔最后一样高，求最小 $k$。

### 思路

设所有塔最终达到共同高度 $H$。第 $i$ 座塔必须增加 $H-h_i$，所以每座塔的增量都已经由 $H$ 决定。由于每座塔必须操作一次且至少加一，最高的塔也不能保持不变，故 $H\ge\max h_i+1$。

固定 $H$ 后，最矮的塔需要最多增量，因此所需上限为 $k=H-\min h_i$。随着 $H$ 增大，这个值只会增大，所以选最小允许的共同高度 $H=\max h_i+1$ 最优，答案为 $\max h_i-\min h_i+1$。

这同时给出可行构造：给每座塔补到上述 $H$，增量至少为一，且不超过答案。比如高度 $[1,3,2]$，共同高度取四，增量为 $[3,1,2]$，最小上限为三。全部塔原来等高时也必须各加一，因此答案仍为一。代码一遍维护最大、最小值，时间 $O(n)$，额外空间 $O(1)$。

### 参考代码

```cpp
// A. Games on the Train
// 题意：n 座塔高度 h_i，每座塔恰好加一次 x_i（1 <= x_i <= k），要全部变成同一高度，
//       求最小的 k。
// 结论：设最终高度为 H。因为每座塔都要加至少 1，所以 H 必须 >= max(h) + 1；
//       而 H 越大，k = H - min(h) 越大，所以取 H = max(h) + 1 最优，答案 = max(h) - min(h) + 1。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 只用 iostream，不混 stdio
    cin.tie(nullptr);

    int t;
    cin >> t;                      // 测试组数
    while (t--) {
        int n;
        cin >> n;                  // 本组塔数
        int mx = 0, mn = INT_MAX;  // 最大 / 最小塔高
        for (int i = 0; i < n; i++) {
            int h;
            cin >> h;              // 读入第 i 座塔
            mx = max(mx, h);       // 维护最大值
            mn = min(mn, h);       // 维护最小值
        }
        // 目标高度 = mx + 1：最高的那座塔加 1，最矮的那座塔加 (mx + 1 - mn)
        cout << mx - mn + 1 << '\n';
    }
    return 0;
}
```

### 易错点

不能漏掉最后的加一；原来全等时答案也为一。

## B. Tatar TV Show

### 题意

一次可同时翻转二进制串中距离为 $k$ 的两个位置，问能否变成全零。

### 思路

一次操作只连接下标相差 $k$ 的两个位置，因此下标模 $k$ 相同的位置构成一条独立的链，链内相邻位置可以一起翻转，不同链之间无法互相影响。

同时翻转两个二进制位，会让链中一的数量增加二、减少二，或保持不变，所以每条链的一的数量奇偶性是不变量。目标全零的每条链都有偶数个一，故原来每条链也必须有偶数个一。只检查整个串的一的总数为偶数还不够，因为两条不同链中的单个一不能互相抵消。

充分性可以直接构造。沿一条链从头向尾处理，除最后一位外，若当前位为一，就翻转它和下一位，让当前位归零；若为零则跳过。之后只处理更后面的边，已经归零的位置不再变化。最后只剩链尾未处理，而链中一的数量始终为偶数，所以链尾也必为零。

因此无需真的执行翻转，代码按零基下标 $i\bmod k$ 计数，检查每个计数是否为偶数即可。链长为一时没有可操作的边，条件恰好要求这一位原本为零。时间 $O(n+k)=O(n)$，空间 $O(k)$。

### 参考代码

```cpp
// B. Tatar TV Show
// 题意：每次选 i（1 <= i <= n-k）同时翻转 s[i] 与 s[i+k]，问能否把串全变成 0。
// 结论：按下标 mod k 把位置分成 k 条链（r, r+k, r+2k, ...）。一次操作只作用在
//       同一条链的相邻两个位置上，所以每条链里 1 的个数奇偶性不变；要全 0
//       必须每条链的 1 的个数都是偶数。这个条件也是充分的：从链首往链尾贪心，
//       遇到 1 就翻它和它的后一个位置，最后一位由奇偶性保证自动是 0。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 只用 iostream
    cin.tie(nullptr);

    int t;
    cin >> t;                      // 测试组数
    while (t--) {
        int n, k;
        string s;
        cin >> n >> k >> s;        // 串长、间距、二进制串
        vector<int> cnt(k, 0);     // cnt[r] = 第 r 条链上 '1' 的个数
        for (int i = 0; i < n; i++)
            if (s[i] == '1') cnt[i % k]++;   // 按 mod k 归类
        bool ok = true;
        for (int r = 0; r < k; r++)
            if (cnt[r] % 2 == 1) ok = false; // 有奇数个 1 的链就无解
        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

不同余数类不能相互消除一个一；链长为一时它必须原本为零。

## C. Omsk Programmers

### 题意

两个非负变化中的数起初为正整数 $a,b$。一次可以给其中一个加一，或把其中一个除以 $x\ge2$ 向下取整。求使两数相等的最少操作次数。

### 思路

#### 把加法移动到除法之后

直接搜索加一可能让数值无限变大，需要先证明无需考虑这种增长。若某个数先加 $d$ 次再除以 $x$，结果为 $\lfloor(a+d)/x\rfloor$。也可以先得到 $\lfloor a/x\rfloor$，再补
$$\left\lfloor\frac{a+d}{x}\right\rfloor-\left\lfloor\frac a x\right\rfloor$$
次加一。这个差非负且不超过 $d$，所以新方案操作数不会更多，结果却完全相同。

反复交换加法与其后的一次除法，就能把每个数的所有除法移到前面、所有加法留到最后。两数的操作互不影响，所以分别整理即可。注意 $d$ 很大时商可能增加许多，不能把上面的差误认为至多一；真正需要的只是它不超过 $d$。

#### 剩余状态只由除法次数决定

若分别除 $i,j$ 次，当前两数为 $\lfloor a/x^i\rfloor$、$\lfloor b/x^j\rfloor$。剩下只有加一时，最优就是把较小数补到较大数，代价为两者差的绝对值；把两边继续抬高没有收益。因此答案是所有
$$i+j+\left|\left\lfloor a/x^i\right\rfloor-\left\lfloor b/x^j\right\rfloor\right|$$
的最小值。

代码用记忆化递归隐式枚举这些组合。状态 $f(a,b)$ 先尝试直接补齐的代价 $|a-b|$，再尝试除左数一次或除右数一次并加一。两数相等时答案零；某个数已经为零时不再除它，否则会递归回同一状态。

例如 $a=10,b=3,x=3$，直接补齐需要七次，但把十除以三立即得到三，只需一次。每个数严格下降到零只有对数种取值，状态数 $S=O((1+\log_x(a+1))(1+\log_x(b+1)))$。参考代码使用有序映射，时间为 $O(S\log S)$，记忆化空间 $O(S)$。每组除数可能不同，必须清空缓存。

### 参考代码

```cpp
// C. Omsk Programmers
// 题意：有两个整数 a、b，每次可以把其中一个加 1，或把其中一个整除 x（向下取整），
//       求让 a == b 的最少操作次数。
// 思路：设 f(a,b) 为最少次数，则 f(a,a)=0，否则
//       f(a,b) = min( |a-b|,                       // 只靠加 1 把小的补上去
//                     1 + f(a/x, b),                // 把 a 除一次
//                     1 + f(a, b/x) )               // 把 b 除一次
//       为什么「先加够再除」不用单独枚举：设 a = q*x + r（0 <= r < x），
//       先加 d 次再除得到 (a+d)/x <= q+1；而从 q 再加 (至多 1) 次同样能到 q+1，
//       代价 1 + 1 = 2 <= d + 1（只要 d >= 1），所以「除完再加」永远不更差。
//       状态只可能是 (a/x^i, b/x^j)，i,j <= 30，加记忆化后每组至多几百个状态。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll X;                                 // 本组测试的除数 x
map<pair<ll, ll>, ll> memo;           // 记忆化表（每组测试前清空）

ll f(ll a, ll b) {
    if (a == b) return 0;             // 已经相等
    pair<ll, ll> key(a, b);
    map<pair<ll, ll>, ll>::iterator it = memo.find(key);
    if (it != memo.end()) return it->second;   // 查表
    ll best = llabs(a - b);           // 方案一：把小的那个纯加 1 补上来
    if (a / X != a)                   // 方案二：把 a 整除 x（a=0 时除不动，跳过防死循环）
        best = min(best, 1 + f(a / X, b));
    if (b / X != b)                   // 方案三：把 b 整除 x
        best = min(best, 1 + f(a, b / X));
    memo[key] = best;                 // 存表
    return best;
}

int main() {
    ios::sync_with_stdio(false);      // 只用 iostream
    cin.tie(nullptr);

    int t;
    cin >> t;                         // 测试组数
    while (t--) {
        ll a, b;
        cin >> a >> b >> X;           // 读 a、b、x
        memo.clear();                 // 换组要清记忆化（x 变了语义就变了）
        cout << f(a, b) << '\n';
    }
    return 0;
}
```

### 易错点

加法次数 $d$ 任意大时，不能声称除后的商最多增加一；正确界是商增加量不超过 $d$。除到零后要阻止原状态递归自己。

## D. Brand New Tatar TV Show

### 题意

先手第一步可任取数组中的一个数，之后必须取一个尚未删除、且与上次取值 $x$ 满足 $x\le y\le x+k$ 的数。无数可取者输。现在替第一位玩家选首步，希望让随后轮到行动的 Egor 必胜，问是否存在这样的首步。

### 从零讲：必胜态与必败态

对有限的轮流行动游戏，只需区分两类状态：没有合法行动就是败态；存在一步能送给对手败态，就是胜态；所有行动都只能送给对手胜态，则自己是败态。这是由游戏长度从短到长得到的递推定义。

本题取值只会不降。一旦跳到更大的值，较小值永远不能再取，而那个更大值之前完全没被动过。因此状态不必记整个剩余多重集合，只要记当前值层、这一层还有几个副本。

设这一层还有 $r$ 个副本，跳到其他值能否获胜记作 $A$。没有同值副本时胜负为 $A$；还有副本时，可以取一个同值，把胜负反过来，也可以直接跳走，所以
$$W(r)=A\lor\neg W(r-1).$$
若 $A$ 真，全都为胜；若 $A$ 假，从 $W(0)=\text{败}$ 开始交替，恰好 $r$ 为奇数时胜。代入首步之后的 $r=c_j-1$，就是正文的计数奇偶公式。

### 思路

#### 首步的目标是给 Egor 一个胜态

Arseniy 替 Dabir 拿走第一个数后，接下来轮到 Egor，所以我们寻找的是“取掉某个首值后，下一位行动者必胜”的状态。胜态表示存在一步把败态交给对方，败态表示没有合法行动，或所有行动都交出胜态。

按不同取值递增分组，值为 $u_j$、数量为 $c_j$。由于后续选值只能不降，一旦已经取到 $u_j$，更小的数永久不可用，而更大的数此前一个都没有取过。因此状态只需知道当前值层和这一层剩余副本数量，不必保存整个删除集合。

#### 同值副本决定交替，跳跃决定直接获胜

设 $P_j$ 表示刚取掉该组第一个数、剩余 $c_j-1$ 个时，下一位行动者是否必胜。更大且能一步选到的组为 $j<j'\le R_j$，满足 $u_{j'}\le u_j+k$。

如果其中存在 $P_{j'}$ 为败，当前玩家可以直接跳到那组，拿走其第一个数，把败态交给对手。因此无论当前同值副本还剩多少，他都能获胜。

否则所有跳跃都会给对手胜态，不能帮助自己获胜。设当前还剩 $r$ 个同值副本，那么没有副本时为败，有副本时唯一可能的获胜方式是再拿一个同值并翻转胜负，故恰好 $r$ 为奇数时获胜。代入 $r=c_j-1$，就得到
$$P_j=[(j,R_j]\text{ 中存在败态}]\lor[c_j\text{ 为偶数}].$$
例如全数组都是同一个数，首步之后还剩 $c_j-1$ 次行动，Egor 能拿到最后一个当且仅当原数量为偶数。

#### 从大值向小值递推

右侧各组状态算好后，当前组才可计算，所以从右向左处理。用败态数量后缀和，区间 $(j,R_j]$ 内的败态数为两个后缀和之差，常数时间判断是否存在。右边界 $R_j$ 随值递增不下降，用双指针一次求完。

最后只要任意 $P_j$ 为真，选择该组的任意一个副本作首步即可。题目值域在 $1$ 至 $n$，参考代码直接计数并顺序提取非空组，无需比较排序，所以实际时间、空间都是 $O(n)$。组内副本可继续选，允许差为零，这也是数量奇偶性不能忽略的原因。

### 参考代码

```cpp
// D. Brand New Tatar TV Show
// 题意：Arseniy 先白拿一个数（记为 x），之后 Egor、Dabir 轮流拿一个 y，要求
//       0 <= y - x <= k（x = 上一个被拿走的数），拿不了的人输。问 Arseniy 是否存在
//       一种首发着法，使无论 Dabir 怎么下 Egor 都必胜（即先手交给 Egor 的是必胜局面）。
//
// 推导（把值去重成 u_1 < u_2 < ... < u_r，出现次数 c_j）：
//   拿走 u_j 后，所有 < u_j 的活子作废，而 >= u_j 的活子一个没动、且永远没被动过
//   （序列单调不减）。所以局面可以用 (j, c) 描述：x = u_j，还剩 c 个 u_j，
//   所有 > u_j 的值都完好无损。记 R_j = 满足 u_{j'} <= u_j + k 的最大 j'。
//   设 W(j,c) = 该局面轮到的人是否必胜，P(j) = W(j, c_j - 1)（首发拿走一个 u_j 后的局面）。
//     · 跳着拿：W(j,c) 可以走到 (j', c_{j'}-1)，j' ∈ (j, R_j]，胜负与 c 无关；
//     · 原地拿：c >= 1 时可以走到 (j, c-1)。
//   于是 A(j) := 「(j, R_j] 里存在 P(j') == false」= 跳到败态就必胜：
//     W(j,0) = A(j)；c >= 1 时 W(j,c) = A(j) or not W(j,c-1)
//     => A(j) 真则全真；否则 W(j,c) 就等于 (c 是奇数)。
//   代回 P(j) = W(j, c_j - 1) = A(j) or (c_j 是偶数)。
//   答案 = 存在 j 使 P(j) 为真。从右往左扫，用后缀计数查 (j, R_j] 里的败态个数，O(n)。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);   // 只用 iostream
    cin.tie(nullptr);

    int t;
    cin >> t;                      // 测试组数
    while (t--) {
        int n;
        ll k;
        cin >> n >> k;             // 数组长度、允许的最大增量 k
        vector<int> cnt(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int v;
            cin >> v;              // 读数组
            cnt[v]++;              // 计数
        }
        // 去重，得到递增的值表 u 与对应次数 c
        vector<int> u, c;
        for (int v = 1; v <= n; v++)
            if (cnt[v]) { u.push_back(v); c.push_back(cnt[v]); }
        int r = (int)u.size();

        // R[j]：值不超过 u[j] + k 的最大下标（双指针，u 递增所以 R 单调不减）
        vector<int> R(r, 0);
        for (int j = 0, p = 0; j < r; j++) {
            if (p < j) p = j;
            while (p + 1 < r && (ll)u[p + 1] <= (ll)u[j] + k) p++;
            R[j] = p;
        }

        // 从右往左定 P[j]；suf[j] = 下标 [j, r) 里「P 为假」的个数
        vector<char> P(r, 0);
        vector<int> suf(r + 2, 0);
        for (int j = r - 1; j >= 0; j--) {
            int bad = suf[j + 1] - suf[R[j] + 1];    // (j, R[j]] 中败态个数
            P[j] = (bad > 0) || (c[j] % 2 == 0);     // A(j) 或「剩偶数个」
            suf[j] = suf[j + 1] + (P[j] ? 0 : 1);
        }

        bool yes = false;
        for (int j = 0; j < r; j++)
            if (P[j]) yes = true;  // 存在一种首发着法把必胜局面交给 Egor
        cout << (yes ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

首步之后轮到 Egor，因此要寻找剩余局面为胜态的起点；这里与通常“先手挑一步让对手输”的目标相反。

## E. Friendly Gifts

### 题意

找两个互不重叠、长度相同的子数组，各自能重排成连续整数，合起来也能重排成连续整数。求最大的共同长度 $L$。

### 从零讲：单调队列（窗口最值为什么能 $O(n)$ 全算出来）

固定窗口长度后，每右移一步只加入一个新元素、移出一个旧元素。求窗口最小值时，用双端队列保留下标，保证对应值从队首到队尾递增。

新值 $x$ 进入时，弹掉队尾所有不小于 $x$ 的值：这些旧值更大且更早过期，以后不可能比 $x$ 更适合作最小值。再把已经离开窗口的队首下标弹出，剩下队首就是当前最小值。每个下标进出至多一次，所以全部窗口只需 $O(n)$。

最大值队列把比较方向反过来。本题还要第三个队列：先记 $\operatorname{prev}_i$ 为相同值上次出现的位置，再维护窗口内这些位置的最大值。它若不小于窗口左端，就证明有一对重复落在窗口里；否则全部互异。三个队列共同给出“互异且值域连续”的判定。

### 思路

#### 两段在位置上分离，值域上必须相邻

长度为 $L$ 的数组能重排成连续整数，当且仅当元素互不相同，且最大值减最小值为 $L-1$。仅看最大最小差不够，例如 $[1,1,3]$ 满足差为二，却有重复和缺失。

设两段各自的最小值为 $v,w$，它们的值集合分别是 $[v,v+L-1]$、$[w,w+L-1]$。合并后既不能重复，也不能断开，因此两个等长值域必须恰好首尾相邻，即 $|v-w|=L$。原数组中哪一段在前，与哪一段的值更小无关，所以两个方向都要查询。

#### 固定长度，一次算出全部合法窗口

长度上界为 $\lfloor n/2\rfloor$，从大到小枚举，第一次可行就是答案。对固定 $L$，用单调队列维护窗口最大、最小值。再预处理 $prev_i$ 为与 $a_i$ 相等的上一个位置，用第三个单调队列维护窗口内 $prev_i$ 的最大值。

窗口左端为 $s$ 时，没有重复当且仅当所有窗口内的 $prev_i<s$：若有重复，后一次出现的前驱就在窗口里；若某个前驱在窗口里，也立即说明存在重复。因此第三个队列给出完整的互异判定。将它与最大最小差条件结合，记录每个窗口是否好，以及它的最小值。

队列弹出已过期的下标；插入新值时，弹出队尾所有不可能再成为最优的旧候选。每个下标在每个队列中最多进出一次，故这一步为线性时间。

#### 扫描时只登记已经不重叠的窗口

当前窗口起点为 $i$，起点不超过 $i-L$ 的旧窗口才与它不重叠。每次向右推进，把刚满足条件的窗口 $i-L$ 加入集合，集合按合法窗口的最小值记录是否出现过。当前最小值为 $v$ 时，检查 $v-L$ 或 $v+L$ 是否已经出现。

例如两个窗口值集合为 $\{2,3\}$、$\{4,5\}$，最小值相差二，合并连续；但仍必须确认它们在原数组中的下标区间不重叠。按结束时间逐步登记，恰好把这项限制纳入查询，无需保存每对窗口。

每个长度只做常数次线性扫描，总时间 $O(n^2)$，空间 $O(n)$，符合 $n\le6000$。枚举中没有依赖长度可行性的单调性，不能直接改成二分；完全没有合法两段时保留答案零。

### 参考代码

```cpp
// E. Friendly Gifts
// 题意：从 a 中选两段**不重叠**的、长度相同的子段，要求每段单独「好」，并且两段
//       首尾相接后的数组也「好」。好 = 元素可以重排成严格递增 1 的序列，
//       即元素恰好是某段连续的 L 个整数（互不相同）。
// 思路：设两段长度为 L，第一段的值集合是 [v, v+L-1]，第二段是 [w, w+L-1]。
//       拼接后要有 2L 个互不相同的元素且连成一片，只能是两段区间紧挨着：|v-w| = L。
//       于是答案 = 最大的 L，使存在两个不重叠的长度 L 窗口，其最小值相差恰好 L。
// 做法：窗口「好」<=> 元素互不相同 且 max-min == L-1。对每个 L 用单调队列 O(n) 求出
//       所有窗口的 min/max/前驱最大值，再从左往右扫：扫到起点 i 时，把「结束于 i-1
//       及更早」的好窗口按它的最小值登记进 seen，然后查 seen[m+L] / seen[m-L]。
//       总复杂度 O(n^2)，n <= 6000，且 sum n <= 6000。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 只用 iostream
    cin.tie(nullptr);

    int t;
    cin >> t;                      // 测试组数
    while (t--) {
        int n;
        cin >> n;                  // 数组长度
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        // prv[i]：与 a[i] 相等的前一个下标（没有则 -1）
        vector<int> prv(n, -1), last(n + 1, -1);
        for (int i = 0; i < n; i++) {
            prv[i] = last[a[i]];
            last[a[i]] = i;
        }

        int ans = 0;               // 选不出两段时答案是 0
        for (int L = n / 2; L >= 1; L--) {          // 从大到小找第一个可行的 L
            vector<char> good(n, 0);                // 起点 s 的长度 L 窗口是否「好」
            vector<int> mn(n, 0);                   // 该窗口的最小值
            deque<int> dqQ, dqMn, dqMx;             // 窗口内 prv 的最大值 / 最小值 / 最大值
            for (int e = 0; e < n; e++) {           // 枚举窗口右端
                while (!dqQ.empty() && prv[dqQ.back()] <= prv[e]) dqQ.pop_back();
                dqQ.push_back(e);
                while (!dqMn.empty() && a[dqMn.back()] >= a[e]) dqMn.pop_back();
                dqMn.push_back(e);
                while (!dqMx.empty() && a[dqMx.back()] <= a[e]) dqMx.pop_back();
                dqMx.push_back(e);
                int s = e - L + 1;                  // 窗口左端
                if (s < 0) continue;
                while (dqQ.front() < s) dqQ.pop_front();    // 过期出队
                while (dqMn.front() < s) dqMn.pop_front();
                while (dqMx.front() < s) dqMx.pop_front();
                int lo = a[dqMn.front()], hi = a[dqMx.front()];
                // 互不相同 <=> 窗口内每个位置的前驱都 < s
                if (prv[dqQ.front()] + 1 <= s && hi - lo == L - 1) {
                    good[s] = 1;
                    mn[s] = lo;
                }
            }

            vector<char> seen(n + 2, 0);            // seen[m]：已有好窗口（结束位置更早）最小值 = m
            bool found = false;
            for (int i = 0; i + L <= n; i++) {
                int j = i - L;                      // 起点 j 的窗口结束于 i-1，与当前窗口不重叠
                if (j >= 0 && good[j]) seen[mn[j]] = 1;
                if (good[i]) {
                    int m = mn[i];
                    if (m + L <= n && seen[m + L]) { found = true; break; }   // 第二段紧挨在上面
                    if (m - L >= 1 && seen[m - L]) { found = true; break; }   // 第二段紧挨在下面
                }
            }
            if (found) { ans = L; break; }
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

值域宽度符合条件不代表互异，例如 $[1,1,3]$ 仍非法。只能登记结束位置严格在当前窗口之前的旧窗口。

## F1. Elections in Saransk (easy version)

### 题意

每个人从 $a_i$ 的正约数中选一个 $p_i$，要求 $\operatorname{lcm}(p_1,\ldots,p_n)=\prod p_i$。统计不同选择数组数量，对 $10^9+7$ 取模。

### 从零讲：把 lcm 与乘积拆到「每个质数的指数」上

把整数拆成质数幂后，乘法会把每个质数的指数相加，最小公倍数则取每个质数指数的最大值。例如 $12=2^2\cdot3$、$18=2\cdot3^2$，乘积里二的指数为三，lcm 里为二。

![lcm 与乘积的指数关系](assets/f-exponents.svg)

设选出的数中，质数 $q$ 的指数是非负整数 $e_1,\ldots,e_n$。题目要求 $\sum e_i=\max e_i$，只有至多一个指数非零才可能成立。不同质数的指数选择互不限制，而且各自不超过 $a_i$ 对应指数就等价于 $p_i\mid a_i$，因此各质数方案数相乘。

例如 $a=[4,2]$，只涉及质数二，允许指数上限为 $2,1$。合法选择为 $(0,0),(1,0),(2,0),(0,1)$，正好 $1+2+1=4$ 种。

### 思路

#### 等式可以对每个质数独立判断

固定质数 $q$，设第 $i$ 个人选出的数中该质数指数为 $e_i$，允许上限为 $C_i=v_q(a_i)$。乘积中该质数指数为 $\sum_i e_i$，最小公倍数中为 $\max_i e_i$。简单版 $x=1$，所以必须满足
$$\sum_i e_i=\max_i e_i.$$
所有指数非负，这个等式成立当且仅当至多一个人的指数大于零。如果两个人都含该质数，去掉最大指数后仍有正数，总和一定超过最大值。

#### 计数的是指数选择，而不是只选某个人

对质数 $q$，所有人都不用它有一种方案；若只让第 $i$ 个人使用，他可以选择指数 $1$ 到 $C_i$，有 $C_i$ 种。因此该质数的总方案数为 $1+\sum_i C_i$。

例如 $a=[4,2]$，二的指数上限为 $[2,1]$。合法指数数组为 $(0,0),(1,0),(2,0),(0,1)$，共四种。只统计“有两个人含二”会漏掉第一个人选择指数一或二的区别。

不同质数的指数可独立选择：对每个人，每个指数不超过对应上限，恰好等价于选出的数整除 $a_i$；也没有跨质数的额外限制。所以答案由乘法原理得到
$$\prod_q\left(1+\sum_i v_q(a_i)\right).$$

代码先筛最小质因子，逐个分解输入并累加各质数指数，再将实际出现过的质数对应因子相乘取模。本组结束后只清空这些被访问的质数，避免每组都扫描整个值域。数一不贡献质因子，它只能选择约数一，正好对应乘法中的空选择。

设值域上界为 $V$，筛法为 $O(V\log\log V)$，一组分解上界为 $O(n\log V)$，额外空间 $O(V)$。乘法中间值使用 $64$ 位整数，并在每次相乘后取模。

### 参考代码

```cpp
// F1. Elections in Saransk (easy version)
// 题意：每人选 a_i 的约数 p_i，问有多少个数组 p 满足 x*lcm(p) = prod(p)（本题 x = 1）。
// 关键：对每个质数 q，设 e_i = v_q(p_i)，则 lcm 的指数是 max e_i、乘积的指数是 sum e_i。
//       因为 e_i >= 0，sum e_i >= max e_i，等号成立当且仅当「至多一个人 e_i > 0」。
//       所以条件等价于：每个质数在所有人的 p_i 里最多出现一次（即各个 p_i 两两互素）。
// 计数：一个质数 q 要么不用，要么整份送给某个人 i（且 q | a_i），送的人有 v_q(a_i) 种指数选择。
//       各质数互相独立，所以答案 = Π_q ( 1 + Σ_i v_q(a_i) )。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 线性筛求最小质因子（a_i <= 5*10^5）
    const int MAXA = 500000;
    vector<int> spf(MAXA + 1);
    for (int i = 0; i <= MAXA; i++) spf[i] = i;
    for (int i = 2; (ll)i * i <= MAXA; i++) {
        if (spf[i] == i) {                       // i 是质数
            for (ll j = (ll)i * i; j <= MAXA; j += i)
                if (spf[j] == j) spf[j] = i;     // 只记最小质因子
        }
    }

    int t;
    cin >> t;
    vector<int> sumexp(MAXA + 1, 0);             // sumexp[q] = Σ_i v_q(a_i)
    vector<int> touched;                         // 本组测试用例里出现过的质数，便于清空
    while (t--) {
        int n;
        ll x;
        cin >> n >> x;                           // 本版恒有 x = 1
        for (int i = 0; i < n; i++) {
            int a;
            cin >> a;
            while (a > 1) {                      // 试除分解 a
                int q = spf[a], c = 0;
                while (a % q == 0) { a /= q; c++; }
                if (sumexp[q] == 0) touched.push_back(q);
                sumexp[q] += c;
            }
        }
        ll ans = 1;
        for (int q : touched) {
            ans = ans * ((1 + (ll)sumexp[q]) % MOD) % MOD;   // 因子 = 1 + Σ_i v_q(a_i)
            sumexp[q] = 0;                                   // 清空，供下一组使用
        }
        touched.clear();
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

累加的是指数，不只是含该质数的人数；数一的质因子集合为空，它的约数选择只有一种。

## F2. Elections in Saransk (hard version)

### 题意

每个人从 $a_i$ 的正约数中选 $p_i$，给定 $x$，要求 $x\cdot\operatorname{lcm}(p)=\prod p_i$。统计选择数组数量，对 $10^9+7$ 取模。数值上界为 $5\times10^5$。

### 从零讲：每人有上限的「定和方案数」

定和计数可以用多项式表达：一个人能选 $0\ldots C$，就写 $1+z+\cdots+z^C$。把所有人的多项式相乘，选择项的指数相加，因此 $z^S$ 的系数就是指数总和为 $S$ 的方案数。例如 $(1+z+z^2)^2$ 的三次项系数为二，对应 $(1,2),(2,1)$。

若 $g$ 人都没有上限，非负整数和为 $S$ 的方案数是 $\binom{S+g-1}{g-1}$：把 $S$ 个相同小球与 $g-1$ 个隔板排在一起，隔板间的小球数就是各人的取值，允许空段。

要求每人不超过 $C$ 时，用容斥扣除越界。指定 $j$ 人至少取 $C+1$，先给他们各放这么多，剩余和为 $S-j(C+1)$，仍用无上限公式。于是
$$[z^S](1+z+\cdots+z^C)^g=\sum_{j\ge0}(-1)^j\binom gj\binom{S-j(C+1)+g-1}{g-1}.$$
剩余和为负的项为零；没有人时多项式就是一。人数可以很大，但要算的次数只有三十多，因此这个求和很短。

组合数采用阶乘、逆阶乘预处理。模数为质数，非零数 $a$ 的逆元为 $a^{P-2}\bmod P$，把除法改成乘逆元；本题阶乘下标远小于模数，不会出现不可逆的零。不同上限组的系数再朴素卷积，就能完成正文的两次定和计数。

### 思路

#### 质数之间独立，但同一质数允许多人使用

固定质数 $q$，令 $k=v_q(x)$，每个人允许的指数上限为 $C_i=v_q(a_i)$。等式等价于
$$\sum_i e_i-\max_i e_i=k,\qquad0\le e_i\le C_i.$$
不同质数仍可独立选择，最后相乘。如果 $k=0$，仍是至多一个正指数，方案数直接为 $1+\sum_i C_i$；复杂计数只需处理整除 $x$ 的质数。

#### 枚举真正最大指数，避免指定最大值属于谁

令实际最大指数为 $M$，则总和必须为 $S=M+k$。先数所有人满足 $e_i\le\min(C_i,M)$ 且总和为 $S$ 的方案，再减去所有人满足 $e_i\le\min(C_i,M-1)$ 且总和仍为 $S$ 的方案，差值恰好是最大值等于 $M$ 的方案数。

这个做法允许多人同时取到最大值，却不会重复计数。若改成枚举“哪个人是最大值”，并列最大时就需要额外处理。不同 $M$ 对应互不相交的方案，累加即可。

例如上限 $[1,2]$、$k=1$，合法指数为 $(1,1)$ 与 $(1,2)$，它们的最大值分别为一、二。不存在正上限的人时，无法产生正的 $k$，该质数因子直接为零。

#### 用短多项式计算带上界的定和方案

一个人的指数可选 $0$ 至 $C$，对应多项式 $1+z+\cdots+z^C$。所有人相乘后，$z^S$ 的系数就是总和为 $S$ 的选择数量。按原上限分组，令 $cnt_t$ 为上限等于 $t$ 的人数。

枚举 $M$ 时，原上限小于 $M$ 的组保持其原多项式，把它们的乘积记为 $Q_{<M}$；其他人数记为 $G_M$，统一截断到上限 $M$。于是第一项来自
$$[z^S]Q_{<M}(z)(1+z+\cdots+z^M)^{G_M}.$$
第二项同理改用 $Q_{<M-1}$ 和统一上限 $M-1$。代码维护当前及上一份低上限乘积，每轮结束后把原上限恰为 $M$ 的组乘进去，为下一轮准备。

#### 同一上限的大组用容斥求系数

对 $g$ 个上限都为 $C$ 的人，先忽略上限。非负整数和为 $u$ 的方案数为 $\binom{u+g-1}{g-1}$。若指定 $j$ 人越界，先给每人扣掉 $C+1$，剩余和为 $u-j(C+1)$，因此
$$[z^u](1+z+\cdots+z^C)^g=\sum_{j\ge0}(-1)^j\binom gj\binom{u-j(C+1)+g-1}{g-1}.$$
负剩余和不参与，空组或上限为零时只有常数项一。`compPoly()` 实现的就是这个公式；组合数用阶乘、逆阶乘常数时间取得。

值域不超过 $5\cdot10^5$，单个质数指数最多十八，所需次数 $S$ 最多三十六，因此人数虽多，所有多项式都很短，直接截断朴素卷积即可。设 $d$ 为 $x$ 的不同质因子数、最大指数为 $E$、保留次数为 $S_{\max}$，多项式部分为 $O(dES_{\max}^2)$，再加筛与分解；存储为 $O(V+n+S_{\max})$ 量级。容斥减法要补模，零指数的人无需加入对应质数的列表。

### 参考代码

```cpp
// F2. Elections in Saransk (hard version)
// 题意：每人选 a_i 的约数 p_i，问有多少个数组 p 满足 x*lcm(p) = prod(p)（本题 1 <= x <= 5*10^5）。
// 关键：逐质数 q 看指数。设 e_i = v_q(p_i)、k = v_q(x)，则条件等价于
//         对每个质数 q：k + max_i e_i = Σ_i e_i.
//       k = 0  → Σ e_i = max e_i，即「至多一个人用 q」：方案数 1 + Σ_i v_q(a_i)。
//       k >= 1 → 需要 Σ e_i - max e_i = k，也就是「把最大值整份拿掉后，其余人恰好凑出 k」。
//       各质数彼此独立（p_i | a_i 也是逐质数各自的约束），所以答案 = Π_q N_q。
// 求 N_q：只考虑 q | a_i 的那些人，设 v_q(a_i) 的直方图为 cnt[1..maxc]。
//       枚举最大值 M、令 S = M + k，则
//         N_q = Σ_M [ A(M) - B(M) ],
//         A(M) = #元组，每人取值 <= min(v_q(a_i), M)、总和 = S（最大值恰好为 M 的情形含在里面）
//         B(M) = 同上但每人取值 <= min(v_q(a_i), M-1)（把「最大值恰好 M」减掉）
//       两个计数都是「每人有上界的定和方案数」，按上界分组后用
//         [x^u] (1+x+...+x^C)^g = Σ_j (-1)^j C(g,j) C(u - j(C+1) + g - 1, g - 1)
//       截断到 S（<= 37）多项式卷积求出：Q_{<M} = Π_{t<M} (1+...+x^t)^{cnt[t]} 沿 M 增量维护。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;
const int MAXA = 500000;

vector<ll> fact(MAXA + 64), ifact(MAXA + 64);

static ll pw(ll b, ll e) {
    ll r = 1; b %= MOD;
    while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
    return r;
}
static ll C(ll n, ll k) {                     // 组合数（模意义）
    if (k < 0 || n < 0 || k > n) return 0;
    return fact[n] * ifact[k] % MOD * ifact[n - k] % MOD;
}

// (1 + x + ... + x^cap)^g 的系数，只算到 maxdeg
// 公式：Σ_{j} (-1)^j C(g,j) C(u - j(cap+1) + g - 1, g - 1)
static vector<ll> compPoly(int g, int cap, int maxdeg) {
    vector<ll> r(maxdeg + 1, 0);
    if (g == 0 || cap == 0) { r[0] = 1; return r; }      // 空积 / 全 0 只能凑出 0
    for (int u = 0; u <= maxdeg; u++) {
        ll s = 0;
        for (int j = 0; j <= g && (ll)j * (cap + 1) <= u; j++) {
            ll t = C(g, j) * C(u - j * (cap + 1) + g - 1, g - 1) % MOD;
            if (j & 1) s = (s - t + MOD) % MOD; else s = (s + t) % MOD;
        }
        r[u] = s;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    fact[0] = 1;
    for (int i = 1; i < (int)fact.size(); i++) fact[i] = fact[i - 1] * i % MOD;
    ifact.back() = pw(fact.back(), MOD - 2);
    for (int i = (int)fact.size() - 2; i >= 0; i--) ifact[i] = ifact[i + 1] * (i + 1) % MOD;

    // 最小质因子筛
    vector<int> spf(MAXA + 1);
    for (int i = 0; i <= MAXA; i++) spf[i] = i;
    for (int i = 2; (ll)i * i <= MAXA; i++)
        if (spf[i] == i)
            for (ll j = (ll)i * i; j <= MAXA; j += i)
                if (spf[j] == j) spf[j] = i;

    int t;
    cin >> t;
    vector<int> sumexp(MAXA + 1, 0);          // 不整除 x 的质数：Σ_i v_q(a_i)
    vector<int> touched;
    vector<int> cnt(20);                      // 每个质数 q|x 的指数直方图 cnt[t]
    vector<vector<int>> explist;              // 与 cnt 配套：每个 q|x 收集到的 v_q(a_i)
    while (t--) {
        int n; ll x;
        cin >> n >> x;
        // 分解 x，得到 q|x 的质数表
        vector<pair<int,int>> xf;
        {
            ll y = x;
            for (int q = 2; (ll)q * q <= y; q++) {
                if (y % q == 0) {
                    int k = 0;
                    while (y % q == 0) { y /= q; k++; }
                    xf.push_back({q, k});
                }
            }
            if (y > 1) xf.push_back({(int)y, 1});
        }
        explist.assign(xf.size(), {});
        touched.clear();
        for (int i = 0; i < n; i++) {
            int a;
            cin >> a;
            while (a > 1) {
                int q = spf[a], c = 0;
                while (a % q == 0) { a /= q; c++; }
                int idx = -1;
                for (int j = 0; j < (int)xf.size(); j++)
                    if (xf[j].first == q) { idx = j; break; }
                if (idx >= 0) explist[idx].push_back(c);           // q | x：单独处理
                else {                                             // q ∤ x：累加 Σ v_q
                    if (sumexp[q] == 0) touched.push_back(q);
                    sumexp[q] += c;
                }
            }
        }
        ll ans = 1;
        for (int q : touched) {                                // 不整除 x 的质数：因子 1 + Σ v_q
            ans = ans * ((1 + (ll)sumexp[q]) % MOD) % MOD;
            sumexp[q] = 0;
        }
        for (int j = 0; j < (int)xf.size(); j++) {              // 整除 x 的质数：解 N_q
            int k = xf[j].second;
            fill(cnt.begin(), cnt.end(), 0);
            int maxc = 0;
            for (int c : explist[j]) { cnt[c]++; maxc = max(maxc, c); }
            if (maxc == 0) { ans = 0; break; }                  // 没人能被 q 整除 → 无条件可满足
            int maxS = maxc + k;                                // 需要系数到 maxS = maxc + k
            vector<ll> Qcur(maxS + 1, 0), Qold(maxS + 1, 0);    // Qcur = Q_{<M}，Qold = Q_{<M-1}
            Qcur[0] = Qold[0] = 1;
            ll N = 0;
            for (int M = 1; M <= maxc; M++) {
                int S = M + k;
                if (S <= maxS) {
                    int GM = 0;
                    for (int tt = M; tt <= maxc; tt++) GM += cnt[tt];       // 上界 >= M 的人数
                    vector<ll> pg = compPoly(GM, M, S);                     // (1+...+x^M)^{G_M}
                    ll A = 0;
                    for (int s = 0; s <= S; s++) A = (A + Qcur[s] * pg[S - s]) % MOD;
                    ll B = 0;
                    if (M == 1) {
                        B = (S == 0) ? 1 : 0;                               // 上界全 0：只有总和 0
                    } else {
                        int Gm1 = 0;
                        for (int tt = M - 1; tt <= maxc; tt++) Gm1 += cnt[tt];
                        vector<ll> pg2 = compPoly(Gm1, M - 1, S);           // (1+...+x^{M-1})^{G_{M-1}}
                        for (int s = 0; s <= S; s++) B = (B + Qold[s] * pg2[S - s]) % MOD;
                    }
                    N = (N + A - B + MOD) % MOD;
                }
                Qold = Qcur;                                            // 供下一轮当 Q_{<M}
                if (cnt[M] > 0) {                                       // Q_{<M+1} = Q_{<M} * (1+...+x^M)^{cnt[M]}
                    vector<ll> g = compPoly(cnt[M], M, maxS);
                    vector<ll> Qn(maxS + 1, 0);
                    for (int i = 0; i <= maxS; i++) {
                        if (!Qcur[i]) continue;
                        for (int u = 0; i + u <= maxS; u++)
                            Qn[i + u] = (Qn[i + u] + Qcur[i] * g[u]) % MOD;
                    }
                    Qcur.swap(Qn);
                }
            }
            ans = ans * N % MOD;
            if (ans == 0) break;
        }
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

多个位置可以并列最大值，用“上限至多 $M$ 减至多 $M-1$”避免重复计数。减法取模后要补模数。

## G. Criterion in Burlandia

### 题意

树上权值满足 $0\le a_i<2^{20}$。每次给出一条路径，统计它的非空连续子段中，按位异或不小于普通和的数量。节点与询问总数均不超过 $10^5$。

### 从零讲：为什么「异或 $\le$ 和」，取等又意味着什么

对两个非负整数，$a+b=(a\oplus b)+2(a\mathbin{\&}b)$，所以异或不会大于和。推广到多个数，设第 $t$ 位有 $c_t$ 个一，则普通和对该位的贡献是 $c_t2^t$，异或贡献是 $(c_t\bmod2)2^t$。每位的差都非负，所以相等当且仅当所有 $c_t\le1$。

![异或与和相等时没有重复二进制位](assets/g-path.svg)

因此题目的“大于等于”实际上只能取等，要求任意两个元素没有公共的一位。扩展区间时维护已占用位的按位或 $M$，新值 $a$ 合法当且仅当 $M\mathbin{\&}a=0$，然后令 $M\leftarrow M\mathbin{|}a$。

每个非零数至少占用一位，总共只有二十位，所以合法段至多含二十个非零数。这不代表区间长度至多二十：零不占任何位，可以夹入任意多次。由此得到算法的两个核心结构：只沿非零点寻找冲突，用长度与深度前缀和把大量零位置整体计数。

倍增表的含义是记录向上第 $1,2,4,8,\ldots$ 个祖先，跳任意步数时按二进制拆分；把“父亲”换成“最近非零祖先”，就得到跨越长零段的非零跳表。最近公共祖先用普通跳表求出，随后只需在它附近处理少量可能跨过转折点的区间。

### 思路

#### 先识别合法区间的真正限制

设某一二进制位在区间内出现 $c$ 次一。普通和在这一位提供 $c2^b$，异或提供 $(c\bmod2)2^b$，前者不小于后者；对各位相加可知异或永远不超过和。题目的反向不等式只能取等，而等号要求每一位最多被一个数使用。

因此维护已使用位的按位或掩码 $mask$，新值 $v$ 能加入恰当且仅当 $mask\mathbin{\&}v=0$。每个非零数至少使用一位，位数只有 $B=20$，所以一个合法区间最多含二十个非零数。零可以任意多，不能因此只检查长度二十的区间；算法要跳过零，同时保留零段的实际长度。

#### 冲突祖先和非零跳表

给树定根。对每个非零点 $f$，沿最近非零祖先向上扫描，累积掩码，记录第一次发生冲突的祖先 $b_f$。至多看到第二十一个非零点就会冲突，所以这一预处理每点只需 $O(B)$ 次检查。

普通倍增表用于最近公共祖先和按深度跳跃；另一张倍增表以“严格最近非零祖先”为父指针，用来直接取某方向上的第几个非零点。另记录根路径非零点数，便可计算任意祖先链含多少非零点。

零节点与其最近非零祖先拥有同一个向上冲突点：在二者之间加入的只是零，无法改变掩码。这使一整段零位置的贡献都能用“深度总和减去长度乘某个固定边界”计算。

#### 查询分成两种互不重叠的区间

对路径 $x\to y$，令最近公共祖先为 $L$。上行部分 $U=x\to L$ 包含 $L$，下行部分 $D$ 从 $L$ 的孩子到 $y$，不含 $L$。所有区间分成完全位于 $U$ 的区间，以及右端点位于 $D$ 的区间，后者允许跨过 $L$。

在 $U$ 内按左端点计数，沿祖先方向扩展。如果第一个冲突祖先为 $b$ 且它仍在查询链内，那么从左端点 $l$ 可选的右端点有 $dep_l-dep_b$ 个；若一路合法到 $L$，则有 $dep_l-dep_L+1$ 个。相邻两个非零点之间的左端点，拥有相同的首个非零点和同一个阻挡者，故可以整组求和。

代码预处理深度和，以及“非零点深度乘阻挡深度”“相邻非零点深度乘阻挡深度”等根路径前缀和。相邻非零深度之差就是组长，因此这些乘积前缀和相减，能得到整段的组长乘阻挡深度之和。紧靠 $x$ 的第一组可能被截断，靠近 $L$ 的组可能能延伸出查询边界，都需要现场修正；其余整段直接使用前缀和。

#### 跨过转折点的部分只修正少量非零组

对 $D$ 中的右端点 $r$，从它向左扩展，先沿祖先方向走。如果冲突点已经在 $D$ 内或恰为 $L$，合法左端点数就是两者深度之差，与另一端 $x$ 无关，根路径前缀和可以整段取出。代码的 $PSphi$ 保存这份贡献。

只有向上能通过 $L$ 的组，才要继续沿 $U$ 朝 $x$ 的方向寻找冲突。这些组必定位于 $D$ 最靠近 $L$ 的至多二十一个非零点中，否则尚未到 $L$ 就已经遇到二进制位重复。每个待修正组，先累积其向上到 $L$ 的掩码，再检查 $U$ 靠近 $L$ 的非零点，同样最多检查常数个位数规模。

若找到阻挡点在整条路径上的位置为 $p$，则右端点位置为 $r$ 时贡献 $r-p$；若直到 $x$ 都没有冲突，令 $p=-1$，贡献为 $r+1$。一组右端点共用阻挡者，因此组贡献就是右端位置之和减去组长乘 $p$。代码先减去该组原来计入的祖先贡献，再加上真实贡献，避免重复统计。下行开头可能全为零，也要单独作为一个组连接到上行部分。

#### 实现中的数值与边界

全零路径长度为 $m$ 时，答案应为 $m(m+1)/2$，这是零段长度不能丢失的直接检验。若所有权值都为一，则只有单点合法，任意方向的答案都应等于路径点数。最近公共祖先只归上行部分，不能算两次。

答案、前缀和以及深度乘阻挡深度的配对项都可能超过 $32$ 位，相关存储必须使用 $64$ 位整数，仅在乘法前转换还不够，接收结果的数组也必须足够宽。预处理为 $O(n\log n+nB)$；参考代码每次按序号跳非零祖先还需对数时间，单问上界为 $O(B^2\log n)$，空间 $O(n\log n)$。

### 参考代码

```cpp
// G. Criterion in Burlandia
//
// 关键转化（本题唯一的"想法"）：
//   对非负整数，异或 <= 和 恒成立（a + b = (a^b) + 2*(a&b)，推广到多个数就是
//   sum - xor = 2*(各级进位数) >= 0），且等号成立 <=> 这些数两两没有公共二进制位。
//   所以题目要数的就是「按位两两不相交」的子段。
//   又因为每个非零数至少占一位、总共只有 20 位，所以合法子段里至多 20 个非零数 ——
//   这条"局部性"（任何一次冲突都发生在最近 21 个非零元素之内）是整份代码的基础。
//
// 记路径位置 0..LL（x 在 0、y 在 LL），对每个右端点 r：
//   f(r) = 沿路径从 r 往前第一个与「以 r 结尾的极大合法块」冲突的元素位置（没有记 -1）。
//   那么以 r 结尾的合法左端点恰是 f(r)+1..r，共 (r - f(r)) 个 ⇒ 答案 = Σ_r (r - f(r))。
//
// 按 LCA 把路径切成 U（x 到 LCA，含 LCA）与 D（LCA 的子往下到 y）：
//   答案 = Σ_{r∈U}(r-f(r)) + Σ_{r∈D}(r-f(r))，两块用不同口径，各自把"与查询无关的部分"预处理：
//   · r ∈ D：往前 = 先沿 D 的祖先向上、过 LCA、再沿 U 往下朝 x。
//     前半段是纯祖先关系（与 x 无关）⇒ 预处理 bconfE/phi 后可用根路径前缀和 O(1) 求出；
//     只有"块能顶到 LCA"的那些 p（必在 D 最靠近 LCA 的 20 个非零元素里）需要现场沿 U 走 ≤21 步。
//   · r ∈ U：往前 = 向下朝 x，和 x 有关 ⇒ 换成"以 l 开头"的正向口径：
//     Σ_{l∈U}(以 l 开头的合法右端点个数，且右端点仍在 U 内)。正向是向上的祖先关系 ⇒ 同样可预处理；
//     同样只修 LCA 附近的 21 个非零元素，以及 U 顶端"全是零"的那一小段。
//   两块的并集 = 全部合法子段（U 内部 + 右端点在 D），不重不漏。
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
static const int LOG = 17;                 // 2^17 = 131072 > 1e5

int n, qn;
vector<int> a, par, dep;
vector<vector<int>> adj;
vector<array<int, LOG>> upj, nzj;           // LCA 跳表 / 非零祖先跳表
vector<int> nzp, nzn, ncnt;                 // 最近非零祖先(含自己/严格) / 根路径非零计数
vector<int> bconf, bconfE, D0;
vector<ll> val4v;       // 阻挡者（正向 / 反向）、阻挡者深度、配对项
vector<ll> PSdep, PSnzDepD, PSval4, PSphi;  // 各类根路径前缀和

// 当前查询的上下文（给几个小工具函数用）
static int curx, cl, cdd, cmU;

//---------------------------------------------------------------- 基础工具
// 跳表语义：nzj[u][0] = u 的最近"严格"非零祖先；nzj[u][k] = 沿它走 2^k 步
static int advance_nz(int u, int m) {
    for (int k = LOG - 1; k >= 0; k--)
        if ((m >> k) & 1) u = nzj[u][k];
    return u;
}
static int kth_nz_up(int u, int t) {        // u 向上的第 t 个非零祖先（含自己，t>=1）
    if (t <= 0) return 0;
    int w = nzp[u];
    return (t == 1) ? w : advance_nz(w, t - 1);
}
static int lca_of(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    int d = dep[u] - dep[v];
    for (int k = 0; k < LOG; k++) if ((d >> k) & 1) u = upj[u][k];
    if (u == v) return u;
    for (int k = LOG - 1; k >= 0; k--)
        if (upj[u][k] != upj[v][k]) { u = upj[u][k]; v = upj[v][k]; }
    return par[u];
}
static int anc_at_depth(int u, int d) {     // u 的深度为 d 的祖先（要求 d <= dep[u]）
    int dd = dep[u] - d;
    for (int k = 0; k < LOG; k++) if ((dd >> k) & 1) u = upj[u][k];
    return u;
}

// 以 f 开头的块在 U 内部能延伸的右端点个数（顶到 LCA 就算到 LCA 为止）
static ll Yf_U(int f) {
    int acc = a[f], u = nzn[f], steps = 0;
    while (u && dep[u] >= cdd && steps < 25) {
        if (a[u] & acc) return (ll)(dep[f] - dep[u]);          // 撞上冲突，右端点只到它前面
        acc |= a[u];
        u = nzn[u];
        steps++;
    }
    return (ll)(dep[f] - cdd + 1);                             // 一路通到 LCA
}

// D 中非零位置 p：把"以 p 结尾的极大合法块"往前（向上）推，返回阻挡者下标（-1 = 通到 x）
static int blocker_D(int p) {
    int acc = a[p], u = nzn[p], steps = 0;
    while (u && dep[u] > cdd && steps < 25) {                  // 先走 D 内的祖先
        if (a[u] & acc) return u;
        acc |= a[u];
        u = nzn[u];
        steps++;
    }
    if (u && dep[u] == cdd && a[u]) {                          // 再走 LCA
        if (a[u] & acc) return u;
        acc |= a[u];
    }
    int lo = max(1, cmU - 21);                                 // 最后沿 U 链从顶往下朝 x
    for (int t = cmU; t >= lo; t--) {
        int f = kth_nz_up(curx, t);
        if (f == cl) continue;                                 // LCA 上面已处理
        if (a[f] & acc) return f;
        acc |= a[f];
    }
    return -1;
}

// U 顶端那个非零元素的块往前（向下朝 x）推，返回阻挡者下标（-1 = 通到 x）
static int blocker_U_top() {
    if (cmU == 0) return -1;
    int p = kth_nz_up(curx, cmU);
    int acc = a[p];
    int lo = max(1, cmU - 22);
    for (int t = cmU - 1; t >= lo; t--) {
        int f = kth_nz_up(curx, t);
        if (a[f] & acc) return f;
        acc |= a[f];
    }
    return -1;
}

//---------------------------------------------------------------- 单次查询
static ll solve_query(int x, int y) {
    int L = lca_of(x, y);
    curx = x; cl = L; cdd = dep[L];
    int mL = ncnt[par[L]];
    cmU = ncnt[x] - mL;                                        // U 里非零元素个数
    int mD = ncnt[y] - ncnt[L];                                // D 里非零元素个数
    ll posL = (ll)(dep[x] - cdd);

    //================= P1：两端都在 U 内部的对 =================
    ll kU = dep[x] - cdd + 1;
    ll sumDepU = PSdep[x] - PSdep[par[L]];
    ll sumPosU = kU * dep[x] - sumDepU;                         // Σ_{l∈U} pos(l)
    // U 顶端的"全零段"：ncnt[u] == mL（[u..L] 内没有任何非零元素）
    int ustar = 0;
    if (ncnt[x] == mL) ustar = x;
    else {
        int w = x;                                              // 找最浅的"非全零"顶点，再取它父亲
        for (int k = LOG - 1; k >= 0; k--) {
            int u = upj[w][k];
            if (u && dep[u] >= cdd && ncnt[u] != mL) w = u;
        }
        int p = par[w];
        if (p && dep[p] >= cdd) ustar = p;
    }
    ll kz = 0, sumPosZ = 0, SzeroTop = 0;
    if (ustar) {
        kz = dep[ustar] - cdd + 1;
        ll sd = PSdep[ustar] - PSdep[par[L]];
        sumPosZ = kz * dep[x] - sd;
        SzeroTop = kz * (posL + 1) - sumPosZ;                   // 这些 l 的子段在 U 内全是零
    }
    ll sumPosFU = sumPosU - sumPosZ;                            // Σ_{l∈U, f(l)∈U} pos(l)
    ll G_all = kU - kz;                                         // 有 f(l) 的 l 的个数
    ll sumVal4 = PSval4[x] - PSval4[par[L]];
    ll sumDepD = PSnzDepD[x] - PSnzDepD[par[L]];
    // 配对项里只有"最顶端那个非零元素"的后继落在 U 外（或在 U 外方向），要剔掉
    ll pairExcl = (cmU >= 1) ? val4v[kth_nz_up(x, cmU)] : 0;
    // Σ_{f∈nz(U)} gapcount(f)*D0[f]（用配对求和 - 自身求和，再补回 f1 的特殊项）
    ll Df1 = 0, depf1 = 0, gc1 = 0;
    if (cmU >= 1) {
        int f1 = nzp[x];
        Df1 = D0[f1]; depf1 = dep[f1];
        gc1 = (ll)(dep[x] - dep[f1] + 1);
    }
    ll sumGC_D = (sumVal4 - pairExcl) - (sumDepD - depf1 * Df1) + gc1 * Df1;
    // EXC = 索引 1 与顶部 21 个（这些 f 的 Yf 必须现场算）
    ll G_exc = 0, sumGC_D_exc = 0, term_exc = 0;
    auto handle = [&](int t) {
        int f = (t == 1) ? nzp[x] : kth_nz_up(x, t);
        ll gpc;
        if (t == 1) gpc = (ll)(dep[x] - dep[f] + 1);
        else { int pv = kth_nz_up(x, t - 1); gpc = (ll)(dep[pv] - dep[f]); }
        G_exc += gpc;
        sumGC_D_exc += gpc * (ll)D0[f];
        term_exc += gpc * (((ll)(dep[x] - dep[f])) + Yf_U(f));
    };
    if (cmU >= 1) handle(1);
    for (int t = max(1, cmU - 21); t <= cmU; t++) if (t != 1) handle(t);
    ll G_safe = G_all - G_exc;
    ll sumGC_D_safe = sumGC_D - sumGC_D_exc;
    ll P1 = (ll)dep[x] * G_safe - sumGC_D_safe + term_exc - sumPosFU + SzeroTop;

    //================= P2：右端点在 D =================
    ll P2 = 0;
    if (dep[y] > cdd) {
        int c1 = anc_at_depth(y, cdd + 1);                      // D 的第一个顶点
        P2 += PSphi[y] - PSphi[par[c1]];                        // phi 前缀和（安全部分）
        // 初始段：r ∈ [c1, e0] 内没有任何非零元素 ⇒ 块要接到 U 那边去
        int firstnz = (mD > 0) ? kth_nz_up(y, mD) : 0;
        int e0 = firstnz ? par[firstnz] : y;
        if (dep[e0] >= dep[c1]) {
            ll k0 = dep[e0] - dep[c1] + 1;
            ll sd0 = PSdep[e0] - PSdep[par[c1]];
            int qb0 = (cmU > 0) ? blocker_U_top() : -1;
            ll posqb0 = (qb0 >= 0) ? (ll)(dep[x] - dep[qb0]) : -1LL;
            P2 += (k0 * (ll)(dep[x] - 2 * cdd) + sd0 - k0 * posqb0)
                  - (PSphi[e0] - PSphi[par[c1]]);
        }
        // 顶部 22 个非零元素里，凡是块能顶到/穿过 LCA 的都要现场修
        for (int t = mD; t >= max(1, mD - 21); t--) {
            int p = kth_nz_up(y, t);
            if (bconf[p] && dep[bconf[p]] >= cdd) continue;      // 安全：已由 PSphi 计入
            int qb = blocker_D(p);
            ll posqb = (qb >= 0) ? (ll)(dep[x] - dep[qb]) : -1LL;
            int nxt = (t > 1) ? kth_nz_up(y, t - 1) : 0;
            int e = nxt ? par[nxt] : y;                          // p 的"段"：p .. nxt 前一个
            ll k = dep[e] - dep[p] + 1;
            ll sd = PSdep[e] - PSdep[par[p]];
            ll phisum = bconf[p] ? (sd - k * (ll)dep[bconf[p]]) : 0;
            P2 += (k * (ll)(dep[x] - 2 * cdd) + sd - k * posqb) - phisum;
        }
    }
    return P1 + P2;
}

//---------------------------------------------------------------- 主程序
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        cin >> n >> qn;
        a.assign(n + 1, 0);
        for (int i = 1; i <= n; i++) cin >> a[i];
        adj.assign(n + 1, {});
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        par.assign(n + 1, 0); dep.assign(n + 1, 0);
        upj.assign(n + 1, {});
        vector<int> ord;
        ord.reserve(n);
        // 迭代 BFS 定根（1 号点为根）
        vector<int> stk{1};
        par[1] = 0;
        vector<char> vis(n + 1, 0);
        vis[1] = 1;
        for (size_t h = 0; h < stk.size(); h++) {
            int u = stk[h];
            ord.push_back(u);
            for (int v : adj[u]) if (!vis[v]) {
                vis[v] = 1; par[v] = u; dep[v] = dep[u] + 1; stk.push_back(v);
            }
        }
        for (int u = 1; u <= n; u++) upj[u][0] = par[u];
        for (int k = 1; k < LOG; k++)
            for (int u = 1; u <= n; u++) upj[u][k] = upj[upj[u][k - 1]][k - 1];
        // 非零链 / 计数 / 阻挡者 / 前缀和（BFS 序保证父亲先算）
        nzp.assign(n + 1, 0); nzn.assign(n + 1, 0); ncnt.assign(n + 1, 0);
        bconf.assign(n + 1, 0); bconfE.assign(n + 1, 0);
        D0.assign(n + 1, 0); val4v.assign(n + 1, 0);
        nzj.assign(n + 1, {});
        PSdep.assign(n + 1, 0); PSnzDepD.assign(n + 1, 0);
        PSval4.assign(n + 1, 0); PSphi.assign(n + 1, 0);
        for (int u : ord) {
            nzp[u] = a[u] ? u : nzp[par[u]];
            nzn[u] = a[par[u]] ? par[u] : nzn[par[u]];
            ncnt[u] = ncnt[par[u]] + (a[u] ? 1 : 0);
            nzj[u][0] = nzn[u];
            for (int k = 1; k < LOG; k++) nzj[u][k] = nzj[nzj[u][k - 1]][k - 1];
            if (a[u]) {                                   // 正向阻挡者：块从 u 往上走
                int acc = a[u], v = nzn[u], bc = 0, steps = 0;
                while (v && steps < 25) {
                    if (a[v] & acc) { bc = v; break; }
                    acc |= a[v]; v = nzn[v]; steps++;
                }
                bconf[u] = bc;
                D0[u] = bc ? dep[bc] : 0;
            }
            bconfE[u] = a[u] ? bconf[u] : (nzp[u] ? bconfE[nzp[u]] : 0);
            ll phi = bconfE[u] ? (ll)(dep[u] - dep[bconfE[u]]) : 0;
            val4v[u] = (a[u] && nzn[u]) ? (ll)dep[u] * D0[nzn[u]] : 0;
            PSdep[u] = PSdep[par[u]] + dep[u];
            PSnzDepD[u] = PSnzDepD[par[u]] + (a[u] ? (ll)dep[u] * D0[u] : 0);
            PSval4[u] = PSval4[par[u]] + val4v[u];
            PSphi[u] = PSphi[par[u]] + phi;
        }
        for (int i = 0; i < qn; i++) {
            int x, y;
            cin >> x >> y;
            cout << solve_query(x, y) << "\n";
        }
    }
    return 0;
}
```

### 易错点

合法段限制的是非零元素数量，零的数量不受限制。LCA 只归 $U$；全零段要保留实际长度。路径子段数量可能超过 32 位，答案使用 64 位。

## A. Divide and Conquer

### 题意

可以选择当前正整数 $x$ 的一个正因数 $z$，把 $x$ 除以 $z$。判断能否把给定的 $x$ 变成 $y$。

### 思路

一次操作把当前数变成它的因数。若连续进行了多次除法，最终结果仍整除上一次的数，而整除关系具有传递性，所以最终一定是最初 $x$ 的因数。这说明 $x\bmod y=0$ 是必要条件，单纯满足 $y\le x$ 还不够。

它也充分：若 $y\mid x$，选择 $z=x/y$，因为 $x=yz$，这个 $z$ 本身也是 $x$ 的正因数，一次操作就能得到 $x/z=y$。无需寻找一条分解链，也无需把 $x$ 分解成质因子。

例如 $12$ 可以直接除以三得到四，但无法到达五；当 $x=y$ 时可以不操作，也可以除以一。题目保证 $y$ 为正，代码直接做一次取模判断，每组时间、空间均为 $O(1)$。

### 参考代码

```cpp
// A. Divide and Conquer
// 操作：选 x 的正因数 z，令 x := x / z。z = 1 时 x 不变，z = x 时 x 变成 1。
// 一次操作后 x 变成 x/z，它一定是原 x 的因数；反过来任意因数 d | x 都能一步到达
// （取 z = x/d，它也是 x 的正因数）。所以「能到达的 x 值」恰好就是原 x 的全部因数，
// 问题退化成一句判断：y 是否整除 x。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int x, y;
        cin >> x >> y;                      // 1 <= x, y <= 100
        cout << (x % y == 0 ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

可以执行零次操作，所以 $x=y$ 时也成立。

## B. Good times Good times

### 题意

十进制表示中至多含两种不同数字的数称为 good。给定 good 数 $1\le x<10^8$，构造 $2\le y\le10^9$，使 $y$ 和 $xy$ 都 good。

### 思路

乘法可能产生进位，从而引入新的数字。一个避免进位的方法是把 $x$ 平移若干位后，与原来的 $x$ 放在互不重叠的位置上相加。

设 $x$ 有 $k$ 位，取 $y=10^k+1$。这时
$$xy=x\cdot10^k+x.$$
第一项的低 $k$ 位全是零，第二项又严格小于 $10^k$，相加没有进位，结果正好是把 $x$ 的十进制表示连续写两遍。例如 $x=122$ 时，选择 $y=1001$，乘积为 $122122$。

复制不会增加 $x$ 的数字种类，所以乘积仍是 good；$y$ 自身只含一和零，也至多两种数字。由于 $x<10^8$，有 $k\le8$，故 $11\le y\le10^8+1\le10^9$，同时满足数值范围与不能取一的限制。

代码从 $p=10$ 开始反复乘十，直到 $p>x$，此时 $p=10^k$，输出 $p+1$。当 $x$ 恰是十的幂时仍应继续增大，故循环判断使用大于等于。时间 $O(\log x)$，空间 $O(1)$，不必计算或输出乘积。

### 参考代码

```cpp
// B. Good times Good times
// 记 x 的十进制位数为 k，取 y = 10^k + 1：
//   · y 的写法是「1 + (k-1) 个 0 + 1」，数字集合是 {1} 或 {1,0}，最多两种数字，是 good；
//   · x * y = x * 10^k + x。因为 x < 10^k，x * 10^k 的低 k 位全是 0，加上 x 恰好把
//     这 k 位填满、不产生进位，所以 x * y 就是「把 x 写两遍」，
//     它的数字集合与 x 的相同 —— 题目保证 x 是 good（最多两种数字），于是 x * y 也是 good。
// 范围：x < 10^8 => k <= 8 => y <= 10^8 + 1 <= 10^9，且 y >= 11 >= 2。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        long long x;
        cin >> x;
        long long p = 10;                    // p = 10^k，k 从 1 开始
        while (x >= p) p *= 10;              // 让 p 成为「比 x 高一位」的 10 的幂
        cout << p + 1 << "\n";               // y = 10^k + 1
    }
    return 0;
}
```

### 易错点

用整数乘十求幂，避免浮点幂函数；题目只要求输出 $y$，无需输出乘积。

## C. RemovevomeR

### 题意

每次选择一个长度至少为二的回文子串，删除其中任意一个字符。给定二进制串，求能得到的最短长度。

### 思路

#### 同字符段都可以缩到一个字符

把串划分成极长的同字符段。某段长度至少为二时，其中任意两个相邻相同字符构成回文，可以删除一个，因此能把每段缩成一个字符。操作每次只能在长度至少二的回文中删一个，所以整个串永远不能被删空，下界为一。

若原来只有一段，反复执行上述操作就达到一。真正的阻碍发生在恰好两段的情况，比如 $\texttt{00011}$：任何跨分界的子串首尾字符不同，不可能回文；因此所有操作都只能在某一段内部进行，而一段只剩一个字符时便不能继续在该段内删除。两个段都永久非空，最短只能为二；各自缩到一个即可达到。

#### 三段以上反而能全部合到一段

先把每段缩成一个字符，得到长度至少三的交替串。若长度大于三，前三个字符一定是 $\texttt{010}$ 或 $\texttt{101}$，构成回文。选择这个回文并删除它的第一个字符，整个剩余串仍交替，长度减少一。反复执行，直到只剩三个字符。

这时改变策略：删除三位回文的中间字符，剩下两个相同字符，再删去一个即可。例如 $\texttt{0101}$ 先利用前三位删首字符，得到 $\texttt{101}$，再删中间的零，得到 $\texttt{11}$，最后变成单字符。

因此答案只在段数恰好为二时是二，其他情况都是一。代码从一段开始，每遇到相邻字符不同就增加段数；只需线性扫描，时间 $O(n)$，除字符串外额外空间 $O(1)$。删到三位之前选择首字符，是保持交替结构所必需的构造细节。

### 参考代码

```cpp
// C. RemovevomeR
// 结论：答案是 2 当且仅当 s 恰好有 2 个连续段（形如 0^a 1^b 或 1^a 0^b），否则答案是 1。
// 证明分三种情况（连续段 = 极长的同字符段）：
//   · 只有 1 段：整串同字符。长度 >= 2 时整串是回文，删掉任意一个字符仍是同字符串（还是回文），
//     可以一路删到只剩 1 个字符，故答案 1。
//   · 恰好 2 段：设分界在 p，长度 >= 2 的回文子串不可能跨过分界——跨分界的子串首字符是左边的字符、
//     尾字符是右边的字符，两者不同，不可能回文。所以每次操作只能删掉某一段内部的一个字符，
//     且被删的那一段长度至少为 2，删完该段仍非空：两段永远都在，长度永远 >= 2。
//     另一方面把两段各删到只剩 1 个字符就能得到长度 2，故答案恰为 2。
//   · >= 3 段：若某一段长度 >= 2，删掉该段内一个字符（该段自带长度为 2 的回文），段数不变；
//     反复做可以降到「每段长度都是 1」的交替串，且段数仍 >= 3。
//     交替串长度恰好为 3 时，整串就是回文 010/101，删中间字符得到 00/11（1 段）→ 再删到 1 个字符；
//     长度 > 3 时删首字符（用前三个字符组成的回文 010/101 作跳板）得到长度减 1 的交替串，递归下去。
//     故答案 1。
// 所以只要数出连续段数即可，O(n)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;
        int seg = 1;                      // 连续段数
        for (int i = 1; i < n; ++i)
            if (s[i] != s[i - 1]) ++seg;
        cout << (seg == 2 ? 2 : 1) << "\n";
    }
    return 0;
}
```

### 易错点

压成交替串后，缩短到三位的阶段删首位；若直接删中间位，会出现相邻相同字符，不能再声称交替形态保持不变。

## D. An Alternative Way

### 题意

一次操作选区间，从左端开始依次加一、减一、加一、减一。允许任意次操作，判断能否把数组 $a$ 变成 $b$。

### 思路

#### 为什么先看前缀总量

令目标变化量为 $d_i=b_i-a_i$，前缀和为 $S_i=\sum_{j=1}^i d_j$。一次操作从左端开始交替加一、减一，对任意前缀的贡献都只能是零或一：前缀还没碰到操作区间时为零；覆盖操作序列前若干项时，偶数项相消、奇数项剩下一；完整越过区间后仍保持这个总和。

因此无论操作多少次，每个前缀的总增量都不能为负。如果某个 $S_i<0$，目标要求这个前缀减少总量，必然无法实现。只看全数组总和不够，限制必须对每个前缀都成立。

#### 所有前缀非负时，可以明确构造

对每个 $i<n$，执行区间 $[i,i+1]$ 共 $S_i$ 次，它给第 $i$ 位加一、给第 $i+1$ 位减一；最后在单点区间 $[n,n]$ 上执行 $S_n$ 次。所有次数都非负，所以这些操作合法。

第一位的净变化是 $S_1=d_1$；中间第 $i$ 位得到前一个区间的 $-S_{i-1}$ 和当前区间的 $+S_i$，净变化为 $S_i-S_{i-1}=d_i$；最后一位同样是 $S_n-S_{n-1}=d_n$。于是每个位置都准确达到目标，这证明条件充分。

例如 $d=[2,-1,1]$，前缀为 $[2,1,2]$。对 $[1,2]$ 操作两次、对 $[2,3]$ 一次、对第三位两次，净变化正是所需数组。实现只需判断前缀，不输出这些可能很多的操作。

代码读完两个数组后累加差，一旦遇负值便可判否。时间 $O(n)$，保存输入空间 $O(n)$；前缀可能达到 $10^{14}$ 量级，必须使用 $64$ 位整数。

### 参考代码

```cpp
// D. An Alternative Way
// 记 d_i = b_i - a_i，S_i = d_1 + ... + d_i（前缀和）。结论：YES ⟺ 所有 S_i >= 0。
//
// 必要性：看一次操作 [l, r] 给 S_i 添了多少。位置 i 上加的是 +1, -1, +1, -1, ...（从 l 开始，l 处 +1）。
//   · i < l：0；
//   · l <= i <= r：取该交错序列前 i-l+1 项之和 = 「i-l 为偶数 ? 1 : 0」；
//   · i > r：同理 = 「r-l 为偶数 ? 1 : 0」。
//   三种情况都 >= 0 —— 每个操作对每个前缀和只增不减，所以 S_i 全 >= 0 是必要条件。
//
// 充分性：把 a 的每一位按 (-1)^i 换号看（i 从 1 开始）。一次操作在换号后的世界里表现为
//   「给区间 [l, r] 整体加 (-1)^l」= 一个带符号的区间加法。目标 D_i = (-1)^i · d_i 要写成
//   若干「区间 [l, r] 整体加 (-1)^l」之和。设 E_i / O_i = 「左端点为偶数 / 奇数的那些区间
//   在位置 i 上还活着的总量」：
//     · i 为偶数：可以现场新开一个区间，E_i 想多大就多大；而 O_i 只能从 O_{i-1} 往下降；
//     · i 为奇数：反过来。
//   由 D_i = E_i - O_i 逐位贪心（能停就尽量停、把量留到后面用），可行性条件化简后恰好是
//   「d 的所有前缀和 >= 0」（n <= 4、值域 [1,4] 的全枚举 BFS 也证实判据无例外）。
// 实现：逐位累加，任何时刻前缀和 < 0 就是 NO。O(n)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> a(n), b(n);
        for (int i = 0; i < n; ++i) cin >> a[i];
        for (int i = 0; i < n; ++i) cin >> b[i];

        long long pre = 0;                        // 前缀和最大 2e5 * 1e9 = 2e14，用 long long
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            pre += b[i] - a[i];
            if (pre < 0) { ok = false; break; }
        }
        cout << (ok ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

操作次数可能很大，构造只用于证明。前缀差和使用 64 位整数。

## E. Fair and Square

### 题意

树上每个点有正整数权值，路径值为路径上所有点权之积。统计互异无序三点组 $\{u,v,w\}$，使三条两两路径值的乘积为完全平方。

### 从零讲：三条路径的积 = 中位点上的值 $\times$ 平方

树上三个点的两两路径会相交于唯一的分叉中心，也可能其中一个点就是这个中心。把三条路径同时画出来：

![三点路径积的中心](assets/e-median.svg)

从中心走向 $u$ 的分支出现在路径 $u\!\to\!v$ 与 $u\!\to\!w$ 中，所以分支上的每个点恰好被乘两次；另外两条分支同理。中心则出现在全部三条路径里，被乘三次。因此总乘积可以写成
$$a_c\cdot\left(a_c\prod_{x\text{ 在三条分支上且 }x\ne c}a_x\right)^2.$$
括号的平方已经是完全平方，剩下只需 $a_c$ 为完全平方。

原本似乎要分解很多点权、处理巨大路径乘积，现在完全不必真正乘这些数。只用点权是否平方以及树的分支大小，便能计数所有三元组。

### 思路

#### 三条路径的中心留下唯一的奇数次贡献

树上三个不同点的两两路径有唯一公共中位点 $c$。它可能是三点之一，也可能是连接三条分支的另一个节点。除中心外，每个出现在路径并集中的点都位于某条分支上，恰好被两条路径经过；中心则被三条路径全部经过。

因此三条路径值的乘积等于 $a_c$ 乘某个整数的平方。点权均为正数，乘上平方不会改变质因子指数的奇偶，所以总乘积为平方当且仅当 $a_c$ 自身为完全平方。无须分解全部路径，也不应真的计算可能极大的乘积。

#### 固定中心后，只需选不同方向

删除中心 $c$ 后，邻接方向分别形成大小为 $s_1,\ldots,s_d$ 的连通块。若三点包含 $c$，另两点必须来自两个不同块，才会以 $c$ 为中位点，数量为 $e_2=\sum_{i<j}s_is_j$。若三点不含 $c$，则必须从三个不同块各选一点，数量为 $e_3=\sum_{i<j<k}s_is_js_k$。

从同一方向选两点时，它们之间的路径不会经过 $c$，所以不能算入这个中心。反过来，上述两种选择都保证三条路径在 $c$ 汇合。每组三点有唯一中心，故对所有平方权值节点累加 $e_2+e_3$，没有重复。

#### 用幂和压掉方向之间的枚举

令 $P_t=\sum_i s_i^t$。平方展开中，每个不同方向对出现两次，故 $e_2=(P_1^2-P_2)/2$。立方展开先排除两项或三项方向相同的项，可得
$$e_3=\frac{P_1^3-3P_1P_2+2P_3}{6}.$$
分母六对应三个不同方向的全部排列。这里 $P_1=n-1$，只需逐邻居累加平方和与立方和。

定根后，儿子方向大小为其子树大小，父亲方向为 $n-sz_c$。迭代遍历获得父亲在前的顺序，再逆序累加子树大小即可。所有节点的邻接表总长为 $2(n-1)$，所以总时间、空间都是 $O(n)$。

例如一条三点链，只有中间节点能作唯一三元组的中心，即使它度数只有二也有贡献，不能只检查度数至少三的节点。平方判定先取平方根，再用整数平方向两侧校正；答案及大小乘积使用 $64$ 位整数。

### 参考代码

```cpp
// E. Fair and Square —— 统计"好三元组"个数
// 关键结论：三个点 u,v,w 的三条路径之积 = a_c * (某个整数)^2，其中 c 是三条路径的交点
//          （即树意义下的"中位点"）。因为除 c 外每个顶点恰好在两条路径上出现、c 在三条上出现。
//          所以"乘积是完全平方" ⟺ a_c 本身是完全平方。
// 于是问题变成：对每个完全平方值的顶点 c，数出"以 c 为中位点"的三元组个数。
// 把 c 的每个邻接方向看成一堆（大小 s_d），c 自己算单独一堆（大小 1）：
//   三堆各取一点 -> e3(s)（三点都在三个不同方向）
//   取 c 加另外两堆各一点 -> e2(s)
// 用幂和公式 O(1) 求出，总复杂度 O(n)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);           // 关闭 stdio 同步，加快 cin
    cin.tie(nullptr);                      // 解除 cin/cout 绑定
    int T;                                 // 测试组数
    cin >> T;
    while (T--) {
        int n;                             // 顶点数
        cin >> n;
        vector<long long> a(n + 1);        // 每个顶点上的值
        for (int i = 1; i <= n; i++) cin >> a[i];
        vector<vector<int>> g(n + 1);      // 邻接表
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        // 1) 迭代 DFS：求父亲、遍历序（递归会爆栈，n 最大 2e5）
        vector<int> par(n + 1, 0), order;
        order.reserve(n);
        vector<int> stk;
        stk.push_back(1);
        par[1] = -1;                       // 根的父亲记 -1，方便"父亲方向"判断
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : g[u])
                if (v != par[u]) {         // 只有父亲这一个邻居是"上坡"
                    par[v] = u;
                    stk.push_back(v);
                }
        }
        // 2) 逆着遍历序累加出子树大小
        vector<long long> sz(n + 1, 1);
        for (int i = n - 1; i >= 1; i--) sz[par[order[i]]] += sz[order[i]];
        long long ans = 0;                 // 答案最大 C(2e5,3) ≈ 1.33e15，long long 够
        // 3) 逐点当"中位点"统计
        for (int c = 1; c <= n; c++) {
            long long r = (long long)sqrtl((long double)a[c]);   // 开方后回代校正
            while (r > 0 && r * r > a[c]) r--;
            while ((r + 1) * (r + 1) <= a[c]) r++;
            if (r * r != a[c]) continue;   // a[c] 不是完全平方 -> 以 c 为中位点的三元组全不好
            long long p1 = n - 1, p2 = 0, p3 = 0;   // 各方向大小的一次/二次/三次幂和
            for (int v : g[c]) {
                long long s = (v == par[c]) ? (n - sz[c]) : sz[v];  // 该方向的分支大小
                p2 += s * s;
                p3 += s * s * s;
            }
            long long e2 = (p1 * p1 - p2) / 2;                        // 两个不同方向各取一点
            long long e3 = (p1 * p1 * p1 - 3 * p1 * p2 + 2 * p3) / 6; // 三个不同方向各取一点
            ans += e2 + e3;                // 这两个情形合起来 = 以 c 为中位点的三元组数
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

不是只枚举度数至少三的中心：三点中包含中心时，两个方向就够。完全平方判断用整数平方回代校正，答案使用 64 位。

## F. A Bit Odd

### 题意

两人轮流从二进制串里删除一个子序列，要求被删子序列的逆序对数量为奇数；无合法操作者输。Alice 先手，双方最优，判断胜者。

### 思路

#### 把一次删除看成删掉一组图顶点

给每个字符建一个顶点，每个逆序对连一条边，即从靠左的一到靠右的零连边。删除的子序列有奇数个逆序对，正好表示被删顶点的内部边数为奇数。

某个零的度数是它前面的一的数量，某个一的度数是它后面的零的数量。最前的零段和最后的一段度数都为零，不参与任何逆序对，因此它们的长度不影响胜负判据。

其余同字符段全部为偶数长度，恰好等价于所有顶点度数为偶数：比较相邻零段之前的一的累计数量，可以逐段推出参与逆序的一段长度为偶数；反向比较相邻一段之后的零的累计数量，同样得到所有参与逆序的零段长度为偶数。反过来，各段长度都偶数时这些累计数显然偶数。这样的局面总边数也为偶数，因为每对相应段贡献的是两个偶数长度之积。

#### 不符合判据的局面都能一步获胜

若全串逆序对数为奇数，直接删掉整个串，对手无字符可选，立即失败。

若全串逆序对数为偶数，但并非所有顶点度数都偶数，则存在一个奇度顶点。只留下这个字符，删除其他所有字符；被删部分的内部边数等于原总边数减去这个顶点的度数，为奇数，因此删除合法。对手面对单字符，同样没有合法操作。

例如 $\texttt{110}$ 有两个逆序对，总数偶数，不能直接删全串；但任意一个一的度数为一，保留它、删除另一个一和零，就删去一个逆序对并留下单字符。

#### 偶数段局面无法一步到另一个偶数段局面

把被删顶点记为 $D$，留下的记为 $R$。原图每个顶点度数都偶数，对 $D$ 内顶点的度数求和，可知跨越 $D,R$ 的边数为偶数，因为内部边被算了两次。如果留下的局面也满足偶数段判据，其内部边数也为偶数；原总边数又为偶数，那么 $D$ 内部边数只能为偶数，与合法删除所需的奇数矛盾。

所以判据中的局面每次只能走到上一段已经证明的必胜局面，它自身就是必败态。Alice 面对它时 Bob 必胜；否则 Alice 有上述一步获胜策略。

实现只需划分极长同字符段，跳过最前零段与最后一段，检查其余段长度奇偶即可。时间、参考代码空间均为 $O(n)$。这里允许删的是子序列，因此“留下任意一个字符，删除其余”完全合法，不受连续性限制。

### 参考代码

```cpp
// F. A Bit Odd —— 取石子式的删子序列博弈
// 结论：把 s 拆成极大连续段（游程），Bob 胜当且仅当
//       除「第一段（若它是 0 段）」和「最后一段（若它是 1 段）」以外，每段长度都是偶数。
// 直观：0 段只可能作为「最靠左的 0 段」豁免，1 段只可能作为「最靠右的 1 段」豁免，
//       这两段一动就改变局面性质；其余段的奇偶性是可被对手利用的"破绽"。
// 判定只需扫一遍，O(n)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 关闭 stdio 同步
    cin.tie(nullptr);                       // 解除 cin/cout 绑定
    int t;                                  // 测试组数
    cin >> t;
    while (t--) {
        int n;                              // 串长
        string s;                           // 二进制串
        cin >> n >> s;
        // 1) 拆连续段：block[i] = (字符, 长度)
        vector<pair<char, int>> blk;
        for (char ch : s) {
            if (!blk.empty() && blk.back().first == ch) blk.back().second++;   // 并进上一段
            else blk.push_back({ch, 1});                                       // 新开一段
        }
        // 2) 逐段检查：不是"豁免段"的段必须长度为偶数
        int k = (int)blk.size();
        bool bob = true;                    // 先假设 Bob（后手）胜
        for (int i = 0; i < k; i++) {
            bool exempt = (i == 0 && blk[i].first == '0')      // 最左的 0 段：豁免
                       || (i == k - 1 && blk[i].first == '1'); // 最右的 1 段：豁免
            if (!exempt && (blk[i].second & 1)) { bob = false; break; }  // 有破绽 -> Alice 胜
        }
        cout << (bob ? "Bob" : "Alice") << '\n';
    }
    return 0;
}
```

### 易错点

忽略的只是最前面的零段、最后面的一段，其他零段和一段都要检查。子序列不要求连续，因此证明里“只留下一个字符”是允许的。

## G. Summmon

### 题意

一次操作可把一个元素加到或减到右边相邻元素上。定义 $f(b)$ 为任意次操作后数组极差的最小值，求给定正整数数组所有子数组的 $f$ 之和。

### 从零讲：操作锁住的「同余类」

从 $[6,4,8]$ 开始，第二项只能加减第一项的倍数，因此始终属于 $4+6\mathbb Z$；第三项则可以借助前两个数，按它们的 $\gcd$ 为步长变化，属于 $8+2\mathbb Z$。

![同余类与最小覆盖窗口](assets/g-window.svg)

一般地，每个前缀的 $\gcd$ 不变，位置 $j$ 只能在 $a_j+g_j\mathbb Z$ 里取值。这不仅是必要条件，也充分。相邻加减可以组合出“给较远位置加一个更早的数，同时还原中间位置”：先让前驱增加这个早期数，把前驱加到目标，再还原前驱、从目标减掉还原后的前驱，净效果就是给目标加了那个早期数。递归使用这个操作，可以给目标加减任意更早元素的整数倍。由裴蜀定理，所有这些组合恰好是前缀 $\gcd$ 的倍数。按从左到右固定目标值，就能同时达到各自同余类内的选择。

第一项 $a_l$ 永远不变，所以把“极差最小”看成找一个包含 $a_l$ 的最窄窗口。对一条同余类，离 $a_l$ 最近的左、右代表点足够判断是否与窗口相交。由于 $g_j$ 整除 $a_l$，这两个距离正是正文的 $q_j,p_j$。

图中第二项在 $6$ 左边最近是 $4$，右边最近是 $10$；第三项可以取任意偶数。窗口 $[4,6]$ 能同时碰到所有可达集合，得到 $[6,4,4]$，极差为二。将所有同余约束逐个加入，便是正文的窗口计算。

### 思路

#### 从三项例子理解可达值

对 $[6,4,8]$，首项永远为六，第二项只能在 $4+6\mathbb Z$ 内变化；第三项可以借助前两项的整数线性组合变化，步长为 $\gcd(6,4)=2$，所以可取任意偶数。选成 $[6,4,4]$ 可得极差二。

一般固定左端点 $l$，位置 $j>l$ 的前驱前缀最大公约数为 $g_j=\gcd(a_l,\ldots,a_{j-1})$。加减相邻前项保持每个前缀的最大公约数不变，所以该位置始终属于 $a_j+g_j\mathbb Z$。

这个同余条件也是充分的。相邻操作可以组合出“给较远位置加一个更早的值，且还原所有中间位置”：先把这个早期值加到目标的前驱，把前驱加到目标，再还原前驱并从目标减去还原后的前驱，净效果只给目标加了早期值。递归构造这种操作，便能加减任意前缀元素的整数倍。由裴蜀定理，这些线性组合恰好是 $g_j$ 的倍数。按从左到右的顺序固定目标值，前缀最大公约数保持不变，后面的调整也不破坏已经固定的前缀。

#### 最小极差变成一个覆盖同余类的窗口

首值 $a_l$ 不动，所以最终最小值与最大值构成的窗口必可写成 $[a_l-A,a_l+B]$，其中 $A,B\ge0$。模数 $g_j$ 整除 $a_l$，令
$$p_j=a_j\bmod g_j,\qquad q_j=(g_j-p_j)\bmod g_j.$$
该同余类在 $a_l$ 右边最近点的距离为 $p_j$，左边最近点距离为 $q_j$。窗口能选到该位置的一个可达值，当且仅当 $B\ge p_j$ 或 $A\ge q_j$。余数为零时可以直接选 $a_l$，没有限制。

固定左扩展量 $A$ 后，所有 $q_j\le A$ 的约束已满足，其他约束只能靠右侧，因此最小右扩展为 $\max_{q_j>A}p_j$。只需枚举零与各个 $q_j$ 作为 $A$：两个相邻阈值之间约束集合不变，增大 $A$ 只会变差。于是
$$f(l,r)=\min_{A\in\{0\}\cup\{q_j\}}\left(A+\max_{q_j>A}p_j\right),$$
空集合的最大值视为零。

`calcF()` 按 $q$ 降序扫描，已扫描项的最大 $p$ 就是当前尚未被左侧满足的右扩展量。同一个 $q$ 的项要先计算候选，再整组加入，因为条件是严格大于，而非大于等于。

#### 只有前缀最大公约数下降时才增加约束

向右加入 $a_j$ 时，如果 $g_j$ 没有下降，说明 $a_j$ 是 $g_j$ 的倍数，余数为零，不增加约束。因此只有最大公约数严格下降的位置会改变 $f$。正整数的真因数至多为原数的一半，所以每个左端点只有 $O(\log V)$ 个这样的转折。

代码从右向左枚举左端点。上一轮已经有从 $l+1$ 开始的区间最大公约数分段，把每段与 $a_l$ 求最大公约数并合并相同结果，就得到从 $l$ 开始的新分段。每段记录这个值首次出现的右端点，既能找出下降位置，也能得到该段包含多少个右端点。

按右端点推进，每遇一次下降就加入一个 $(q,p)$ 约束，重新线性扫描当前至多对数个约束求 $f$，然后乘上这一档右端点数量累加。首档没有任何限制，贡献零。时间 $O(n\log^2V)$，空间 $O(n+\log V)$。

原数组为正不代表操作过程或最终选择必须为正，题目没有这种限制，同余类可以向两侧延伸。所有子数组贡献总和可能超过 $64$ 位，代码用 `__int128` 累加，并通过十进制逐位输出。

### 参考代码

```cpp
// G. Summmon —— 求所有子区间的 f 之和
// 一、f 的刻画（可达值）
//   操作 b[i+1] += ±b[i] 保持 gcd(b1..bj) 不变，且 b[j] 只能落在 a[j] + gcd(a_l..a_{j-1})·Z 里；
//   反过来这些值都能达到（先用 Bézout 组合凑出任意倍数，最后再把右边位置调回目标）。
//   于是 f(l,r) = 把每个位置的值选在自己那条「同余类」里，使极差最小。
//   等价说法：取一个包含 a_l 的窗口 [a_l-A, a_l+B]，每个位置 j 的同余类要跟窗口有交。
//   同余类与窗口有交 ⟺ 最近的左右代表点之一落在窗口里，于是约束变成一对数：
//       m = gcd(a_l..a_{j-1})，p = a_j mod m（往右最近距离），q = (-a_j) mod m（往左最近距离）
//       约束 = 「p <= B 或 q <= A」；p = 0 时自动满足
//   f = min(A+B) 满足全部约束 = min over τ ∈ {0} ∪ {q_j} 的 (τ + max{p_j : q_j > τ})。
// 二、为什么只需看 O(log A) 个位置
//   m_{j+1} = gcd(m_j, a_j)，所以同一档（m 不变）里的 a_j 都是 m 的倍数 -> p = 0 -> 无约束。
//   一档里唯一可能非平凡的就是「gcd 掉档的那一个位置」，而 gcd 每掉一次至少减半，档数 <= 30。
// 三、求和
//   对每个左端点 l，用「后缀 gcd 序列」O(log A) 地拿到所有档与掉档位置，
//   随着 r 右移逐个加入非平凡约束，f 单调不减、每档才变一次，按区间长度加权累加。
//   答案会超 long long（最多约 1e9 * 2e10），所以用 __int128。
#include <bits/stdc++.h>
using namespace std;
using i128 = __int128_t;

// 输出 __int128
static void print128(i128 x) {
    if (x == 0) { cout << '0'; return; }
    if (x < 0) { cout << '-'; x = -x; }
    string s;
    while (x > 0) { s += char('0' + (int)(x % 10)); x /= 10; }
    reverse(s.begin(), s.end());
    cout << s;
}

// pairs 按 q 降序存放；返回 min(A+B)：A 取某个 q 或 0，B 取「q 比 A 大的那些对里最大的 p」
static long long calcF(const vector<pair<long long, long long>>& v) {
    long long best = LLONG_MAX, pmax = 0;     // pmax = 已经扫过的（q 更大的）那些对的 p 最大值
    size_t i = 0;
    while (i < v.size()) {
        long long q = v[i].first;             // 同一 q 值的算一组（约束里是 q_j > A，严格大于）
        best = min(best, q + pmax);           // 取 A = q
        while (i < v.size() && v[i].first == q) { pmax = max(pmax, v[i].second); i++; }
    }
    best = min(best, pmax);                   // 取 A = 0
    return best;
}

int main() {
    ios::sync_with_stdio(false);              // 关闭 stdio 同步
    cin.tie(nullptr);                         // 解除 cin/cout 绑定
    int t;                                    // 测试组数
    cin >> t;
    while (t--) {
        int n;                                // 数组长度
        cin >> n;
        vector<long long> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        i128 total = 0;
        // nxt：从 l+1 出发的「后缀 gcd 分段」列表，(gcd 值, 该值能取到的最小右端点)
        vector<pair<long long, int>> nxt;
        for (int l = n - 1; l >= 0; l--) {
            // 1) 把 a[l] 并进去，得到从 l 出发的分段（gcd 值严格递减）
            vector<pair<long long, int>> cur;
            cur.push_back({a[l], l});
            for (auto& pr : nxt) {
                long long g = std::gcd(a[l], pr.first);
                if (g == cur.back().first) continue;   // 与上一档相同：并档，保留更小的起点
                cur.push_back({g, pr.second});
            }
            nxt = cur;
            int K = (int)cur.size();
            // 2) 逐档累加：r ∈ [cur[t].second, cur[t+1].second - 1] 时，生效的约束是前 t 条
            vector<pair<long long, long long>> pairs;   // 按 q 降序维护的非平凡约束
            for (int k = 1; k < K; k++) {
                long long M = cur[k - 1].first;          // 掉档前的 gcd = 该位置的模数
                int j = cur[k].second;                   // 掉档位置：唯一可能有非平凡约束的地方
                long long p = a[j] % M;                  // 往右最近的同类值距离
                long long q = (M - p) % M;               // 往左最近的同类值距离
                if (p != 0) {                            // p = 0 表示该同余类含 a_l，自动满足
                    size_t pos = 0;                      // 插入排序保持按 q 降序
                    while (pos < pairs.size() && pairs[pos].first > q) pos++;
                    pairs.insert(pairs.begin() + pos, {q, p});
                }
                long long F = calcF(pairs);              // 当前约束下的 f
                int rlo = cur[k].second;                 // 这一段 r 的左右端
                int rhi = (k + 1 < K) ? cur[k + 1].second - 1 : n - 1;
                total += (i128)F * (i128)(rhi - rlo + 1);   // 每个 r 贡献同一个 f
            }
            // r ∈ [l, cur[1].second - 1]（没有非平凡约束）时 f = 0，不必累加
        }
        print128(total);
        cout << '\n';
    }
    return 0;
}
```

### 易错点

$g_j$ 不包含 $a_j$ 自己。窗口约束是二选一，不能要求左右代表点都落在里面。相同 $\gcd$ 段按右端点数量加权，不能只贡献一次。

## A. Iskander and Drawings

### 题意

字符 `'#'` 表示有画线，`'*'` 表示空白。每段连续的线从左右两头同时擦，每秒最多擦掉两格。求最长的一条线需要多少秒；没有线则为零。

### 思路

一条长度为 $L$ 的线，每秒从两端各擦一格；当剩一格时两人擦的是同一格，所以最后一秒也只计一次。擦完需要的时间为 $\lceil L/2\rceil$，用整数除法可写成 $(L+1)/2$。例如长度五依次变为三、一、零，恰好三秒；长度六也是三秒。

所需时间随长度不减，因此选择最长的连续井号段即可，不需要把各段时间相加。扫描时记录当前段长，遇到井号就加一并更新最大值，遇到星号就清零。最大值在每次延长时更新，因此串末尾的最后一段也会被计入。

若全是空白，最大段长保持零，公式也输出零。时间 $O(n)$，除输入串外额外空间 $O(1)$。题目只选择一条线让两人擦，目标是各段耗时的最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        // 扫一遍，数出每一段连续 '#' 的长度，取最大值
        int best = 0, cur = 0;
        for (char c : s) {
            if (c == '#') {
                cur++;                      // 这一笔还在继续
                best = max(best, cur);      // 顺手更新最长的一笔
            } else {
                cur = 0;                    // 遇到 '*' 说明这一段结束
            }
        }

        // 长度 L 的一笔：每秒两头各擦 1 厘米，长度降到 1 或 2 时下一
        // 秒整段擦掉，所以正好是 ceil(L / 2)，即整数除法 (L + 1) / 2
        cout << (best + 1) / 2 << "\n";
    }
    return 0;
}
```

### 易错点

遇到空白要把当前段长清零；最长段可能结束在串末尾。

## B. Nikita and Books

### 题意

第 $i$ 摞书有 $a_i$ 本。可以从至少有两本的某摞拿一本，移到右边相邻的一摞。判断能否使各摞数量严格递增。

### 思路

#### 右移不能补救缺书的前缀

最终每摞仍至少有一本，因为只允许从多于一本的摞中拿书。严格递增的正整数序列，第 $i$ 项至少为 $i$，所以前 $i$ 项至少需要 $1+2+\cdots+i=i(i+1)/2$ 本。

一次右移如果发生在前缀内部，总量不变；如果跨过前缀右边界，总量减少。书永远不会从右侧搬回来，因此每个原前缀总量都必须不小于上述三角数。比如 $[1,1,10]$ 的总书数很多，但前两摞只有两本，无法达到至少一本、两本，仍然无解。

#### 前缀都够时，逐摞留下最低需求

从左往右处理，对每个 $i<n$，在第 $i$ 摞留下恰好 $i$ 本，多余的全部搬到下一摞。处理到这里时，之前原前缀中的书只有两种去向：已经留在更左侧的 $1+\cdots+(i-1)$ 本，以及目前集中到第 $i$ 摞的余量。

因此当前可用量为原前缀和减去 $i(i-1)/2$，条件保证它至少为 $i$，一定能完成。搬运时最终还留至少一本，所以不会违反操作限制。最后一摞无需继续右移，总量条件保证它至少有 $n$ 本，从而得到 $1,2,\ldots,n-1$ 加一个至少为 $n$ 的严格递增序列。

这证明所有前缀条件既必要又充分。代码边读边维护前缀和，即使已发现失败也继续读完本组。时间 $O(n)$、额外空间 $O(1)$；前缀和与三角数乘法用 $64$ 位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;

        long long pre = 0;                  // 前缀和
        bool ok = true;
        for (int i = 1; i <= n; i++) {
            long long x;
            cin >> x;
            pre += x;
            // 最终数组必须严格递增、每堆至少 1 本，
            // 所以前 i 堆至少是 1 + 2 + ... + i = i(i+1)/2 本；
            // 而搬书只会把书往右挪，任何时刻前 i 堆的和都不会超过初始值
            if (pre < (long long)i * (i + 1) / 2) ok = false;
        }
        cout << (ok ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

每个前缀都要检查，不能只检查总量；前缀和和三角数使用 64 位。

## C. Stepan and Permutation

### 题意

长度 $n$ 的排列可以交换距离为 $x$ 或 $y$ 的两个位置，且保证 $x+y\le n$。判断能否排成 $1,2,\ldots,n$。

### 从零讲：位置的可达性由 $\gcd(x, y)$ 决定

把每个位置当成点，可交换的两个位置之间连边。沿一条路径反复交换，可以把元素送到该连通块内任意位置；树边上的交换也能实现连通块内部的任意排列。问题就变成每个元素的目标位置是否在同一块。

走一条边，下标变化为 $\pm x$ 或 $\pm y$，都不改变模 $g=\gcd(x,y)$ 的余数，这是必要限制。

还要证明相同余数确实连通，而且途中不出界。先看前 $x+y$ 个位置：若当前位置不超过 $y$ 就向右跳 $x$，否则向左跳 $y$。这等价于在长度 $x+y$ 的圆环上加 $x$，访问到的恰是一个模 $\gcd(x,x+y)=g$ 的余数类；每一步在原数组里都是合法交换边。所有更靠右的位置都能不断减 $x$ 接回这段。这样，有限边界内的连通性也得到了证明。

例如 $x=4,y=6$ 时，奇数位置与偶数位置互不连通，各自内部却可以自由重排。

### 思路

#### 把交换限制转成位置连通性

以每个位置为顶点，距离为 $x$ 或 $y$ 的位置连边。沿边交换可以把元素搬到同一连通块内的任意位置，而且连通图的树边交换足以实现块内任意排列。因此排序可行，当且仅当每个数的当前位置与它的目标位置属于同一块。

令 $g=\gcd(x,y)$。每条边的下标变化都是 $g$ 的倍数，所以不同模 $g$ 余数的位置永远不能互达。还需证明相同余数确实连通，不能只使用无界数轴上的整数线性组合，因为数组边界可能阻挡中间步骤。

#### 用题目的长度保证构造不越界的环

先看前 $x+y$ 个位置，这一段存在是因为题目保证 $x+y\le n$。对位置 $i$，若 $i\le y$，向右走 $x$；否则向左走 $y$。两种移动都留在这一段里，且都是合法交换边。

把这一段首尾相接来看，该移动就是模 $x+y$ 加 $x$。它生成的每个环恰好包含一个模 $\gcd(x,x+y)=g$ 的余数类，因此前面这一段的同余位置全部连通。对更靠右的位置，不断减 $x$，可以沿合法边回到这一段，并且余数始终不变。于是整个数组的连通块正好就是模 $g$ 余数类。

值 $p_i$ 排序后要去位置 $p_i$，故检查 $i\equiv p_i\pmod g$ 即可。所有元素都通过时，每个块里装的正是该块需要的数，能独立排好。例如 $x=4,y=6$ 时 $g=2$，奇数与偶数位置各自成块；若 $g=1$，全部位置连通，任何排列都能排好。

求最大公约数后线性读取并检查，时间 $O(n+\log\min(x,y))$，额外空间 $O(1)$。判断整除时差值可能为负，但余数是否为零不受影响。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        long long n, x, y;
        cin >> n >> x >> y;

        // 一次操作是「走 x 格」或「走 y 格」，所以任何一串操作
        // 净走的格数都是 g = gcd(x, y) 的倍数；
        // 反过来，在 x + y <= n 的保证下，同余类 mod g 里的位置全都连通
        long long g = gcd(x, y);

        bool ok = true;
        for (long long i = 1; i <= n; i++) {
            long long p;
            cin >> p;                       // 现在站在位置 i 上的是数值 p
            // 数值 p 要到位置 i，要求 p 与 i 同属一个模 g 同余类
            if ((i - p) % g != 0) ok = false;
        }
        cout << (ok ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

有限数组上的可达性需要用到 $x+y\le n$，不能只拿无界数轴上的 $\gcd$ 结论代替证明。

## D. Yaroslav and Productivity

### 题意

数组允许含负数。给定若干前缀终点，每个对应的操作可以把该前缀全部取反，任选操作执行。求数组总和最大值。

### 从零讲：前缀取反 —— 在「翻转点」处切段，段内符号锁死

例如只允许翻前 $2$ 项、前 $5$ 项，那么位置 $1,2$ 总是一起变号，位置 $3,4,5$ 也总是一起变号。它们各自构成一个不可再拆的段。

![前缀翻转划分符号段](assets/d-prefix.svg)

这些段的符号又可以独立选择。从最右的可控段开始：用最长前缀操作决定它的符号，随后用更短的前缀操作修正左侧，不会再碰到已经确定的右侧。依次向左，就能实现任意一组段符号。

一段的原和为 $S$，可选贡献只有 $S$ 和 $-S$，最优自然为 $|S|$。最后终点右侧从来不在任何操作内，不能选择符号。这解释了公式为何由若干绝对值与一个原样尾和组成。

### 思路

#### 可翻转终点把数组切成固定整体

把给定前缀终点排序为 $b_1\le\cdots\le b_m$，并令 $b_0=0$。同一段 $(b_{j-1},b_j]$ 内的所有位置，对任意一次允许操作来说总是同时被覆盖或同时不被覆盖，因此它们的最终符号变化必然一致。一段的原和为 $S$ 时，最终贡献只能是 $S$ 或 $-S$，最多为 $|S|$。

最长终点之后的尾部不在任何允许前缀中，完全不能改变，必须保留其原和。不能对尾部取绝对值，也不能把一段内的各元素分别取绝对值。

#### 各段最佳符号能同时实现

从最右侧可控段开始，决定是否执行最长前缀操作，使这段达到所需符号。这个操作也会影响左侧，但还没关系。接着用次长前缀调整左一段，它不会再影响已经确定的右侧。依次从右向左，就能实现任意一组段符号，特别是让每段贡献都为其段和的绝对值。

例如只允许翻前两项和前五项时，前两项是一块、第三至第五项是另一块。先用前五项操作决定后一块，再用前两项操作修正前一块，两块就能独立选择正负。

代码建立前缀和 $P_i$，对排序后的每个终点累加 $|P_{b_j}-P_{b_{j-1}}|$，最后加 $P_n-P_{b_m}$。重复终点只产生和为零的空段，不影响答案；相同操作也只需考虑执行次数奇偶，读不读即可实现两种选择。

建立前缀和为 $O(n)$，排序为 $O(m\log m)$，空间 $O(n+m)$。数组可含负数，前缀和、段和及答案都使用 $64$ 位有符号整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;

        vector<long long> pre(n + 1, 0);    // pre[i] = 前 i 个数的和
        for (int i = 1; i <= n; i++) {
            long long x;
            cin >> x;
            pre[i] = pre[i - 1] + x;
        }

        vector<int> b(m);
        for (int i = 0; i < m; i++) cin >> b[i];
        sort(b.begin(), b.end());           // 按位置从小到大处理这些「取反点」

        long long ans = 0;
        int last = 0;                       // 上一段的右端点
        for (int i = 0; i < m; i++) {
            // 段 (last, b[i]] 整体要么全正、要么全负（被翻转奇数次还是偶数次），
            // 它和别的段互不影响，所以这一段取 |段和| 就是它的最大贡献
            ans += llabs(pre[b[i]] - pre[last]);
            last = b[i];
        }
        // b_m 之后的那一段永远不会被翻转，只能取原值
        ans += pre[n] - pre[last];

        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

尾部不能取绝对值；可以独立选择的是整段的符号，不能把段内各元素分别取绝对值。

## E. Masha and the Garland

### 题意

可翻转二进制串中一个连续区间。每个独立询问给出 $l,r,k$，判断能否用不超过 $k$ 次翻转，让子串 $[l,r]$ 相邻位全部不同。

### 思路

#### 翻转整段，真正改变的是两侧连接关系

将相邻字符相同的位置称为坏边。区间内部的两个相邻字符会同时翻转，原来相同则翻完仍相同，原来不同则仍不同；区间外完全不变。只有区间左右边界处，一侧翻转、一侧不翻转，坏边与好边才会互换。

因此一次操作至多修复两条查询内部的坏边。如果当前有 $t$ 条坏边，至少需要 $\lceil t/2\rceil$ 次；即使允许操作碰到查询之外，也不能突破这个下界。

#### 按坏边顺序配对即可达到下界

设相邻两条待修坏边位于位置对 $(i,i+1)$ 与 $(j,j+1)$。翻转字符区间 $[i+1,j]$，恰好让这两条边改变状态，内部的其他相邻关系保持不变，所以同时修好它们且不制造新的内部坏边。

把坏边依次两两配对。如果总数为奇数，最后一条坏边位于 $(i,i+1)$，就翻转 $[i+1,r]$，只改变这一条查询内边；右边界之外即使受影响，也不属于本次目标。于是总次数正好为 $\lceil t/2\rceil$。

例如 $\texttt{0000}$ 有三条坏边。先翻第二个字符修复前两条，得到 $\texttt{0100}$，再翻最后一个字符，得到交替串，恰好两次。

对每对原相邻字符是否相同做前缀和，查询 $[l,r]$ 只统计左端点位于 $l$ 到 $r-1$ 的边。代码零基数组里的数量为 $pre[r-1]-pre[l-1]$，判断 $(t+1)/2\le k$ 即可。单字符区间的边数为零。所有询问独立，不真正修改串，预处理 $O(n)$，每问 $O(1)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        string s;
        cin >> s;

        // bad[i] = 「第 i+1 个字符和第 i+2 个字符相同」（0 起下标）
        // pre[k] = bad[0] + ... + bad[k-1]
        vector<int> pre(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int bad = (i + 1 < n && s[i] == s[i + 1]) ? 1 : 0;
            pre[i + 1] = pre[i] + bad;
        }

        while (q--) {
            int l, r, k;
            cin >> l >> r >> k;
            // 段 [l, r] 内部的相邻关系就是 bad[l-1 .. r-2]
            int bad = pre[r - 1] - pre[l - 1];
            // 一次「翻转某个子段」最多同时修好两个坏相邻（一次性打包），
            // 所以 t 个坏相邻最少要 ceil(t / 2) 次
            int need = (bad + 1) / 2;
            cout << (need <= k ? "YES" : "NO") << "\n";
        }
    }
    return 0;
}
```

### 易错点

长为一的子串没有坏边。查询的是相邻对的左端点 $l\ldots r-1$，不要多算右边界外的一对。

## F. Anya Loves Trees!

### 题意

有根树的孩子按编号升序排列，叶子上写着 $1\ldots k$ 的一个排列。可以把任意节点的孩子列表循环移位，判断能否让从左到右读到的叶子恰为 $1,2,\ldots,k$。

### 从零讲：循环移位只改变「从哪个孩子开始读」

一个节点的全部叶子，在最终叶序中始终占据一段连续位置。若最终全局按 $1,2,\ldots,k$ 排列，这个子树包含的叶值必须也是连续整数；它的儿子子树则是若干不能互相穿插的整块。

例如三个儿子分别含叶段 $[4,5],[6,7],[1,3]$。目标顺序只能是第三块、第一块、第二块，这正是循环移动起点，所以可行。若原来是 $[4,5],[1,3],[6,7]$，所需顺序会改变圆周上的相邻关系，循环移位无法做到。

因此在每个节点，只需知道每块的最小值、最大值，以及内部能否排好。连续性通过相邻两块的“前一最大值加一等于后一最小值”检查；可实现的块次序通过循环移位检查。由于父节点的操作只移动整块，不会破坏儿子内部已经整理好的顺序，后序归纳既是必要条件也是充分条件。

### 思路

#### 一个子树的叶子永远是不可穿插的一块

父节点调整孩子顺序时，移动的是整个儿子子树。子树内部可以继续调整，但其叶子在最终全局序列中始终连续。因此若全局最终是 $1,2,\ldots,k$，每个子树拥有的叶值必须恰好是一段连续整数。

从叶子开始向上处理，记录子树是否可行，以及最小叶值 $lo$、最大叶值 $hi$。叶子自身只有一个数，天然是一个可行区间。内部节点先要求每个儿子内部都能整理好，否则父亲无论怎么移动整块都无法修复内部乱序。

#### 连续值域确定了唯一所需孩子顺序

把儿子按最小叶值排序。若相邻两块满足前块最大值加一等于后块最小值，就能首尾相接成一个连续整数段；任何间隙或交错都意味着该节点的叶值无法形成目标中的连续一段。

因为叶值全局互异，目标递增顺序也唯一确定了这些儿子块的排列。接下来只需检查这个排列能否由原孩子列表循环移位得到。找到目标第一个孩子在原列表中的位置，再从那里绕一圈逐个比较。全部相同才合法；循环移位只改变起点，不允许反转或任意交换块。

例如原孩子块为 $[4,5],[6,7],[1,3]$，所需次序是第三、第一、第二块，正好一次轮换；若原来是 $[4,5],[1,3],[6,7]$，则目标顺序改变了环上的相邻关系，无法实现。

#### 后序归纳给出充分性

若儿子都能各自排成递增连续区间，且所需块次序是原列表的轮换，就先完成儿子内部操作，再在当前节点轮换到所需起点，得到整个子树递增。父亲之后只移动整块，不会破坏这个结果。由此逐层归纳，根可行就意味着全局确实可以完成。

代码按节点编号读入父亲，孩子列表天然保持编号升序。用迭代遍历后反转顺序，使儿子先于父亲处理，避免深链递归。各节点孩子排序的总时间不超过 $O(n\log n)$，其他检查线性，空间 $O(n)$。只有一个孩子时轮换条件自动成立，但仍要传递其内部可行性。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;

        vector<vector<int>> ch(n + 1);      // 每个点的孩子，天然按编号升序
        for (int i = 2; i <= n; i++) {
            int p;
            cin >> p;
            ch[p].push_back(i);
        }
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];

        // 迭代 DFS 求后序（孩子一定排在父亲前面），n 可达 2e5，递归会爆栈
        vector<int> order;
        vector<int> st;
        st.push_back(1);
        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            order.push_back(v);
            for (int c : ch[v]) st.push_back(c);
        }
        reverse(order.begin(), order.end());   // 反转为「孩子在前」的顺序

        vector<long long> lo(n + 1, 0), hi(n + 1, 0);
        vector<char> good(n + 1, 1);

        for (int v : order) {
            if (ch[v].empty()) {            // 叶子：它的值就是一段长为 1 的区间
                lo[v] = hi[v] = a[v];
                continue;
            }
            vector<pair<long long, int>> rng;   // (区间左端, 孩子编号)
            for (int c : ch[v]) {
                if (!good[c]) good[v] = 0;
                rng.push_back({lo[c], c});
            }
            if (!good[v]) continue;
            sort(rng.begin(), rng.end());   // 按区间左端排序 = 按「应有的先后」排

            int d = (int)rng.size();
            // 1) 这些区间必须首尾相接，正好拼成一段
            for (int j = 1; j < d; j++) {
                if (rng[j].first != hi[rng[j - 1].second] + 1) {
                    good[v] = 0;
                    break;
                }
            }
            if (!good[v]) continue;

            // 2) 「应有的孩子顺序」必须是「按编号升序」的一个循环轮换
            int pos = -1;
            for (int j = 0; j < d; j++)
                if (ch[v][j] == rng[0].second) { pos = j; break; }
            for (int j = 0; j < d; j++) {
                if (rng[j].second != ch[v][(pos + j) % d]) {
                    good[v] = 0;
                    break;
                }
            }
            if (!good[v]) continue;

            lo[v] = rng.front().first;
            hi[v] = hi[rng.back().second];
        }

        cout << (good[1] ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

循环移位保留圆周顺序，不等于任意重排。判断排列是否为轮换时需完整比较一圈，仅数线性序列里的一次下降并不充分。

## G. Yura and Deadlines

### 题意

第 $i$ 个作业的权值为非负整数 $a_i$。选若干作业，使任意两个选中下标都满足 $|i-j|>\max(a_i,a_j)$，求最大总权值。

### 从零讲：把 $|i - j| > \max(a_i, a_j)$ 拆成两条单变量条件

先把选中下标排序，只检查相邻选中作业就足够。例如 $h<j<i$，如果相邻两对合法，$i-h$ 比 $j-h$ 更大，已超过 $a_h$；又比 $i-j$ 更大，已超过 $a_i$，所以远处的一对也合法。这让“最后选中的是谁”成为足够的 DP 状态。

![把双侧距离限制拆成激活和查询](assets/g-sweep.svg)

对前驱 $j$，它向右要求空出的距离由 $a_j$ 决定；对当前点 $i$，它向左要求空出的距离由 $a_i$ 决定。直接枚举所有 $j$ 会平方复杂度，把两种限制分开后，一种随着扫描时间永久满足，另一种变成位置前缀。

线段树的每个叶子对应一个位置，尚未激活时没有贡献，激活后填入该位置的 $dp_j$；内部节点存两侧最大值。区间查询只访问对数个完整区间，因此能快速找出所有合法前驱里最好的一个。

### 思路

#### 选中位置只需检查相邻两项

将选中的作业按下标排序。若所有相邻选中作业都合法，任意更远的两个也合法：它们的距离比左端点到其下一项的距离更大，所以超过左端权值；也比右端点到其前一项的距离更大，所以超过右端权值。两项合起来就超过两端权值的最大值。

因此令 $dp_i$ 为最后选中位置是 $i$ 的最大收益，只需寻找一个合法前驱 $j<i$，并在其最优方案后接上 $i$。合法条件可以拆成
$$i-j>a_j\quad\text{且}\quad i-j>a_i,$$
即 $j+a_j<i$ 与 $j\le i-a_i-1$。

#### 两条限制分别用扫描时间和位置查询处理

从左往右扫描 $i$。对固定前驱 $j$，第一条限制从时刻 $i=j+a_j+1$ 开始永久成立，因此可以在这个时刻激活它。按 $j+a_j$ 分桶，处理 $i$ 之前把桶 $i-1$ 中的位置放入数据结构即可。因为权值非负，激活的必是已经计算过的前驱，不会用到未来状态。

数据结构按位置保存已激活的 $dp_j$，未激活位置视为负无穷。第二条限制只要求查询前缀 $[1,i-a_i-1]$ 的最大值，于是
$$dp_i=a_i+\max\left(0,\max_{j\text{ 已激活},\ j\le i-a_i-1}dp_j\right).$$
零表示不选前驱、只选当前位置。线段树支持单点写入和前缀最大值，各需对数时间。

例如下标二的权值为三，它最早能在处理下标六时作为前驱，因为距离四才严格超过三；如果当前作业自身权值更大，还需要通过查询上界进一步排除过近的前驱。这说明只按前驱的等待时间激活还不够，当前作业的距离要求也必须检查。

每个位置只激活一次、查询一次，最终答案取所有 $dp_i$ 的最大值。激活时刻超过整个数组范围的作业无需入桶，但它自身仍可以单独贡献答案。查询前缀为空时直接使用零。总时间 $O(n\log n)$，空间 $O(n)$，权值和采用 $64$ 位整数；两个严格不等式中的减一都不能省略。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll NEG = LLONG_MIN / 4;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<ll> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];

        // 迭代式线段树：维护「已经被激活的位置 j」上的 dp[j] 最大值
        int sz = 1;
        while (sz < n) sz <<= 1;
        vector<ll> seg(2 * sz, NEG);
        auto update = [&](int p, ll v) {          // 位置 p（1 起）用 v 取 max
            p += sz - 1;
            seg[p] = max(seg[p], v);
            for (p >>= 1; p; p >>= 1) seg[p] = max(seg[2 * p], seg[2 * p + 1]);
        };
        auto query = [&](int l, int r) {          // 闭区间 [l, r] 的最大值
            ll res = NEG;
            if (l > r) return res;
            l += sz - 1;
            r += sz - 1;
            while (l <= r) {
                if (l & 1) res = max(res, seg[l++]);
                if (!(r & 1)) res = max(res, seg[r--]);
                l >>= 1;
                r >>= 1;
            }
            return res;
        };

        // bucket[t] 收集所有满足 j + a_j = t 的 j：
        // 处理 i 之前，凡是 j + a_j < i 的 j 都已激活（t 随 i 一格一格扫过）
        vector<vector<int>> bucket(n + 1);
        for (int j = 1; j <= n; j++) {
            ll tt = (ll)j + a[j];
            if (tt <= n) bucket[(int)tt].push_back(j);
        }

        vector<ll> dp(n + 1, 0);                   // dp[i] = 以 i 结尾的最优总权值
        ll ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j : bucket[i - 1]) update(j, dp[j]);

            // 前驱 j 要满足：i - j > max(a_i, a_j)
            //   ⇔ j < i - a_i  且  j + a_j < i
            // 后者由「激活」保证，前者是一次前缀最大值查询
            ll lim = (ll)i - a[i] - 1;
            ll best = 0;
            if (lim >= 1) {
                if (lim > n) lim = n;
                best = max(0LL, query(1, (int)lim));
            }
            dp[i] = a[i] + best;
            ans = max(ans, dp[i]);
        }
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

不等式严格，所以激活时刻为 $j+a_j+1$，查询上界为 $i-a_i-1$。空前缀的最优权值视为零。

## A. Riptide

### 题意

三人各有 $a,b,c$ 枚代币。每轮开始，若任意两人数目相同就结束；否则最多者给最少者一枚。求进行多少轮。

### 思路

先把三人的数量排序为 $x\le y\le z$。若存在相等值，游戏在第一轮之前就结束，两侧差中至少一个为零，答案自然为零。

否则三者严格递增。在最小者或最大者碰到中间值之前，每轮都仍由同一个最大者给同一个最小者一枚，故经过 $t$ 轮后数量为 $x+t,y,z-t$。中间的人没有参与转移，数量始终为 $y$。

左边第一次相等需要 $y-x$ 轮，右边第一次相等需要 $z-y$ 轮，较早出现的就是停止时间，所以答案为两者最小值。两端也不可能在此之前互相追上，因为要相等必须先到达或越过位于中间的 $y$。

例如 $[2,5,9]$ 中左侧差三、右侧差四，三轮后变成 $[5,5,6]$，下一轮检查立即结束，共三轮。排序三个数和计算差值均为常数时间、常数空间，数量用 $64$ 位整数保存。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        long long v[3];
        cin >> v[0] >> v[1] >> v[2];
        sort(v, v + 3);              // 排成「最小、中间、最大」

        // 每一轮：最大的人给最小的人 1 枚，所以最小值每轮 +1、最大值每轮 -1，
        // 中间那个数始终不变。谁先追上中间值谁就结束（两人相等），
        // 于是轮数 = 两侧到中间的距离里较小的那个。
        cout << min(v[1] - v[0], v[2] - v[1]) << "\n";
    }
    return 0;
}
```

### 易错点

先检查相等再开始一轮，因此追到相等的轮数就是答案，不再多加一。

## B. Evanescent

### 题意

把字符串每段连续相同字符压成一个字符。必须删除原串中一个非首尾字符，求删除后压缩串的最小长度。

### 思路

压缩串长度就是原串的极长同字符段数。先从一段开始扫描，每遇到相邻字符不同就多一段，得到原段数 $runs$。

删除一个字符只会影响它所在的段及左右相邻段。如果该段长度至少为二，删完仍非空，段数不变。如果该段恰好只有当前字符，它会整段消失，使段数减少一；此时若左右字符相同，原来被隔开的左右两段还会合并，再减少一。

对于允许删除的内部位置 $i$，它独自成段恰当且仅当 $s_i\ne s_{i-1}$ 且 $s_i\ne s_{i+1}$。满足时，左右相同可减少二，否则减少一；不满足时减少零。枚举所有内部位置，取最大的减少量即可。

例如 $\texttt{aabaa}$ 删中间的 $\texttt{b}$，三段变为一段；$\texttt{abc}$ 删中间字符，三段变为两段；$\texttt{aaaa}$ 删除任意允许位置后仍只有一段。题目要求必须删一次，但当最大减少量为零时，执行一次不会改变段数的删除就行，并不是不操作。

首尾字符不可删除，所以枚举仅覆盖零基下标一至 $n-2$。每次只看相邻三个字符，总时间 $O(n)$，除字符串外额外空间 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        // runs = 压缩后 |f(s)|：相邻字符每变一次就多一段
        int runs = 1;
        for (int i = 1; i < n; i++)
            if (s[i] != s[i - 1]) runs++;

        // 只能删下标 1..n-2（0 起）。
        // 删掉长 ≥2 的段里任何一格，段还在，|f| 不变；
        // 只有删掉「长度为 1 的整段」才可能让 |f| 变小：
        //   左右邻居同字符 → 两段合并，少 2；
        //   左右邻居不同   → 只少掉这一段，少 1。
        int best = 0;
        for (int i = 1; i <= n - 2; i++) {
            if (s[i] != s[i - 1] && s[i] != s[i + 1]) {   // s[i] 自成一段
                if (s[i - 1] == s[i + 1]) best = 2;
                else best = max(best, 1);
            }
        }
        cout << runs - best << "\n";
    }
    return 0;
}
```

### 易错点

首尾禁止删除。必须删除一个字符，但没有可减少段数的位置时，压缩长度仍可保持不变。

## C1. Marenol (easy version)

### 题意

两个等长二进制串，允许把连续三位中的 $\texttt{001}$ 与 $\texttt{100}$ 互换，或把 $\texttt{110}$ 与 $\texttt{011}$ 互换。判断能否互相转化。

### 从零讲：一次操作，只在「同一奇偶类」里换位置

观察一次 $\texttt{001}\leftrightarrow\texttt{100}$：只把第一个与第三个字符交换，中间的零没有动。另一种操作的中间位是一，作用仍是交换端点。

![按奇偶位置拆开三格交换](assets/c-parity.svg)

当相隔两位的两个端点不同时，中间位只有零、一两种可能，恰好分别对应题目允许的操作。因此任意相隔二的不同字符都能交换。

把位置 $1,3,5,\ldots$ 抽成一个串，把 $2,4,6,\ldots$ 抽成另一个串。原操作就变成其中一个串内的相邻交换。这不会改变该串一的数量；反过来，可以像冒泡排序一样把所有一移到任意所需位置，故除了各自计数之外没有别的限制。

### 思路

#### 三位替换的本质是交换首尾

$\texttt{001}\leftrightarrow\texttt{100}$ 只交换相隔两位的端点，中间的零不动；$\texttt{110}\leftrightarrow\texttt{011}$ 也只交换端点，中间的一不动。只要两个端点不同，中间位无论是零还是一，都会对应某种允许操作；端点相同则交换没有必要。

因此可将奇数位置 $1,3,5,\ldots$ 抽成一个短串，偶数位置 $2,4,6,\ldots$ 抽成另一个短串。一次原操作等价于在其中一个短串里交换相邻的零与一。另一类位置虽然位于操作窗口中间，但它的字符保持不变，两类可以独立处理。

#### 每类一的数量就是完整判据

相邻交换显然不会改变每个短串一的数量，所以两个原串必须在奇数位置和偶数位置上分别具有相同的一数。反过来，若某类计数相同，就能通过相邻交换把各个一移动到目标位置，例如从左向右依次把需要的一搬到当前缺少一的位置；零会自动填充剩余位置。因此类内任意同计数二进制串都互相可达。

比如 $\texttt{100}$ 可以直接变成 $\texttt{001}$，一从第一位移动到第三位；却不能变成 $\texttt{010}$，因为它不能跨到另一奇偶类。只统计全串一数会漏掉这个限制。

代码同时扫描两串，分别累加两类的一数，四个计数完成后比较对应两项。时间 $O(n)$，除输入串外额外空间 $O(1)$，不需要真的输出交换过程。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string a, b;
        cin >> n >> a >> b;

        // 操作 = 把某个 a[i] 与 a[i+2] 换位（首尾不同的窗口恰好就是 001/100/110/011），
        // 所以字符永远只在「同奇偶」的位置之间流动：奇位上的 1 数、偶位上的 1 数都是不变量。
        int ca[2] = {0, 0}, cb[2] = {0, 0};
        for (int i = 0; i < n; i++) {
            ca[i % 2] += (a[i] == '1');
            cb[i % 2] += (b[i] == '1');
        }
        cout << (ca[0] == cb[0] && ca[1] == cb[1] ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

只统计全串一的数量不够；必须按下标奇偶分别统计。

## C2. Marenol (hard version)

### 题意

操作与 C1 相同，求把二进制串 $a$ 变成 $b$ 的最少操作次数；不能实现时输出 $-1$。

### 从零讲：最少相邻交换 = 按顺序配对的距离和

拆成奇偶位置的两个短串后，每一步都是把一个一与相邻的零交换。假设某个短串的一原来位于 $p_1<p_2<\cdots$，目标位于 $q_1<q_2<\cdots$。

给一按从左到右编号，它们无需相互跨越。交叉配对也不会更省：若 $p_i\le p_j$ 且 $q_i\le q_j$，则
$$|p_i-q_i|+|p_j-q_j|\le |p_i-q_j|+|p_j-q_i|.$$
把交叉的配对解开，距离和不会增大，因此顺序配对最优。

每步只把一个一移动一格，至少需要距离和这么多步；按顺序搬运一，遇到零就交换，恰好实现这些位移，也不会让一互相穿过。所以距离和就是最少相邻交换数。换回原串坐标时，每一步移动两格，答案需除以二。例如同一奇偶类的两个一从原下标 $1,7$ 移到 $3,5$，需要 $1+1=2$ 步。

### 思路

#### 先拆成两条相邻交换链

允许的三位操作只交换相隔两位的两个不同端点，中间位保持不变，而且中间为零或一都有相应操作。因此奇数位置、偶数位置各自形成一条可以做相邻零一交换的链，两个类别互不影响。

分别收集每类在原串和目标串中一的位置。某一类数量不同就不可能转化，输出 $-1$。下面假设两类数量都匹配，讨论每类的最小代价。

#### 从左到右的一应当按顺序配对

设一的位置为 $p_1<p_2<\cdots$，目标为 $q_1<q_2<\cdots$。把同样的一临时编号时，让它们交叉移动没有意义。对两对交叉配对，有
$$|p_i-q_i|+|p_j-q_j|\le|p_i-q_j|+|p_j-q_i|\qquad(i<j).$$
解开交叉不会增加总距离，所以存在最优方案把第一个一配给第一个目标、第二个配给第二个目标，依此类推。

一次操作在短链中只使一个一移动一格，所以至少需要所有一的位移距离之和。该下界也能达到：在两串第一个不同的位置，若目标需要一，就把右边最近的一沿零向左搬来；若目标需要零，则把相应的零向左搬来，等价于把中间的一依次向右搬。固定这个位置后处理后缀，整个过程中一的相对次序不变，每一步都用于完成顺序配对所需的移动，没有额外绕路。

#### 换回原坐标时除以二

代码保存的是原串下标，同一类相邻位置相差二，因此每对贡献为 $|p_j-q_j|/2$。例如同一类的一从原位置一、七移动到三、五，两个一各移动一次，代价为 $2/2+2/2=2$。

将两类的代价相加就是总最少次数。扫描得到的位置天然递增，无需排序；时间 $O(n)$，存位置空间 $O(n)$。总移动量可达平方规模，答案必须用 $64$ 位整数，不能先把有符号差直接除二而漏掉绝对值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string a, b;
        cin >> n >> a >> b;

        // 每个 1 只能一次挪两格：它在自己的奇偶类里就是一枚可以在相邻格之间滑动的棋子。
        // 两个奇偶类互不干扰，所以分别看：第 j 个 1 只要和对面的第 j 个 1 配对即可
        // （两串都已按下标升序扫出，天然有序），代价 = 距离 / 2，各步独立相加。
        vector<long long> pa[2], pb[2];
        for (int i = 0; i < n; i++) {
            if (a[i] == '1') pa[i % 2].push_back(i);
            if (b[i] == '1') pb[i % 2].push_back(i);
        }
        if (pa[0].size() != pb[0].size() || pa[1].size() != pb[1].size()) {
            cout << -1 << "\n";                      // 每个奇偶类里的 1 数必须一样
            continue;
        }
        long long ans = 0;
        for (int p = 0; p < 2; p++)
            for (size_t j = 0; j < pa[p].size(); j++)
                ans += llabs(pa[p][j] - pb[p][j]) / 2;
        cout << ans << "\n";
    }
    return 0;
}
```

### 易错点

距离先取绝对值，再除二；配对的是同一奇偶类中的第几个一。

## D. Silhouette

### 题意

正整数数组中，$b_i$ 定义为所有严格小于 $a_i$ 的元素之和。只给影子数组 $b$，求字典序最小的原数组 $a$，无解输出 $-1$。

### 思路

#### 正数让影子大小唯一决定原值分组

若两个原值相等，严格小于它们的元素集合相同，影子也相等。若原值 $u<v$，较大值的影子除了包含所有小于 $u$ 的元素外，还至少包含一个正的 $u$，所以影子严格更大。于是原值相等当且仅当影子相等，且两者大小顺序完全一致。

将不同影子排序为 $s_0<\cdots<s_{m-1}$，对应出现次数为 $c_k$，原值记为 $v_k$。最小原值之前没有更小元素，因此必须有 $s_0=0$，否则立即无解。

#### 相邻影子差锁定前一组的值

第 $k+1$ 组的影子相比第 $k$ 组，恰好多包含了第 $k$ 组的全部元素，因此
$$s_{k+1}-s_k=c_kv_k.$$
所以除最大值组外，每组的原值都被唯一确定。差值必须能整除该组个数，所得值还必须是正整数，并严格大于前一组原值；任何条件失败都说明不存在合法原数组。

例如影子为 $[0,0,4]$，零组有两个元素，相邻差为四，所以它们的原值都只能为二；最大组取三，得到 $[2,2,3]$。若影子改成 $[0,0,3]$，差三不能被组大小二整除，无解。

#### 最大组取最小允许值就得到字典序最小

最大组的值不会被任何更大元素的影子统计，因此没有下一条差分方程限制它。它只需严格大于上一组，最小取 $v_{m-2}+1$；若只有一组，所有影子为零，直接把所有原值取一。

其他组已经唯一确定，唯一可变的最大组所有位置都选择最小允许值，当然使原顺序下的数组字典序最小。由相邻差方程逐项相加，可恢复每组影子为之前所有组的总和，所以这些条件通过后也确实充分。

代码保留原影子顺序，用排序副本分组并求组值，最后二分查找每个原位置所属组输出。时间 $O(n\log n)$，空间 $O(n)$，影子差与重建值均用 $64$ 位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> orig(n), b(n);
        for (int i = 0; i < n; i++) {
            cin >> orig[i];
            b[i] = orig[i];
        }
        sort(b.begin(), b.end());

        // 影子值相同 ⟺ 值相同（值更大的那个，影子一定更大），所以按影子值分组是唯一的。
        // 设第 k 组（升序第 k 个不同影子值）的值的个数为 c_k，则
        //   影子值 s_k = 前缀「值 × 个数」之和 = c_0 v_0 + ... + c_{k-1} v_{k-1}，
        // 于是 c_{k-1} v_{k-1} = s_k - s_{k-1}，整组的值被影子差完全钉死；
        // 最后一组（最大值那组）没有人比它大，它的值可以自由取，取 v_{m-2}+1 最省（字典序最小）。
        vector<long long> sv;
        vector<long long> sc;
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && b[j] == b[i]) j++;
            sv.push_back(b[i]);
            sc.push_back(j - i);
            i = j;
        }
        int m = (int)sv.size();

        bool ok = true;
        if (sv[0] != 0) ok = false;                 // 最小那组的影子必须是 0
        vector<long long> gv(m, 0);
        long long prev = 0;                         // 上一组的值
        for (int k = 0; k + 1 < m && ok; k++) {
            long long d = sv[k + 1] - sv[k];        // = 第 k 组的 值 × 个数
            if (d % sc[k] != 0) { ok = false; break; }
            long long v = d / sc[k];
            if (v <= prev) { ok = false; break; }   // 各组的值必须严格递增
            gv[k] = v;
            prev = v;
        }
        if (!ok) {
            cout << -1 << "\n";
            continue;
        }
        gv[m - 1] = prev + 1;                       // 最大组取能取的最小值

        for (int i = 0; i < n; i++) {
            int k = (int)(lower_bound(sv.begin(), sv.end(), orig[i]) - sv.begin());
            cout << gv[k] << " \n"[i == n - 1];
        }
    }
    return 0;
}
```

### 易错点

原值严格为正，推导依赖这一点。最后一组没有下一项影子，不能套除法公式。

## E. Chronostasis

### 题意

正整数数组的差分为 $b_1=a_1$、$b_i=a_i-a_{i-1}$，差分被打乱后交给你。求可能的原数组中字典序最小的一个，无解输出 $-1$。

### 思路

#### 重排差分后，原数组就是前缀和

将给定差分按某个顺序排列为 $c$，重建数组满足 $a_i=\sum_{j=1}^i c_j$。于是目标变成排列这些数，使每个前缀和严格为正，同时前缀和序列字典序最小。

当前前缀和为 $s$ 时，下一差分 $x$ 必须满足 $s+x\ge1$，即 $x\ge1-s$。固定前缀下，下一项越小越好，所以应选择剩余差分中满足这个门槛的最小值。例如当前和三、剩余 $[-3,-1,4]$，门槛为负二，应选负一得到下一项二，不能选会让前缀变零的负三。

#### 为什么最小合法下一项不会堵死后续

所有差分总和 $S$ 无论如何排列都等于最后一项，因此 $S\ge1$ 是必要条件。如果它成立，那么在任意已经合法的前缀之后，都存在一种完成方法：先放剩余的所有非负数，让前缀和不减，再放剩余负数。后一阶段前缀和单调下降，最终停在固定的 $S\ge1$，因此途中也不会变成非正。

所以在可行输入中，任何保持当前前缀为正的选择都能继续完成。贪心只需选其中最小的下一项：若另一个可行答案与当前结果第一次不同，它在这一位只能更大，因此我们的答案字典序最小。

#### 多重集合支持动态门槛

代码用有序多重集合保存剩余差分，调用 `lower_bound(1-cur)` 找到最小可接元素，加入当前和并输出该前缀，再删除这个副本。找不到时说明无解；代码没有预先检查总和，但不可行输入最终也会在某一步暴露出来。

负差分并非不能选，门槛会随着当前和变化；零差分也可能合法，只是首项必须为正。重复值用迭代器删掉一个副本，不能按值一次删除全部。每步查找和删除为 $O(\log n)$，总时间 $O(n\log n)$，空间 $O(n)$，前缀和使用 $64$ 位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        multiset<long long> s;
        for (int i = 0; i < n; i++) {
            long long x;
            cin >> x;
            s.insert(x);
        }

        // b 是 a 的「首项 + 相邻差」这个多重集：把某一种排列 c 摆好后，a 就是 c 的前缀和。
        // 每一步只关心下一个 a_i = 当前和 + 选的元素；只要「当前和 + 元素 ≥ 1」，
        // 剩下的元素总还能排（先把非负的排完、再把负的依次减回去，最小值就是最终和 a_n ≥ 1），
        // 所以每步挑「能让新和最小、又不小于 1」的那个元素，即最小的 ≥ 1 - 当前和 的元素。
        multiset<long long>::iterator it;
        long long cur = 0;
        vector<long long> ans;
        bool ok = true;
        for (int i = 0; i < n; i++) {
            it = s.lower_bound(1 - cur);            // 最小的、能保证新和 ≥ 1 的元素
            if (it == s.end()) { ok = false; break; }  // 没有能接的，无解
            cur += *it;
            ans.push_back(cur);
            s.erase(it);
        }
        if (!ok) {
            cout << -1 << "\n";
            continue;
        }
        for (int i = 0; i < n; i++) cout << ans[i] << " \n"[i == n - 1];
    }
    return 0;
}
```

### 易错点

门槛随当前前缀和改变，负差分也可以合法。重复元素一次只删除一个副本；前缀和用 64 位。

## F. Whiplash

### 题意

给定偶数长度数组。一次操作选下标 $i$，保持 $a_i$ 不变，把所有其他元素异或上 $a_i$。判断能否通过任意次操作把 $a$ 变为 $b$。

### 思路

#### 位置顺序可以通过三次操作任意交换

设两位置当前值为 $u,v$。依次选位置 $i,j,i$ 操作，直接跟踪可知：第 $i$ 位最终变成 $v$，第 $j$ 位变成 $u$；其他位置先后异或的量总共为零，恢复原值。因此这三步恰好交换两个位置，任意排列都能实现，接下来只需研究可达多重集合。

#### 补一个零，操作变成公共异或

在数组外补一个额外的零。选中原值 $x$ 操作时，可以等价地先让这 $n+1$ 个值全部异或 $x$，再交换选中位置和额外位置：原选中值先变零，额外零先变 $x$，交换后原位置仍是 $x$，额外位置恢复零，其他位置正好异或 $x$。

忽略位置后，每步只是对扩展多重集合做一次公共异或。若进行了多步，所有公共异或合并成某个 $X$。最终额外集合必须仍包含零，所以原扩展集合中必须有值 $X$。若 $X=0$，多重集合没有改变；否则 $X$ 必须是原数组的某个元素，对它直接做一次操作就能得到同样的多重集合。

这证明任意多步的候选都能缩成“多重集合不变”或“选一个原值做一次操作”，而实际位置差异可由前述交换补齐。

#### 偶数长度让候选原值唯一

令原、目标数组总异或分别为 $S_a,S_b$。一次操作让其余 $n-1$ 个元素异或 $X$，由于 $n$ 为偶数，$n-1$ 为奇数，总异或恰好改变一个 $X$，故
$$X=S_a\oplus S_b.$$
因此无需枚举每个原值。先排序比较两数组，若多重集合已相同便可成功；否则计算唯一候选 $X$，检查它是否出现。如果存在，保留它的一个副本，其他所有值异或 $X$，再排序与目标比较。

例如 $[1,2]$ 选一后得到 $[1,3]$，总异或从三变成二，候选正是 $3\oplus2=1$。如果有多个相同的 $X$，只有被选中的那个副本不变，其余副本都会变零。

总异或相同不是完整可达判据，最终必须比较整个多重集合。时间由排序主导，为 $O(n\log n)$，空间 $O(n)$。补零只是证明工具，参考代码无需真正增加一个数组位置。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> a(n), b(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        for (int i = 0; i < n; i++) cin >> b[i];

        vector<long long> sa = a, sb = b;
        sort(sa.begin(), sa.end());
        sort(sb.begin(), sb.end());
        if (sa == sb) {                             // 一次操作都不做
            cout << "YES\n";
            continue;
        }

        // 连做两次操作，结果的多重集与「只做后一次」完全一样（i 与 j 只是换了个位置），
        // 所以任意多次操作的结果，多重集要么和 a 相同，要么和「对 a 做恰好一次操作」相同。
        // n 是偶数 ⟹ 一次操作把总异或和从 S_a 变成 S_a ^ a_i，于是被选的那个元素必是 x = S_a ^ S_b。
        long long x = 0;
        for (long long v : sa) x ^= v;
        for (long long v : sb) x ^= v;

        int idx = -1;
        for (int i = 0; i < n; i++)
            if (sa[i] == x) { idx = i; break; }
        if (idx == -1) {                            // 数组里没有这个元素，做不出 b
            cout << "NO\n";
            continue;
        }
        vector<long long> c = sa;                    // 实际做一次「选 x 去异或其它元素」
        for (int i = 0; i < n; i++)
            if (i != idx) c[i] ^= x;
        sort(c.begin(), c.end());
        cout << (c == sb ? "YES" : "NO") << "\n";
    }
    return 0;
}
```

### 易错点

被选中的那个副本不参与异或；其他等值副本仍要改变。总异或相等只是筛选条件，必须比较完整多重集合。

## G. Nightcrawler

### 题意

把有根树的全部节点分成恰好 $k$ 个集合，每个集合中的点两两具有祖先关系，得分为该集合内最大权值。对所有 $k=1\ldots n$ 求总分最大值，不可行输出 $-1$。

### 从零讲：叶子各开一条链，往上走时只能接进一条

两两具有祖先关系的点只能位于同一条向下路径，因此每个集合可以看作一条链，但不要求包含路径中间的所有节点。不同叶子之间没有祖先关系，一条链最多含一个叶子；至少需要 $L$ 条链。每个叶子开一条链，向上把父节点接入某条子链，就能恰好使用 $L$ 条。

![选择较小的链最大值接入父节点](assets/g-chains.svg)

图中两个叶子值为 $10,30$，根值为 $25$。把根接到 $10$ 那条链，原来的 $10$ 被 $25$ 覆盖，得分 $55$；若接到 $30$，得分只有 $40$。所以要尽量少损失一个原有分数。

在构造出的每条链中，只有一个最大值正在计分，其他节点的值都进入备用列表。若再允许一个集合，可以取出某个备用节点，让它自成一个集合；原链的最大值仍在，其他点仍两两有祖先关系，所以总分恰好多出该备用值。连续取出若干点也始终合法，因此备用值的恢复彼此独立，按从大到小恢复即可。

小根堆用来快速找到当前最小的链最大值；合并时把元素少的堆倒入元素多的堆。一个元素每次作为小堆成员搬家后，所在堆的大小至少翻倍，所以搬家次数只有对数级。

### 思路

#### 最少链数等于叶子数

集合中的点两两有祖先关系，所以它是一条祖先链，但可以跳过路径上的中间节点。不同叶子互不为祖先，不能进入同一个集合，因此至少需要叶子数 $L$ 条链。反过来，每个叶子开一条链，自底向上把父节点接进某条儿子链，就能覆盖所有节点且只用 $L$ 条。

对一个这样的最少链划分，每条链只有最大权值正在计分，其他节点都是未计分值。若多允许一个集合，可以把任意一个未计分节点取出来单独成链；原链中选定的最大值还在，其余节点仍两两可比较，原分数不变，新分数恰好多出被取节点的权值。因此一旦找到合适的最少链划分，增加链数就可以按最大未计分值依次恢复。

#### 自底向上保留最有价值的链最大值

每个节点维护小根堆，元素是当前子树中各条链的最大值。合并所有儿子的堆，叶子直接放入自己的权值。非叶节点 $u$ 要接入一条已有链，若该链原最大值为 $x$，接入后只保留 $\max(x,a_u)$ 计分，而 $\min(x,a_u)$ 不再单独计分。

选择最小的链最大值 $x$，就等价于把所有已有最大值与 $a_u$ 放在一起，再丢掉其中最小的一个。丢掉的值加入备用列表。例如两条儿子链最大值为十、三十，父亲为二十五，接到十的链得到二十五、三十，备用为十；若接到三十的链，只能得到十、三十，损失更大。

#### 为什么这一个划分同时适用于所有链数

只说当前损失最小，还不足以说明增加链数后的答案也最优。可以固定任意阈值 $T$，把权值至少为 $T$ 的节点视为高值，比较各方案有多少条链能贡献高值最大值。

令子树叶数为 $L_u$。在恰好每个叶子一条链的情形，来自某个子树的高值代表最多占用该子树的 $L_u$ 个叶子名额。设各儿子最多能保留的高值代表数为 $H_v$，则当前子树上界为
$$H_u=\min\left(L_u,[a_u\ge T]+\sum_{v\text{ 是儿子}}H_v\right).$$
堆操作恰好达到这个上界：儿子合并后加入父亲，若必须去掉一个值，总是优先去掉低于阈值的最小值；只有所有候选都高时，才减少一个高值。因此同一个按实际权值执行的堆贪心，对所有阈值都同时保留最多的高值代表。

再看任意恰好 $k\ge L$ 条链的划分。其中恰有 $L$ 条链包含原始叶子，其他只有 $k-L$ 条。给每条叶子链挑选一个达到其最大值的代表，它位于该叶子的祖先路径上，所以这些代表满足上述叶子名额限制，高值代表数至多为根的 $H$。额外链每条至多再贡献一个高值最大值，故所有链的高值分数数量至多为
$$\min(N_T,H+k-L),$$
其中 $N_T$ 是全树高值节点总数。

堆贪心得到的最少链划分已有 $H$ 个高值代表，备用列表中恰有 $N_T-H$ 个高值。恢复最大的 $k-L$ 个备用值时，高值分数数量正好达到上述上界。这个结论对每个阈值都成立，而正整数权值之和等于各阈值下“至少达到阈值的分数个数”之和，所以恢复方案的总得分也必然最大。

#### 与代码对应的输出与复杂度

根堆共有 $L$ 个计分值，先求和得到 $k=L$ 的答案；将 $n-L$ 个备用值降序排序，逐个累加得到后续答案，$k<L$ 输出 $-1$。备用值可对应具体节点，即使权值重复，也只取出未计分的那个副本，保持每条原链仍有一个代表。

父亲编号小于孩子，代码直接倒序处理编号。合并时把小堆元素逐个移入大堆，每个元素搬迁后所在堆大小至少翻倍，因此最多搬迁 $O(\log n)$ 次；每次堆插入或删除又需 $O(\log n)$，总时间上界 $O(n\log^2n)$，空间 $O(n)$。总分使用 $64$ 位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        vector<int> par(n + 1, 0);
        for (int i = 2; i <= n; i++) cin >> par[i];

        // 每个叶子上来就是一条链；往上走到父结点时，父结点只能加入一条链。
        // 贪心：加入「当前最大值为所有链里最小」的那条 —— 若 a[u] 更大就把这条链的最大值顶上去，
        // 旧最大值被「腾出来」；若 a[u] 更小则链不变，a[u] 自己被腾出来。
        // 被腾出来的值攒起来，等允许更多子集时按从大到小补上。
        vector<priority_queue<long long, vector<long long>, greater<long long>>> pq(n + 1);
        vector<long long> spare;

        for (int i = n; i >= 1; i--) {              // par[i] < i，倒着扫即可自底向上
            if (pq[i].empty()) {
                pq[i].push(a[i]);                   // 叶子：自己开一条链
            } else {
                long long x = pq[i].top();          // 所有子链里最小的最大值
                pq[i].pop();
                pq[i].push(max(x, a[i]));           // 结点 i 接进这条链
                spare.push_back(min(x, a[i]));      // 另一个值被腾出来
            }
            if (i > 1) {                            // 小到大合并：小的堆并进大的堆
                int p = par[i];
                if (pq[p].size() < pq[i].size()) swap(pq[p], pq[i]);
                while (!pq[i].empty()) {
                    pq[p].push(pq[i].top());
                    pq[i].pop();
                }
            }
        }

        int L = (int)pq[1].size();                  // 链数下界 = 叶子数
        long long sum = 0;
        while (!pq[1].empty()) { sum += pq[1].top(); pq[1].pop(); }

        vector<long long> ans(n + 1, -1);
        ans[L] = sum;                               // 恰好 L 条链（每条链一个叶子）
        sort(spare.rbegin(), spare.rend());         // 多允许一条链就补进当前最大的备胎值
        for (size_t i = 0; i < spare.size(); i++) {
            sum += spare[i];
            ans[L + (int)i + 1] = sum;
        }

        for (int k = 1; k <= n; k++) cout << ans[k] << " \n"[k == n];
    }
    return 0;
}
```

### 易错点

挑最小链最大值是为了让当前被覆盖的分数最小。二叉堆的小到大搬迁还要乘上单次堆操作的对数，不能漏掉复杂度中的这一层。

## A. Moo Language School

### 题意

有 $n$ 块田，按输入顺序每连续 $k$ 块固定组成一个农场，且 $k$ 整除 $n$。归属串中零表示 John 自己的田，一表示在其上建校需要额外付费的 Nhoj 的田。每个农场至少要建一所学校，求最少需要在 Nhoj 的田上建校多少次。

### 思路

设每三块田为一个农场，归属串为 $\texttt{111010111}$。第一、第三个农场全部属于 Nhoj，无论在哪块田建校都必须付费；第二个农场含有零，可以选 John 自己的田免费建校，所以最少付费两次。

每个农场只要求至少一所学校，多建不会降低付费次数，因此可以只建一所。对某个固定农场，若存在归属为零的田，在那里建校就能达到零成本；若所有田都是一，一所必需的学校就至少产生一次费用，而且任选一块建一所便能达到一次。各农场的田互不重叠、学校要求独立，因此把各块的零或一最低成本相加即可。

代码按左端点每次增加 $k$ 扫描固定块，检查块中是否出现零；没有零就给答案加一。这里不是自由选择连续 $k$ 块田组成农场，也不是统计所有滑动窗口，分组边界由题目预先确定。

### 参考代码

```cpp
// A. Moo Language School
// 题意：n 块田，每连续 k 块算一个农场（n 是 k 的倍数）。每个农场至少要有一所学校，
// 求「把学校建在 Nhoj 的地（s_i = 1）上」的最少次数。
// 结论：农场之间互不影响 —— 某个农场里只要有一块 s_i = 0 的地（自己的地），
// 就把学校建在那里，本农场代价 0；若这 k 块全是 Nhoj 的地，则无论建在哪一块都要付 1。
// 所以答案 = 全部由 1 组成的农场个数。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);            // 关掉 cin/cout 与 C 标准流的同步，读入更快
    cin.tie(nullptr);                       // 解除 cin 与 cout 的绑定
    int t;                                  // 数据组数
    cin >> t;
    while (t--) {                           // 逐组处理
        int n, k;                           // n 块田，每 k 块一个农场
        string s;                           // 归属串：s_i = '1' 表示第 i 块田属于 Nhoj
        cin >> n >> k >> s;
        int ans = 0;                        // 需要建在 Nhoj 地上的学校次数
        for (int st = 0; st < n; st += k) { // 逐个农场扫描（st = 农场左端点）
            bool hasFree = false;           // 本农场里是否存在属于 John 自己的田
            for (int i = st; i < st + k; i++)
                if (s[i] == '0') hasFree = true;
            if (!hasFree) ans++;            // 整段都是 Nhoj 的地 -> 本农场必须付 1 次
        }
        cout << ans << '\n';                // 输出本组答案
    }
    return 0;
}
```

### 易错点

这是固定分组，不是统计所有长度为 $k$ 的全一子数组。

## B. Minus Two

### 题意

每次同时把所有数 $x$ 替换为 $|x-2|$。可以执行任意多次，求某一时刻相同数字最多能有多少个。

### 思路

数五、九依次经过 $5\to3\to1$、$9\to7\to5\to3\to1$，最终会一起停在一；数四、八最终也能同步落在零、二中的同一个值。可是四与六始终差一个循环相位：当一个为零时，另一个为二，不能在同一时刻合并。

变换保留奇偶性。对奇数，大于一时每次减二，到一后保持不动，所以全部奇数最终同为一。对偶数，先减二到零，随后在零、二之间交替；初始值 $x$ 到零需 $x/2$ 步，两个偶数只有 $x/2$ 的奇偶相同时才会同相位，也就是原数模四同余。于是全部偶数应分别统计余零、余二两类。

还要排除较早时刻出现更大频次的可能。若某时刻目标值至少为三，相关数尚未进入末尾固定点或循环，此前始终只减二。因此做了 $t$ 次后等于该目标的数，原来都必须等于目标加 $2t$，其数量不超过原数组单值最大频次。若目标为一，数量至多为奇数总数；若为零或二，数量至多为对应模四类别总数。

这四个上界均有实现方式：原单值最大频次在零次操作时可取，其他三类在足够晚的共同时间可分别取满。因此代码统计原值频次、奇数数量和两类偶数数量，再取最大。所有元素必须使用同一个操作次数，不能把两类偶数各自挑不同终点后混为一类。

### 参考代码

```cpp
// B. Minus Two
// 题意：一次操作把整张数组同时变成 a_i = |a_i - 2|，可以操作任意次（同一个次数作用于全部元素），
// 问最终某个整数的出现次数最大能是多少。
// 单个数的轨迹：x -> |x - 2|，即「每次减 2」，所以
//   · 奇数一路减到 1（1 -> |1-2| = 1，之后永远停在 1）；
//   · 偶数一路减到 0，然后 0 -> 2 -> 0 来回跳（周期 2）。
// 记第 k 次操作后：奇数 x 在 k >= (x-1)/2 时变成 1；偶数 x 在 k >= x/2 后按 (k - x/2) 的奇偶取 0 或 2。
// 关键上界（也是可达的）：
//   ① 任何「某个值 v >= 3」的出现次数，最多是原数组里值 v 的出现次数（每次操作后同值元素始终同值，
//      不同值只有在「还没落定」时才可能撞上，撞上时也只会撞在 0/1/2 上）；
//   ② 值 1 的出现次数 <= 奇数个数，且取 k 足够大时全部奇数同时停在 1，可以取满；
//   ③ 值 0（或 2）的出现次数 <= 偶数里 x/2 同奇偶的那一类个数，取 k 足够大时这一类同时停在 0、另一类停在 2。
//      x/2 的奇偶看 x mod 4：x ≡ 0 (mod 4) 时 x/2 为偶，x ≡ 2 (mod 4) 时 x/2 为奇。
// 于是答案 = max(原数组最大重数, 奇数个数, x≡0(mod 4) 的个数, x≡2(mod 4) 的个数)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关同步、解绑，读入更快
    cin.tie(nullptr);
    int t;                         // 数据组数
    cin >> t;
    while (t--) {
        int n;                     // 本组数组长度
        cin >> n;
        map<int, int> cnt;         // 原数组里每个值的出现次数（用来算最大重数）
        int odd = 0;               // 奇数个数：最终会全部停在 1
        int m0 = 0;                // x ≡ 0 (mod 4) 的个数：x/2 是偶数，最终会停在同一侧
        int m2 = 0;                // x ≡ 2 (mod 4) 的个数：x/2 是奇数，与上一类错开
        for (int i = 0; i < n; i++) {
            int x;
            cin >> x;
            cnt[x]++;
            if (x & 1) odd++;
            else if (x % 4 == 0) m0++;
            else m2++;
        }
        int best = 0;                                    // 枚举三种来源取最大
        for (auto &p : cnt) best = max(best, p.second);   // ① 原数组最大重数（k = 0 就能取到）
        best = max(best, odd);                           // ② 全部奇数同时变成 1
        best = max(best, max(m0, m2));                   // ③ 偶数按 x/2 奇偶分成两拨
        cout << best << '\n';                            // 输出本组答案
    }
    return 0;
}
```

### 易错点

每次对所有数一起操作，不能分别挑选操作次数；两类偶数不能合并统计。

## C. 101

### 题意

把数组里的 $-1$ 替换成 $0$ 或 $1$，希望得到最长的连续段：两端为 $1$、中间全为 $0$。单独一个 $1$ 也合法，求最大长度。

### 思路

例如 $[-1,0,-1,1,0,-1]$，可以让前一个未知位为 $1$、中间未知位为 $0$，得到长度 $4$ 的 $1001$。

合法端点必须原来不是 $0$；中间不能有固定的 $1$。枚举左端点 $i$ 后，如果右边还有固定 $1$，最远只能选右侧遇到的第一个固定 $1$ 为右端点；若右边没有固定 $1$，就选最右的非零位置。区间内的未知位填零即可。

从右往左维护最近的固定 $1$ 与最右可作端点的位置，或预处理后枚举，时间和空间均为 $O(n)$。若全是固定零，答案为 $0$。

#### 最远右端点不能穿过固定的一

数组为 $[-1,0,1,0,-1]$。若左端取第一位，它可以填一；但右端不能越过第三位的固定一，否则这个固定一会落入应全为零的内部，所以最远只能到第三位，长度三。

以第三位作左端时，可把第五位填一，中间第四位本来是零，同样得到长度三。整个五位不能直接把两端未知位都填一，因为中间的固定一无法改掉。

从右往左扫描时，“最近的固定一”负责阻止越界，“最右可作端点的位置”负责在没有固定一阻拦时尽量延长。未知位是否填一不需要全局统一规划：我们只求某一个最长区间，把该区间两端填一、内部未知填零就已构成方案。

### 参考代码

```cpp
// C. 101
// 题意：分数的定义 = 最长的「两端都是 1、中间全是 0」的子段长度（长度 1 的单个 1、
// 长度 2 的两个相邻 1 也都算，因为中间为空）。数组里有若干 -1 可以自己填 0 或 1，
// 要输出一种填法使分数最大。
// 观察：分数只由「哪两个位置是 1」决定 —— 固定为 1 的位置改不了，它们把可选区间切断。
// 结论：任取一对位置 (i, j) 都填成 1，只要 (i, j) 严格中间没有「本来就是 1」的位置，
// 就能把中间全填 0、拿到长度 j - i + 1；反过来任何合法子段也必然是这种形状。
// 于是枚举左端点 i、取它能取到的最远右端点，O(n)：
//   · 左端点必须能填成 1：a_i != 0；
//   · 若 i 右边还有固定 1（最近的在 q），右端点最远只能到 q（q 当端点合法，中间没有固定 1）；
//   · 若 i 右边没有固定 1，右端点取「整个数组里最靠右的、a_j != 0 的位置」。
// 最后把这一对填 1、其余 -1 全填 0（固定的 1 原样保留），分数就正好是最优值。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关同步、解绑，读入更快
    cin.tie(nullptr);
    int t;                         // 数据组数
    cin >> t;
    while (t--) {
        int n;                     // 本组长度
        cin >> n;
        vector<int> a(n);          // 原始数组，元素属于 {-1, 0, 1}
        for (int i = 0; i < n; i++) cin >> a[i];

        vector<int> nxt1(n, -1);          // nxt1[i] = 严格在 i 右边、最近的「固定 1」下标
        int last1 = -1;
        for (int i = n - 1; i >= 0; i--) {
            nxt1[i] = last1;
            if (a[i] == 1) last1 = i;
        }
        int rnz = -1;                     // 整个数组里最靠右的、能填成 1 的位置（a != 0）
        for (int i = n - 1; i >= 0; i--)
            if (a[i] != 0) { rnz = i; break; }   // 从右往左第一个非零就是全局最右

        int bi = -1, bj = -1, best = 0;   // 最优的一对端点（bi,bj）与对应的分数
        for (int i = 0; i < n; i++) {
            if (a[i] == 0) continue;      // 左端点必须能填成 1
            int j = (nxt1[i] != -1) ? nxt1[i] : rnz;   // 右边有固定 1 就到它，否则到最右非零
            if (j - i + 1 > best) {       // 取更长的区间
                best = j - i + 1;
                bi = i;
                bj = j;
            }
        }

        for (int p = 0; p < n; p++) {
            // 固定的 1 原样保留；选中的两个端点填 1；其余位置（含所有没选中的 -1）填 0
            int v = (a[p] == 1 || p == bi || p == bj) ? 1 : 0;
            cout << v << (p + 1 == n ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

中间的固定 $1$ 不能越过；允许左右端点重合。

## D. MEX Multiset

### 题意

把给定多重集合中的每个元素分到三个多重集合之一，集合可以为空，使三个 MEX 中的最大值不超过另两者之和。MEX 是最小的未出现非负整数，空集合的 MEX 为零。构造一种分法，无法做到则输出无解。

### 思路

把目标 MEX 排成 $x\le y\le z$。要让三个 MEX 都超过某个值 $v$，就至少需要三个 $v$；让两个超过它，则至少需要两个 $v$。这提示寻找库存第一次不足的位置。

若零只出现一次，只有一个集合 MEX 为正，另外两个为零，必无解；若没有零，任意分配即可，三个 MEX 都为零。其余情况定义：$t$ 为第一个出现次数小于 $3$ 的数，$m$ 为整个集合的 MEX，$q$ 为从 $t$ 起第一个出现次数小于 $2$ 的数。

- 若 $t=m$，取三个目标均为 $m$。
- 若 $q>t$，取目标 $t,q,q$。
- 若 $q=t$，取目标 $t,t,\min(m,2t)$。

这些目标都满足三角不等式。对每个值 $v$，给所有目标 MEX 大于 $v$ 的集合各放一份；剩余副本放进一个目标 MEX 不等于 $v$ 的集合，避免破坏它的缺失值。上面的分界定义保证所需副本充足；若三个目标相同，该目标处原本就没有元素，不会遇到多余副本无处安放的问题。

按值用哈希表计数后构造，期望时间 $O(n)$，空间 $O(n)$。

#### 从目标 MEX 反推每个副本放在哪

假设零有两份，一有三份，二有一份，没有三。此时 $t=0,m=3,q=2$，目标为 $0,2,2$。

可以分成 $[1,2]$、$[0,1]$、$[0,1]$，MEX 分别是 $0,2,2$，最大值二恰好等于另两者之和。第一个集合必须没有零，后两个必须有零、一而没有二，这也解释了剩余的二为什么只能放进第一个集合。

再看零有三份、一有一份、二有一份、没有三。此时 $t=q=1,m=3$，目标为 $1,1,2$，可分为 $[0,2]$、$[0]$、$[0,1]$。

构造时先满足“目标之前每个数各一份”，再安置余量；余量不能放进目标恰等于当前数的集合，因为那个目标要求当前数缺失。MEX 的“低位齐全”和“自身缺失”必须同时保持。

### 参考代码

```cpp
// D. MEX Multiset
// 题意：把每个 a_i 放进 A / B / C 三个多重集之一，问能否让
// mex(A) + mex(B) + mex(C) >= 2 * max(mex(A), mex(B), mex(C))，能就输出一种放法。
// 记三个 mex 排序后为 x <= y <= z，不等式等价于 x + y >= z。
// 结论：无解当且仅当数组里恰好有 1 个 0。
//   · 没有 0：三个集合的 mex 都是 0，0 + 0 + 0 >= 0，一定可以；
//   · 恰好 1 个 0：含 0 的那个集合 mex >= 1，另外两个集合没有 0、mex 只能是 0，
//     于是「和 = 那个非零 mex」< 2 ×（最大 mex），必不满足；
//   · 0 的个数 >= 2：按下面三种情况构造，三种都满足 x + y >= z。
// 构造的依据：想让某个集合的 mex 恰好等于 t，就必须「值 0..t-1 各给它一份，且不给它值 t」。
// 于是先定三个目标 mex，再让每个值 v 出现在所有「mex > v」的集合里，多余副本丢给任意
// 「mex != v」的集合（只要存在这样一个集合，就一定塞得下）。
//   t = 第一个出现次数 < 3 的值（0..t-1 都至少有 3 份，正好三家各一份）；
//   q = 从 t 起第一个出现次数 < 2 的值（t..q-1 每个恰好还够第二份）；
//   ① t == m（m = 整个数组的 mex，即 0..m-1 每个都 >= 3 份）：三家都取 mex = m；
//   ② q > t：取 mex (t, q, q)，和 = t + 2q >= 2q = 2 × 最大；
//   ③ q == t（此时必有 t >= 1，因为 0 至少有 2 份）：取 mex (t, t, min(m, 2t))，和 = 2t + z >= 2z。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关同步、解绑，读入更快
    cin.tie(nullptr);
    int t;                         // 数据组数
    cin >> t;
    while (t--) {
        int n;                     // 本组元素个数
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        unordered_map<int, int> cnt;                  // 每个值的出现次数
        for (int x : a) cnt[x]++;
        auto get = [&](int v) {                        // 取出现次数，没出现就是 0
            auto it = cnt.find(v);
            return it == cnt.end() ? 0 : it->second;
        };

        if (get(0) == 1) {                             // 恰好一个 0：可证无解
            cout << "NO\n";
            continue;
        }

        int m = 0;                                     // 整个数组的 mex
        while (get(m) > 0) m++;
        int t3 = 0;                                    // 第一个出现次数 < 3 的值
        while (get(t3) >= 3) t3++;
        int q = t3;                                    // 从 t3 起第一个出现次数 < 2 的值
        while (get(q) >= 2) q++;

        int mx[3];                                     // 三个集合的目标 mex（排序后 = x <= y <= z）
        if (t3 == m) {                                 // ① 0..m-1 每个都够 3 份
            mx[0] = mx[1] = mx[2] = m;
        } else if (q > t3) {                           // ② t3..q-1 每个恰好还够 2 份
            mx[0] = t3;
            mx[1] = q;
            mx[2] = q;
        } else {                                       // ③ q == t3，此时 t3 >= 1
            mx[0] = t3;
            mx[1] = t3;
            mx[2] = min(m, 2 * t3);
        }

        unordered_map<int, vector<int>> pos;           // 每个值出现过的下标
        for (int i = 0; i < n; i++) pos[a[i]].push_back(i);

        string s(n, 'A');                              // 输出的放置串
        for (auto &kv : pos) {
            int v = kv.first;
            vector<int> &idx = kv.second;
            int req = 0;                               // 必须包含 v 的集合个数 = mex > v 的个数
            for (int c = 0; c < 3; c++)
                if (mx[c] > v) req++;
            int used = 0;
            for (int c = 0; c < 3 && used < req; c++)  // 每个「mex > v」的集合放一份
                if (mx[c] > v) s[idx[used++]] = char('A' + c);
            if (used < (int)idx.size()) {              // 多出来的副本塞进任意 mex != v 的集合
                for (int c = 0; c < 3; c++)
                    if (mx[c] != v) {
                        for (int k = used; k < (int)idx.size(); k++) s[idx[k]] = char('A' + c);
                        break;
                    }
            }
        }
        cout << "YES\n" << s << '\n';                  // 输出构造
    }
    return 0;
}
```

### 易错点

MEX 等于 $x$ 不仅要求包含 $0\ldots x-1$，还要求不能含 $x$。集合允许为空；无零时可以把所有元素都放进同一个集合。

## E. Treasure Map Destruction (Constructive Version)

### 题意

数轴位置为 $1\ldots n$，其中有一个非空宝藏集合。给出部分位置到最近宝藏的距离 $b_i$，$-1$ 表示未知。构造满足所有已知距离的宝藏集合，或判断无解。

### 从零讲：把「最近宝藏的距离」翻译成「禁区 + 两个候选端点」

“最近距离等于 $v$”包含两件事：距离小于 $v$ 的位置一个宝藏也不能有；距离恰好等于 $v$ 的位置至少有一个宝藏。只有第一件事不足以保证距离真的等于 $v$。

当 $v>0$ 时，位置 $i$ 的禁区是
$$[i-v+1,i+v-1]\cap[1,n],$$
可能的宝藏端点只有 $i-v$ 和 $i+v$。当 $v=0$ 时，直接强制位置 $i$ 是宝藏。

![距离约束变成禁区和候选端点](assets/e-treasure.svg)

图中距离数组是 $[-1,1,-1,1,-1]$。位置 $2,4$ 不能埋宝；约束分别是“$1$ 或 $3$ 要埋”和“$3$ 或 $5$ 要埋”。把 $1,3,5$ 全选上就满足要求。

为什么多放宝藏不会破坏距离？因为所有过近的位置已经统一禁止了。只要新宝藏来自禁区之外，它不可能让任何已知位置的最近距离变得过小；多选只能帮助满足“至少有一个端点”的条件。

### 思路

用差分数组把所有正距离对应的禁区标出来：对区间左端加一、右端后一位减一，前缀和大于零的位置都禁止放宝藏。然后把所有未禁位置全部选入集合。

最后检查每个已知距离。$b_i=0$ 时位置 $i$ 必须被选；$b_i>0$ 时两个候选端点至少有一个被选。若检查通过且集合非空，这就是答案；否则无解。为什么失败便是无解？任何合法集合都只能从未禁位置中选，我们已经全选了；连这个最大集合都缺少所需端点，选它的子集更不可能补上。

时间和空间均为 $O(n)$。

#### 最大允许宝藏集合，既给方案也给无解证据

取 $n=6$，只知道位置二的距离为二、位置五的距离为一。第一个约束禁止位置 $1,2,3$，且要求位置四有宝藏；第二个禁止位置五，要求四或六有宝藏。所有未禁位置为 $\{4,6\}$，全选后两个已知距离分别为二、一，合法。

若取 $n=3$，已知距离为 $[2,0,-1]$：位置一距离二会禁止位置一、二，并要求位置三有宝藏；位置二距离零却又强制位置二有宝藏，与禁区矛盾，直接无解。

无解不是因为某种贪心放错了点，而是任何合法集合都只能是未禁位置的子集。连最大的允许集合都无法满足强制点或候选端点条件时，任何更小集合也不会补出缺失的点。

### 参考代码

```cpp
// E. Treasure Map Destruction (Constructive Version)
// 题意：b 是「到最近宝藏的距离」数组，部分位置被毁成 -1；求任一合法的宝藏集合。
//
// 做法：把「已知值」翻译成对宝藏位置的硬约束，再取最贪心的那组宝藏。
//
//   1) 若 b[i] = v >= 1，则 i 到最近宝藏的距离恰为 v，于是：
//        · 开区间 (i-v, i+v) 内一个宝藏都不能有（否则距离会小于 v）；
//        · i-v 或 i+v 必须有一个在范围内且能放宝藏（距离恰为 v）。
//   2) 若 b[i] = 0，则 i 本身必须是宝藏。
//
// 把所有「不能放宝藏」的位置并起来记成 forbid（区间并，用差分 O(n) 求），
// 只要每个子句都还剩一个候选位置不在 forbid 里，就把「所有不在 forbid 里的位置」
// 全埋上宝藏——它一定满足全部已知值（多埋不会让任何已知距离变小，
// 因为多埋的位置都不在 forbid 里），且非空。

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 只用 cin/cout，不混 stdio
    cin.tie(nullptr);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        vector<int> b(n + 2, -1);
        for (int i = 1; i <= n; ++i) cin >> b[i];

        // forbid：差分标记「不能放宝藏」的位置（区间 (i-v, i+v) 的整数部分）
        vector<int> diff(n + 3, 0);
        for (int i = 1; i <= n; ++i) {
            int v = b[i];
            if (v < 1) continue;                       // -1（未知）与 0（宝藏）不产生禁区
            int lo = max(1, i - v + 1), hi = min(n, i + v - 1);
            if (lo <= hi) { diff[lo] += 1; diff[hi + 1] -= 1; }
        }
        vector<char> forbid(n + 2, 0);
        for (int i = 1, cur = 0; i <= n; ++i) {
            cur += diff[i];
            forbid[i] = (cur > 0);
        }

        bool ok = true;
        // b[i] = 0 必须是宝藏，若它落在禁区里 → 无解
        for (int i = 1; i <= n; ++i) {
            if (b[i] == 0 && forbid[i]) { ok = false; break; }
        }
        // 每个已知 v >= 1 的位置 i，i-v 与 i+v 里至少要有一个能放宝藏
        for (int i = 1; i <= n && ok; ++i) {
            int v = b[i];
            if (v < 1) continue;
            bool canL = (i - v >= 1) && !forbid[i - v];
            bool canR = (i + v <= n) && !forbid[i + v];
            if (!canL && !canR) { ok = false; break; }
        }

        if (!ok) { cout << -1 << '\n'; continue; }

        // 全部非禁区位置都埋宝藏：每个子句的候选里至少有一个在里面，答案非空
        string s(n, '0');
        for (int i = 1; i <= n; ++i) if (!forbid[i]) s[i - 1] = '1';
        cout << s << '\n';
    }
    return 0;
}
```

### 易错点

禁区是开区间的整数部分，两个距离恰好等于 $b_i$ 的端点不能一起禁掉。计算区间和候选时都要检查越界。

## F. Binary Bubble Sort Inversions

### 题意

给定二进制串，依次执行两类操作：从左到右扫一遍相邻位置，遇到 $10$ 就交换；或从右到左做同样的一遍扫描。每次操作后输出逆序对数，即前面为 $1$、后面为 $0$ 的位置对数量。

### 从零讲：01 数组的逆序对 = 每个 0 左边的 1 的个数之和

逆序对可以按右端点分摊：一个零的贡献，恰好等于它前面有多少个一。把同一对相邻一之间的零放在同一组，它们的贡献相同。

![冒泡方向对零的贡献的影响](assets/f-gaps.svg)

左向右扫描时，一个一可以继续向右移动，但被它换到左边的零已经离开扫描位置。因此每个前面存在一的零恰好跨过一个一，其贡献减一；原本贡献为零的零不变。

右向左扫描时，最右边尚有一在前面的零会一路向左，跨过前面的所有一；本轮其他零的贡献不变。因此右扫等价于删除一个当前最大正贡献。

这些贡献始终按从小到大排列。左扫影响所有正项，用一个公共偏移表示；右扫只删末尾一项；降为零的项从开头退出。双端队列正好支持这三件事。

### 思路

把所有有正贡献的零按所在间隙分组，组的原始贡献记为 $j$、数量记为 $c_j$。用双端队列保存非空组，并维护
$$V=\sum c_j,\qquad W=\sum j\,c_j.$$
设累计执行了 $t$ 次左扫，则当前贡献是 $j-t$，总逆序对为 $W-tV$。

左扫时只需让 $t$ 加一，弹出队首所有 $j\le t$ 的组并扣除它们的 $V,W$。右扫时把队尾组的数量减一，同时 $V$ 减一、$W$ 减去该组的 $j$；组空了就弹出。队列空时答案保持零。

每个组只入队和出队一次，预处理及全部查询总时间 $O(n+q)$，空间 $O(n)$。

#### 左扫与右扫交替时，公共偏移怎样保持

初始串 `"11010"` 的两个零前面分别有二、三个一，逆序数为五。一次左扫后得到 `"10101"`，两个正贡献变为一、二，总数三。

再一次右扫得到 `"01011"`，最右零越过它前面的全部两个一，贡献二变为零，另一零贡献一保留，所以答案为一。再左扫一次变为 `"00111"`，答案为零。

队列始终保存原始组编号二、三。第一次左扫只把公共偏移变成一；右扫移除原编号三的那一项后，剩下原编号二，读取时仍用 $2-1=1$。不能把组编号也减一，再在答案中重复减偏移。

贡献降到零的组以后永远不会重新变成正贡献，所以可从队首永久移除；这正是全部查询能摊到线性总工作的依据。

### 参考代码

```cpp
// F. Binary Bubble Sort Inversions
// 题意：01 数组 a 与 01 串 s，第 i 次操作按 s_i 做一次「左冒泡」或「右冒泡」，
//       输出初始以及每次操作后的逆序对个数。
//
// 关键观察：01 数组的逆序对 = Σ_j j * c_j，其中 c_j 是「第 j 个 1 与第 j+1 个 1
// （最后一个 1 之后）之间的 0 的个数」——每个这样的 0 恰好与它左边的 j 个 1 组成逆序对。
// 于是只要维护空隙数组 c_1..c_k（k 为 1 的个数，操作不改变 k）：
//
//   · 左冒泡（s_i = 1）：扫描时把 1 一路往右带，等价于
//         c_1..c_k -> (c_2, c_3, ..., c_k, 0)
//     即整体左移一格、末尾补 0（原来最左那个空隙被推出数组）。
//   · 右冒泡（s_i = 0）：每个 1 右移一格，只有「贴住末尾的那串 1」不动，
//     等价于把**最靠右的非零空隙**减 1（全是 0 时不做任何事）。
//
// 空隙元素只会随左冒泡整体左移（当前下标 = 初始下标 j - t，t 为已做过的左冒泡次数），
// 且只有初始就非零的元素会非零，值只会被右冒泡减 1 → 用一个双端队列按初始下标
// 递增存放非零元素即可：左冒泡时弹出队首 j <= t 的（已移出数组），
// 右冒泡时处理队尾（初始下标最大 = 当前最靠右的非零空隙）。
// 逆序对 I = Σ (j - t) * c_j = W - t * V，其中 W = Σ j * c_j、V = Σ c_j。

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];
        string s;
        cin >> s;

        vector<int> p;                       // 每个 1 的位置（1 下标）
        for (int i = 0; i < n; ++i) if (a[i] == 1) p.push_back(i + 1);
        int k = (int)p.size();

        if (k == 0) {                        // 全 0：两种操作都是空转
            for (int i = 0; i <= n; ++i) cout << 0 << (i == n ? '\n' : ' ');
            continue;
        }

        deque<pair<int, long long>> dq;      // (初始下标 j, 空隙值)，j 递增
        long long W = 0, V = 0;
        for (int j = 1; j <= k; ++j) {
            long long c = (j < k) ? (long long)(p[j] - p[j - 1] - 1)
                                  : (long long)(n - p[k - 1]);
            if (c > 0) { dq.push_back({j, c}); W += (long long)j * c; V += c; }
        }

        long long moved = 0;                 // 已做过的左冒泡次数
        cout << (W - moved * V);
        for (char ch : s) {
            if (ch == '1') {                 // 左冒泡：整体左移，末尾补 0
                ++moved;
                while (!dq.empty() && dq.front().first <= moved) {
                    W -= (long long)dq.front().first * dq.front().second;
                    V -= dq.front().second;
                    dq.pop_front();
                }
            } else {                         // 右冒泡：最靠右的非零空隙减 1
                if (!dq.empty()) {
                    int j = dq.back().first;
                    long long c = dq.back().second;
                    W -= j;
                    V -= 1;
                    if (c == 1) dq.pop_back();
                    else dq.back().second = c - 1;
                }
            }
            cout << ' ' << (W - moved * V);
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

$W$ 使用原始组编号，答案中统一减去偏移；不要给每组真的减一。逆序对可达平方量级，使用 64 位整数。

## G. Index Removal

### 题意

非递减数组满足原来每对相邻数的差不超过 $k$。对每个位置独立询问：删除该位置后，只能继续减小其他数，要重新满足非递减且相邻差不超过 $k$，最少总共减小多少。

### 从零讲：删掉一个数之后的「缺口」，以及它怎么沿数组传下去

删除后从左往右考虑。若上一个保留值最终是 $c$，当前值最大只能取 $\min(a_j,c+k)$。取这个最大值既让当前减得最少，也给后面留下最宽松的上限，所以逐个贪心是最优的。结果仍非递减，因为原数组非递减，且 $c$ 没有超过原来的前一项。

![缺口被间距余量逐步吸收](assets/g-deficit.svg)

若前一项降低了 $\delta$，当前原间隙还有 $w=k-(a_j-a_{j-1})$ 的余量，则它可以先吸收 $w$；当前必须降低的量只有
$$\delta'=\max(0,\delta-w).$$
图中删去 $4$ 后，$7$ 与 $1$ 相差 $6$，所以要把 $7$ 降低 $2$。下一段原间距只有 $2$，还空着 $2$ 的余量，恰好吸收全部缺口，后面的数都不用动。

反复使用递推式，缺口就是“初始缺口减去一路经过的余量总和，再与零取最大”。余量非负使它只会缩小，因此能用前缀和与二分，一次算完整段连锁影响。

### 思路

删除端点不产生新间隙，答案为零。删除内部位置 $p$ 后，唯一可能超标的是 $a_{p+1}-a_{p-1}$，初始缺口
$$d=\max(0,a_{p+1}-a_{p-1}-k).$$
若 $d=0$，同样无需操作。否则定义原间隙的余量
$$w_j=k-(a_j-a_{j-1})\ge0,\qquad W_j=\sum_{i=2}^j w_i.$$
传到 $j\ge p+1$ 的缺口为 $\max(0,T-W_j)$，其中 $T=d+W_{p+1}$。由于 $W$ 非递减，二分找到最后一个 $W_j<T$ 的位置 $r$。再用 $W$ 的前缀和 $P$ 计算
$$\sum_{j=p+1}^{r}(T-W_j)=(r-p)T-(P_r-P_p).$$
预处理 $O(n)$，每个询问二分 $O(\log n)$，总计 $O(n\log n)$，空间 $O(n)$。

参考代码用无符号 64 位数存累计量。某些中间前缀和可以很大，但无符号加减按 $2^{64}$ 取模有定义；最终表达式等价于真实缺口总和，而该结果在范围内，因此抵消后仍得到正确值。不能把同一实现直接改成会溢出的有符号整数。

#### 缺口逐段缩小，等于零的位置不进求和

取数组 $[1,4,7,10,13]$、$k=4$，删除第二项四。七与一的间隙为六，先把七降到五，花二；下一段原间隙为三，还有一个单位余量，所以十只需下降一到九；再下一段的一个单位余量吸收剩余缺口，十三不动。

最终数组为 $[1,5,9,13]$，各间隙都是四，总代价为三。传播中的缺口为 $2,1,0$，不是让全部后缀都下降二。

对应余量前缀和在后面依次增长一，二分要找严格小于阈值的位置。某位置的前缀和恰等于阈值时，它的缺口已经为零，不应算入受影响的段长。

每步取当前允许的最大值，既使本位置减得最少，也使后继上限最大；降低得更多只会让当前和后续代价更差。因此这个从左到右的递推给出的总缺口和，就是最小总减量。

### 参考代码

```cpp
// G. Index Removal
// 题意：给定「好的」数组 a（非降、相邻差 ≤ k）。对每个 i 独立地问：
//       删掉 a_i 之后，每次操作可以把任一元素减 1，最少要减多少才能让剩下的数组重新变好。
//
// 只减不增 ⇒ 设最终数组为 c，则 c 必须满足：非降、相邻差 ≤ k、且 c_j ≤ a'_j（a' 是删掉 a_i 的数组）。
// 反过来，任何满足这三条的 c 都能由减法得到，代价 = Σ a'_j - Σ c_j。
// 于是「代价最小」= 「Σ c_j 最大」，而逐位最贪心的 c 就是逐点最大的可行解：
//       c_1 = a'_1,  c_j = min(a'_j, c_{j-1} + k)。
//
// 注意只有 i 之后的部分会变（前缀 a_1..a_{i-1} 原样保留）。记 w_j = k - (a_j - a_{j-1}) ≥ 0，
// 令「缺口」δ_j = a_j - c_j（在删 i 后的数组里、对应原下标 j > i 的位置）：
//       δ_{i+1} = max(0, a_{i+1} - a_{i-1} - k) = Δ_i,   δ_j = max(0, δ_{j-1} - w_j)。
// 解这个「带 0 下界的减法递推」得 δ_j = max(0, Δ_i - (W_j - W_{i+1}))，其中 W 是 w 的前缀和。
// 于是 答案_i = Σ_{j>i} δ_j = Σ_{j ≥ i+1} max(0, Δ_i + W_{i+1} - W_j)。
// W 单调不降 ⇒ 满足 W_j < Δ_i + W_{i+1} 的 j 是连续一段前缀，二分右端点 + 前缀和 O(log n) 求完。
// 总复杂度 O(n log n)。

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        long long k;
        cin >> n >> k;
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; ++i) cin >> a[i];

        // w[j] = k - (a[j] - a[j-1]) ≥ 0（原数组是好的保证）；W 是 w 的前缀和，
        // PW 是 W 的前缀和（可能到 2e19，故用无符号 64 位存，见下面的说明）
        vector<long long> W(n + 1, 0);
        vector<unsigned long long> PW(n + 1, 0);
        for (int j = 2; j <= n; ++j) W[j] = W[j - 1] + (k - (a[j] - a[j - 1]));
        for (int j = 2; j <= n; ++j) PW[j] = PW[j - 1] + (unsigned long long)W[j];

        for (int i = 1; i <= n; ++i) {
            long long cost = 0;
            // 只有 i ≥ 2 且 i 后面还有元素时才会产生缺口（删首元素 / 删尾元素都仍是好数组）
            if (i >= 2 && i + 1 <= n) {
                long long d = a[i + 1] - a[i - 1] - k;     // 跨过被删元素的那一步超了多少
                if (d > 0) {
                    long long T = d + W[i + 1];            // 需要 W_j < T
                    int lo = i + 1, hi = n, r = i;         // r = i 表示一个 j 都不满足
                    while (lo <= hi) {
                        int mid = (lo + hi) >> 1;
                        if (W[mid] < T) { r = mid; lo = mid + 1; }
                        else hi = mid - 1;
                    }
                    if (r > i) {
                        long long cnt = r - i;             // 区间 [i+1, r] 的元素个数
                        // 窗口内的 W 之和一定 ≤ cnt * T ≤ 约 1e15（每个 j 都满足 W_j < T），
                        // 但 PW 本身（W 的全局前缀和）最大可到 2e19、会超出 long long ——
                        // 用无符号 64 位回绕相减，差值仍然精确（真值远小于 2^64）。
                        unsigned long long winSum = PW[r] - PW[i];
                        cost = (long long)((unsigned long long)cnt *
                                           (unsigned long long)T - winSum);
                    }
                }
            }
            cout << cost << (i == n ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

二分取严格小于 $T$ 的最后位置；等于 $T$ 时缺口已经为零。每次删除都是独立询问，不要修改原数组。

## H. Treasure Map Destruction (Counting Version)

### 题意

与 E 题相同，给出数轴上部分位置到最近宝藏的距离。现在要求满足条件的非空宝藏集合数量，答案对 $10^9+7$ 取模。

### 从零讲：把「二选一」的子句画成图，数点覆盖

E 题可以把所有允许位置都选上；计数时必须区分它们选与不选。对还没被强制选中的候选，每条“二者至少选一个”画成一条边。合法选择就是图的点覆盖：每条边至少有一个端点被选。

图示沿用 E 题的例子。链 $1-3-5$ 的合法集合恰为 $\{3\},\{1,3\},\{1,5\},\{3,5\},\{1,3,5\}$，一共五种。

为什么这里只需处理链和环？假设一个未被强制的候选点 $p$，被左侧两个已知位置 $i_1<i_2<p$ 同时作为右端点使用。较近位置的另一候选是 $2i_2-p$，它落在较远位置的禁区 $(2i_1-p,p)$ 内，因此较近约束只剩候选 $p$，会强制选它，与假设矛盾。右侧同理。每个自由点左右最多各连一条边，度数至多为二，所以连通块只能是链或环。

设 $C_m$ 是 $m$ 个点的链的点覆盖数。最后一点选中，前面任意合法，有 $C_{m-1}$ 种；最后一点不选，它的邻居必须选，有 $C_{m-2}$ 种。因此 $C_m=C_{m-1}+C_{m-2}$，且 $C_0=1,C_1=2$，即 $C_m=\mathrm{fib}_{m+2}$。

对 $m$ 个点的环，固定第一个点：选它，剩下是长 $m-1$ 的链；不选它，两侧邻居必须选，剩下是长 $m-3$ 的链。总数为 $\mathrm{fib}_{m+1}+\mathrm{fib}_{m-1}$。例如三角形只有三个“两点集合”和全选集合合法，共四种；空集与三个单点集合都不合法。各连通块的选择独立，所以相乘。

### 思路

取五个位置，已知第二、第四位置到最近宝藏的距离均为一，其余未知。位置二、四自身不能藏宝，且要求一或三至少有一个宝藏、三或五至少有一个宝藏。候选图为 $1-3-5$，合法集合是 $\{3\},\{1,3\},\{3,5\},\{1,5\},\{1,3,5\}$，共五种。计数问题要保留所有这些选择，不能像构造版一样把允许位置全选。

#### 距离条件同时提供禁区和至少一个端点

若已知 $b_i=v>0$，距离严格小于 $v$ 的位置全部不能藏宝，即禁区 $[i-v+1,i+v-1]$；距离恰好为 $v$ 的两个位置 $i-v,i+v$ 中至少一个必须藏宝。先对所有禁区做差分求并集，裁掉越界部分。若某个已知零距离位置落入禁区，立即无解。

对每条正距离约束，删除越界或被禁的候选。若剩零个，无解；若已有已知零距离端点，约束已经满足；若仅剩一个，强制选择它；若剩两个，暂存一条至少选一个端点的边。必须先收齐全部强制点，再删除与强制点相连的边，否则后面才出现的强制选择会使前面已经建好的边失效。

#### 剩余图为何只有链和环

设一个未被强制的候选 $p$ 同时作为其左边两个位置 $i_1<i_2<p$ 的右候选。对应距离为 $p-i_1,p-i_2$，较近约束的另一候选是 $2i_2-p$。由于
$$2i_1-p<2i_2-p<p,$$
它位于较远约束的禁区内部，因而不可用，较近约束就只剩 $p$，会强制选择 $p$，与其仍自由矛盾。右边同理，所以每个自由候选从左右各至多连来一条边，度数至多二。

每个有边连通分量因此为链或环。选择宝藏需覆盖每条边至少一个端点，正是图的点覆盖计数；也可等价地把不选点视为独立集。

#### 分量计数与自由孤点

设 $C_m$ 为 $m$ 点链的点覆盖数。末点选中时前面任取合法覆盖，贡献 $C_{m-1}$；末点不选时前一节点必须选，剩余前段任取，贡献 $C_{m-2}$。边界 $C_0=1,C_1=2$，所以 $C_m=\mathrm{fib}_{m+2}$。对 $m$ 点环，固定首点：选首点后剩一条 $m-1$ 点链；不选首点时它两个邻居都必须选，剩一条 $m-3$ 点链。总数为 $\mathrm{fib}_{m+1}+\mathrm{fib}_{m-1}$。

不同连通分量没有共同约束，方案数相乘。没被禁止、没被强制、也不与任何剩余边关联的未知位置，可以独立选或不选，每个乘二。被强制的点只有一种选择，禁点只有不选一种。

若没有正距离约束，直接对所有未知位置乘二；存在已知零点时集合天然非空，否则必须扣掉全不选的空集。有正距离约束时，每个合法方案都已通过某个端点满足它，必然非空，无需再减一。差分、建图与遍历的总规模均为线性。

### 参考代码

```cpp
// H. Treasure Map Destruction (Counting Version)
// 题意：同 E（构造版），但要求「合法的宝藏集合」个数 mod 1e9+7。
//
// 先把「b 已知项」翻译成对宝藏集合 S 的硬约束（记宝藏 = 该位置为 1）：
//   · b_i = 0        → i ∈ S（强制为真）
//   · b_i = v ≥ 1    → S ∩ (i-v, i+v) = ∅（记成 forbid 区间并），且 i-v 或 i+v ∈ S。
// 于是 S 的可选范围 = 不在 forbid 里的位置，每个 b_i = -1 且不在 forbid 里的位置是自由布尔变量；
// 每个 v ≥ 1 的已知项给出一条「(i-v) 或 (i+v) 至少一个为真」的子句（正文字子句）。
//
// 若某候选落在 forbid 里 / 越界就不能用；只剩一个候选 → 该位置被强制为真（变量消失）；
// 一个候选都没有 → 答案 0。剩下的两条腿子句就是图上的边，要求每条边至少一个端点为真
// = 「假点集是独立集」= 数点覆盖：链 m 个点有 fib[m+2] 种，环 m 个点有 fib[m-1]+fib[m+1] 种，
// 与边无关的自由点各乘 2。
//
// 为什么每个点度数 ≤ 2（链/环，不是任意图）：设自由点 p 左侧有两个已知项 i1 < i2 < p
// 满足 b = p - i，则较近那个（i2）的远候选 2*i2 - p 必落在较远那个（i1）的 forbid 区间
// [2*i1-p+1, p-1] 里 → 该子句退化成「p 必须为真」的单位子句，p 不再是变量。右侧同理。

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;
const int MAXN = 200005;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // fib 与 2 的幂预处理（下标最大用 n+2）
    vector<long long> fib(MAXN + 3, 0), pw2(MAXN + 3, 1);
    fib[1] = 1;
    for (int i = 2; i <= MAXN + 2; ++i) fib[i] = (fib[i - 1] + fib[i - 2]) % MOD;
    for (int i = 1; i <= MAXN + 2; ++i) pw2[i] = pw2[i - 1] * 2 % MOD;

    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        vector<int> b(n + 2, -1);
        for (int i = 1; i <= n; ++i) cin >> b[i];

        // forbid：差分求「不能放宝藏」的区间并
        vector<int> diff(n + 3, 0);
        for (int i = 1; i <= n; ++i) {
            int v = b[i];
            if (v < 1) continue;
            int lo = max(1, i - v + 1), hi = min(n, i + v - 1);
            if (lo <= hi) { diff[lo] += 1; diff[hi + 1] -= 1; }
        }
        vector<char> forbid(n + 2, 0);
        for (int i = 1, cur = 0; i <= n; ++i) { cur += diff[i]; forbid[i] = (cur > 0); }

        bool zero = false;                       // 是否存在已知的宝藏（b_i = 0）
        bool bad = false;
        for (int i = 1; i <= n; ++i) {
            if (b[i] == 0) {
                zero = true;
                if (forbid[i]) bad = true;       // 必须埋宝的位置被禁 → 无解
            }
        }
        if (bad) { cout << 0 << '\n'; continue; }

        // 子句处理：先收集单位子句（强制为真），两条腿的先挂起
        vector<char> forced(n + 2, 0);
        vector<pair<int, int>> pend;
        int clauses = 0;
        for (int i = 1; i <= n && !bad; ++i) {
            int v = b[i];
            if (v < 1) continue;
            ++clauses;
            int cand[2] = { i - v, i + v };
            vector<int> avail;                   // 可自由决定的候选（b = -1 且不在 forbid 里）
            bool sat = false;                    // 候选里已有 b = 0 的强制宝藏
            for (int id = 0; id < 2; ++id) {
                int c = cand[id];
                if (c < 1 || c > n) continue;
                if (forbid[c]) continue;
                if (b[c] == 0) { sat = true; break; }
                avail.push_back(c);
            }
            if (sat) continue;                   // 子句已被强制宝藏满足
            if (avail.empty()) { bad = true; break; }
            if (avail.size() == 1) forced[avail[0]] = 1;
            else pend.push_back({avail[0], avail[1]});
        }
        if (bad) { cout << 0 << '\n'; continue; }

        if (clauses == 0) {
            // 一条子句都没有：所有 b = -1 的位置自由（2 的幂），若没有任何 b = 0 还要去掉空集
            int freeCnt = 0;
            for (int i = 1; i <= n; ++i) if (b[i] == -1) ++freeCnt;
            long long ans = pw2[freeCnt];
            if (!zero) ans = (ans - 1 + MOD) % MOD;
            cout << ans << '\n';
            continue;
        }

        // 挂起的边：端点被强制为真 → 子句已满足，直接丢
        vector<vector<int>> adj(n + 2);
        for (auto &pr : pend) {
            int u = pr.first, w = pr.second;
            if (forced[u] || forced[w]) continue;
            adj[u].push_back(w);
            adj[w].push_back(u);
        }

        long long ans = 1;
        vector<char> vis(n + 2, 0);
        for (int s = 1; s <= n; ++s) {
            if (adj[s].empty() || vis[s]) continue;
            vector<int> st;
            st.push_back(s);
            vis[s] = 1;
            int m = 0, degSum = 0;
            bool allDeg2 = true;
            while (!st.empty()) {                // 迭代遍历，避免深链爆栈
                int u = st.back(); st.pop_back();
                ++m;
                degSum += (int)adj[u].size();
                if (adj[u].size() != 2) allDeg2 = false;
                for (int v : adj[u]) if (!vis[v]) { vis[v] = 1; st.push_back(v); }
            }
            int e2 = degSum / 2;
            if (allDeg2 && e2 == m)              // 环
                ans = ans * ((fib[m - 1] + fib[m + 1]) % MOD) % MOD;
            else                                 // 链
                ans = ans * fib[m + 2] % MOD;
        }

        // 与任何边都无关的自由点：各自 2 种（埋 / 不埋）
        int iso = 0;
        for (int i = 1; i <= n; ++i)
            if (b[i] == -1 && !forbid[i] && !forced[i] && adj[i].empty()) ++iso;
        ans = ans * pw2[iso] % MOD;
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

先收集所有强制选择，再删除已满足的边，不能一边建图一边忽略之后产生的强制条件。长链遍历使用显式栈；斐波那契预处理到 $n+2$。

## A. Good Contest

### 题意

比赛有 $n$ 位选手，三道题分别有 $a_1,a_2,a_3$ 人通过。没有通过全部三题的人称为弱选手，求弱选手最少有多少人。

### 思路

有六名选手，三题通过人数为四、二、五。可以让编号一、二的两人通过全部三题，再为第一、第三题分别补足其他通过者；这样全过人数是二，弱选手四人。

弱选手是没有做全三题的人，因此使弱选手最少，等价于使三题通过集合的交集最大。任何全过选手都属于每一题的通过集合，所以交集大小不超过三个人数的最小值 $s$，弱选手至少有 $n-s$ 人。

这个下界可达到：先选固定的 $s$ 个人，让他们通过三题；再在其余人中为每题补足所需通过人数。人数最少的那道题已经满额，不再增加通过者，因此没有其他人会额外成为全过选手，而其他题的补充均可在总人数范围内完成。故代码直接输出 $n-\min(a_1,a_2,a_3)$。

### 参考代码

```cpp
// A. Good Contest
// 题意：n 个选手、3 道题，a[i] 是做对第 i 题的人数；问最少有多少人没做全三题。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;                       // 选手总数
        int x, y, z;
        cin >> x >> y >> z;             // 三道题各自的做对人数
        int both = min({x, y, z});      // 三题全对的人最多只能有 min 个
        cout << n - both << '\n';       // 剩下的人都是“弱选手”
    }
    return 0;
}
```

### 易错点

要求弱选手最少，相当于三题全过的人最多。

## B. Three Piles

### 题意

Alice、Bob 各有 $a,b$ 个物品，公共堆里还有 $c$ 个。两人轮流拿走公共堆中的任意多个物品，可以拿零个，连续两次拿零个时结束。Alice 先手，希望最终数量差的绝对值最大；Bob 希望最小。求最优对抗下的结果。

### 思路

Alice 有两种简单选择：不拿，保留原来的差；或一次拿完，把自己的数量变成 $a+c$。答案是
$$\max\bigl(|a-b|,a+c-b\bigr).$$
下面同时证明双方能做到什么。

若 $a\ge b$，Alice 一次拿完，保证差为 $a+c-b$。若 $a<b$，Alice 可以一直不拿；Bob 无论拿多少，只会让自己更领先，因此 Alice 至少保证 $b-a$。此外她仍可直接拿完，得到 $|a+c-b|$。两种策略保证的最大值就是上式。

Bob 则可以始终拿零个。此时 Alice 最后拿到某个 $x\in[0,c]$，差为 $|a+x-b|$。这个折线函数在区间上的最大值位于端点，不超过 $\max(|a-b|,|a+c-b|)$，也就是上式。上下界一致。每组 $O(1)$。

#### Alice 不拿公共堆，可能比一次拿完更好

取 $a=2,b=8,c=3$。Alice 一次拿完后为 $5$ 对 $8$，差只有三；若她始终拿零，Bob 为了让差小，也只能拿零，最后差为六。所以不能把“多拿物品”直接当成 Alice 的最优目标。

若只把公共堆改为 $c=20$，Alice 一次拿完后为 $22$ 对 $8$，差为十四，比保留原差六更好。答案正是这两个端点结果的最大值。

Bob 始终拿零的策略不是假设对手配合，而是一个他能够单方面执行的上界策略。此时 Alice 无论怎样分次拿，累计只会拿到某个 $x\in[0,c]$，差不超过折线函数在两个端点的最大值。与 Alice 的保证策略对上，才构成最优对抗证明。

### 参考代码

```cpp
// B. Three Piles
// 题意：三堆石子 a、b、c。两人轮流从第三堆取任意多（可 0）添进自己堆；
//       连续两次都取 0 就结束，得分 |A-B|。Alice 想大、Bob 想小。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        ll a, b, c;
        cin >> a >> b >> c;                     // 三堆石子数
        ll d = (a > b) ? (a - b) : (b - a);     // 什么都不取时的分差
        ll e = a + c - b;                       // Alice 一次取光第三堆后的分差
        cout << max(d, e) << '\n';              // 其余取法都夹在这两个极端之间
    }
    return 0;
}
```

### 易错点

差要取绝对值；数量与加法使用 64 位整数。

## C. AND, OR, Sort!

### 题意

给定二进制串。一次操作选一个位置，把该位改成从开头到该位置所有位的按位与，或者按位或。求把串变成非递减序列的最少操作次数。

### 思路

若首位是 $1$，它永远不能变成 $0$，最终只能全为 $1$。每个 $0$ 用前缀或改一次即可，答案是零的个数。

若首位是 $0$，最终形态必为若干个 $0$ 后接若干个 $1$。枚举分界 $k$，前 $k$ 位改为 $0$、后面改为 $1$，至少需要
$$\text{前缀中 1 的个数}+\text{后缀中 0 的个数}$$
次操作。维护前缀计数就能在线性时间求最小值。

还需确认这些改动可以实现。所有需要变成 $0$ 的位都有首位这个 $0$ 可借，用前缀与即可。需要变成 $1$ 的后缀则借用原串最早的 $1$，先做前缀或，再清理前缀中的 $1$。最优分界不会把最早的 $1$ 之前的零放入后缀：把这些零留在前缀只会减少代价。全零串本来有序。故这个计数下界确实可达。

时间 $O(n)$，额外空间 $O(1)$。

#### 分界代价与一条实际操作顺序

串为 `"001010"`。若分界在第四位之后，目标为 `"000011"`：前四位有一个一，后两位有一个零，计数下界为二。

先把第六位用前缀或改成一，因为前面存在一；再把第三位用前缀与改成零，因为前面存在零。两次操作恰好实现目标，因此这个分界的下界能达到。

枚举分界时，把一个字符从后缀挪到前缀，只需相应更新“前缀一”和“后缀零”的数量，不用重新扫描两段。分界允许在串尾，代表全变零；首位为零时，这始终是一种可行候选。

首位为一时上述自由分界不存在：前缀与、前缀或在第一位都仍为一，任何最终有序串就只能全为一，应直接统计零的个数。

### 参考代码

```cpp
// C. AND, OR, Sort!
// 题意：二进制串 s，每次可把某一位 s[i] 改成前缀 s[1..i] 的按位 AND 或 OR；
//       问最少几次操作能让 s 变成非降序（即 0…01…1）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;
        int zeros = 0;
        for (char ch : s) if (ch == '0') zeros++;   // 全串 0 的个数
        if (s[0] == '1') {                          // 第一位永远是 1，只能全改成 1
            cout << zeros << '\n';
            continue;
        }
        // s[0] == '0'：枚举分界点 i，左边全 1、右边全 0
        int left1 = 0, right0 = zeros, best = INT_MAX;
        for (int i = 0; i < n; i++) {
            if (s[i] == '1') left1++;               // 这一位归到左边
            else right0--;                          // 这一位不再算右边的 0
            best = min(best, left1 + right0);       // 要改的位数
        }
        cout << best << '\n';
    }
    return 0;
}
```

### 易错点

首位不能修改，必须先分类。构造的论证里应先做或操作，避免提前抹掉唯一可借用的 $1$。

## D. Falling Concrete

### 题意

一列混凝土块的高度为 $a_i$。可以把某块向左移动若干格：它每左移一格高度减一，被它跨过的块高度加一。求通过操作能够形成的最长等高连续段。

### 思路

位置从 $1$ 开始编号。一个块左移时，高度与位置一起减小；被跨过的块右移时，高度与位置一起增大。所以块携带的量
$$v=a_i-i$$
始终不变。反过来，把指定块逐个移到前面，可以实现这些块的任意排列。

例如想在位置 $p,p+1,p+2$ 都得到高度 $H$，三块携带的量就必须依次是 $H-p,H-p-1,H-p-2$。因此等高段对应一组互不相同、连续的整数标签，顺序从大到小。

把所有 $a_i-i$ 排序、去重，求最长连续整数段。必要性来自上面的等式；充分性是把这一段标签按递减顺序放在连续位置，得到的高度自然相等。排序 $O(n\log n)$，空间 $O(n)$。

#### 重复标签为什么不能凑成更长的等高段

数组 $[5,5,7,7]$ 使用从一开始的下标，标签为 $[4,3,4,3]$。看起来四个标签只差一，但去重后只有 $3,4$ 两个，最长等高段只能为二。

如果四个连续位置都要高度为 $H$，对应标签必须为 $H-p,H-p-1,H-p-2,H-p-3$，彼此不同。两个同为四的标签无论摆在哪里，只要位置不同，它们的最终高度也不同，所以不能重复利用。

反过来，挑出标签四、三，放到连续位置一、二，会得到高度五、五。操作不变式不仅给出了“最多多长”的上界，也给出了把一段连续标签放成等高段的具体排列目标。

### 参考代码

```cpp
// D. Falling Concrete
// 题意：数组 a，每次选 i<j，把第 j 段搬到第 i 位；被搬的降 (j-i) 高度，
//       被跨过的每段升 1 高度。问能造出的最长“等高连续段”。
// 关键：搬运只重排，a[i] - i 这个量对每一段永远不变。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        set<int> inv;                       // 所有不同的 a[i] - i
        for (int i = 1; i <= n; i++) {
            int a;
            cin >> a;
            inv.insert(a - i);              // 这一段的“不变量”
        }
        int best = 0, cur = 0, prev = INT_MIN;
        for (int c : inv) {                 // 在集合里扫最长连续整数段
            if (c == prev + 1) cur++;       // 接上一段
            else cur = 1;                   // 从这一段重新开始
            prev = c;
            best = max(best, cur);
        }
        cout << best << '\n';
    }
    return 0;
}
```

### 易错点

重复标签不能延长连续段；计算标签时统一使用同一种下标。

## E. Prime Destruction

### 题意

可以把一个大小为 $x$ 的物品选一个素因子 $p$，拆成 $p$ 个大小为 $x/p$ 的物品，代价为一次操作。给定若干初始大小和阈值 $k$，求让所有大小不超过 $k$ 的最少操作总数。

### 思路

拆出的 $p$ 个子问题大小相同，却是 $p$ 件不同物品。例如 $x=12$、选 $p=3$，后续要处理三个 $4$，不能只计算一个。

令 $f(x)$ 表示从一个大小 $x$ 的物品开始的最少操作数。若 $x\le k$，无需拆分，$f(x)=0$；否则枚举第一次选的素因子：
$$f(x)=\min_{p\mid x,\ p\text{ 为素数}}\{1+p\,f(x/p)\}.$$
所有转移都到更小的数，按 $x$ 递增计算即可。最小素因子筛能快速枚举每个数的不同素因子。初始物品互不影响，把对应的 $f(a_i)$ 相加。

设最大输入为 $V$，预处理和动态规划 $O(V\log V)$ 是足够的上界，求和 $O(n)$，空间 $O(V)$。

#### 第一刀不同，后续物品数量会放大代价

取 $x=12,k=3$。若第一刀选素因子二，拆出两件六；每件六再选三拆成三件二，各需一次，所以总操作为 $1+2\times1=3$。

若第一刀选三，拆出三件四；每件四再拆一次，总操作为 $1+3\times1=4$。因此不能只挑“子件大小更小”的第一刀，还要把子件数量乘进去。

对一个大于阈值的质数，例如十三，一次选十三就拆成十三件一，代价只有一次，而不是十三次。操作次数统计的是拆分动作，子件数量只影响未来还需执行多少动作。

转移到的 $x/p$ 总严格小于 $x$，所以递增枚举大小时，所需子状态已经算好，不存在循环依赖。不同初始物品互不合并，最终直接把各自最优代价相加。

### 参考代码

```cpp
// E. Prime Destruction
// 题意：多重集 a，一次操作选一个 x>1 和它的一个素因子 p，把一份 x 换成 p 份 x/p；
//       求让多重集里所有数都 ≤ k 的最少操作数。
// 关键：
//   ① 每个原始元素各自长出一棵“分解树”，互不干扰，所以答案 = 各元素代价之和；
//   ② 记 dp[x] = 把一份 x 变成“全都 ≤ k”的最少操作数：
//         x ≤ k          → dp[x] = 0
//         x > k          → dp[x] = min over 素因子 p of (1 + p * dp[x/p])
//      因为 x/p < x，按 x 递增填表即可；素因子用最小素因子筛枚举。
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200000;                // n ≤ 2e5，故 a_i ≤ 2e5
int spf[MAXN + 1];                      // spf[x] = x 的最小素因子
long long dp[MAXN + 1];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (int i = 2; i <= MAXN; i++) {           // 埃氏筛：只填一次，得到最小素因子
        if (spf[i] == 0) {
            for (int j = i; j <= MAXN; j += i)
                if (spf[j] == 0) spf[j] = i;
        }
    }

    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;                          // 初始元素个数与阈值
        vector<int> a(n);
        int hi = n;                             // 题面保证 a_i ≤ n，这里照样按实际最大值算，更稳
        for (int i = 0; i < n; i++) {
            cin >> a[i];
            hi = max(hi, a[i]);
        }
        for (int x = 1; x <= hi; x++) {
            if (x <= k) {                       // 已经达标，不用动
                dp[x] = 0;
                continue;
            }
            long long best = LLONG_MAX;
            int y = x;
            while (y > 1) {                     // 枚举 x 的每个不同素因子
                int p = spf[y];
                best = min(best, 1 + (long long)p * dp[x / p]);   // 一次操作 + p 棵子树
                while (y % p == 0) y /= p;      // 同一个素因子只算一次
            }
            dp[x] = best;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += dp[a[i]];   // 各元素独立，直接累加
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

相同素因子只枚举一次；拆出的份数要乘进代价，总答案使用 64 位整数。

## F. MEX Replacement

### 题意

多重集合用不同的数 $x_i$ 及其出现次数 $y_i$ 表示。一次操作选择非空子多重集合，删掉它们并加入这些数的 MEX，即最小的未出现非负整数。求最终能获得的最大数。

### 从零讲：倒着推需求 —— 要造出一个数，先得备齐比它小的所有数

MEX 为 $3$ 意味着选出的集合里必须有 $0,1,2$，且不能有 $3$。要造出一个更大的数，可以反过来问：这些较小的数要准备几份？

![倒推 MEX 的统一需求](assets/f-demand.svg)

从目标 $M$ 开始，最初每个 $0,1,\ldots,M-1$ 都需要一份。设处理到 $x$ 时，每种尚未处理的小数都需要 $q$ 份，而现有 $c_x$ 个 $x$。

若 $c_x\ge q$，直接使用 $q$ 个，多出来的 $c_x-q$ 个可以各自取单元素集合，转化为 $0$。若 $c_x<q$，缺的 $q-c_x$ 个 $x$ 都必须新造；每造一个又需要一套 $0,1,\ldots,x-1$，所以较小数的统一需求更新为
$$q\leftarrow q+(q-c_x)=2q-c_x.$$
优先使用现成的 $x$ 不会吃亏：拆掉它再重造，只会额外消耗较小数。展开到零后，现有零加上所有多余正数转成的零，只要不少于最终需求，就可沿相反顺序逐层合成。

例如 $\{2,2,2\}$ 可以得到 $3$：保留一个 $2$，另两个变成两个 $0$；再把一个单独的 $0$ 变成 $1$，最后对 $\{0,1,2\}$ 取 MEX。这里不能从“有两个零”直接跳到“有 $0,1,2$”，制造 $1$ 也会消耗一个零。

如果连续 $d$ 个值都没有库存，每层把 $q$ 翻倍，合并成一次乘 $2^d$。这就是压缩计数输入仍能快速处理的原因。

### 思路

设当前最大数为 $M_0$。保留它即可得到答案下界 $M_0$。对候选 $M>M_0$，调用下面的倒推判定，从 $M-1$ 到 $1$ 处理实际出现的值与空档；最后检查零是否够用。

初始总数量最多 $2\times10^{14}$。在 $M_0$ 上方每经过一个没有库存的层，需求至少翻倍，因此超过 $M_0$ 太远必定不可行。代码只尝试到 $M_0+64$，并在需求超过总数量时立刻失败。空档长度为 $d$ 时直接把需求乘 $2^d$，无需逐个访问巨大的数值。

排序 $O(n\log n)$，之后至多 $64$ 次线性判定，时间 $O(n\log n+64n)$，空间 $O(n)$。

#### 只有零的库存，也能从倒推需求看出增长速度

从四个零开始，可以造出三：先把两个单独的零分别变成两个一，剩下两个零；用一个零与一个一造二；最后用余下的零、一和二造三。

倒推同一目标：要造三，先需零、一、二各一份。没有现成的二，就要再准备一套零、一，此时零与一各需两份；没有一，就要再造两个一，各消耗一个零，最终需要四个零，恰好够用。

想造四时，在这个过程外还多一层缺失数三，需求再次翻倍到八个零，所以四个零不够。每个连续空档让统一需求乘二，这正是不能按巨大数值范围逐层循环、而要一次跳过空档的原因。

当某种正数库存多于需求，多出来的每件都能单独取 MEX 变为零；用掉现成需求后再把余量记入零库存，不能把同一副本既保留又折成零。

### 参考代码

```cpp
// F. MEX Replacement
// 题意：多重集用压缩形式给出（值 x_i、出现次数 y_i）。一次操作：任选一个非空子集，
//       把它们全部删掉、插入这些数的 MEX。问过程中能出现过的最大整数。
// 关键（倒着想“造出一份 M”）：
//   要造一份 M，就得先让 0..M-1 各有一份。从大到小扫值 x，记当前需要 q 份 x：
//     · 初始有 c 份，c ≥ q：用掉 q 份，多出的 c-q 份是“闲余”——单个取出来就能变成 0；
//     · c < q：缺的 q-c 份每份都要再造一整套更小的值，于是下一层的需求
//       q' = q + (q-c) = 2q - c（原来那 q 份也各要消耗一份 x-1）；
//     · (x,p) 之间连续 d 个值在初始多重集里没有 → 需求连着翻倍 d 次，q ← q·2^d。
//   扫到 0 时，初始的 0 的份数加上所有闲余 ≥ q，就说明 M 造得出来。
//   能造 M 则 M-1 也一定能造；又因缺口每步翻倍，M 最多比 max x_i 大 48 左右，
//   所以只需在 [mx, mx+64] 这个小区间里挑最大的可行值。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<pair<ll, ll>> a(n);              // (值, 份数)
        ll mx = 0, total = 0;                   // 最大初始值、元素总个数
        bool hasZero = false;
        for (int i = 0; i < n; i++) {
            cin >> a[i].first >> a[i].second;
            mx = max(mx, a[i].first);
            total += a[i].second;
            if (a[i].first == 0) hasZero = true;
        }
        sort(a.begin(), a.end(), [](const pair<ll, ll> &p, const pair<ll, ll> &q) {
            return p.first > q.first;           // 按值从大到小扫
        });
        if (!hasZero) a.push_back(make_pair(0LL, 0LL));   // 没给 0 就补一个空条目，好收尾

        // can(M)：M（> mx）能不能被造出来
        auto can = [&](ll M) -> bool {
            ll q = 1;                           // 还需要 1 份 M
            ll ex = 0;                          // 闲余元素数（每个都能单独变成一份 0）
            ll p = M;                           // 上一次处理到的值
            for (size_t i = 0; i < a.size(); i++) {
                ll x = a[i].first, c = a[i].second;
                ll gap = p - x - 1;             // (x, p) 之间缺失的整数值个数
                if (gap > 60) return false;     // 2^60 已超过元素总数上限 → 不可能
                if (q > (total >> gap)) return false;   // 翻倍后必然超过总元素数
                q <<= gap;
                if (q > total) return false;
                p = x;
                if (x == 0) {                   // 扫到 0：初始的 0 全归入闲余，收尾
                    ex += c;
                    break;
                }
                if (c >= q) ex += c - q;        // 多余的份数变闲余，需求 q 不变
                else q = 2 * q - c;             // 缺的份数各要再造一整套更小的值
                if (q > total) return false;
            }
            return ex >= q;                     // 闲余 + 初始 0 够不够填 0 的需求
        };

        ll ans = mx;                            // 初始就存在的最大值天然可达
        for (ll M = mx + 1; M <= mx + 64; M++)  // 线性扫一遍取最大（不依赖单调性）
            if (can(M)) ans = M;
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

总物品数远大于显式数组长度，不能展开。大位移与需求翻倍先判断上界，再计算，避免溢出。候选等于原最大值时无需执行操作。

## G. Modular Tree

### 题意

以 $1$ 为根的树上，每个点有当前值 $a_u$ 和模数 $b_u$，且 $0\le a_u<b_u$。一次操作选点 $u$，把它的值加上所有直接儿子的当前值，再对 $b_u$ 取模。求所有点的值之和最大能是多少。

### 从零讲：一个点能取到哪些值 —— 模意义下的等差数列

先看模 $10$ 下不断加 $4$：从 $1$ 出发依次得到 $1,5,9,3,7$，再回到 $1$。能到的值恰好是所有奇数，其共同特征是与初值模 $\gcd(10,4)=2$ 同余。

如果有多种可选增量，能到的差值由“模数与全部增量的 $\gcd$”决定。原因是每次加法保持这个余数；反方向利用裴蜀定理可以把 $\gcd$ 表示成增量与模数的整数线性组合。负次数也不成问题：模意义下重复有限次会回到原位，逆操作能由若干次正向操作实现。

在树上，父亲的增量是儿子值之和。固定儿子时得到初始和 $S$；某个可变儿子的可达值是一条间隔为 $g_v$ 的同余类，选相邻两项能使父亲的增量相差 $g_v$。所以全部可能增量生成的步长就是正文的 $\gcd$。

这也给出归纳：叶子的同余类只有初值；知道所有儿子的可达集合后，就能确定父亲的可达集合。注意“同余类”包含小于初值的项，不能只理解成不断加步长而不发生回绕。

### 思路

一个点模十、初值一，若唯一固定儿子的值为四，重复操作得到 $1,5,9,3,7$ 后回到一，最大为九。所有可达值都与初值模二同余，这里的二正是 $\gcd(10,4)$。当儿子也能变化时，父亲可以选用多种增量，需要求出这些增量共同生成的步长。

#### 可达集合用一个公约数表示

在模 $b_u$ 下，如果允许若干增量，重复相加生成的差值恰是它们与模数最大公约数的倍数。一方面所有操作保持对应同余；另一方面这些增量生成的有限加法子群包含它们的最大公约数倍数。负向操作也可实现，因为固定增量重复有限次会回到原值，逆向一步可替换为若干次正向加法。

因此把点 $u$ 的可达集合记为所有满足 $x_u\equiv a_u\pmod{g_u}$、$0\le x_u<b_u$ 的值，其中 $g_u\mid b_u$。叶子增量为零，不能变化，故 $g_u=b_u$。

#### 儿子如何影响父亲的步长

令儿子初值之和为 $S$。把它们保持在初始状态，父亲就能加 $S$。若某个儿子 $v$ 可变，即 $g_v<b_v$，它的可达值有至少两个且按间距 $g_v$ 排列；取两个相邻可达值，其他儿子不动，父亲两种可用增量恰相差 $g_v$。所以父亲生成的子群包含 $S$ 以及所有可变儿子的 $g_v$。

反过来，任何儿子可达值与其初值的差都是 $g_v$ 的倍数，因此任意父亲增量都是 $S$ 加这些步长的整数组合，不会生成额外的更小步长。由此得到精确递推
$$g_u=\gcd\bigl(b_u,S,\{g_v:g_v<b_v\}\bigr).$$
固定儿子只有一个可达值，不提供差值，不能把它的模数放进集合；它的贡献已包含在 $S$ 中。

#### 单点最大值为何可以同时实现

小于 $b_u$ 且与 $a_u$ 模 $g_u$ 同余的最大值为
$$a_u+\left\lfloor\frac{b_u-1-a_u}{g_u}\right\rfloor g_u.$$
先将根调到最大，再调各孩子及后代。对子树操作只改变选中的节点，不会自动改变已经固定的祖先，因此可以依次固定各点。

还需说明先前调父亲时用过的子树状态不会让后续选择受限：每一步模加在保持儿子状态不变时都可重复若干次撤销，所以任意已到达的整体状态都能沿逆操作回到此前状态。子树内的可达范围不会因为曾经被用于辅助祖先而缩水。于是每点单独求出的最大值能够全部共存，答案直接求和。

代码先迭代遍历树记录父亲及访问序，倒序时孩子的 $g_v$ 已求出，逐条边合并公约数即可，避免深链递归风险。

### 参考代码

```cpp
// G. Modular Tree
// 题意：根为 1 的树，每个点有当前值 x_i 和模数 b_i。一次操作选一个点 u：
//       设 s = u 的所有直接孩子的当前值之和，令 x_u = (x_u + s) mod b_u。
//       可以操作任意多次，求最终所有点的值之和的最大值。
// 关键（官方题解）：
//   ① 点 u 能取到的值恰好是等差列 (a_u + g_u · t) mod b_u，其中
//        g_u = gcd(b_u, S_u, { g_v : v 是 u 的“可变”直接孩子 })
//        S_u = u 的所有直接孩子的**初始值**之和；孩子 v“可变”当且仅当 g_v ≠ b_v。
//        直观：孩子全留在初始值时，一次操作就给 u 加上 S_u；每个可变孩子还能把这个
//        和挪动 g_v 的任意倍数（它自己值总是 ≡ a_v mod g_v）；能取的步长就是
//        这些量与 b_u 的最大公约数。叶子没有孩子 → g = gcd(0, b) = b，值被钉死在 a_u。
//   ② 每个点各自能取到的最大值可以同时取到：先把某个点推到它的最大值，再进它孩子的
//        子树里折腾——子树里的操作只改孩子自己，不会回头动已经推到位的这个点。
//   所以答案 = Σ ( a_u + ⌊(b_u − 1 − a_u) / g_u⌋ · g_u )。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<ll> a(n + 1), b(n + 1), g(n + 1, 0);
        for (int i = 1; i <= n; i++) cin >> a[i];       // 初始值
        for (int i = 1; i <= n; i++) cin >> b[i];       // 模数
        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            cin >> u >> v;                              // 无向边，后面按根 1 定向
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // 迭代式 DFS 求“访问序 + 每个点的父亲”，再逆序自底向上算 g（n 到 2e5，递归会爆栈）
        vector<int> par(n + 1, 0), order;
        vector<char> vis(n + 1, 0);
        order.reserve(n);
        vector<int> stk;
        stk.push_back(1);
        vis[1] = 1;
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (size_t i = 0; i < adj[u].size(); i++) {
                int v = adj[u][i];
                if (!vis[v]) {
                    vis[v] = 1;
                    par[v] = u;                         // 定父亲
                    stk.push_back(v);
                }
            }
        }
        for (int idx = (int)order.size() - 1; idx >= 0; idx--) {
            int u = order[idx];
            ll gc = 0, S = 0;                           // gc 收集各可变孩子贡献的步长
            for (size_t i = 0; i < adj[u].size(); i++) {
                int v = adj[u][i];
                if (v == par[u]) continue;              // 只看直接孩子
                if (g[v] != b[v]) gc = gcd(gc, g[v]);   // g_v == b_v 的孩子值被钉死
                S += a[v];                              // 孩子都留在初始值时的和
            }
            gc = gcd(gc, S);
            g[u] = gcd(gc, b[u]);                       // 还要和模数取 gcd
        }

        ll ans = 0;
        for (int i = 1; i <= n; i++)
            ans += a[i] + (b[i] - 1 - a[i]) / g[i] * g[i];   // 该点能取到的最大值
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

固定儿子满足 $g_v=b_v$，它不提供可变步长。答案和取模前的加法均使用 64 位整数。

## H. Deque Malfunction

### 题意

数值 $b_1,\ldots,b_m$ 依次到达。每次必须把到达的元素放在双端队列某一端，或花一次代价插到任意位置；随时可以免费删除两端元素。要求最终队列恰为 $1,2,\ldots,n$，求最小代价，无法实现则输出 $-1$。

### 从零讲：留下来的那一次出现 —— 前缀最小与后缀最小

最终每个值只保留一次，记值 $i$ 选中的到达时间为 $t_i$。没有选中的出现可以放到队首后立即删除，不影响保留元素。

到达值 $i$ 时，如果所有更小的保留值都还没到，即
$$t_i<\min(t_1,\ldots,t_{i-1}),$$
它是当前已保留元素中的最小值，可以免费放队首。这个条件称为按数值扫描时的“前缀最小纪录”。同理，若所有更大的值都没到，它可以放队尾，对应后缀最小纪录。两边都有已到元素时，它必须插入中间，至少付一次代价；把此前保留的元素始终按序摆放，就能恰好付一次完成。

![前缀最小与后缀最小的例子](assets/h-records.svg)

图中 $t=(7,3,2,5,4)$，前缀纪录有 $3$ 个，后缀纪录有 $2$ 个。只有全局最早的时间 $2$ 同时属于两类，免费元素数为 $3+2-1=4$，剩下一个需付费。

难点是每个值可能出现多次，不能先随意选时间再数纪录。需要 DP 同时优化选择。状态只保留“目前最早时间”和“已有纪录数”，因为下一次是否创造新纪录，只取决于新时间是否更早；其他已选时间不再影响转移。线段树只是把“所有比 $t$ 晚的状态里最好的一个”这次查询加速到 $O(\log m)$：叶子存一个时间的最优值，父节点存两个儿子的最大值，区间查询拆成若干完整节点后取最大。

### 思路

假设最终选中的到达时刻按数值一到五排列为 $[7,3,2,5,4]$。最早到的是三，之后二可以免费放前端、五可以免费放后端、一又可放前端；四到达时三与五都已在队列中，只能花一次费用插在它们中间。费用由选中时刻的相对顺序决定，而重复出现提供了选择这些时刻的余地。

#### 将队列操作化为纪录数

最终每个值只保留某一次出现，记其时刻为 $t_i$。其他出现可以从某一端放入后立即删掉，不干扰这些保留元素。它们的相对次序以后无法靠端点删除交换，因此可以始终让已保留元素按数值有序。

值 $i$ 到达时，若所有更小值的保留时刻都更晚，它就是当前最小值，可放前端，条件为 $t_i<\min_{j<i}t_j$；若所有更大值都更晚，它就是当前最大值，可放后端，条件为 $t_i<\min_{j>i}t_j$。若两侧都有更早到达的保留值，必须插中间，至少付一，而且按序插入恰付一即可。

前一个条件是从小值到大值扫描的前缀最小纪录，后一个是反向的纪录。只有全局最早时刻同时属于两类，所以免费次数为两类纪录数之和减一，总代价为 $n$ 减免费次数。任何值完全没出现时当然无解。

#### 用最早时刻作为 DP 状态

从小到大处理数值，令 $dp[p]$ 表示已经为每个已处理数值选过一次出现、最早选中时刻为 $p$ 时，最多有多少个前缀纪录。下一值选择时刻 $t$，若它成为新纪录，则旧最早时刻必须严格大于 $t$，得到
$$\mathrm{new}[t]=1+\max_{p>t}dp[p].$$
处理第一个数值时，没有旧状态，每个出现都可作为一条纪录起步。若新数值不创造纪录，则保留旧状态 $p$，但必须有一次出现晚于 $p$，只需检查其最后出现时刻是否大于 $p$。不同数值不可能占据同一到达时刻，所以代码删除 $p>\mathrm{last}$ 的旧状态就足够；等于最后时刻的是当前数值新建的状态，应保留。

线段树按时刻保存 $dp$ 最大值，区间查询 $(t,m]$ 得到转移；有序集合保存仍存活的时刻，用于从大端批量删除超过当前最后出现时间的状态。当前值所有出现的转移必须先查询完再写入，否则后一次查询可能利用同一数值刚创建的状态，虚增纪录数。每个位置在一遍处理中只创建、删除各一次。

#### 两个方向为什么能拼接

正向处理全部数值得到 $L[p]$，反向处理得到 $R[p]$，均表示全局最早时刻固定为 $p$ 的最优纪录数。设该时刻的数值为 $v$，在正向扫描中，遇到 $v$ 后不再可能有新的前缀纪录，故真正影响 $L[p]$ 的是数值不超过 $v$ 的选择；大于 $v$ 的值只需各有一个晚于 $p$ 的出现。反向同理，真正影响 $R[p]$ 的是数值不小于 $v$ 的选择。

因此两者各自最优的两侧选择可以合并，唯一共享的是 $v$ 在时刻 $p$ 的那次出现。取 $\max_p(L[p]+R[p]-1)$ 就是最多免费元素数，从 $n$ 减去即可。两个方向总共 $O(m\log m)$，不需枚举每个值的所有出现组合。

### 参考代码

```cpp
// H. Deque Malfunction
// 题意：元素 b_1..b_m 依次到达，每个到达时必须三选一：压到队首 / 压到队尾 / 故障插入到任意位置（代价 1）；
//       任意时刻还能从队首或队尾删除。最后要求队列恰好是 [1,2,...,n]。求最少故障次数，做不到输出 -1。
// 关键（官方题解）：
//   ① 每个值 1..n 只留一个出现：其余出现都能“压到某一端、再立刻从同一端删掉”，不花代价。
//      设值 i 留下的是第 t_i 次到达，则
//        压队首不故障 ⟺ t_i < min(t_1..t_{i-1})，即 t_i 是前缀最小；
//        压队尾不故障 ⟺ t_i < min(t_{i+1}..t_n)，即 t_i 是后缀最小。
//      所以免故障个数 = 前缀最小数 L + 后缀最小数 R − 1（全局最小被两边各算一次）。
//   ② 固定全局最小的位置 p，前缀、后缀两侧可以分别最优化：
//      dp[p] = 已处理完若干值时“当前最小位置是 p”前提下最多的前缀最小个数。
//      当前值 i 的某个出现 t 若要当上新的最小：dp_new[t] = 1 + max_{p>t} dp[p]；
//      旧状态 p 只有在“值 i 还有比 p 更靠后的出现”时才留得住，所以每步把 p > last_i 的状态清掉。
//   ③ 后缀侧把值的处理顺序倒过来跑同一套 DP。答案 = n − max_p (L[p] + R[p] − 1)。
//   实现：位置 1..m 上的“单点赋值 + 区间最大值”线段树，外加一个存活跃位置的有序集合做
//         摊还删除（每个位置一趟最多被删一次，总 O(m log m)）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;                              // 目标长度、到达元素个数
        vector<vector<int>> occ(n + 1);
        for (int i = 1; i <= m; i++) {
            int x;
            cin >> x;
            occ[x].push_back(i);                    // 记下每个值的所有到达位置（递增）
        }
        bool impossible = false;
        for (int i = 1; i <= n; i++)
            if (occ[i].empty()) impossible = true;  // 少一个值就凑不齐 [1..n]
        if (impossible) {
            cout << -1 << '\n';
            continue;
        }

        int sz = 1;
        while (sz < m + 1) sz <<= 1;                // 线段树下标 1..m
        // forward = true 跑前缀最小；false 把值的顺序倒过来跑后缀最小
        auto run = [&](bool forward) {
            vector<int> tree(2 * sz, 0), val(m + 2, 0);
            auto upd = [&](int pos, int v) {        // 单点赋值
                val[pos] = v;
                int p = sz + pos - 1;
                tree[p] = v;
                for (p >>= 1; p >= 1; p >>= 1)
                    tree[p] = max(tree[p << 1], tree[(p << 1) | 1]);
            };
            auto qry = [&](int l, int r) {          // 闭区间最大值；空区间给 0
                int res = 0;
                if (l > r) return res;
                for (l += sz - 1, r += sz - 1; l <= r; l >>= 1, r >>= 1) {
                    if (l & 1) res = max(res, tree[l++]);
                    if (!(r & 1)) res = max(res, tree[r--]);
                }
                return res;
            };
            set<int> alive;                         // 当前值 > 0 的位置
            bool first = true;                      // 处理第一个值时，任何出现都能当最小
            for (int step = 0; step < n; step++) {
                int i = forward ? (step + 1) : (n - step);
                vector<pair<int, int>> nw;
                for (size_t j = 0; j < occ[i].size(); j++) {
                    int tt = occ[i][j];
                    int rr = qry(tt + 1, m);        // 新的最小必须比旧最小更靠前
                    int nv = rr > 0 ? rr + 1 : (first ? 1 : 0);
                    nw.push_back(make_pair(tt, nv));    // 先全部算完再插入，避免层内污染
                }
                for (size_t j = 0; j < nw.size(); j++) {
                    if (nw[j].second > 0) {
                        upd(nw[j].first, nw[j].second);
                        alive.insert(nw[j].first);
                    }
                }
                int last = occ[i].back();
                while (!alive.empty() && *alive.rbegin() > last) {   // p > last_i 的状态作废
                    int p = *alive.rbegin();
                    alive.erase(p);
                    upd(p, 0);
                }
                first = false;
            }
            return val;
        };

        vector<int> L = run(true), R = run(false);
        int best = 0;
        for (int p = 1; p <= m; p++)
            best = max(best, L[p] + R[p] - 1);      // 两侧共享同一个全局最小
        cout << n - best << '\n';                   // 剩下的人都得靠“故障插入”
    }
    return 0;
}
```

### 易错点

DP 的轴是出现时间 $1\ldots m$，不是数值。合并减去重复计入的最早元素；清除的是严格大于当前值最后出现时间的状态。

## A. In Search of Convenience

### 题意

给整点 $(x_0,y_0)$ 与正整数半径 $R$，输出距离它恰为 $R$ 的任意整点。[原题](https://codeforces.com/contest/2275/problem/A)

### 思路

假设路由器在 $(-2,3)$，半径为四，可以把电脑放在 $(2,3)$。两点纵坐标相同，横向恰好相差四，距离自然就是四，而且新坐标仍为整数。

一般地，距离条件平方后为 $(x-x_0)^2+(y-y_0)^2=R^2$。不必搜索圆周上的所有整点；直接令 $y-y_0=0$，剩下的式子就是 $(x-x_0)^2=R^2$。选正方向即可得到 $x=x_0+R,y=y_0$。代回距离公式，结果为 $\sqrt{R^2}=R$，其中题目保证半径为正。

代码输出横坐标加半径、纵坐标保持原值。输入中中心坐标的范围仅限制输入，并不要求答案仍位于这个小区间，所以靠近输入边界时也无需换方向或截断坐标。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int x, y, r;
        cin >> x >> y >> r;
        // 水平方向移动 r，纵坐标不变，距离恰好为 r。
        cout << x + r << ' ' << y << '\n';
    }
}
```

### 易错点

输出点坐标不受输入中心的 $[-10,10]$ 范围限制；不同合法点都可接受。

## B. Did Not Go to Print

### 题意

命令一把当前文档存入栈；命令二优先打印并移除栈顶，栈空才打印当前文档；命令三直接打印当前文档。输出从未打印的编号。

### 思路

栈像一叠纸，后放入的先取出。用数组末端作为栈顶，再用标记数组记录真正打印过的文档。例如命令串 `"1122"` 先存一、二，后打印二、一，当前的三、四反而没有打印。逐命令模拟对应动作，最后递增输出未标记的编号即可。时间、空间均为 $O(n)$。

#### 当前文档与栈顶文档是两个身份

命令为 `"12123"`。第一步把文档一压栈；第二步打印并弹出文档一，文档二本身没打印。第三步把文档三压栈；第四步打印文档三，文档四本身没打印；第五步直接打印文档五。因此未打印的是 $2,4$。

保存栈只负责“以后命令二优先取谁”，打印标记才负责最终答案。一个文档可能留在栈中直到结束，也可能根本没有入栈；这两种情况只要从未真正执行打印，都应输出。

处理命令二时必须先分支：栈非空只标记栈顶，并弹出；栈空才标记当前编号。不能在分支外统一再标记当前文档，否则会把第二、四步的文档错误地当成已打印。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); // 统一使用 C++ 输入输出。
    cin.tie(nullptr); // 解除输入与输出的绑定。
    int t; cin >> t; // 读取测试组数。
    while (t--) {
        int n; string s; cin >> n >> s; // 读取文档数与命令串。
        vector<int> pending; // 数组末尾表示打印机栈顶。
        vector<bool> printed(n + 1, false); // 标记真正打印过的文档。
        for (int i = 1; i <= n; ++i) {
            if (s[i - 1] == '1') {
                pending.push_back(i); // 扫描当前文档，将它压到栈顶。
            } else if (s[i - 1] == '2' && !pending.empty()) {
                printed[pending.back()] = true; // 打印栈顶，而非当前文档。
                pending.pop_back(); // 已打印的文档退出内存。
            } else {
                printed[i] = true; // 快印或空栈打印，打印当前文档。
            }
        }
        vector<int> missing; // 收集未打印文档。
        for (int i = 1; i <= n; ++i) {
            if (!printed[i]) missing.push_back(i); // 按编号递增收集。
        }
        cout << missing.size() << '\n'; // 输出未打印数量。
        for (int id : missing) cout << id << ' '; // 输出编号。
        cout << '\n'; // 没有遗漏时也保留空行。
    }
}
```

### 易错点

命令二打印了栈顶时，当前文档不会自动入栈，也不算打印过。

## D. Precision Alignment

### 题意

每组读数为有序三元组 $(a,b,c)$，一次可执行 $c\gets c+\operatorname{sgn}(a-b)$、$b\gets b+\operatorname{sgn}(a-c)$ 或 $a\gets a+\operatorname{sgn}(b-c)$。共有多个实验室，总操作预算为 $k$，最大化它们最终总和的最小值。

### 思路

先固定共同目标 $X$，单个实验室原总和为 $s$。若 $X\le s$，什么也不做，代价零。若已有 $a>b$ 或 $b>c$，固定形成逆序的两数，反复增加第三个数，每次总和加一，代价恰为 $X-s$。

若三数全等，所有符号均为零，无法提高。剩下是 $a\le b\le c$ 且不全等，第一次出现逆序前只能做减法。要使 $a>b$ 至少减少 $b-a+1$，要使 $b>c$ 至少减少 $c-b+1$，因此启动至少花

$$r=\min(b-a,c-b)+1$$

步。降低较小间隔对应的右端点可以达到它：降低 $b$ 由 $a<c$ 保证方向为负；选择降低 $c$ 时对应 $a<b$。例如 $(1,2,5)$，将中间数降到零花两步，随后固定 $1>0$ 就可一直增加末项。

启动使总和先少了 $r$，再补回损失并升到 $X$，总成本为 $X-s+2r$。其它减法不能更快造出逆序，因为每次只能消除至多一个单位的上述间隔。

各实验室互不影响，最小成本相加不超过 $k$ 即可行；目标越高越难，二分最大可行值。范围取初始最小和到它加 $k$，并由冻结实验室截断。时间 $O(n\log(k+1))$，空间 $O(n)$。

#### 启动费为什么要算两遍，且不能无条件收取

实验室为 $(1,2,5)$，原和为 $8$，启动步数 $r=2$。若目标为 $10$，先把中间数由 $2$ 降到 $0$，花两步，总和先降到 $6$；之后固定 $1>0$，把末项增加四次，升到总和 $10$。总共六步，等于 $10-8+2\times2$。

其中一份 $r$ 是实际启动操作，另一份是后面补回启动损失的操作，不能只收一次。

若还有实验室 $(3,1,2)$，预算为五步：共同目标 $8$ 时，第一个已经达标，费用零；第二个已有逆序，只需两步，合计二。共同目标 $9$ 时，第一个需五步、第二个需三步，合计八，不可行。

这个例子说明，启动代价只在原和低于目标时付；若给所有单调实验室都预收启动费，会连本来不需改变的状态也算贵。二分判定逐实验室采用各自最小成本，彼此不共享状态，最后只累加预算。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Lab {
    long long sum, activation; // 当前总和，以及首次获得上升操作所需的下降次数。
    bool frozen; // 三个读数相同的实验室永远不变。
};

int main() {
    ios::sync_with_stdio(false); // 统一使用 C++ 输入输出。
    cin.tie(nullptr); // 解除输入与输出的绑定。
    int t; cin >> t; // 读取测试组数。
    while (t--) {
        int n; long long k; cin >> n >> k; // 读取实验室数与操作预算。
        vector<Lab> labs(n); // 保存各实验室的独立代价参数。
        long long minimum = LLONG_MAX, frozenCap = LLONG_MAX;
        for (Lab &lab : labs) {
            long long a, b, c; cin >> a >> b >> c; // 顺序固定，不能排序。
            lab.sum = a + b + c; // 初始总和。
            lab.frozen = (a == b && b == c); // 相等时三个符号函数都为零。
            lab.activation = (a > b || b > c) ? 0 : min(b - a, c - b) + 1;
            minimum = min(minimum, lab.sum); // 不操作时的答案。
            if (lab.frozen) frozenCap = min(frozenCap, lab.sum); // 冻结实验室给出硬上界。
        }
        auto feasible = [&](long long target) {
            long long remaining = k; // 用剩余预算，避免累加全部代价造成溢出。
            for (const Lab &lab : labs) {
                if (lab.sum >= target) continue; // 已达标的实验室不用动。
                if (lab.frozen) return false; // 冻结实验室不可能提升。
                long long need = target - lab.sum + 2 * lab.activation;
                if (need > remaining) return false; // 预算不足即可提前结束。
                remaining -= need; // 扣除这个实验室的最少操作数。
            }
            return true; // 所有实验室均可达标。
        };
        long long low = minimum, high = min(minimum + k, frozenCap);
        while (low < high) {
            long long mid = low + (high - low + 1) / 2; // 取上中点，寻找最大可行值。
            if (feasible(mid)) low = mid; // 可行时继续尝试更大的目标。
            else high = mid - 1; // 不可行时缩小上界。
        }
        cout << low << '\n'; // 输出最大可行的最小总和。
    }
}
```

### 易错点

已经达到目标时不付启动费；累加成本超过预算立即停止，防止总和溢出。

## G. Copper Squander

### 题意

卖掉旧边得到收入，保留边不收钱；添加第 $r$ 条新边花 $rx$，可连任意两点。要求最终连通，对每个 $x$ 求最大利润。

### 从零讲：Kruskal 前缀与离散凸性

先假想全部旧边都卖掉。保留一条边等于支付它的回收价格，因此希望留下能连接更多点的便宜边。保留边不应成环，否则卖掉环上一条仍保持连通性，还能多赚收入。

Kruskal 将边由便宜到贵扫描，只在两端属于不同连通块时保留。并查集用代表点表示连通块，查询代表相同说明已连通，合并两块就减少一个块。它的前 $s$ 条选边是最便宜的 $s$ 边森林：向任意候选森林逐条加入贪心边，若成环便删去环上尚未固定且不更便宜的边；若不成环则删去另一条尚未固定边。每次都能维持边数且不增加费用。

保留边数增加时，新增保留成本越来越高、省下的新建费用越来越少，因此总成本先下降后上升。这种相邻差分非降的性质，就是这里使用的离散凸性。

### 思路

设全部旧边收入为 $T$，按价从小到大进行 Kruskal，得到选中边价 $w_1,\ldots,w_r$ 与前缀和 $P_s$。保留 $s$ 条边后还需 $k=n-1-s$ 条新边，利润为

$$T-P_s-x\frac{k(k+1)}2.$$

增加第 $s$ 条保留边，放弃收入 $w_s$，但省掉一条最贵新边，其价格为 $x(n-s)$。只要 $w_s\le x(n-s)$ 就值得保留。左边非降，右边递减，条件只会由成立变为不成立，二分最后可保留边即可。

例如两点间旧边值五：$x=1$ 时卖掉再建赚四，$x=6$ 时保留赚零更好。预处理 $O(m\log(m+1)+m\alpha(n))$，每询问 $O(\log n)$，空间 $O(n+m)$。

#### 用所有保留条数核对二分分界

四个点的旧图是一条链，三条边回收价为 $2,5,9$，总收入 $T=16$。设新建单价参数 $x=1$。

| 保留旧边数 $s$ | 放弃收入 $P_s$ | 新边数 $k$ | 利润 |
|---|---|---|---|
| $0$ | $0$ | $3$ | $16-6=10$ |
| $1$ | $2$ | $2$ | $16-2-3=11$ |
| $2$ | $7$ | $1$ | $16-7-1=8$ |
| $3$ | $16$ | $0$ | $0$ |

新增第一条保留边只放弃两元，却省掉原本最贵的第三条新边三元，值得；新增第二条保留边放弃五元，却只省掉第二条新边两元，不值得。后面的保留价更高，能省掉的费用又更低，因此不会重新变得值得。

二分找的正是这个“最后仍值得”的前缀长度。Kruskal 未选中的旧边本来就在环上，保留它不会减少连通块数；卖掉更好，所以不用把全部旧边都放入这条边价序列。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size; // 父指针和集合大小。
    explicit DSU(int n) : parent(n), size(n, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) { // 迭代寻找代表元，并压缩路径。
        while (x != parent[x]) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    bool merge(int x, int y) { // 已连通时返回假，避免加入成环的边。
        x = find(x); y = find(y);
        if (x == y) return false;
        if (size[x] < size[y]) swap(x, y); // 小集合挂到大集合下面。
        parent[y] = x; size[x] += size[y]; // 更新父指针和大小。
        return true;
    }
};
struct Edge { int u, v; long long value; }; // 一条旧电缆。

int main() {
    ios::sync_with_stdio(false); // 统一使用 C++ 输入输出。
    cin.tie(nullptr); // 解除输入与输出的绑定。
    int t; cin >> t; // 读取测试组数。
    while (t--) {
        int n, m, q; cin >> n >> m >> q; // 读取建筑数、旧电缆数和询问数。
        vector<Edge> edges(m); long long total = 0; // total 是卖掉全部旧电缆的收入。
        for (Edge &e : edges) {
            cin >> e.u >> e.v >> e.value; --e.u; --e.v; // 转成零起始编号。
            total += e.value; // 累加全部旧电缆价值。
        }
        sort(edges.begin(), edges.end(), [](const Edge &a, const Edge &b) {
            return a.value < b.value; // 留下旧电缆等于放弃收入，所以优先留下便宜的。
        });
        DSU dsu(n); vector<long long> chosen, prefix(1, 0); // Kruskal 的选边序列及前缀代价。
        for (const Edge &e : edges) {
            if (dsu.merge(e.u, e.v)) {
                chosen.push_back(e.value); // 只保留能减少连通块数的边。
                prefix.push_back(prefix.back() + e.value); // 任意前缀都是对应边数的最便宜森林。
            }
        }
        while (q--) {
            long long x; cin >> x; // 当前场景的新电缆成本增量。
            int low = 0, high = (int)chosen.size(); // 二分最优保留边数。
            while (low < high) {
                int mid = (low + high) / 2; // 检查再保留第 mid+1 条边是否值得。
                if (chosen[mid] <= x * (n - 1LL - mid)) low = mid + 1;
                else high = mid; // 边价递增、节省递减，后面更不值得。
            }
            long long added = n - 1LL - low; // 剩余连通块之间还需的新电缆数。
            long long cost = prefix[low] + added * (added + 1) / 2 * x;
            cout << total - cost << ' '; // 全卖收入减去保留损失与安装成本。
        }
        cout << '\n'; // 一组场景输出一行。
    }
}
```

### 易错点

原图可能不连通，选中边数可能少于 $n-1$；利润也可能为负。

## A. Skibidus and Amog'u

### 题意

输入词根加后缀 `"us"` 形成的单词，输出相同词根加后缀 `"i"`。

### 思路

例如 $\texttt{cactus}$ 的词根是 $\texttt{cact}$，把末尾 $\texttt{us}$ 换成 $\texttt{i}$ 后得到 $\texttt{cacti}$。只替换最后两个字符，而不是删除单词中所有相同字母组合。

题目已保证输入由某个词根拼上 $\texttt{us}$ 得到，所以词根就是去掉末尾两字符后的前缀，无需查找后缀或判断语法。代码连续删除末尾字符两次，再追加 $\texttt{i}$，恰好执行这个定义。

词根允许为空：输入 $\texttt{us}$ 时，两次删除后字符串为空，随后追加得到 $\texttt{i}$。因此不能为了保留至少一个原字符而少删一次。

### 参考代码

```cpp
// A. Skibidus and Amog'u
// 题意：给定单数形式 W（保证以 "us" 结尾），输出对应的复数形式，
//       规则是单数 = 词根 S + "us"，复数 = 词根 S + "i"。
// 做法：把末尾的 "us" 换成 "i" 即可；注意词根可以为空（"us" -> "i"）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        string w;
        cin >> w;
        // 去掉最后两个字符 "us"，换成 "i"
        w.pop_back();          // 删掉 's'
        w.pop_back();          // 删掉 'u'
        w.push_back('i');      // 接上复数字尾 'i'
        cout << w << '\n';
    }
    return 0;
}
```

### 易错点

词根可以为空，不能强行保留首字符。

## B. Skibidus and Ohio

### 题意

可将相邻相等的两个字符合并成任意字符，求最终最短长度。

### 思路

从 $\texttt{abbd}$ 开始，可以把中间两个 $b$ 合成 $a$，得到 $\texttt{aad}$；再把两个 $a$ 合成 $d$，得到 $\texttt{dd}$；最后合成任意字符，长度变为一。每次都主动让合并结果等于旁边字符，才能继续操作。

若初始串没有相邻相同字符，操作的前提根本无法满足，状态也不可能自行变化，最短长度就是原长度。若存在相同的一对，证明可以一直缩短：当串长大于二时，这一对至少有一侧邻居，把合并结果选成该邻居的字符，就在新串中又得到一对相邻相同字符。长度每次减少一，这个性质一直维持到只剩两字符；再合并一次得到一字符。

操作一次只删除一个字符，无法把一字符变为空串，所以一就是绝对下界。代码仅检查是否存在相邻相同，不必实际执行构造；有则输出一，无则输出原长度。

### 参考代码

```cpp
// B. Skibidus and Ohio
// 题意：每次可以选一对相邻且相同的字符 (s_i, s_{i+1})，把 s_i 改成任意小写字母并删掉 s_{i+1}。
//       问经过任意多次操作后，字符串长度最小能是多少。
// 结论：只要串里存在一处相邻相等，长度就能一路降到 1；否则一次操作都做不了，答案就是原长。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        string s;
        cin >> s;

        bool has_pair = false;              // 是否存在相邻且相等的一对
        for (size_t i = 0; i + 1 < s.size(); ++i) {
            if (s[i] == s[i + 1]) {
                has_pair = true;
                break;
            }
        }

        if (has_pair) {
            cout << 1 << '\n';              // 有相邻相等 -> 可以一直缩到 1 个字符
        } else {
            cout << s.size() << '\n';       // 没有相邻相等 -> 做不了任何操作
        }
    }
    return 0;
}
```

### 易错点

合并结果可以任意改字母，这是能持续吞并其它字符的关键。

## C1. Skibidus and Fanum Tax (easy version)

### 题意

每个 $a_i$ 可保持原值或变为 $b_1-a_i$，每位置至多一次，判断能否变为不下降数组。

### 思路

设唯一的 $b_1=10$，数组为 $[8,3,7]$。第一项可以选八或二，取二；第二项可以选三或七，取三；第三项可以选七或三，取三，得到不下降的 $[2,3,3]$。提前取较小值，让后面更容易接上。

每个位置独立地有两个候选 $a_i,b_1-a_i$，且等值允许相邻。设此前确定的最后一个值为 $v$，当前位置必须从不小于 $v$ 的候选中选择。贪心选其中最小值：如果某个完整方案在这里选了更大的数，把它降为这个最小候选，前面仍然不下降，后面的第一个数也仍不小于它，因此后续方案不受破坏。

更形式化地，贪心前缀末值始终不超过任意合法方案对应末值。若当前两个候选都小于贪心末值，它们也不可能接到其他更大的前缀末值上，所以可以判无解。代码先比较两个候选大小，小候选合法就取小的，否则尝试大的。

第一项没有下界，初始末值用足够小的负数。操作后允许出现零和负数，不能把末值初始化为零而误删这些合法候选。

### 参考代码

```cpp
// C1. Skibidus and Fanum Tax (easy version)
// 题意：给定数组 a[1..n] 和只含一个元素的 b（本版本保证 m = 1）。
//       对每个 i 至多操作一次：a_i := b_1 - a_i（结果可以是非正数）。
//       问能否把 a 变成非降序列。
// 做法：从左往右贪心。设前一个位置的最终值为 pre，每个位置只有两个候选
//       （保持 a_i，或改成 b_1 - a_i），取「不小于 pre 的候选里最小的那个」，
//       这样给后面留的余地最大；两个候选都小于 pre 就无解。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;

        vector<long long> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        vector<long long> b(m);
        for (int i = 0; i < m; ++i) cin >> b[i];

        long long pre = LLONG_MIN / 4;   // 上一个位置的最终值；首元素没有下界
        bool ok = true;

        for (int i = 0; i < n; ++i) {
            long long keep = a[i];               // 候选一：不操作
            long long change = b[0] - a[i];      // 候选二：操作一次（m = 1，只有 b_1）
            long long lo = min(keep, change);
            long long hi = max(keep, change);

            if (lo >= pre) {
                pre = lo;                        // 小的那个就够大，取它
            } else if (hi >= pre) {
                pre = hi;                        // 只能退而取大的那个
            } else {
                ok = false;                      // 两个都小于 pre，本组无解
                break;
            }
        }

        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

允许操作出零或负数，初始下界不能设成零。

## C2. Skibidus and Fanum Tax (hard version)

### 题意

每个 $a_i$ 可不变或选择任意 $b_j$ 变为 $b_j-a_i$，判断能否使数组不下降。

### 思路

若当前原值为七、前一个最终值为三，且 $b=[5,10,13]$，操作后的候选为负二、三、六。最小可接上的操作结果是三；与不操作得到的七比较，最终取三。这里要找的不是最小的 $b_j$，而是足以达到前缀下界的最小 $b_j$。

仍从左到右让当前最终值尽可能小。设前一项为 $v$，不操作仅在 $a_i\ge v$ 时可用；若操作，则要满足 $b_j-a_i\ge v$，等价于 $b_j\ge v+a_i$。固定 $a_i$ 后，操作结果随 $b_j$ 递增，因此把 $b$ 排序并查找第一个不小于 $v+a_i$ 的元素，就得到最小合法操作结果。

将这个结果与合法的原值候选取较小者。选择较小值只会降低后续位置需要满足的下界，不会增加任何限制；从任意可行方案出发，逐项替换为贪心值仍然可行，证明不会漏解。若两类候选均不存在，贪心前缀已经具有最小的末值，换任何其他前缀也无法让当前项接上，故无解。

同一个 $b_j$ 可被多个位置使用，并不是一次性的资源，所以查到后无需删除。代码以负无穷处理第一项，以最大整数作为尚无候选的标记，每个位置一次二分，时间 $O(m\log m+n\log m)$。

### 参考代码

```cpp
// C2. Skibidus and Fanum Tax (hard version)
// 贪心 + 排序 + 二分查找
//
// 每个 a[i] 只有两类取值：原值 a[i]（不操作），或 b[j] - a[i]（操作，选某个 j）。
// 从左往右定：为了让后面尽量好排，当前位置应当取「不小于前一个位置」的最小可行值。
// 若选操作，条件是 b[j] - a[i] >= prev，即 b[j] >= prev + a[i]；
// 想让结果最小，就要取满足该式的最小的 b[j] —— 把 b 排序后二分即可。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 stdio 的同步，读入更快
    cin.tie(nullptr);              // 解开 cin 与 cout 的绑定，少一次刷新

    int t;
    cin >> t;                      // 数据组数
    while (t--) {
        int n, m;
        cin >> n >> m;             // a 的长度、b 的长度
        vector<long long> a(n), b(m);
        for (int i = 0; i < n; i++) cin >> a[i];
        for (int j = 0; j < m; j++) cin >> b[j];

        sort(b.begin(), b.end());  // 排好序，b 上就能二分找「最小的够大的元素」

        const long long NEG = -(1LL << 62);  // 负无穷：第 1 个位置没有「前一个」的约束
        long long prev = NEG;                // prev = 上一个位置最终定下来的值
        bool ok = true;                      // 目前是否还有合法排法

        for (int i = 0; i < n; i++) {
            long long best = LLONG_MAX;              // 当前位置能取到的最小可行值
            if (a[i] >= prev) best = min(best, a[i]);  // 选择一：不操作

            // 选择二：操作。b[j] - a[i] >= prev  <=>  b[j] >= prev + a[i]
            // prev 取了 -2^62 这样的哨兵，加上 a[i] 也不会溢出 long long
            auto it = lower_bound(b.begin(), b.end(), prev + a[i]);
            if (it != b.end()) best = min(best, *it - a[i]);  // 最小的够大的 b[j]

            if (best == LLONG_MAX) { ok = false; break; }  // 两种选择都不合法 -> 排不出来
            prev = best;   // 压到最小，给后面的位置留最大余地
        }

        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

同一个 $b_j$ 可以被不同位置重复使用；不要把它从集合删除。

## D. Skibidus and Sigma

### 题意

若干等长数组可任意顺序拼接，最大化拼接数组的所有前缀和之和。

### 从零讲：拆贡献（每个元素被数了几次）

数组 $[2,3,1]$ 的前缀和总和为 $2+(2+3)+(2+3+1)$。换成逐元素数次数，二出现三次、三出现两次、一出现一次，得到 $3\times2+2\times3+1$。因此越靠前的元素，被后面更多前缀重复计入。对整块而言，顺序变化带来的额外贡献只由块和决定。

### 思路

有两块 $A=[5,1]$ 与 $B=[2,2]$。先放 $A$ 得到前缀和 $5,6,8,10$，总分二十九；先放 $B$ 得到 $2,4,9,10$，总分二十五。块和六大于四，将它提前带来的提升恰好为块长二乘和之差二，即四。

一块内部的第 $j$ 个元素，至少会出现在从自己到本块结束的 $m-j+1$ 个前缀中，这些内部贡献与块的相对顺序无关。若该块之后还有 $T$ 个元素，那么后面每一个前缀又会包含整块，所以额外贡献为 $T$ 乘该块元素和。

比较相邻两块，设它们和为 $S_A,S_B$，后面共同还有 $T$ 个元素。两种顺序的内部贡献不变，额外贡献之差为
$$((T+m)S_A+TS_B)-((T+m)S_B+TS_A)=m(S_A-S_B).$$
故较大块和在前不劣。如果一个排列中较小和位于相邻较大和之前，交换它们不会降低得分；不断消除这种逆序，最终得到块和降序的最优排列。和相等时顺序无关。

代码读入时累加全部内部得分，只保存每块总和。排序后，第零基下标 $i$ 块之后有 $m(n-1-i)$ 个元素，再乘它的块和加到答案即可，不必真正拼接大数组。

### 参考代码

```cpp
// D. Skibidus and Sigma
// 贪心 + 排序（交换论证：块的和越大越该往前放）
//
// 记第 k 块的和为 S_k，块内得分为 score_k = Σ_j (m-j+1) * a_{k,j}
// （块内第 j 个元素在整段里被数到的次数，至少是它自己到块尾这一截）。
// 把一块放到「它后面还剩 T 个元素」的位置上时，块里每个元素都会被后面每个前缀和再数一遍，
// 所以这块的总贡献 = score_k + T * S_k。
// 相邻两块 A、B，它们后面共同还剩 T 个元素：
//   A 在前 -> (T+m)*S_A + T*S_B
//   B 在前 -> (T+m)*S_B + T*S_A
// 两者相差 m*(S_A - S_B)：和大的放前面更优。于是全局最优 = 按块和降序排列。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 stdio 的同步
    cin.tie(nullptr);              // 解开 cin 与 cout 的绑定

    int t;
    cin >> t;                      // 数据组数
    while (t--) {
        int n, m;
        cin >> n >> m;             // n 个数组，每个长 m
        vector<long long> sum(n);  // 每个数组的元素和
        long long base = 0;        // 各数组「块内得分」之和（与排列顺序无关）

        for (int i = 0; i < n; i++) {
            long long s = 0;
            for (int j = 1; j <= m; j++) {
                long long x;
                cin >> x;
                s += x;
                // 块内第 j 个元素至少被「自己到块尾」这几个前缀和数到，共 (m-j+1) 次
                base += (long long)(m - j + 1) * x;
            }
            sum[i] = s;
        }

        sort(sum.begin(), sum.end(), greater<long long>());  // 块和从大到小

        long long ans = base;
        for (int k = 0; k < n; k++) {
            // 第 k 块（从 0 数）后面还有 (n-1-k) 个整块，即 m*(n-1-k) 个元素
            ans += (long long)m * (n - 1 - k) * sum[k];
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

块内元素次序不能改变；所有和与乘法用 `long long`。

## E. Skibidus and Rizz

### 题意

构造含 $n$ 个零、$m$ 个一的二进制串，使所有子串中零一数量差绝对值的最大值恰为 $k$。

### 从零讲：$\pm 1$ 映射与前缀和极差

把多数字符记为 $+1$，少数记为 $-1$，前缀和表示走过的高度。任意子串的差就是两个前缀高度之差，取绝对值后最大可能值等于最高高度减最低高度。即使最高点先出现，选两点之间的子串仍得到同一绝对差。因此本题等价于安排一条高度跨度恰为 $k$ 的路径。

### 思路

要放五个零、三个一，并令最大不平衡度为三，可以构造 $\texttt{00010101}$。将零看成上升一步、一看成下降一步，前缀高度为 $0,1,2,3,2,3,2,3,2$，最高三、最低零，任何子串的差都不超过三，而开头三个零达到三。

若把多数字符记为上升，总数为 $A$，少数字符记为下降，总数为 $B$，则起点高度为零、最终高度为 $A-B$。子串的零一差是两个前缀高度之差，最大绝对差就是整个前缀高度的极差。因此必须有 $k\ge A-B$；另一方面任何子串的同类字符最多只有 $A$ 个，不平衡度不可能超过 $A$，故还需 $k\le A$。

满足这两个条件时，先放 $k$ 个上升字符，从零升到 $k$。还剩 $A-k$ 个上升字符，每个配一个下降字符，按“下降、上升”顺序输出，使高度在 $k-1,k$ 之间往返。需要的下降数不超过 $B$，恰由 $k\ge A-B$ 保证。最后只剩下降字符，连续输出，将高度从 $k$ 降到 $A-B\ge0$。

初始上升阶段、中间往返和末尾下降都不越出 $[0,k]$，且零、$k$ 确实出现，因此极差恰好为 $k$。构造中两种字符用量分别是 $k+(A-k)=A$ 和 $(A-k)+(B-A+k)=B$。当一方数量为零时，可行条件迫使 $k=A$，直接输出全部同色字符即可。

### 参考代码

```cpp
// E. Skibidus and Rizz
// 构造 + 前缀和极差
//
// 把 0 看成 +1、1 看成 -1，则子串的 balance = 该段前缀和之差的绝对值（即 |x-y|）。
// 「所有子串 balance 的最大值」= 前缀和序列的 (最大值 - 最小值)，因为 P_0 = 0 一定在序列里。
// 记多数派字符的个数 A、少数派 B（若 n >= m 就让 up='0'，否则 up='1'，两者对称）。
// 可行 ⟺ |n-m| <= k <= max(n,m)：
//   · k >= |n-m|：整串自己就是一个 balance = |n-m| 的子串，最大值不会更小；
//   · k <= max(n,m)：某个子串要有 balance k，它里面至少有 k 个同一种字符，而任一种字符总数就那么多。
// 构造（以 up 为上升步）：
//   up^k 先爬到 k，再用 (down up)^(A-k) 在 k-1 与 k 之间来回，最后 down^(B-(A-k)) 一路降回 A-B。
//   路径始终落在 [A-B, k] 内（A-B >= 0），因此极差恰好是 k。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 stdio 的同步
    cin.tie(nullptr);              // 解开 cin 与 cout 的绑定

    int t;
    cin >> t;                      // 数据组数
    while (t--) {
        int n, m, k;
        cin >> n >> m >> k;        // n 个 0、m 个 1，要求最大 balance 恰好为 k

        // 选出「多数派」当上升步：n >= m 时 0 是上升步，否则 1 是上升步
        char up, down;
        int A, B;                  // A = 上升步总数，B = 下降步总数
        if (n >= m) { up = '0'; down = '1'; A = n; B = m; }
        else        { up = '1'; down = '0'; A = m; B = n; }

        if (k > A || k < A - B) {  // 两条必要条件都验一遍，不满足就无解
            cout << -1 << '\n';
            continue;
        }

        string s;
        s.append(k, up);                                  // up^k：一路升到 k
        for (int i = 0; i < A - k; i++) {                 // (down up)^(A-k)：原地来回，不越界
            s.push_back(down);
            s.push_back(up);
        }
        s.append(B - (A - k), down);                      // 剩下的下降步一路降回 A-B

        cout << s << '\n';
    }
    return 0;
}
```

### 易错点

前缀高度包括起点零；末尾高度通常大于零，不能把它误当整个过程的最低高度。

## F. Skibidus and Slay

### 题意

树上每点有值。对每个值 $x$，判断是否存在至少两个点的简单路径，使 $x$ 严格占多数。

### 从零讲：把「占多数」记成 $+1/-1$ 权值和，以及虚树

固定值 $x$，把等于它的点记为一，其余记为负一。若一条路径有 $u$ 个 $x$、$v$ 个其它点，权值和为 $u-v$，大于零恰好表示严格多数。

![长路径压成一条边，保留中间点的负权](assets/f-virtual.svg)

虚树只保留关键点和它们汇合的祖先，将没有关键点的长链压成边。链中间每删掉一个非关键点，就在边权中扣一，路径总分保持不变。最近公共祖先是两个点共有祖先中最深的那个；DFS 进入和退出编号可判断祖先关系，倍增表存向上 $1,2,4,\ldots$ 步的祖先，让查找在 $O(\log n)$ 完成。

### 思路

固定值二，路径上的数若为 $[2,7,2]$，将等于二的点记为一、其他点记为负一，权值和为一，说明二严格占多数；若为 $[2,7,8,2]$，权值和为零，只占一半，不合格。任务由此变成对每种值寻找一条至少含两个点的正权路径。

#### 只保留当前值的点和必要分叉

一条合法正权路径至少包含两个当前值的点。若其端点不是当前值，删去这个负权端点会增加得分，所以可以把两端修剪到当前值的点上，而仍有至少两个这样的点。故只需研究连接所有当前值点的路径。

对某个值 $x$，把其全部出现位置作为关键点，按 DFS 进入顺序排序，并加入相邻关键点的最近公共祖先。这些祖先涵盖连接关键点时遇到的分叉：如果某祖先的不同儿子子树中都有关键点，按 DFS 顺序从一个子树切换到另一个时，就会出现一对相邻关键点以它为最近公共祖先。再排序去重，用祖先栈将每点连接到最近的已保留祖先，即得到虚树。

关键点及加入的祖先仍保留原来的点权 $+1$ 或 $-1$。一条虚边若在原树上长为 $d$ 条边，中间省略的 $d-1$ 个点都不是关键点，所以让虚边额外贡献 $-(d-1)$。这样任何虚树路径展开回原树后，总得分完全相同。

#### 两条向下链如何合成路径

按虚树 DFS 序倒序处理，孩子一定先于父亲。对每点保存不同孩子提供的最大、次大链贡献；链贡献包括孩子及以下路径的点权，也包括连接父亲的虚边权，但不包含父亲点权。若当前点点权为 $w$，则以它为最高点的路径，最佳得分为 $w$ 加最多两条非负孩子链。

负链不会帮助提高得分，可以舍弃。但零链必须保留：例如两个值为 $x$ 的点间隔一个非 $x$ 点，下方送来的贡献是 $1-1=0$，加上上方关键点的一便得到合法三点路径。如果错误丢弃零链，可能只剩单点并被误判无解。

代码还要求至少接入一条真实孩子链，才检查得分是否为正，避免把单独一个关键点当作非平凡路径。向父亲上传时，用当前点权加最优孩子链，再扣掉虚边中间负权；非负才进入父亲的两个最大值。

#### 总规模为何可控

某个值出现 $c$ 次，补入的相邻祖先至多 $c-1$ 个，虚树规模为 $O(c)$。所有值的出现次数总和是 $n$，因此各虚树总规模仍为线性。原树迭代 DFS 与倍增表提供祖先关系、距离及最近公共祖先查询，排序和查询后的总时间上界为 $O(n\log n)$。出现不足两次的值直接输出否。

### 参考代码

```cpp
// F. Skibidus and Slay
// 做法：把「x 是多数」翻译成路径上的权值和 > 0（x 记 +1、非 x 记 -1），
//       最优路径两端必是 x，于是只需在所有「值为 x 的点」的虚树上求最大权路径。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 500005;   // n 的上界（sum n <= 5e5）
static const int LOG = 20;        // 2^19 = 524288 > 5e5，倍增 20 层够用
static const int NEG = -1000000;  // 「没有儿子链递上来」的哨兵值

int n;                                        // 本组的顶点数
int a[MAXN];                                  // a[v]：顶点 v 上写的数字
int head[MAXN], nxt[2 * MAXN], to[2 * MAXN], ec;   // 链式前向星存树
int par[MAXN], dep[MAXN], tin[MAXN], tout[MAXN], timer_;   // 父、深度、DFS 进出时刻
int up[LOG][MAXN];                            // up[k][v] = v 往上 2^k 步的祖先

int cntVal[MAXN], startVal[MAXN], curVal[MAXN], ord[MAXN];   // 按「值」分组用的桶
int vs_[2 * MAXN];                            // 虚树顶点序列（按 tin 排序）
int vidx[MAXN];                               // 虚树构造栈：存 vs_ 里的下标
int pidx[2 * MAXN], b1[2 * MAXN], b2[2 * MAXN];  // 虚树上：父下标、最大/次大向下链
int it_[MAXN], stk_[MAXN];                    // 迭代 DFS 用：当前出边、手写栈
char ans[MAXN];                               // ans[x]：值 x 能否当某个非平凡路径的多数

// 加一条有向边（无向边加两次）
void addEdge(int u, int v) {
    to[ec] = v;
    nxt[ec] = head[u];
    head[u] = ec++;
}

// u 是否是 v 的祖先（含 u == v）
inline bool isAnc(int u, int v) {
    return tin[u] <= tin[v] && tout[v] <= tout[u];
}

// 最近公共祖先：先判祖先关系，否则把 u 跳到「最浅的非 v 祖先」的下方一层
int lca(int u, int v) {
    if (isAnc(u, v)) return u;
    if (isAnc(v, u)) return v;
    for (int k = LOG - 1; k >= 0; --k) {
        int w = up[k][u];
        if (w && !isAnc(w, v)) u = w;         // 跳上去之后仍不能覆盖 v，就跳
    }
    return up[0][u];
}

int main() {
    ios::sync_with_stdio(false);              // 关掉与 stdio 的同步，加速 cin/cout
    cin.tie(nullptr);                         // 解绑 cin 与 cout，避免每次读入都冲刷

    int T;
    cin >> T;                                 // 组数
    while (T--) {
        cin >> n;                             // 本组顶点数
        for (int i = 1; i <= n; ++i) cin >> a[i];   // 每个点上的数字

        ec = 0;                               // 清空邻接表
        for (int i = 1; i <= n; ++i) head[i] = -1;
        for (int i = 1; i < n; ++i) {         // n - 1 条边
            int u, v;
            cin >> u >> v;
            addEdge(u, v);
            addEdge(v, u);
        }

        // ---- 迭代 DFS：算 par / dep / tin / tout（n 可达 5e5，递归会爆栈）
        timer_ = 0;
        int sp = 0;
        par[1] = 0; dep[1] = 0; tin[1] = ++timer_; it_[1] = head[1];
        stk_[sp++] = 1;
        while (sp > 0) {
            int u = stk_[sp - 1];             // 看栈顶
            int e = it_[u];                   // 它下一条待处理的出边
            if (e != -1) {
                it_[u] = nxt[e];              // 这条边用掉了
                int v = to[e];
                if (v == par[u]) continue;    // 不回走到父亲
                par[v] = u;                   // 记父
                dep[v] = dep[u] + 1;          // 记深度
                tin[v] = ++timer_;            // 进入时刻 = 前序编号
                it_[v] = head[v];             // 初始化它的出边游标
                stk_[sp++] = v;               // 下潜
            } else {
                tout[u] = timer_;             // 离开时刻：子树里最后的前序编号
                --sp;                         // 回溯
            }
        }

        // ---- 倍增表：up[k][v]
        for (int v = 1; v <= n; ++v) up[0][v] = par[v];
        for (int k = 1; k < LOG; ++k)
            for (int v = 1; v <= n; ++v)
                up[k][v] = up[k - 1][up[k - 1][v]];

        // ---- 按「值」分组：计数排序，把值相同的点连续摆放
        for (int x = 1; x <= n; ++x) cntVal[x] = 0;
        for (int i = 1; i <= n; ++i) ++cntVal[a[i]];
        int s = 0;
        for (int x = 1; x <= n; ++x) { startVal[x] = s; curVal[x] = s; s += cntVal[x]; }
        for (int i = 1; i <= n; ++i) ord[curVal[a[i]]++] = i;

        for (int x = 1; x <= n; ++x) {
            ans[x] = '0';                     // 默认「当不了多数」
            int c = cntVal[x];                // 值为 x 的点数
            if (c < 2) continue;              // 少于两个点，路径上最多出现一次 x，必不占多数

            int* g = ord + startVal[x];       // 值为 x 的点表
            sort(g, g + c, [](int u, int v) { return tin[u] < tin[v]; });  // 按 DFS 序排

            // ---- 建虚树点集：所有 x 点 + 相邻两点（按 DFS 序）的 LCA
            int m = 0;
            for (int i = 0; i < c; ++i) vs_[m++] = g[i];
            for (int i = 0; i + 1 < c; ++i) vs_[m++] = lca(g[i], g[i + 1]);
            sort(vs_, vs_ + m, [](int u, int v) { return tin[u] < tin[v]; });
            m = (int)(unique(vs_, vs_ + m) - vs_);   // 同一个点只会重复出现，按 tin 去重即可

            // ---- 用栈把虚树的父子关系建出来（父亲 = 栈里第一个祖先）
            int vsp = 0;
            for (int i = 0; i < m; ++i) {
                int v = vs_[i];
                while (vsp > 0 && !isAnc(vs_[vidx[vsp - 1]], v)) --vsp;
                pidx[i] = (vsp > 0) ? vidx[vsp - 1] : -1;   // 父亲在 vs_ 里的下标
                b1[i] = b2[i] = NEG;                        // NEG = 还没有儿子链递上来
                vidx[vsp++] = i;
            }

            // ---- 倒着扫（父亲的下标一定比儿子小）：虚树上的最大权路径
            //      点权：值为 x 的点 +1，其它点 -1；虚树边的权：-(距离-1)（中间的都不是 x）
            bool ok = false;
            for (int i = m - 1; i >= 0; --i) {
                int val = (a[vs_[i]] == x) ? 1 : -1;
                if (b1[i] != NEG) {                          // 有儿子链 = 路径至少有一条虚树边（≥ 2 个点）
                    int sec = (b2[i] == NEG) ? 0 : b2[i];    // 只有一条链时，另一侧就到 i 为止
                    if (val + b1[i] + sec > 0) { ok = true; break; }   // 以 i 为最高点的路径
                }
                int p = pidx[i];
                if (p >= 0) {
                    int d = dep[vs_[i]] - dep[vs_[p]];            // 虚树边在原树上的长度（边数）
                    int chain = -(d - 1) + val + (b1[i] == NEG ? 0 : b1[i]);  // 往上接到父亲的链
                    if (chain >= 0) {                             // 只留不小于 0 的链（0 不能丢！）
                        if (chain > b1[p]) { b2[p] = b1[p]; b1[p] = chain; }
                        else if (chain > b2[p]) b2[p] = chain;
                    }
                }
            }
            if (ok) ans[x] = '1';
        }

        string out;                           // 本组答案：长度 n 的 01 串
        out.resize(n);
        for (int x = 1; x <= n; ++x) out[x - 1] = ans[x];
        cout << out << '\n';
    }
    return 0;
}
```

### 易错点

得分为零的孩子链也要保留，它能使路径包含更多点并与根的正权合成合法答案；单点路径不合法。

## G. Skibidus and Capping

### 题意

统计 $i\le j$ 且 $\operatorname{lcm}(a_i,a_j)$ 是两个素数乘积的下标对，允许两个素数相同，且 $a_i\ge2$。

### 从零讲：$\operatorname{lcm}$ 什么时候是半素数——三个抽屉

最小公倍数对每种质数取两数指数的较大值。例如 $\operatorname{lcm}(6,2)=6=2\times3$，但 $\operatorname{lcm}(4,6)=12=2^2\times3$，质因子总数为三，不合格。

合格结果只能是 $p^2$ 或 $pq$。由于两个输入都必须整除最小公倍数，前者的输入只可能为 $p,p^2$，后者只可能为 $p,q,pq$。再按是否出现 $pq$ 分开，就得到三类互不相交的配对。

### 思路

数组里出现二、三、四、六时，二与三的最小公倍数为六，二与四为四，二与六为六，均是半素数；但四与六得到十二，含三个质因子而不合格。一个值与自己配对也允许，例如四与自身应计一次，二与自身则不计。

合格最小公倍数只可能是 $p^2$ 或两个不同素数的乘积 $pq$。原来的两个数都必须整除它，且题目保证至少为二，因此可以完整分类，不必枚举所有下标对。

若结果是 $p^2$，输入只能是 $p$ 或 $p^2$，且至少一个为 $p^2$。记频次为 $c_p,c_{p^2}$，从两类共 $c_p+c_{p^2}$ 个位置中选允许相同下标的一对，有 $m(m+1)/2$ 种；减去两边都是素数 $p$ 的情况，得到代码的第一类贡献。这里加一对应允许 $i=j$。

若结果是 $pq$ 且 $p\ne q$，可用输入只有 $p,q,pq$。若至少一个输入等于 $pq$，贡献为 $c_{pq}(c_p+c_q)+c_{pq}(c_{pq}+1)/2$。若没有输入等于 $pq$，就只能选两个不同的素数。设所有素数出现次数总和为 $T$、各素数频次平方和为 $S$，这一类统一计为 $(T^2-S)/2$：先数有序选择，排除同素数，再除二消除顺序。

三类按最终质因子形状、是否含合数分开，互不重叠；含三个以上质因子的输入也不可能整除半素数，自动不参与。代码预处理最小质因子，剥去一个后检查剩余部分是否为素数，即可识别半素数。频次按值聚合后只需遍历实际出现值，使用长整型累加答案。

### 参考代码

```cpp
// G. Skibidus and Capping
// 半素数 = 恰好两个质因子（可相同）：p^2 或 p*q (p≠q)。
// 于是 lcm(a_i, a_j) 是半素数只有三类情形：
//   A) 两个值都在 {p, p^2} 里，且至少有一个是 p^2；
//   B) 一个值是 v = p*q (p≠q)，另一个值 ∈ {p, q, v}；
//   C) 两个值是互不相同的质数 p、q（lcm 恰好 = p*q）。
// 三类互不重叠，分别用计数公式求和即可。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200005;   // n 的上界（sum n <= 2e5）

int spf[MAXN];                    // spf[v] = v 的最小质因子
int primes[MAXN], pc;             // 质数表（线性筛顺带收集）
int cnt[MAXN];                    // cnt[v] = 值 v 在本组里出现的次数
int used[MAXN], uc;               // 本组出现过的值（结束时按这个清桶，别清整张表）

int main() {
    ios::sync_with_stdio(false);  // 关掉与 stdio 的同步，加速 cin
    cin.tie(nullptr);             // 解绑 cin / cout

    // ---- 线性筛：每个合数只被它的最小质因子筛一次
    spf[1] = 1;                                   // 1 不是质数，占位
    for (int i = 2; i < MAXN; ++i) {
        if (!spf[i]) { spf[i] = i; primes[pc++] = i; }   // i 是质数
        for (int j = 0; j < pc && primes[j] <= spf[i] && 1LL * i * primes[j] < MAXN; ++j)
            spf[i * primes[j]] = primes[j];       // i 的最小质因子是 primes[j] 时才有资格筛
    }

    int T;
    cin >> T;                                     // 组数
    while (T--) {
        int n;
        cin >> n;                                 // 本组长度
        uc = 0;                                   // 清「出现过的值」表
        for (int i = 0; i < n; ++i) {
            int x;
            cin >> x;                             // 读入每个数（2 <= x <= n）
            if (cnt[x] == 0) used[uc++] = x;      // 第一次见到这个值就记下来
            ++cnt[x];                             // 计数
        }

        long long A = 0, B = 0, C = 0;            // 三类分别累计（答案可能到 2e10，用 long long）

        // ---- A 类：值只可能是 p 或 p^2，且至少要有一个 p^2
        for (int i = 0; i < pc; ++i) {
            long long p = primes[i];
            if (p * p > n) break;                 // p^2 超过值域就没得谈
            long long c1 = cnt[p], c2 = cnt[p * p];              // 值为 p 的个数、值为 p^2 的个数
            long long m = c1 + c2;                                // 这一族的总个数
            A += m * (m + 1) / 2 - c1 * (c1 + 1) / 2;             // 全部对 - 两个都是 p 的对
        }

        // ---- B 类与 C 类要用的两个量：质数出现次数之和 T、平方和 S
        long long T = 0, S = 0;
        for (int i = 0; i < uc; ++i) {
            int v = used[i];                      // 只看真正出现过的值，省时间
            int p = spf[v];                       // v 的最小质因子
            if (p == v) {                         // v 本身是质数
                long long c = cnt[v];
                T += c;                           // C 类要用
                S += c * c;
                continue;
            }
            int w = v / p;                        // 剥掉一个最小质因子
            if (w > 1 && spf[w] == w && w != p) { // v = p * w，且 p、w 是两个不同的质数
                // 另一侧可以取 p、w 或 v 本身；两边都是 v 的情况单独算一次
                B += 1LL * cnt[v] * (cnt[p] + cnt[w]) + 1LL * cnt[v] * (cnt[v] + 1) / 2;
            }
        }
        C = (T * T - S) / 2;                      // 互不相同质数对的乘积和（每对算一次）

        for (int i = 0; i < uc; ++i) cnt[used[i]] = 0;   // 只清本组用过的桶
        cout << A + B + C << '\n';                // 三类互不重叠，直接相加
    }
    return 0;
}
```

### 易错点

$i=j$ 合法，某个半素数单独与自己配对也计一次；同一个素数与自己配对不是半素数。

## H. Bro Thinks He's Him

### 题意

每次翻转二进制串的一位，求全部非空子序列的同字符连续段数之和，模 $998244353$。

### 从零讲：把「所有子序列的段数和」拆成每个位置的贡献

一个选出的字符串若有 $L$ 个字符，相邻同字符的对数为 $E$，则段数为 $L-E$。例如 `"001"` 长三，只有前两个字符形成同字符相邻对，段数为二。

每个原位置出现在 $2^{n-1}$ 个子序列里，故全部长度和为 $n2^{n-1}$。再固定同字符位置 $i<j$，要让它们在所选子序列中相邻，必须选中两端且不选中间；左边 $i-1$ 位任意选、右边 $n-j$ 位任意选，所以贡献 $2^{i-1}2^{n-j}$ 个相邻同字符对。逐对扣除便得到段数总和，每次扣除都对应一次真实的段合并。

### 思路

字符串 $\texttt{00}$ 的三个非空下标子序列分别贡献一、一、一，总和三；翻转第二位成 $\texttt{01}$ 后，三个子序列贡献一、一、二，总和四。变化只来自选中这两个位置且使它们相邻的子序列，单字符子序列的贡献不变。

#### 长度减去同字符相邻对

任意非空串由若干同字符段组成，长度为 $L$ 的一段内部恰有 $L-1$ 对相邻相同字符。将各段相加，得到段数等于字符总数减去相邻相同对数。对全部子序列求和，每个原位置都能与其他 $n-1$ 个位置任意搭配，出现 $2^{n-1}$ 次，故长度总和恒为 $n2^{n-1}$。

固定原位置 $i<j$ 且字符相同，要让它们在所选子序列中相邻，必须选中两端、不选中间位置；左边 $i-1$ 个位置和右边 $n-j$ 个位置任意选择，所以该对贡献 $2^{i-1}2^{n-j}$。记这些贡献之和为 $B$，答案就是 $n2^{n-1}-B$。同一子序列可能有多个相邻相同对，每个都应扣一次，恰好对应段内部的全部合并。

#### 翻转只改变以该位置为端点的数对

翻转位置 $p$，旧字符为 $c$、新字符为 $d$。不含 $p$ 的数对字符关系不变。对于左端 $i<p$，原来等于 $c$ 的贡献要删除，等于 $d$ 的贡献要新增，每项公共因子为 $2^{n-p}$；对于右端 $j>p$，公共因子为 $2^{p-1}$。因此
$$\Delta B=2^{n-p}(L_d-L_c)+2^{p-1}(R_d-R_c),$$
其中 $L$ 统计严格左侧的 $2^{i-1}$ 加权和，$R$ 统计严格右侧的 $2^{n-j}$ 加权和。

每种字符各用两棵树状数组，分别保存这两种权值。左侧查询取前缀 $p-1$，右侧查询用该字符总权值减去到 $p$ 的前缀，确保不把自己组成数对。先用旧状态算增量并更新 $B$，再把位置 $p$ 的两种权值从旧字符表移到新字符表，同时改写字符串，供下次查询继续使用。

初始的 $B$ 也无需枚举数对：从左向右扫右端 $j$，乘上此前同字符位置的左权值和即可。所有加减均在模数下归一化，单次翻转只有常数次树状数组操作，耗时 $O(\log n)$。

### 参考代码

```cpp
// H. Bro Thinks He's Him
// 把 f(b) 拆成「块的开头个数」：b 里每个被选中的位置，只要它是第一个被选的，
// 或者它前一个被选中的位置字符不同，就算一个块的开始。
// 逐位置数贡献（推导见题解「思路」），最后得到
//     S = m * 2^(m-1) - B,   B = sum_{i<j, s_i == s_j} 2^(i-1) * 2^(m-j)  (mod 998244353)
// 一次翻转只影响「跨过 p」的项，用两棵 BIT 维护每个字符的加权前缀 / 后缀和。
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;   // 题目要求的模数
static const int MAXM = 200005;           // |s| 的上界

long long p2[MAXM];                       // p2[k] = 2^k mod MOD

// ---- 树状数组：单点加、前缀和（全部对 MOD 取模）
struct BIT {
    int n;
    vector<long long> t;
    void init(int n_) { n = n_; t.assign(n + 2, 0); }
    void add(int i, long long v) {
        for (; i <= n; i += i & (-i)) {
            t[i] += v;                        // 加完立刻归一，别让它越滚越大
            if (t[i] >= MOD) t[i] -= MOD;
        }
    }
    long long sum(int i) {                    // 前 i 个位置的和
        long long r = 0;
        for (; i > 0; i -= i & (-i)) {
            r += t[i];
            if (r >= MOD) r -= MOD;
        }
        return r;
    }
};

int main() {
    ios::sync_with_stdio(false);              // 关同步，加速读入
    cin.tie(nullptr);

    p2[0] = 1;                                // 2 的幂预处理
    for (int i = 1; i < MAXM; ++i) p2[i] = p2[i - 1] * 2 % MOD;

    int T;
    cin >> T;                                 // 组数
    while (T--) {
        string s;
        cin >> s;                             // 二进制串
        int m = (int)s.size();
        int q;
        cin >> q;                             // 询问个数
        vector<int> qs(q);
        for (int i = 0; i < q; ++i) cin >> qs[i];

        BIT f1[2], f2[2];                     // f1[c]：权 2^(i-1) 的前缀和；f2[c]：权 2^(m-i)
        for (int c = 0; c < 2; ++c) { f1[c].init(m); f2[c].init(m); }
        long long tot2[2] = {0, 0};           // 每个字符的 2^(m-i) 总和（用来把后缀和变成「总和减前缀」）
        long long runA[2] = {0, 0};           // 扫描时每个字符的 2^(i-1) 累计
        long long B = 0;                      // 上面那个 B

        for (int j = 1; j <= m; ++j) {        // 从左到右扫一遍，初始化 B 和两棵 BIT
            int c = s[j - 1] - '0';
            B = (B + p2[m - j] * runA[c]) % MOD;      // 与前面同字符的位置配成 (i, j)
            runA[c] = (runA[c] + p2[j - 1]) % MOD;
            f1[c].add(j, p2[j - 1]);                  // 位置权 2^(j-1)
            f2[c].add(j, p2[m - j]);                  // 位置权 2^(m-j)
            tot2[c] = (tot2[c] + p2[m - j]) % MOD;
        }
        long long base = (long long)m % MOD * p2[m - 1] % MOD;   // m * 2^(m-1)

        for (int qi = 0; qi < q; ++qi) {
            int p = qs[qi];                   // 翻转位置 p（1 起）
            int c = s[p - 1] - '0';           // 原来的字符
            int d = c ^ 1;                    // 翻转后的字符

            // 前缀：严格在 p 左边、字符为 c / d 的 2^(i-1) 和
            long long Ac = f1[c].sum(p - 1), Ad = f1[d].sum(p - 1);
            // 后缀：严格在 p 右边、字符为 c / d 的 2^(m-j) 和
            long long Sc = (tot2[c] - f2[c].sum(p) % MOD + MOD) % MOD;
            long long Sd = (tot2[d] - f2[d].sum(p) % MOD + MOD) % MOD;

            // 位置 p 自己那一项（权 2^(m-p)） + 右边所有位置被它改变的那部分（权 2^(p-1)）
            long long dB = (p2[m - p] * ((Ad - Ac + MOD) % MOD)
                          + p2[p - 1] * ((Sd - Sc + MOD) % MOD)) % MOD;
            B = (B + dB) % MOD;

            f1[c].add(p, MOD - p2[p - 1]);    // 把 p 从旧字符的账上摘掉
            f2[c].add(p, MOD - p2[m - p]);
            tot2[c] = (tot2[c] - p2[m - p] + MOD) % MOD;
            s[p - 1] = char('0' + d);         // 真的翻转（后续询问接着用）
            f1[d].add(p, p2[p - 1]);          // 记到新字符的账上
            f2[d].add(p, p2[m - p]);
            tot2[d] = (tot2[d] + p2[m - p]) % MOD;

            long long ans = (base - B + MOD) % MOD;   // S = m * 2^(m-1) - B
            cout << ans << (qi + 1 == q ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 易错点

左右查询都排除位置 $p$；负数增量取模后归一化，翻转要写回字符串。

## A. Trippi Troppi

### 题意

读入三个单词，依次输出它们的首字母组成的简称。

### 思路

例如三个单词为 $\texttt{red green blue}$，现代名就是依次取首字母得到的 $\texttt{rgb}$。需要保留单词顺序，单词内部其余字符不参与答案。

输入的空格已经分隔了三个单词，用三个字符串直接读取即可。字符串首字符的下标为零，按顺序输出 $a[0],b[0],c[0]$，中间不加空格，最后换行。题目保证单词非空，因此这三个下标一定存在。

### 参考代码

```cpp
// A. Trippi Troppi
// 题意：每个古国名由三个单词组成，取每个单词的首字母拼成现代名。
